/**
 * JPEG artifact denoiser via ONNX Runtime Web.
 *
 * Model I/O:
 *   f16  — Float16Array in/out, values in [0, 1]   (WebGPU + shader-f16)
 *   f32  — Float32Array in/out, values in [0, 1]   (WebGPU)
 *   uint8 — Uint8Array in/out, values in [0, 255]  (WASM; model has built-in
 *            DequantizeLinear/QuantizeLinear nodes — no JS float conversion)
 *
 * Large images are split into tiles padded by the model's receptive field.
 * Only the unpadded center of each tile is written to the output — no blending.
 */

import type { RGBAImage } from "../formats/rgba_image.ts";
import type { OnnxSession } from "./onnx_session.ts";

/** Configuration for the denoiser. */
export interface DenoiserConfig {
  /** Tile size in pixels. */
  tileSize: number;
}

const DEFAULT_CONFIG: DenoiserConfig = {
  tileSize: 512,
};

/** Fallback receptive field when the model has no metadata entry. */
const DEFAULT_RECEPTIVE_FIELD = 21;

/**
 * Lookup table for uint8 → float32 conversion (precomputed once at module load).
 * Used by the f32 and f16 paths instead of per-pixel division by 255.
 */
const UINT8_TO_F32: Float32Array = Float32Array.from(
  { length: 256 },
  (_, i) => i / 255,
);

/** Progress callback: reports fraction complete [0, 1]. */
export type DenoiserProgressCallback = (progress: number) => void;

/**
 * Run the denoiser on an RGBA image using tiled inference.
 *
 * Each tile is padded by the model's receptive field on all four sides;
 * only the unpadded center is written to the output (no blending needed).
 * Small images that fit in a single tile are processed in one pass.
 */
export async function denoise(
  image: RGBAImage,
  session: OnnxSession,
  config: DenoiserConfig = DEFAULT_CONFIG,
  onProgress?: DenoiserProgressCallback,
): Promise<RGBAImage> {
  const { width, height } = image;
  const rfPadding = Math.floor((session.receptiveField ?? DEFAULT_RECEPTIVE_FIELD) / 2);
  const { tileSize } = config;
  const precision = session.precision;

  // Small image: single-pass inference
  if (width <= tileSize && height <= tileSize) {
    onProgress?.(0);
    const input = extractTile(image, 0, 0, width, height, precision);
    const output = await session.run("input", input, [1, 3, height, width]);
    onProgress?.(1);
    return { width, height, data: chwToRgba(output, width, height, 0, height) };
  }

  return tiledDenoise(image, session, tileSize, rfPadding, onProgress);
}

/**
 * Tiled denoiser for images larger than a single tile.
 *
 * Strategy:
 *  1. Divide image into non-overlapping tiles
 *  2. Pad each tile by the model's receptive field on all four sides
 *  3. Run inference on the padded tile
 *  4. Blit only the unpadded center region into the output
 *
 * No blending, no accumulation buffers — only one tile in memory at a time
 * (plus the final output image).  This keeps GPU memory use low and avoids
 * context resets on large images.
 */
async function tiledDenoise(
  image: RGBAImage,
  session: OnnxSession,
  tileSize: number,
  rfPadding: number,
  onProgress?: DenoiserProgressCallback,
): Promise<RGBAImage> {
  const { width, height } = image;
  const precision = session.precision;

  const tilesX = Math.ceil(width / tileSize);
  const tilesY = Math.ceil(height / tileSize);
  const totalTiles = tilesX * tilesY;

  console.log(
    `[ONNX Tiled] Denoising ${width}×${height} image with ${tilesX}×${tilesY}=${totalTiles} tiles` +
      ` (${tileSize}px, padding=${rfPadding}px)`,
  );

  const t0 = performance.now();
  const data = new Uint8ClampedArray(width * height * 4);
  let totalInferenceTime = 0;

  for (let ty = 0; ty < tilesY; ty++) {
    for (let tx = 0; tx < tilesX; tx++) {
      // Unpadded tile bounds
      const x0 = tx * tileSize;
      const y0 = ty * tileSize;
      const tileW = Math.min(tileSize, width - x0);
      const tileH = Math.min(tileSize, height - y0);

      // Padded bounds, clamped to image edges
      const padX0 = Math.max(0, x0 - rfPadding);
      const padY0 = Math.max(0, y0 - rfPadding);
      const padX1 = Math.min(width, x0 + tileW + rfPadding);
      const padY1 = Math.min(height, y0 + tileH + rfPadding);
      const padW = padX1 - padX0;
      const padH = padY1 - padY0;

      const input = extractTile(image, padX0, padY0, padW, padH, precision);

      const inferenceT0 = performance.now();
      const output = await session.run("input", input, [1, 3, padH, padW]);
      totalInferenceTime += performance.now() - inferenceT0;

      // Blit only the unpadded center into the output image
      blitTileToOutput(
        output,
        padW,
        padH,
        x0 - padX0,
        y0 - padY0,
        tileW,
        tileH,
        x0,
        y0,
        width,
        data,
      );

      onProgress?.((ty * tilesX + tx + 1) / totalTiles);
    }
  }

  const totalTime = performance.now() - t0;
  console.log(
    `[ONNX Tiled] Inference: ${totalInferenceTime.toFixed(0)}ms` +
      ` (${(totalInferenceTime / totalTiles).toFixed(0)}ms avg/tile),` +
      ` total: ${totalTime.toFixed(0)}ms`,
  );

  return { width, height, data };
}

/**
 * Extract a tile from the source image as CHW data.
 *
 * - uint8 precision: returns Uint8Array with raw [0,255] values (no arithmetic)
 * - f16  precision: returns Float16Array with values in [0, 1]
 * - f32  precision: returns Float32Array with values in [0, 1]
 *
 * For f32/f16, UINT8_TO_F32 replaces per-pixel division by 255.
 */
function extractTile(
  image: RGBAImage,
  x0: number,
  y0: number,
  tileW: number,
  tileH: number,
  precision: "f16" | "f32" | "uint8",
): Float32Array | Float16Array | Uint8Array {
  const { width, data } = image;
  const planeSize = tileH * tileW;

  if (precision === "uint8") {
    const chw = new Uint8Array(3 * tileH * tileW);
    for (let y = 0; y < tileH; y++) {
      for (let x = 0; x < tileW; x++) {
        const srcIdx = ((y0 + y) * width + (x0 + x)) * 4;
        const dstIdx = y * tileW + x;
        chw[dstIdx] = data[srcIdx];
        chw[planeSize + dstIdx] = data[srcIdx + 1];
        chw[2 * planeSize + dstIdx] = data[srcIdx + 2];
      }
    }
    return chw;
  }

  const chw: Float32Array | Float16Array = precision === "f16"
    ? new Float16Array(3 * tileH * tileW)
    : new Float32Array(3 * tileH * tileW);

  for (let y = 0; y < tileH; y++) {
    for (let x = 0; x < tileW; x++) {
      const srcIdx = ((y0 + y) * width + (x0 + x)) * 4;
      const dstIdx = y * tileW + x;
      chw[dstIdx] = UINT8_TO_F32[data[srcIdx]];
      chw[planeSize + dstIdx] = UINT8_TO_F32[data[srcIdx + 1]];
      chw[2 * planeSize + dstIdx] = UINT8_TO_F32[data[srcIdx + 2]];
    }
  }
  return chw;
}

/**
 * Convert a CHW model output slice to an RGBA Uint8ClampedArray.
 * Used for single-pass (small image) inference.
 *
 * Handles all three precision variants:
 * - Uint8Array:  direct copy (values already [0,255])
 * - Float32/16:  multiply × 255 and round
 */
function chwToRgba(
  chw: Float32Array | Float16Array | Uint8Array,
  width: number,
  paddedHeight: number,
  y0InPadded: number,
  stripHeight: number,
): Uint8ClampedArray {
  const planeSize = paddedHeight * width;
  const rgba = new Uint8ClampedArray(width * stripHeight * 4);

  if (chw instanceof Uint8Array) {
    for (let y = 0; y < stripHeight; y++) {
      const srcY = y0InPadded + y;
      for (let x = 0; x < width; x++) {
        const srcIdx = srcY * width + x;
        const dstIdx = (y * width + x) * 4;
        rgba[dstIdx] = chw[srcIdx];
        rgba[dstIdx + 1] = chw[planeSize + srcIdx];
        rgba[dstIdx + 2] = chw[2 * planeSize + srcIdx];
        rgba[dstIdx + 3] = 255;
      }
    }
  } else {
    for (let y = 0; y < stripHeight; y++) {
      const srcY = y0InPadded + y;
      for (let x = 0; x < width; x++) {
        const srcIdx = srcY * width + x;
        const dstIdx = (y * width + x) * 4;
        rgba[dstIdx] = Math.round(chw[srcIdx] * 255);
        rgba[dstIdx + 1] = Math.round(chw[planeSize + srcIdx] * 255);
        rgba[dstIdx + 2] = Math.round(chw[2 * planeSize + srcIdx] * 255);
        rgba[dstIdx + 3] = 255;
      }
    }
  }

  return rgba;
}

/**
 * Blit the unpadded center of a CHW tile into an RGBA output buffer.
 *
 * @param tileCHW   Model output (CHW, padded tile dimensions)
 * @param tileW     Width of the padded tile
 * @param tileH     Height of the padded tile
 * @param srcX0     X offset of the unpadded region within the tile
 * @param srcY0     Y offset of the unpadded region within the tile
 * @param copyW     Width of the region to copy
 * @param copyH     Height of the region to copy
 * @param dstX0     X position in the output image
 * @param dstY0     Y position in the output image
 * @param imageWidth Width of the output image
 * @param output    RGBA output buffer
 */
function blitTileToOutput(
  tileCHW: Float32Array | Float16Array | Uint8Array,
  tileW: number,
  tileH: number,
  srcX0: number,
  srcY0: number,
  copyW: number,
  copyH: number,
  dstX0: number,
  dstY0: number,
  imageWidth: number,
  output: Uint8ClampedArray,
): void {
  const planeSize = tileH * tileW;

  if (tileCHW instanceof Uint8Array) {
    // uint8 path: direct byte copy, no arithmetic
    for (let y = 0; y < copyH; y++) {
      for (let x = 0; x < copyW; x++) {
        const srcIdx = (srcY0 + y) * tileW + (srcX0 + x);
        const dstIdx = ((dstY0 + y) * imageWidth + (dstX0 + x)) * 4;
        output[dstIdx] = tileCHW[srcIdx];
        output[dstIdx + 1] = tileCHW[planeSize + srcIdx];
        output[dstIdx + 2] = tileCHW[2 * planeSize + srcIdx];
        output[dstIdx + 3] = 255;
      }
    }
  } else {
    // float path: multiply × 255 and round
    for (let y = 0; y < copyH; y++) {
      for (let x = 0; x < copyW; x++) {
        const srcIdx = (srcY0 + y) * tileW + (srcX0 + x);
        const dstIdx = ((dstY0 + y) * imageWidth + (dstX0 + x)) * 4;
        output[dstIdx] = Math.round(tileCHW[srcIdx] * 255);
        output[dstIdx + 1] = Math.round(tileCHW[planeSize + srcIdx] * 255);
        output[dstIdx + 2] = Math.round(tileCHW[2 * planeSize + srcIdx] * 255);
        output[dstIdx + 3] = 255;
      }
    }
  }
}
