/**
 * GPU-accelerated content-mask building for auto-crop.
 *
 * Classifies every pixel as background or content by looking up a precomputed
 * 64³ RGB→OKLab LUT and comparing the OKLab distance to the page background
 * against a threshold.  The output is a 1-bit-per-pixel packed Uint32Array
 * whose layout matches the PackedMask type in auto_crop.ts.
 *
 * LUT format
 * ──────────
 *   64 levels per R/G/B channel → 64³ = 262,144 entries × 4 bytes ≈ 1 MB.
 *   Entry for (r64, g64, b64) describes the representative colour
 *   r = r64*4, g = g64*4, b = b64*4 in OKLab:
 *     bits  7:0   L  in [0,1]        → quantised to [0,255]
 *     bits 15:8   a  in [−0.4,+0.4] → quantised to [0,255]
 *     bits 23:16  b  in [−0.4,+0.4] → quantised to [0,255]
 *     bits 31:24  unused (0)
 *
 * The LUT GPU buffer is cached per device and rebuilt on device loss.
 */

import type { RGBAImage } from "../formats/rgba_image.ts";
import { srgbToOklab } from "../color/palette.ts";
import contentMaskShader from "./shaders/content_mask.wgsl?raw";

// ---------------------------------------------------------------------------
// Constants — must match content_mask.wgsl
// ---------------------------------------------------------------------------

const LUT_DIM  = 64;
const LUT_SIZE = LUT_DIM * LUT_DIM * LUT_DIM;  // 262,144
const AB_RANGE = 0.4;

// ---------------------------------------------------------------------------
// Pipeline + LUT cache (invalidated on device loss)
// ---------------------------------------------------------------------------

interface ContentMaskCache {
  device:    GPUDevice;
  pipeline:  GPUComputePipeline;
  bgl:       GPUBindGroupLayout;
  lutBuffer: GPUBuffer;
}

let cachedContentMask: ContentMaskCache | null = null;

function getOrCreateContentMask(device: GPUDevice): ContentMaskCache {
  if (cachedContentMask && cachedContentMask.device !== device) {
    cachedContentMask.lutBuffer.destroy();
    cachedContentMask = null;
  }
  if (cachedContentMask) return cachedContentMask;

  // ── Build 64³ LUT on the CPU ──────────────────────────────────────────────
  const lutData = new Uint32Array(LUT_SIZE);
  for (let r64 = 0; r64 < LUT_DIM; r64++) {
    for (let g64 = 0; g64 < LUT_DIM; g64++) {
      for (let b64 = 0; b64 < LUT_DIM; b64++) {
        const [L, a, b] = srgbToOklab(r64 * 4, g64 * 4, b64 * 4);
        const lU8 = Math.max(0, Math.min(255, Math.round(L * 255)));
        const aU8 = Math.max(0, Math.min(255, Math.round((a + AB_RANGE) / (2 * AB_RANGE) * 255)));
        const bU8 = Math.max(0, Math.min(255, Math.round((b + AB_RANGE) / (2 * AB_RANGE) * 255)));
        lutData[r64 * LUT_DIM * LUT_DIM + g64 * LUT_DIM + b64] = lU8 | (aU8 << 8) | (bU8 << 16);
      }
    }
  }

  // ── Upload LUT to a persistent GPU buffer ────────────────────────────────
  const lutBuffer = device.createBuffer({
    size:             LUT_SIZE * 4,
    usage:            GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_DST,
    mappedAtCreation: true,
  });
  new Uint32Array(lutBuffer.getMappedRange()).set(lutData);
  lutBuffer.unmap();

  // ── Create pipeline ───────────────────────────────────────────────────────
  const bgl = device.createBindGroupLayout({
    entries: [
      { binding: 0, visibility: GPUShaderStage.COMPUTE, texture: { sampleType: "float" } },
      { binding: 1, visibility: GPUShaderStage.COMPUTE, buffer:  { type: "uniform" } },
      { binding: 2, visibility: GPUShaderStage.COMPUTE, buffer:  { type: "read-only-storage" } },
      { binding: 3, visibility: GPUShaderStage.COMPUTE, buffer:  { type: "storage" } },
    ],
  });

  const module = device.createShaderModule({ code: contentMaskShader });
  const pipeline = device.createComputePipeline({
    layout:  device.createPipelineLayout({ bindGroupLayouts: [bgl] }),
    compute: { module, entryPoint: "main" },
  });

  cachedContentMask = { device, pipeline, bgl, lutBuffer };
  return cachedContentMask;
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/**
 * Build a 1-bpp content mask on the GPU for a single page image.
 *
 * Each pixel is classified as content (bit = 1) if its OKLab distance from
 * `bgOklab` exceeds `threshold`.  The quantised RGB→OKLab LUT is precomputed
 * once per device (~1 MB GPU buffer, cached across calls).
 *
 * The returned object is structurally identical to the `PackedMask` type in
 * `auto_crop.ts` and can be passed directly to `computeAutoCropFromMasks`.
 *
 * @param device    Shared WebGPU device from `getGPUContext()`.
 * @param image     Source image in CPU memory (RGBA8).
 * @param bgOklab   Background colour in OKLab [L, a, b].
 * @param threshold OKLab distance threshold (content if dist > threshold).
 */
export async function buildContentMaskGPU(
  device:    GPUDevice,
  image:     RGBAImage,
  bgOklab:   [number, number, number],
  threshold: number,
): Promise<{ words: Uint32Array; width: number; height: number; rowStride: number }> {
  const { pipeline, bgl, lutBuffer } = getOrCreateContentMask(device);

  const rowStride = Math.ceil(image.width / 32);
  const maskWords = rowStride * image.height;

  // ── Input texture ─────────────────────────────────────────────────────────
  const texture = device.createTexture({
    size:   { width: image.width, height: image.height },
    format: "rgba8unorm",
    usage:  GPUTextureUsage.TEXTURE_BINDING | GPUTextureUsage.COPY_DST,
  });
  device.queue.writeTexture(
    { texture },
    image.data as unknown as Uint8ClampedArray<ArrayBuffer>,
    { bytesPerRow: image.width * 4 },
    { width: image.width, height: image.height },
  );

  // ── Uniform buffer (32 bytes: 4 × u32 then 4 × f32) ──────────────────────
  // Struct layout (see content_mask.wgsl):
  //   [0]  u32  width       offset  0
  //   [1]  u32  height      offset  4
  //   [2]  u32  rowStride   offset  8
  //   [3]  u32  _pad        offset 12
  //   [4]  f32  bgL         offset 16
  //   [5]  f32  bgA         offset 20
  //   [6]  f32  bgB         offset 24
  //   [7]  f32  threshSq    offset 28
  const uniformRaw = new ArrayBuffer(32);
  const u32View    = new Uint32Array(uniformRaw);
  const f32View    = new Float32Array(uniformRaw);
  u32View[0] = image.width;
  u32View[1] = image.height;
  u32View[2] = rowStride;
  u32View[3] = 0;
  f32View[4] = bgOklab[0];
  f32View[5] = bgOklab[1];
  f32View[6] = bgOklab[2];
  f32View[7] = threshold * threshold;

  const uniformBuffer = device.createBuffer({
    size:             32,
    usage:            GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST,
    mappedAtCreation: true,
  });
  new Uint8Array(uniformBuffer.getMappedRange()).set(new Uint8Array(uniformRaw));
  uniformBuffer.unmap();

  // ── Output mask buffer ────────────────────────────────────────────────────
  // The shader writes every word it owns, so no explicit clear is needed.
  const maskBuffer = device.createBuffer({
    size:  maskWords * 4,
    usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_SRC,
  });

  // ── Staging buffer for readback ────────────────────────────────────────
  const stagingBuffer = device.createBuffer({
    size:  maskWords * 4,
    usage: GPUBufferUsage.COPY_DST | GPUBufferUsage.MAP_READ,
  });

  // ── Bind group ────────────────────────────────────────────────────────────
  const bindGroup = device.createBindGroup({
    layout: bgl,
    entries: [
      { binding: 0, resource: texture.createView() },
      { binding: 1, resource: { buffer: uniformBuffer } },
      { binding: 2, resource: { buffer: lutBuffer } },
      { binding: 3, resource: { buffer: maskBuffer } },
    ],
  });

  // ── Encode: compute + copy to staging ─────────────────────────────────────
  const encoder = device.createCommandEncoder();

  const pass = encoder.beginComputePass();
  pass.setPipeline(pipeline);
  pass.setBindGroup(0, bindGroup);
  // One workgroup per output word: rowStride columns × image.height rows.
  pass.dispatchWorkgroups(rowStride, image.height);
  pass.end();

  encoder.copyBufferToBuffer(maskBuffer, 0, stagingBuffer, 0, maskWords * 4);
  device.queue.submit([encoder.finish()]);

  // ── Readback ──────────────────────────────────────────────────────────────
  await stagingBuffer.mapAsync(GPUMapMode.READ);
  const words = new Uint32Array(stagingBuffer.getMappedRange()).slice();
  stagingBuffer.unmap();

  // ── Release transient GPU objects ─────────────────────────────────────────
  texture.destroy();
  uniformBuffer.destroy();
  maskBuffer.destroy();
  stagingBuffer.destroy();

  return { words, width: image.width, height: image.height, rowStride };
}
