/**
 * WebGPU context management.
 *
 * Provides a singleton GPUDevice shared across all GPU operations
 * (denoising, future skeletonization, palettization, etc.).
 */

export interface GPUContext {
  readonly device: GPUDevice;
  readonly adapter: GPUAdapter;
}

let cachedContext: GPUContext | null = null;
let initPromise: Promise<GPUContext> | null = null;

/**
 * Get or create the shared WebGPU context.
 * Safe to call multiple times — returns the same device.
 */
export async function getGPUContext(): Promise<GPUContext> {
  if (cachedContext) return cachedContext;
  if (initPromise) return initPromise;

  initPromise = (async () => {
    // deno-lint-ignore no-explicit-any
    const gpu = (navigator as any).gpu as GPU | undefined;
    if (!gpu) {
      throw new Error("WebGPU is not supported in this browser");
    }

    const adapter = await gpu.requestAdapter();
    if (!adapter) {
      throw new Error("Failed to obtain WebGPU adapter");
    }

    const device = await adapter.requestDevice();

    device.addEventListener("uncapturederror", (event: Event) => {
      const gpuEvent = event as GPUUncapturedErrorEvent;
      console.error("WebGPU uncaptured error:", gpuEvent.error);
    });

    // When the device is lost, clear the singleton so the next call
    // to getGPUContext() creates a fresh device.
    device.lost.then((info: GPUDeviceLostInfo) => {
      console.warn(`WebGPU device lost (${info.reason}): ${info.message}`);
      if (cachedContext?.device === device) {
        cachedContext = null;
        initPromise = null;
      }
    });

    cachedContext = { device, adapter };
    initPromise = null;
    return cachedContext;
  })();

  return initPromise;
}

/** Check whether WebGPU is available in the current environment. */
export function isWebGPUAvailable(): boolean {
  // deno-lint-ignore no-explicit-any
  return typeof navigator !== "undefined" && !!(navigator as any).gpu;
}

/**
 * Create a GPU buffer initialized with data.
 */
export function createGPUBuffer(
  device: GPUDevice,
  data: Uint8Array | Uint32Array | Float32Array,
  usage: GPUBufferUsageFlags,
): GPUBuffer {
  const buffer = device.createBuffer({
    size: data.byteLength,
    usage,
    mappedAtCreation: true,
  });

  const mapped = buffer.getMappedRange();
  if (data instanceof Float32Array) {
    new Float32Array(mapped).set(data);
  } else if (data instanceof Uint32Array) {
    new Uint32Array(mapped).set(data);
  } else {
    new Uint8Array(mapped).set(data);
  }
  buffer.unmap();
  return buffer;
}

/**
 * Read data back from a GPU buffer to CPU.
 */
export async function readGPUBuffer(
  device: GPUDevice,
  buffer: GPUBuffer,
  size: number,
): Promise<Uint8Array> {
  const readBuffer = device.createBuffer({
    size,
    usage: GPUBufferUsage.COPY_DST | GPUBufferUsage.MAP_READ,
  });

  const encoder = device.createCommandEncoder();
  encoder.copyBufferToBuffer(buffer, 0, readBuffer, 0, size);
  device.queue.submit([encoder.finish()]);

  await readBuffer.mapAsync(GPUMapMode.READ);
  const result = new Uint8Array(readBuffer.getMappedRange()).slice();
  readBuffer.unmap();
  readBuffer.destroy();
  return result;
}
