/**
 * CPU-side path connection pass.
 *
 * After Guo-Hall thinning, reads each skeleton layer from GPU memory and
 * builds a pixel-adjacency graph: every "on" pixel becomes a vertex, and
 * edges connect directly adjacent "on" pixels in the 8-connected
 * neighbourhood.
 *
 * Graph construction
 * ──────────────────
 * Pixel classification (by effective degree after orthogonal suppression):
 *   degree 0 : isolated pixel → "isolated" vertex
 *   degree 1 : endpoint       → "endpoint" vertex
 *   degree 2 : path pixel     → "chain" vertex
 *   degree ≥ 3 : junction     → "junction" vertex
 *
 * Orthogonal-preference rule
 * ──────────────────────────
 * For diagonal neighbor D of pixel P, let O1 and O2 be the two orthogonal
 * neighbors adjacent to both P and D:
 *
 *   NE diagonal (x+1, y-1): O1 = N (x, y-1),   O2 = E (x+1, y)
 *   SE diagonal (x+1, y+1): O1 = S (x, y+1),   O2 = E (x+1, y)
 *   SW diagonal (x-1, y+1): O1 = S (x, y+1),   O2 = W (x-1, y)
 *   NW diagonal (x-1, y-1): O1 = N (x, y-1),   O2 = W (x-1, y)
 *
 * If either O1 or O2 is "on", the diagonal connection P↔D is skipped.
 * This avoids creating extra graph edges where an orthogonal path already
 * connects the same two pixels.
 *
 * Edge representation
 * ───────────────────
 * Each edge connects two immediately adjacent pixels.  All edges are
 * emitted in canonical order (lower pixel index → higher pixel index) to
 * avoid duplicates.
 */

import type { PaletteDecomposition } from "./palette_decompose_types.ts";

// ---------------------------------------------------------------------------
// Public types
// ---------------------------------------------------------------------------

export interface PathVertex {
  /** Image-pixel X coordinate (within the thinned layer). */
  x: number;
  /** Image-pixel Y coordinate. */
  y: number;
  /** Index of the palette layer this vertex belongs to. */
  layer: number;
  /**
   * Vertex type based on effective degree:
   *   "isolated"  — degree 0 (no neighbours)
   *   "endpoint"  — degree 1 (dangling end of a path)
   *   "chain"     — degree 2 (interior of a path)
   *   "junction"  — degree ≥ 3 (branching point)
   */
  type: "endpoint" | "junction" | "chain" | "isolated";
}

export interface PathEdge {
  /** Index into PathGraph.vertices for the start vertex. */
  from: number;
  /** Index into PathGraph.vertices for the end vertex. */
  to: number;
  /** Index of the palette layer this edge belongs to. */
  layer: number;
}

export interface PathGraph {
  /** Width of the source image (thinned layer dimensions). */
  width: number;
  /** Height of the source image. */
  height: number;
  /** Number of palette layers. */
  layerCount: number;
  vertices: PathVertex[];
  edges: PathEdge[];
}

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

/**
 * Compute the pixel index → effective neighbor list for one skeleton layer,
 * applying the orthogonal-preference rule to suppress diagonal connections
 * that are already reachable via orthogonal steps.
 *
 * Only "on" pixels are present as keys in the returned map.
 */
function buildAdjacency(
  pixels: Uint8Array,
  width: number,
  height: number,
): Map<number, number[]> {
  const adj = new Map<number, number[]>();

  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      if (!pixels[y * width + x]) continue;

      const hasN  = y > 0             && !!pixels[(y - 1) * width + x];
      const hasS  = y < height - 1    && !!pixels[(y + 1) * width + x];
      const hasE  = x < width - 1     && !!pixels[y * width + (x + 1)];
      const hasW  = x > 0             && !!pixels[y * width + (x - 1)];
      const hasNE = y > 0 && x < width - 1    && !!pixels[(y - 1) * width + (x + 1)];
      const hasSE = y < height - 1 && x < width - 1 && !!pixels[(y + 1) * width + (x + 1)];
      const hasSW = y < height - 1 && x > 0   && !!pixels[(y + 1) * width + (x - 1)];
      const hasNW = y > 0 && x > 0            && !!pixels[(y - 1) * width + (x - 1)];

      const neighbors: number[] = [];

      // Orthogonal connections (always preferred)
      if (hasN) neighbors.push((y - 1) * width + x);
      if (hasS) neighbors.push((y + 1) * width + x);
      if (hasE) neighbors.push(y * width + (x + 1));
      if (hasW) neighbors.push(y * width + (x - 1));

      // Diagonal connections — only when no orthogonal shortcut exists
      if (hasNE && !hasN && !hasE) neighbors.push((y - 1) * width + (x + 1));
      if (hasSE && !hasS && !hasE) neighbors.push((y + 1) * width + (x + 1));
      if (hasSW && !hasS && !hasW) neighbors.push((y + 1) * width + (x - 1));
      if (hasNW && !hasN && !hasW) neighbors.push((y - 1) * width + (x - 1));

      adj.set(y * width + x, neighbors);
    }
  }

  return adj;
}

/**
 * Read all skeleton pixels for one layer from the packed u32 buffer.
 * Returns a flat Uint8Array of size width*height with 1 = on, 0 = off.
 */
function unpackLayer(
  words: Uint32Array,
  layerOffset: number, // word offset into words[]
  width: number,
  height: number,
  rowStride: number,
): Uint8Array {
  const pixels = new Uint8Array(width * height);
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      const wordIdx = layerOffset + y * rowStride + (x >>> 5);
      const bit = (words[wordIdx] >>> (x & 31)) & 1;
      pixels[y * width + x] = bit;
    }
  }
  return pixels;
}

/**
 * Build a pixel-adjacency graph for one skeleton layer.
 *
 * Every "on" pixel becomes a vertex.  Edges connect immediately adjacent
 * "on" pixels (8-connected, with orthogonal-preference suppression).
 * Each undirected edge is emitted exactly once (lower pixel index first).
 */
function buildLayerGraph(
  pixels: Uint8Array,
  width: number,
  height: number,
  layerIndex: number,
  outVertices: PathVertex[],
  outEdges: PathEdge[],
): void {
  const adj = buildAdjacency(pixels, width, height);
  if (adj.size === 0) return;

  // ── Create one vertex per "on" pixel ──────────────────────────────────────
  const pixelToVertex = new Map<number, number>();

  for (const [idx, neighbors] of adj) {
    const x = idx % width;
    const y = (idx - x) / width;
    const degree = neighbors.length;

    let type: PathVertex["type"];
    if      (degree === 0) type = "isolated";
    else if (degree === 1) type = "endpoint";
    else if (degree === 2) type = "chain";
    else                   type = "junction";

    pixelToVertex.set(idx, outVertices.length);
    outVertices.push({ x, y, layer: layerIndex, type });
  }

  // ── Emit edges (canonical: lower pixel index → higher pixel index) ────────
  for (const [idx, neighbors] of adj) {
    const fromV = pixelToVertex.get(idx)!;
    for (const nidx of neighbors) {
      if (nidx > idx) {
        const toV = pixelToVertex.get(nidx);
        if (toV !== undefined) {
          outEdges.push({ from: fromV, to: toV, layer: layerIndex });
        }
      }
    }
  }
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/**
 * Read all layers of a thinned `PaletteDecomposition` from GPU memory and
 * build a pixel-adjacency path graph for each layer.
 *
 * Every skeleton pixel becomes a vertex; edges connect only to immediate
 * 8-connected neighbours (with orthogonal-preference suppression of
 * diagonal edges where an orthogonal path already exists).
 *
 * @param device  WebGPU device (used for buffer readback).
 * @param decomp  A thinned `PaletteDecomposition` (result of `thinDecomposition`).
 * @returns       A `PathGraph` containing vertices and edges for all layers.
 */
export async function connectPaths(
  device: GPUDevice | null,
  decomp: PaletteDecomposition,
): Promise<PathGraph> {
  const { width, height, rowStride, layers, buffer } = decomp;
  const numLayers = layers.length;

  if (numLayers === 0) {
    return { width, height, layerCount: 0, vertices: [], edges: [] };
  }

  // ── Read entire buffer back to CPU ─────────────────────────────────────────
  const layerWords = rowStride * height;
  const totalBytes = numLayers * layerWords * 4;

  // CPU-backed decomposition: use the words directly, no GPU round-trip.
  let words: Uint32Array;
  let staging: GPUBuffer | null = null;

  if (decomp.cpuWords) {
    words = decomp.cpuWords;
  } else {
    if (!device) {
      throw new Error("connectPaths: no GPU device and no cpuWords fallback");
    }
    staging = device.createBuffer({
      size: totalBytes,
      usage: GPUBufferUsage.COPY_DST | GPUBufferUsage.MAP_READ,
    });

    const encoder = device.createCommandEncoder();
    encoder.copyBufferToBuffer(buffer, 0, staging, 0, totalBytes);
    device.queue.submit([encoder.finish()]);

    await staging.mapAsync(GPUMapMode.READ);
    words = new Uint32Array(staging.getMappedRange());
  }

  // ── Build graph per layer ──────────────────────────────────────────────────
  const vertices: PathVertex[] = [];
  const edges: PathEdge[] = [];

  for (let li = 0; li < numLayers; li++) {
    const layerOffset = li * layerWords;
    const pixels = unpackLayer(words, layerOffset, width, height, rowStride);
    buildLayerGraph(pixels, width, height, li, vertices, edges);
  }

  if (staging) {
    staging.unmap();
    staging.destroy();
  }

  return { width, height, layerCount: numLayers, vertices, edges };
}
