/** Handle a newly selected file from disk: save to IndexedDB then load. */
async function onNewFile(file: File): Promise<void> {
  setStatus(`Saving ${file.name}...`);

  try {
    const id = await saveFile(file);
    state.currentFileId = id;
  } catch (err) {
    console.error("Failed to save file:", err);
  }

  const buffer = await file.arrayBuffer();
  await loadPdf(new Uint8Array(buffer), file.name);
  refreshFileList();
}

/** Handle reopening a previously stored file from IndexedDB. */
async function onStoredFileSelected(stored: StoredFile): Promise<void> {
  state.currentFileId = stored.id;
  await loadPdf(stored.data, stored.name);
}

/** Common PDF load logic shared by new-file and stored-file paths. */
/**
 * Drop everything derived from the currently-open document.
 *
 * These maps are keyed by PAGE NUMBER, not by file, so leaving them in place
 * across a file switch made page 2 of the new document show page 2 of the old
 * one's decomposition and fitted curves.  They also hold GPU buffers, which
 * leaked a document's worth of memory on every switch.
 */
function resetPipelineState(): void {
  // Before the destroys below: the viewer may hold bind groups referencing
  // these buffers, and rendering through a destroyed buffer is a GPU error.
  setInkSources(new Map(), null);
  getTextureManager()?.setSuspended(false);
  for (const d of state.paletteDecompositions.values()) d.destroy();
  for (const d of state.thinnedDecompositions.values()) d.destroy();
  state.paletteDecompositions.clear();
  state.thinnedDecompositions.clear();
  state.inkLayers.clear();
  state.pathGraphs.clear();
  state.simplifiedPathGraphs.clear();
  state.undashedPathGraphs.clear();
  state.curveGraphs.clear();
  state.curvePathGraphs.clear();
  state.cropRects.clear();
  state.viewerLayer = "denoised";
  state.activeLayerIndex = -1;
  state.showFittedCurves = true;
  refreshGraphOverlay();
}

async function loadPdf(data: Uint8Array, fileName: string): Promise<void> {
  resetPipelineState();
  state.pdfFileName = fileName;
  state.selectedPage = 0;
  state.rawImage = null;
  state.croppedRawImage = null;
  state.denoisedImage = null;
  state.paletteEntries = null;
  state.bwCounts = null;
  state.editablePalette = null;
  state.selectedPages = new Set();
  state.coverPage = 1;
  state.denoisedPages = new Set();
  state.pageSizes = [];
  state.pageLayout = null;
  state.activePageNumber = 0;
  clearPaletteEditor();

  setStatus(`Loading ${fileName}...`);

  try {
    state.pdfDoc = await loadPdfDocument(data, pdfjsLib);
    state.pdfPageCount = state.pdfDoc.numPages;
  } catch (err) {
    console.error("Failed to read PDF:", err);
    setStatus("Failed to read PDF");
    return;
  }

  // Cache page sizes for layout computation
  state.pageSizes = await getPageSizes(state.pdfDoc);

  // Load saved project state for this file
  if (state.currentFileId) {
    try {
      const sel = await getPageSelection(state.currentFileId);
      if (sel) {
        state.selectedPages = new Set(sel.selectedPages);
        state.coverPage = sel.coverPage;
      }

      const denoisedNums = await getDenoisedPagesForFile(state.currentFileId);
      state.denoisedPages = new Set(denoisedNums);

      const savedPalette = await getPalette(state.currentFileId);
      if (savedPalette) {
        state.editablePalette = savedPalette;
        renderPaletteEditor(savedPalette);
      }
    } catch (err) {
      console.error("Failed to load saved state:", err);
    }
  }

  // Generate cover thumbnail (fire-and-forget)
  updateCoverThumbnail().then(() => refreshFileList()).catch(() => {});

  // Cache page labels
  state.pageLabels = await getPageLabels(state.pdfDoc);

  // For single-page PDFs, go directly to inspection
  if (state.pdfPageCount === 1) {
    state.selectedPages.add(1);
    showScreen("viewer");
    await enterInspection();
    return;
  }

  showScreen("viewer");

  // Update the filename display in the sidebar
  const pageName = document.getElementById("viewerPageName");
  if (pageName) pageName.textContent = fileName;

  await populatePageGrid(
    state.pdfDoc, state.pdfPageCount, browserCanvasBackend,
    state.selectedPages, state.denoisedPages, state.pageLabels,
  );
  updatePageGridState(state.selectedPages, state.denoisedPages);
  updateSelectionInfo(state.selectedPages.size, state.denoisedPages.size);
  updateContinueButton();

  // If pages are already selected from saved state, go straight to inspection.
  // The page grid is already populated so the user can return to it via "Select Pages".
  if (state.selectedPages.size > 0) {
    await enterInspection();
  } else {
    setPagePickerMode(true);
  }
}

/** Enter the multi-page inspection screen for all selected pages. */
async function enterInspection(): Promise<void> {
  if (!state.pdfDoc || state.selectedPages.size === 0) return;

  // Re-render palette if present
  if (state.editablePalette) {
    renderPaletteEditor(state.editablePalette);
  }

  setPagePickerMode(false);
  showScreen("viewer");
  setStatus("Rendering pages...");

  const sorted = [...state.selectedPages].sort((a, b) => a - b);

  // Load saved crop rects for these pages
  if (state.currentFileId) {
    try {
      const savedRects = await getCropRectsForFile(state.currentFileId);
      for (const sr of savedRects) {
        if (state.selectedPages.has(sr.pageNumber)) {
          state.cropRects.set(sr.pageNumber, {
            x: sr.x, y: sr.y, width: sr.width, height: sr.height,
          });
        }
      }
    } catch { /* ignore */ }
  }

  // Compute page layout — apply crops if we have them (show cropped view by default)
  const crops = state.cropRects.size > 0 ? state.cropRects : undefined;
  const layout = computePageLayout(sorted, state.pageSizes, 200, crops);
  state.pageLayout = layout;

  // Enter the multi-page GPU viewer.
  // Denoised composites are loaded inline after each overview (no race condition).
  await enterMultiPageView(
    layout, state.pdfDoc, browserCanvasBackend, state.currentFileId ?? "",
    state.denoisedPages,
    (pageNumber) => {
      // Called when a denoised image fails to decode — remove from state
      state.denoisedPages.delete(pageNumber);
    },
  );

  // Set first page as active
  if (sorted.length > 0) {
    onActivePageChanged(sorted[0]);
  }

  setStatus(`${sorted.length} page${sorted.length !== 1 ? "s" : ""} loaded`);
  refreshSidebar();
}

/** Called when the active page changes (from viewport tracking or initial load). */
function onActivePageChanged(pageNumber: number): void {
  state.selectedPage = pageNumber;
  state.activePageNumber = pageNumber;

  // Update page name in sidebar
  const pageName = state.pageLabels[pageNumber - 1] ?? `Page ${pageNumber}`;
  const nameEl = document.getElementById("viewerPageName");
  if (nameEl) nameEl.textContent = pageName;

  // Reset per-page image state (legacy single-page fields)
  state.rawImage = null;
  state.croppedRawImage = null;
  state.denoisedImage = null;
  state.cropRect = null;
  // Don't reset viewerLayer or cropMode — preserve user's crop session

  // Load this page's state (denoised image, etc.) in the background
  loadActivePageState(pageNumber);
}

/** Load denoised image state for the active page. */
async function loadActivePageState(pageNumber: number): Promise<void> {
  if (!state.pdfDoc) return;

  const loadedDenoised = await tryLoadDenoisedImage(pageNumber);
  if (loadedDenoised) {
    state.denoisedImage = loadedDenoised;
    onDenoiseComplete();
    setStatus(`Page ${state.pageLabels[pageNumber - 1] ?? pageNumber} — denoised`);
  } else {
    showFreshPageControls();
    setDenoiseButtonEnabled(true);
    setStatus(`Page ${state.pageLabels[pageNumber - 1] ?? pageNumber}`);
  }
}

// ---------------------------------------------------------------------------
// Denoised image persistence
// ---------------------------------------------------------------------------

async function tryLoadDenoisedImage(pageNumber: number): Promise<RGBAImage | null> {
  if (!state.currentFileId) return null;
  try {
    const stored = await getDenoisedImage(state.currentFileId, pageNumber);
    if (!stored) return null;
    return await pngBlobToRgbaImage(stored.pngBlob, stored.width, stored.height);
  } catch (err) {
    console.error("Failed to load denoised image:", err);
    return null;
  }
}

// ---------------------------------------------------------------------------
// Page selection
// ---------------------------------------------------------------------------

function onPageToggled(pageNumber: number): void {
  if (state.selectedPages.has(pageNumber)) {
    state.selectedPages.delete(pageNumber);
  } else {
    state.selectedPages.add(pageNumber);
  }
  updatePageGridState(state.selectedPages, state.denoisedPages);
  updateSelectionInfo(state.selectedPages.size, state.denoisedPages.size);
  updateContinueButton();
  persistPageSelection();
}

// ---------------------------------------------------------------------------
// Crop rect loading / inheritance
// ---------------------------------------------------------------------------

function defaultCropRect(w: number, h: number): CropRect {
  const inset = 0.05;
  const x = Math.round(w * inset);
  const y = Math.round(h * inset);
  return { x, y, width: w - 2 * x, height: h - 2 * y };
}

async function loadOrInheritCropRect(
  imgW: number,
  imgH: number,
  pageNumber: number,
): Promise<CropRect> {
  if (!state.currentFileId) return defaultCropRect(imgW, imgH);

  try {
    const saved = await getCropRect(state.currentFileId, pageNumber);
    if (saved) return { x: saved.x, y: saved.y, width: saved.width, height: saved.height };

    const allRects = await getCropRectsForFile(state.currentFileId);
    if (allRects.length > 0) {
      const sorted = allRects.sort((a, b) => b.pageNumber - a.pageNumber);
      const inherited = sorted[0];
      if (inherited.x + inherited.width <= imgW &&
          inherited.y + inherited.height <= imgH) {
        return { x: inherited.x, y: inherited.y, width: inherited.width, height: inherited.height };
      }
    }
  } catch (err) {
    console.error("Failed to load crop rect:", err);
  }

  return defaultCropRect(imgW, imgH);
}

// ---------------------------------------------------------------------------
// Persistence helpers
// ---------------------------------------------------------------------------

function rgbaImageToDataUrl(image: RGBAImage): string {
  const canvas = document.createElement("canvas");
  canvas.width = image.width;
  canvas.height = image.height;
  const ctx = canvas.getContext("2d")!;
  ctx.putImageData(
    new ImageData(new Uint8ClampedArray(image.data), image.width, image.height),
    0, 0,
  );
  return canvas.toDataURL("image/png");
}

async function updateCoverThumbnail(): Promise<void> {
  if (!state.currentFileId || !state.pdfDoc) return;
  try {
    const thumb = await renderPdfThumbnail(state.pdfDoc, state.coverPage, browserCanvasBackend);
    const dataUrl = rgbaImageToDataUrl(thumb);
    await updateFile(state.currentFileId, { thumbnail: dataUrl });
  } catch (err) {
    console.error("Failed to update cover thumbnail:", err);
  }
}

async function persistPalette(): Promise<void> {
  if (!state.currentFileId || !state.editablePalette) return;
  try {
    await savePalette(state.currentFileId, state.editablePalette);
  } catch (err) {
    console.error("Failed to save palette:", err);
  }
}

async function persistPageSelection(): Promise<void> {
  if (!state.currentFileId) return;
  try {
    await savePageSelection({
      fileId: state.currentFileId,
      selectedPages: [...state.selectedPages],
      coverPage: state.coverPage,
    });
  } catch (err) {
    console.error("Failed to save page selection:", err);
  }
}

// ---------------------------------------------------------------------------
// Project-level palette extraction
// ---------------------------------------------------------------------------

async function runProjectPalette(): Promise<void> {
  if (state.isPaletteExtracting) return;

  const layout = state.pageLayout;

  // Use all pages from the layout (viewer) or selected pages (page-select screen)
  const pages = layout
    ? layout.pages.map(p => p.pageNumber)
    : [...state.selectedPages];

  const tm = getTextureManager();

  // Quick pass to count eligible pages so we can show accurate progress
  const eligiblePages = pages.filter(p => state.denoisedPages.has(p));
  if (eligiblePages.length === 0) {
    setStatus("No denoised pages found — denoise first, then extract palette");
    return;
  }

  state.isPaletteExtracting = true;
  setPaletteButtonsEnabled(false);
  updatePaletteProgress(0.01); // show bar immediately so user knows it started

  try {
    // Always start fresh when user explicitly clicks Extract Palette
    state.editablePalette = null;

    const total = eligiblePages.length;
    const t0 = performance.now();

    // Combined load + bin phase.
    // Each page contributes equally to the first 90% of progress.
    const voxelGrids: VoxelGrid[] = [];
    const bwCountsList: BWCounts[] = [];

    for (let i = 0; i < total; i++) {
      const page = eligiblePages[i];
      setStatus(`Extracting palette: loading page ${i + 1} of ${total}…`);
      await new Promise<void>((r) => setTimeout(r, 0));

      let img: RGBAImage | null = null;

      if (tm) {
        try { img = await tm.getFullImage(page); } catch { /* ignore */ }
      }
      if (!img) img = await tryLoadDenoisedImage(page);
      if (!img) continue;

      // Apply crop rect if available
      const crop = state.cropRects.get(page);
      if (crop && crop.width > 0 && crop.height > 0 &&
          crop.x + crop.width <= img.width && crop.y + crop.height <= img.height) {
        img = cropRGBAImage(img, crop.x, crop.y, crop.width, crop.height);
      }

      // Re-acquire the GPU device before each page so that if the device was
      // lost (and the lost handler has since cleared the cache), we get a
      // fresh one rather than continuing with a dead device.
      const gpuCtx = await getGPUContext();

      setStatus(`Extracting palette: binning page ${i + 1} of ${total}…`);
      const { grid, bw } = await buildVoxelGridGPU(gpuCtx.device, img);
      voxelGrids.push(grid);
      bwCountsList.push(bw);

      // 0–90% = loading + binning phase
      updatePaletteProgress((i + 1) / total * 0.9);
    }

    if (voxelGrids.length === 0) {
      setStatus("No denoised pages could be loaded — check console");
      return;
    }

    // Smooth + extract phase  (90–100%)
    setStatus("Smoothing histogram and extracting palette…");
    updatePaletteProgress(0.92);
    await new Promise<void>((r) => setTimeout(r, 0));

    const mergedGrid = mergeVoxelGrids(voxelGrids);
    const entries = extractPaletteFromVoxels(mergedGrid);
    updatePaletteProgress(0.98);
    const mergedBW = mergeBWCounts(bwCountsList);
    state.editablePalette = createEditablePalette(entries, mergedBW);

    const t1 = performance.now();
    updatePaletteProgress(1);

    renderPaletteEditor(state.editablePalette!);
    await persistPalette();
    setStatus(`Palette: ${state.editablePalette!.inputs.length} colors from ${voxelGrids.length} pages (${(t1 - t0).toFixed(0)}ms)`);
  } catch (err: unknown) {
    console.error("Palette extraction failed:", err);
    setStatus("Palette extraction failed — try again (GPU may have been reset)");
  } finally {
    state.isPaletteExtracting = false;
    setPaletteButtonsEnabled(true);
    updatePaletteProgress(0); // hides the bar
  }
}

// ---------------------------------------------------------------------------
// Apply palette
// ---------------------------------------------------------------------------

async function runApplyPalette(): Promise<void> {
  perf.beginStage("apply palette (decompose+cleanup)");
  const palette = state.editablePalette;
  if (!palette) {
    setStatus("Extract a palette first");
    return;
  }

  const layout = state.pageLayout;
  const pages = layout
    ? layout.pages.map(p => p.pageNumber)
    : [...state.selectedPages];

  const tm = getTextureManager();
  const eligible = pages.filter(p => state.denoisedPages.has(p));

  if (eligible.length === 0) {
    setStatus("No denoised pages found — denoise first, then apply palette");
    return;
  }

  // The viewer may be drawing straight from the buffers this pass is about to
  // destroy and replace.  Release those bindings; they are re-established at
  // the end if an ink view is still selected.
  const wasInkView = state.viewerLayer === "combined" || state.viewerLayer === "layer";
  const inkLayerIndex = state.activeLayerIndex;
  setInkSources(new Map(), null);

  setStatus(`Decomposing palette across ${eligible.length} page(s)…`);
  let decomposed = 0;

  for (let i = 0; i < eligible.length; i++) {
    const pageNumber = eligible[i];
    setStatus(`Palette decomposition: page ${i + 1} of ${eligible.length}…`);
    await new Promise(r => setTimeout(r, 0));

    try {
      // Get denoised full image
      let img: RGBAImage | null = null;
      if (tm) {
        try { img = await tm.getFullImage(pageNumber); } catch { /* ignore */ }
      }
      if (!img) img = await tryLoadDenoisedImage(pageNumber);
      if (!img) continue;

      // Crop to region of interest. The decomposition operates on the cropped
      // area; consumers use the stored crop rect for positioning it on the page.
      const crop = state.cropRects.get(pageNumber);
      if (crop && crop.width > 0 && crop.height > 0 &&
          crop.x + crop.width <= img.width && crop.y + crop.height <= img.height) {
        img = cropRGBAImage(img, crop.x, crop.y, crop.width, crop.height);
      }

      // Re-acquire per page so a device-lost mid-loop gets a fresh device.
      const gpuDevice = (await getGPUContext()).device;

      // Destroy any previous decomposition for this page.
      state.paletteDecompositions.get(pageNumber)?.destroy();

      const rawDecomp  = await decomposePalette(gpuDevice, img, palette);
      const cleaned1   = await cleanupPalette(gpuDevice, rawDecomp);
      rawDecomp.destroy();
      // Second pass: catches single-pixel relics left by the first pass
      // (e.g. one surviving pixel of a diagonal stipple pair).
      const decomp     = await cleanupPalette(gpuDevice, cleaned1);
      cleaned1.destroy();
      state.paletteDecompositions.set(pageNumber, decomp);
      decomposed++;
    } catch (err) {
      console.error(`Palette decomposition failed for page ${pageNumber}:`, err);
    }
  }

  if (decomposed === 0) {
    setStatus("Palette decomposition failed — check console");
    return;
  }

  if (wasInkView) selectDecompositionView(inkLayerIndex);

  setStatus(`Decomposed palette into ${state.paletteDecompositions.get(eligible[0])?.layers.length ?? 0} layer(s) for ${decomposed} page(s)`);
  refreshSidebar();
}

// ---------------------------------------------------------------------------
// Thinning
// ---------------------------------------------------------------------------

async function runThinning(): Promise<void> {
  perf.beginStage("thin");
  if (state.isThinning) return;

  if (state.paletteDecompositions.size === 0) {
    setStatus("Apply palette first, then thin");
    return;
  }

  let gpuDevice: GPUDevice | null = null;
  // Guo-Hall is iterative — one full-image dispatch per pass until the skeleton
  // settles.  On a software rasteriser each dispatch is a CPU round trip, and a
  // 6000x4000 sheet takes ~20 min versus 1.8 s for the CPU port doing the same
  // work.  So on those adapters the CPU path is simply the fast one.
  let thinOnCpu = false;
  try {
    const ctx = await getGPUContext();
    gpuDevice = ctx.device;
    thinOnCpu = isSoftwareAdapter(ctx.adapter);
    if (thinOnCpu) {
      console.log(`[thin] software adapter (${describeAdapter(ctx.adapter)}) → CPU Guo-Hall`);
    }
  } catch (err) {
    setStatus("WebGPU unavailable — cannot thin");
    console.error("getGPUContext failed:", err);
    return;
  }

  state.isThinning = true;

  const pages = [...state.paletteDecompositions.keys()].sort((a, b) => a - b);
  setStatus(`Thinning ${pages.length} page(s)…`);

  let thinned = 0;
  for (let i = 0; i < pages.length; i++) {
    const pageNumber = pages[i];
    setStatus(`Thinning: page ${i + 1} of ${pages.length}…`);
    await new Promise(r => setTimeout(r, 0));

    try {
      const decomp = state.paletteDecompositions.get(pageNumber)!;

      // Destroy any previous thinned decomposition for this page.
      state.thinnedDecompositions.get(pageNumber)?.destroy();

      const result = await thinDecompositionAuto(gpuDevice, decomp, { forceCpu: thinOnCpu });
      state.thinnedDecompositions.set(pageNumber, result);
      state.inkLayers.set(pageNumber, result.layers);
      thinned++;
    } catch (err) {
      console.error(`Thinning failed for page ${pageNumber}:`, err);
    }
  }

  state.isThinning = false;

  if (thinned === 0) {
    setStatus("Thinning failed — check console");
    return;
  }

  setStatus(`Thinned ${thinned} page(s)`);
  refreshSidebar();

  // Build path graphs and update the graph overlay.
  await runPathConnect(gpuDevice!);

}

// ---------------------------------------------------------------------------
// Path connection
// ---------------------------------------------------------------------------

/**
 * Connect all thinned layers into path graphs and push to the graph overlay.
 * Called automatically at the end of runThinning().
 */
async function runPathConnect(gpuDevice: GPUDevice): Promise<void> {
  perf.beginStage("path connect");
  const pages = [...state.thinnedDecompositions.keys()].sort((a, b) => a - b);
  if (pages.length === 0) return;

  setStatus("Connecting paths…");
  state.pathGraphs.clear();

  for (const pageNumber of pages) {
    const decomp = state.thinnedDecompositions.get(pageNumber)!;
    try {
      const graph = await connectPaths(gpuDevice, decomp);
      state.pathGraphs.set(pageNumber, graph);
    } catch (err) {
      console.error(`connectPaths failed for page ${pageNumber}:`, err);
    }
    // The skeleton bitmap has done its job — nothing downstream reads it again,
    // only the ink colours, which are kept in state.inkLayers.  Releasing here
    // rather than at end of session saves ~9 MB of GPU per page.
    decomp.destroy();
    state.thinnedDecompositions.delete(pageNumber);
  }

  // Downstream graphs are now stale — clear them.
  state.simplifiedPathGraphs.clear();
  state.undashedPathGraphs.clear();
  state.curveGraphs.clear();
  state.curvePathGraphs.clear();
  refreshGraphOverlay();
  refreshSidebar();

  const totalV = [...state.pathGraphs.values()].reduce((s, g) => s + g.vertices.length, 0);
  const totalE = [...state.pathGraphs.values()].reduce((s, g) => s + g.edges.length, 0);
  setStatus(`Paths connected: ${totalV} vertices, ${totalE} edges`);
}

/**
 * (Re-)upload graph data to the overlay renderer using the current layout
 * and layer colors.  Safe to call any time after connectPaths has run.
 */
function refreshGraphOverlay(): void {
  const layout = state.pageLayout;

  if (!layout || !state.showFittedCurves || state.curvePathGraphs.size === 0) {
    updateGraphOverlay([], -1);
    setGraphOverlayVisible(false);
    return;
  }

  const overlayPages: GraphPageInput[] = [];

  for (const page of layout.pages) {
    const graph = state.curvePathGraphs.get(page.pageNumber);
    if (!graph) continue;

    // Virtual-space origin of the skeleton's (0,0) pixel.
    // The skeleton was computed on the cropped image, and the layout's page
    // dimensions already match the crop dimensions (page.width = crop.width).
    const imgOriginX = (layout.maxWidth - page.width) / 2;
    const imgOriginY = page.yOffset;

    const layerColors: Array<[number, number, number]> =
      (state.inkLayers.get(page.pageNumber) ?? []).map(l => l.outputRgb);

    overlayPages.push({ graph, imgOriginX, imgOriginY, layerColors });
  }

  // A failure here is a display problem, not a pipeline one.  It used to
  // propagate out of runCurveFit and abort the rest of runVectorize, which is
  // how a GPU buffer limit ended up leaving the viewer on the wrong background.
  try {
    updateGraphOverlay(overlayPages, state.activeLayerIndex);
    setGraphOverlayVisible(overlayPages.length > 0);
  } catch (err) {
    console.error("Fitted-curve overlay upload failed:", err);
    setGraphOverlayVisible(false);
  }
}

/** Turn the fitted-curve overlay on or off. */
function setShowFittedCurves(show: boolean): void {
  state.showFittedCurves = show;
  const cb = document.getElementById("showFittedCurves") as HTMLInputElement | null;
  if (cb) cb.checked = show;
  refreshGraphOverlay();
}

/**
 * Always-on cursor coordinate readout: page-local pixel position under the
 * mouse.  This is how a defect gets located well enough to describe — "the
 * arc at (5274, 3294)" — which is the whole in-app debugging story now.
 */
function initCursorReadout(): void {
  const viewerContainer = document.getElementById("viewerContainer");
  if (!viewerContainer) return;

  const clear = () => {
    const posEl = document.getElementById("viewerCursorPos");
    const sepEl = document.getElementById("cursorPosSep");
    if (posEl) posEl.textContent = "";
    if (sepEl) sepEl.style.display = "none";
  };

  viewerContainer.addEventListener("mouseleave", clear);

  viewerContainer.addEventListener("mousemove", (e) => {
    const posEl = document.getElementById("viewerCursorPos");
    const sepEl = document.getElementById("cursorPosSep");
    if (!posEl || !sepEl) return;

    const layout = state.pageLayout;
    if (!layout) { clear(); return; }

    const rect     = viewerContainer.getBoundingClientRect();
    const virtualX = (e.clientX - rect.left  - state.panX) / state.zoom;
    const virtualY = (e.clientY - rect.top   - state.panY) / state.zoom;

    let localX = -1, localY = -1;
    for (const page of layout.pages) {
      const pl = (layout.maxWidth - page.width) / 2;
      if (virtualX >= pl && virtualX < pl + page.width &&
          virtualY >= page.yOffset && virtualY < page.yOffset + page.height) {
        localX = virtualX - pl;
        localY = virtualY - page.yOffset;
        break;
      }
    }

    if (localX < 0) { clear(); return; }

    sepEl.style.display = "";
    posEl.textContent = `${Math.round(localX)}, ${Math.round(localY)} px`;
  });
}

// ---------------------------------------------------------------------------
// ---------------------------------------------------------------------------
// Path simplification
// ---------------------------------------------------------------------------

// Simplify / spur settings imported from pipeline_defaults.ts

/**
 * Run Douglas-Peucker simplification followed by spur removal on all raw
 * path graphs and store the results in state.simplifiedPathGraphs.
 */
async function runPathSimplify(): Promise<void> {
  perf.beginStage("simplify + despur");
  if (state.pathGraphs.size === 0) {
    setStatus("Run Thin first to generate path graphs");
    return;
  }

  setStatus("Simplifying paths…");

  state.simplifiedPathGraphs.clear();

  for (const [pageNumber, graph] of state.pathGraphs) {
    const simplified = simplifyPathGraph(graph, DEFAULT_SIMPLIFY_TOL);
    // The pre-thinning raster, so `removeSpurs` can tell a two-pixel whisker
    // from a short real stroke whose skeleton thinning ate into.
    const decomp = state.paletteDecompositions.get(pageNumber);
    const ink = decomp ? await readInkProbe((await getGPUContext()).device, decomp) : undefined;
    const marks: StrokeMark[] = [];
    state.simplifiedPathGraphs.set(pageNumber, removeSpurs(simplified, DEFAULT_SPUR_MAX, ink, marks));
    state.strokeMarks.set(pageNumber, marks);
  }

  // Enable the "Simplified paths" overlay option now that data is available.
  const simplifiedOption = document.getElementById("simplifiedOverlayOption");
  if (simplifiedOption) simplifiedOption.style.display = "";

  // Simplified graphs changed — clear stale undashed and fitted results.
  state.undashedPathGraphs.clear();
  state.curveGraphs.clear();
  state.curvePathGraphs.clear();
  updateExportButtons();

  const totalV = [...state.simplifiedPathGraphs.values()].reduce((s, g) => s + g.vertices.length, 0);
  const totalE = [...state.simplifiedPathGraphs.values()].reduce((s, g) => s + g.edges.length, 0);
  setStatus(`Simplified: ${totalV} vertices, ${totalE} edges (tolerance ${DEFAULT_SIMPLIFY_TOL}px)`);
}

// Undash settings imported from pipeline_defaults.ts

/**
 * Trim endpoint burrs and bridge gaps between nearby collinear dash segments.
 * Operates on simplifiedPathGraphs and stores results in undashedPathGraphs.
 */
function runUndash(): void {
  perf.beginStage("undash");
  if (state.simplifiedPathGraphs.size === 0) {
    setStatus("Run Simplify first");
    return;
  }

  setStatus("Undashing…");

  state.undashedPathGraphs.clear();
  state.curveGraphs.clear();
  state.curvePathGraphs.clear();
  updateExportButtons();

  for (const [pageNumber, graph] of state.simplifiedPathGraphs) {
    const undashed = undashPaths(graph, DEFAULT_UNDASH_MAX_GAP, DEFAULT_UNDASH_MAX_ANGLE);
    state.undashedPathGraphs.set(
      pageNumber,
      simplifyPathGraph(undashed, DEFAULT_SIMPLIFY_TOL),
    );
  }

  const totalV = [...state.undashedPathGraphs.values()].reduce((s, g) => s + g.vertices.length, 0);
  const totalE = [...state.undashedPathGraphs.values()].reduce((s, g) => s + g.edges.length, 0);
  setStatus(`Undashed: ${totalV} vertices, ${totalE} edges (gap ≤${DEFAULT_UNDASH_MAX_GAP}px, angle ≤${DEFAULT_UNDASH_MAX_ANGLE}°)`);
}

/**
 * Fit lines, arcs, and circles to the undashed paths, reconciling against
 * the pre-thinning palettized pixel data.  Options come from
 * pipeline_defaults.ts so the app, the tests and the e2e runners agree.
 */
async function runCurveFit(): Promise<void> {
  perf.beginStage("curve fit");
  if (state.undashedPathGraphs.size === 0) {
    setStatus("Run Undash first");
    return;
  }

  const { device: gpuDevice } = await getGPUContext();

  setStatus("Fitting curves…");

  state.curveGraphs.clear();
  state.curvePathGraphs.clear();

  const opts = { ...DEFAULT_FIT_OPTS };

  const pages = [...state.undashedPathGraphs.entries()];
  for (let pi = 0; pi < pages.length; pi++) {
    const [pageNumber, graph] = pages[pi];
    const decomp = state.paletteDecompositions.get(pageNumber);
    if (!decomp) continue;

    const pagePrefix = pages.length > 1 ? `p${pageNumber} ` : "";
    const validationOut = {} as { result: FitValidationResult };
    const curveGraph = await fitCurves(gpuDevice, graph, decomp, opts, (_frac, label) => {
      setStatus(`${pagePrefix}${label}`);
    }, validationOut);
    appendStrokeMarks(curveGraph, state.strokeMarks.get(pageNumber) ?? []);
    state.curveGraphs.set(pageNumber, curveGraph);
    state.curvePathGraphs.set(pageNumber, curveGraphToPathGraph(curveGraph, DEFAULT_FIT_OPTS.arcStep));

    // Log validation summary. Warnings are grouped by type for quick triage.
    const v = validationOut.result;
    const summary = [
      `chains: ${v.totalChains} total, ${v.absorbedChains} absorbed, ${v.droppedChains} dropped`,
      `coverage: mean ${v.meanCoverageError.toFixed(2)} px, max ${v.maxCoverageError.toFixed(2)} px (${v.coveredVertices} verts)`,
      `backward segs: ${v.backwardSegments}`,
      `junction gaps: ${v.disconnectedJunctions}`,
    ].join(" | ");
    if (v.droppedChains > 0 || v.backwardSegments > 0 || v.disconnectedJunctions > 0) {
      console.warn(`[fit validation] ${pagePrefix}${summary}`);
      for (const w of v.warnings) console.warn(`  [${w.type}] ${w.message}`, w.x != null ? `@ (${w.x?.toFixed(1)}, ${w.y?.toFixed(1)})` : "");
    } else {
      console.log(`[fit validation] ${pagePrefix}${summary}`);
    }
  }

  refreshSidebar();
  setShowFittedCurves(true);

  const totalSegs = [...state.curveGraphs.values()].reduce((s, g) => s + g.segments.length, 0);
  setStatus(`Fitted curves: ${totalSegs} segments`);
}

// ---------------------------------------------------------------------------
// Export (fitted CurveGraph → SVG / DXF, one file per page)
// ---------------------------------------------------------------------------

const EXPORT_DPI = 200; // pages are rendered at 200 DPI throughout the app

function triggerDownload(filename: string, content: string | Uint8Array, mime: string): void {
  const blob = new Blob([content as unknown as BlobPart], { type: mime });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 10_000);
}

/**
 * Show the last responsiveness report, and enable the ways of getting it off
 * the device.
 *
 * Copy first, save second: on a phone or tablet the clipboard is the path of
 * least resistance into a message, and a downloaded file is several taps and a
 * file manager away. Both exist because clipboard writes need a secure context
 * and a user gesture, and quietly do nothing when either is missing.
 */
function refreshDiagnostics(): void {
  const summary = document.getElementById("diagnosticsSummary");
  const details = document.getElementById("diagnosticsDetails");
  const text = document.getElementById("diagnosticsText");
  const copyBtn = document.getElementById("copyDiagnosticsBtn") as HTMLButtonElement | null;
  const saveBtn = document.getElementById("saveDiagnosticsBtn") as HTMLButtonElement | null;

  const r = perf.getReport();
  if (r.stages.length === 0) return;

  lastDiagnosticsText = perf.formatReport();
  if (text) text.textContent = lastDiagnosticsText;
  if (details) (details as HTMLElement).style.display = "";
  if (copyBtn) copyBtn.disabled = false;
  if (saveBtn) saveBtn.disabled = false;

  const pct = (r.blockedFraction * 100).toFixed(0);
  const worst = (Math.max(r.longTaskMaxMs, r.worstFrameGapMs) / 1000).toFixed(1);
  if (summary) {
    summary.textContent =
      `${(r.totalMs / 1000).toFixed(0)}s total, unresponsive for ${pct}% of it. ` +
      `Longest single freeze ${worst}s.`;
  }
  console.log("\n" + lastDiagnosticsText);
}

let lastDiagnosticsText = "";

/** Enable the export buttons only while fitted curves exist. */
function updateExportButtons(): void {
  const canExport = state.curveGraphs.size > 0;
  for (const id of ["exportSvgBtn", "exportDxfBtn", "exportOverlayPdfBtn"]) {
    const btn = document.getElementById(id) as HTMLButtonElement | null;
    if (btn) btn.disabled = !canExport;
  }
}

/**
 * Layer styling for a page, sourced from the decomposition colours (thinned
 * preferred, palette as fallback); synthesized from the curve graph's layer
 * count if neither survives.
 */
function exportLayersForPage(pageNumber: number, layerCount: number): ExportLayer[] {
  const layers = state.inkLayers.get(pageNumber) ??
    state.paletteDecompositions.get(pageNumber)?.layers;
  if (layers) {
    return layers.map((l, i) => ({ name: `Ink ${i + 1}`, rgb: l.outputRgb }));
  }
  return Array.from({ length: layerCount }, (_, i) => ({
    name: `Layer ${i + 1}`,
    rgb: [0, 0, 0] as [number, number, number],
  }));
}

/** Download every fitted page as one SVG or DXF file. */
async function runExport(format: "svg" | "dxf"): Promise<void> {
  if (state.curveGraphs.size === 0) {
    setStatus("Run Vectorize first — nothing to export yet");
    return;
  }

  const base = (state.pdfFileName || "cleanplans").replace(/\.pdf$/i, "");
  const pages = [...state.curveGraphs.keys()].sort((a, b) => a - b);
  const opts = { dpi: EXPORT_DPI };
  let exported = 0;

  for (const pageNumber of pages) {
    const graph = state.curveGraphs.get(pageNumber)!;
    const layers = exportLayersForPage(pageNumber, graph.layerCount);
    const content = format === "svg"
      ? curveGraphToSvg(graph, { ...opts, layers })
      : curveGraphToDxf(graph, { ...opts, layers });
    const mime = format === "svg" ? "image/svg+xml" : "application/dxf";
    triggerDownload(`${base}-page${pageNumber}.${format}`, content, mime);
    exported++;
    // Chrome prompts once for multi-file downloads; space them out slightly.
    if (pages.length > 1) await new Promise((r) => setTimeout(r, 300));
  }

  setStatus(`Exported ${exported} ${format.toUpperCase()} file${exported !== 1 ? "s" : ""}`);
}

/**
 * Download the cleaned pages — denoised, cropped, palettised — as lossless
 * PNGs (one per page) or a single lossless PDF.
 *
 * This is the raster half's output. Those stages are the expensive, hardware
 * dependent ones; the vector half is cheap and re-run constantly. Exporting the
 * clean page means the denoise/palette work can be done once on capable
 * hardware and the result reused or handed on, without redoing it.
 */
async function runCleanExport(format: "png" | "pdf"): Promise<void> {
  if (state.paletteDecompositions.size === 0) {
    setStatus("Apply a palette first — no cleaned pages yet");
    return;
  }

  let gpuDevice: GPUDevice;
  try {
    gpuDevice = (await getGPUContext()).device;
  } catch (err) {
    setStatus("WebGPU unavailable — cannot read cleaned pages");
    console.error("getGPUContext failed:", err);
    return;
  }

  const base = (state.pdfFileName || "cleanplans").replace(/\.pdf$/i, "");
  const pages = [...state.paletteDecompositions.keys()].sort((a, b) => a - b);

  try {
    if (format === "png") {
      let n = 0;
      for (const pageNumber of pages) {
        setStatus(`Encoding clean PNG for page ${pageNumber}…`);
        const img = await readAllLayersAsRGBA(gpuDevice, state.paletteDecompositions.get(pageNumber)!);
        triggerDownload(`${base}-page${pageNumber}-clean.png`, await encodeCleanPng(img), "image/png");
        n++;
        if (pages.length > 1) await new Promise((r) => setTimeout(r, 300));
      }
      setStatus(`Exported ${n} clean PNG${n !== 1 ? "s" : ""}`);
    } else {
      const rasterPages: RasterPage[] = [];
      for (const pageNumber of pages) {
        setStatus(`Reading clean page ${pageNumber}…`);
        rasterPages.push({
          image: await readAllLayersAsRGBA(gpuDevice, state.paletteDecompositions.get(pageNumber)!),
          dpi: EXPORT_DPI,
        });
      }
      setStatus("Encoding clean PDF…");
      triggerDownload(`${base}-clean.pdf`, await encodeCleanPdf(rasterPages), "application/pdf");
      setStatus(`Exported clean PDF (${rasterPages.length} page${rasterPages.length !== 1 ? "s" : ""})`);
    }
  } catch (err) {
    console.error("clean export failed:", err);
    setStatus("Clean export failed — check console");
  }
}

/**
 * Download the cleaned pages with the fitted vectors drawn over them, as one
 * PDF with the two as togglable layers.
 *
 * This is the proofing export: the clean page is the evidence the fit was
 * derived from, so putting them in one file at one scale is what makes the fit
 * checkable by eye — which is how every real defect in this fitter has actually
 * been found. Neither existing export can do it. SVG and DXF carry the vectors
 * with no ink to judge them against, and the clean PDF carries the ink with no
 * fit on it.
 *
 * Only pages that have both halves are exported; a page that was fitted but
 * whose cleaned raster is gone is skipped and reported rather than emitted with
 * the overlay floating on nothing.
 */
async function runOverlayExport(): Promise<void> {
  if (state.curveGraphs.size === 0) {
    setStatus("Run Vectorize first — nothing to overlay yet");
    return;
  }

  let gpuDevice: GPUDevice;
  try {
    gpuDevice = (await getGPUContext()).device;
  } catch (err) {
    setStatus("WebGPU unavailable — cannot read cleaned pages");
    console.error("getGPUContext failed:", err);
    return;
  }

  const base = (state.pdfFileName || "cleanplans").replace(/\.pdf$/i, "");
  const pages = [...state.curveGraphs.keys()].sort((a, b) => a - b);

  try {
    const rasterPages: RasterPage[] = [];
    const skipped: number[] = [];
    for (const pageNumber of pages) {
      const decomp = state.paletteDecompositions.get(pageNumber);
      if (!decomp) { skipped.push(pageNumber); continue; }
      setStatus(`Reading clean page ${pageNumber}…`);
      const graph = state.curveGraphs.get(pageNumber)!;
      rasterPages.push({
        image: await readAllLayersAsRGBA(gpuDevice, decomp),
        dpi: EXPORT_DPI,
        overlay: curveGraphToPdfOverlay(graph, {
          dpi: EXPORT_DPI,
          layers: exportLayersForPage(pageNumber, graph.layerCount),
        }),
      });
    }

    if (rasterPages.length === 0) {
      setStatus("No page has both a cleaned raster and a fit — nothing to overlay");
      return;
    }

    setStatus("Encoding overlay PDF…");
    triggerDownload(`${base}-overlay.pdf`, await encodeCleanPdf(rasterPages), "application/pdf");
    const n = rasterPages.length;
    setStatus(
      `Exported overlay PDF (${n} page${n !== 1 ? "s" : ""})` +
      (skipped.length ? ` — skipped ${skipped.join(", ")}: no cleaned raster` : ""),
    );
  } catch (err) {
    console.error("overlay export failed:", err);
    setStatus("Overlay export failed — check console");
  }
}

// ---------------------------------------------------------------------------
// Vectorize (Apply Palette → Thin → Simplify → Undash → Fit Curves)
// ---------------------------------------------------------------------------

async function runVectorize(): Promise<void> {
  if (state.isVectorizing) return;
  if (!state.editablePalette) {
    setStatus("Extract a palette first");
    return;
  }

  state.isVectorizing = true;
  const btn = document.getElementById("vectorizeBtn") as HTMLButtonElement | null;
  if (btn) { btn.disabled = true; btn.textContent = "Vectorizing…"; }

  await perf.startProfile();
  perf.note(`vectorize ${state.selectedPages.size || 1} page(s) at ${EXPORT_DPI} dpi`);

  try {
    // Each stage opens its own perf stage on entry (a stage closes the previous
    // one), so they read as a flat sequence even though runThinning calls
    // runPathConnect internally.
    await runApplyPalette();
    if (state.paletteDecompositions.size === 0) return;

    await runThinning();
    if (state.pathGraphs.size === 0) return;

    await runPathSimplify();
    if (state.simplifiedPathGraphs.size === 0) return;

    runUndash();
    if (state.undashedPathGraphs.size === 0) return;

    await runCurveFit();

    // Switch to combined view after the full pipeline — runThinning auto-selects
    // a thinned layer, so we override here at the end.
    await selectCombinedLayer();
  } finally {
    state.isVectorizing = false;
    if (btn) { btn.disabled = false; btn.textContent = "Vectorize"; }
    perf.stopProfile();
    refreshDiagnostics();
  }
}

// ---------------------------------------------------------------------------
// Layer / view-mode helpers
// ---------------------------------------------------------------------------

function setViewLayer(mode: "raw" | "denoised"): void {
  // Back to the RGBA texture path: raw and denoised pages are photographic.
  setInkSources(new Map(), null);
  const tm = getTextureManager();
  // setViewMode re-requests whatever levels are currently on screen; asking for
  // every page in the layout, as this used to, loads pages nobody is looking at.
  tm?.setSuspended(false);
  tm?.setViewMode(mode);
  state.viewerLayer = mode;
  state.activeLayerIndex = -1;
  refreshSidebar();
  requestRedraw();
  if (state.pathGraphs.size > 0) refreshGraphOverlay();
}

// ---------------------------------------------------------------------------
// Ink-layer and cleaned-page backgrounds
// ---------------------------------------------------------------------------

/**
 * Show a background built from the palette decomposition: one ink
 * (`layerIndex >= 0`) or every ink composited over white (`layerIndex < 0`,
 * the cleaned page).
 *
 * These are drawn straight from the bit-planes already sitting on the GPU.
 * There used to be a readback here — unpack the bits to a full-page RGBA
 * image on the CPU (96 MB for a 30x20" sheet at 200 DPI), cache it, then hand
 * it back to the GPU as a texture — which spent ~200 MB round-tripping 9 MB of
 * actual information, and stalled the UI on the buffer map while it did.
 *
 * The raw scan and the denoised page still go through the RGBA texture path:
 * they are photographic, with no small palette to exploit.
 */
function selectDecompositionView(layerIndex: number): void {
  const combined = layerIndex < 0;
  state.viewerLayer = combined ? "combined" : "layer";
  state.activeLayerIndex = combined ? -1 : layerIndex;

  const sources = new Map<number, InkSource>();
  let colors: Array<[number, number, number]> = [];

  for (const [pageNumber, decomp] of state.paletteDecompositions) {
    // CPU-backed decompositions (tests, batch runs) have no GPU buffer to bind.
    if (decomp.cpuWords) continue;
    if (!combined && layerIndex >= decomp.layers.length) continue;
    if (colors.length === 0) colors = decomp.layers.map(l => l.outputRgb);
    sources.set(pageNumber, {
      buffer:      decomp.buffer,
      width:       decomp.width,
      height:      decomp.height,
      rowStride:   decomp.rowStride,
      layerCount:  decomp.layers.length,
      activeLayer: combined ? -1 : layerIndex,
    });
  }

  // The pipeline maps the page background to white; matching it here keeps the
  // display identical to the PNG/PDF clean export.
  setInkSources(sources, { colors, background: [255, 255, 255] });

  // Stop the texture manager refreshing levels nobody is looking at while the
  // ink path owns the display.  Textures already resident stay put for the
  // switch back, and evictInvisible still reclaims them on scroll.  If no page
  // had a usable decomposition there is nothing to draw, so leave the texture
  // path running rather than blanking the viewer.
  getTextureManager()?.setSuspended(sources.size > 0);

  refreshSidebar();
  requestRedraw();
  if (state.pathGraphs.size > 0) refreshGraphOverlay();
}

const selectLayer = (layerIndex: number) => selectDecompositionView(layerIndex);
const selectCombinedLayer = () => selectDecompositionView(-1);

/**
 * Re-render everything in the sidebar that is derived from pipeline state: the
 * prepare-step summaries, the background radio list, the fitted-curve toggle
 * and the export buttons.  Cheap, and called from every pipeline step, so the
 * sidebar can never drift from what has actually run.
 */
function refreshSidebar(): void {
  refreshSteps();

  // The palette Edit/Reset controls only mean something once a palette exists.
  const paletteHeader = document.getElementById("paletteHeader");
  if (paletteHeader) paletteHeader.style.display = state.editablePalette ? "" : "none";

  // Update static radio inputs
  const radios = document.querySelectorAll<HTMLInputElement>(
    '#viewRadioList input[name="viewLayer"]'
  );
  for (const radio of radios) {
    const val = radio.value;
    radio.checked = (
      (val === "denoised" && state.viewerLayer === "denoised") ||
      (val === "raw"      && state.viewerLayer === "raw")
    );
  }

  // Rebuild dynamic layer entries
  const container = document.getElementById("layerRadioEntries");
  if (!container) return;
  container.innerHTML = "";

  // Ink layers from the palette decomposition.  "Cleaned page" comes first:
  // it recomposes every ink over white, which is byte-for-byte what the PNG /
  // PDF clean export writes, so it is the background you normally want under
  // the fit and the one you can hand to someone else alongside a screenshot.
  const anyDecomp = [...state.paletteDecompositions.values()][0];
  if (anyDecomp && anyDecomp.layers.length > 0) {
    const item = (value: string, checked: boolean, swatches: HTMLElement, text: string) => {
      const label = document.createElement("label");
      label.className = "view-radio-item";
      const input = document.createElement("input");
      input.type = "radio";
      input.name = "viewLayer";
      input.value = value;
      input.checked = checked;
      const name = document.createElement("span");
      name.textContent = text;
      label.append(input, swatches, name);
      container.appendChild(label);
    };

    const swatchRow = document.createElement("span");
    swatchRow.className = "view-swatch-row";
    for (const layer of anyDecomp.layers) {
      const [r, g, b] = layer.outputRgb;
      const s = document.createElement("span");
      s.className = "view-swatch view-swatch-mini";
      s.style.background = `rgb(${r},${g},${b})`;
      swatchRow.appendChild(s);
    }
    item("combined", state.viewerLayer === "combined", swatchRow, "Cleaned page");

    for (let i = 0; i < anyDecomp.layers.length; i++) {
      const [r, g, b] = anyDecomp.layers[i].outputRgb;
      const swatch = document.createElement("span");
      swatch.className = "view-swatch";
      swatch.style.background = `rgb(${r},${g},${b})`;
      item(
        `layer:${i}`,
        state.viewerLayer === "layer" && state.activeLayerIndex === i,
        swatch,
        `Ink ${i + 1}`,
      );
    }
  }

  // Fitted-curve overlay toggle — only meaningful once curves exist.
  const fitRow = document.getElementById("fittedOverlayRow");
  if (fitRow) fitRow.style.display = state.curvePathGraphs.size > 0 ? "" : "none";
  const showFitCb = document.getElementById("showFittedCurves") as HTMLInputElement | null;
  if (showFitCb) showFitCb.checked = state.showFittedCurves;

  updateExportButtons();
}

/**
 * Push the current pipeline state into the collapsing prepare steps.
 *
 * A step reports a summary only once it is genuinely settled — an empty string
 * keeps it open.  Cheap enough to call from anywhere that changes state.
 */
function refreshSteps(): void {
  const pages = [...state.selectedPages].sort((a, b) => a - b);
  let pagesValue = "";
  if (pages.length === 1) pagesValue = `page ${pages[0]}`;
  else if (pages.length > 1) {
    const contiguous = pages[pages.length - 1] - pages[0] === pages.length - 1;
    pagesValue = contiguous
      ? `pages ${pages[0]}–${pages[pages.length - 1]}`
      : `${pages.length} pages`;
  }

  // Denoise is done when every selected page has a denoised render.
  const denoised = pages.filter(p => state.denoisedPages.has(p)).length;
  const denoiseValue = pages.length > 0 && denoised === pages.length
    ? (denoised === 1 ? "1 page" : `${denoised} pages`)
    : "";

  // Crop reports the active page's rectangle in inches at the 200 DPI the
  // whole app works in — the number the user actually thinks in.
  const crop = state.cropRects.get(state.activePageNumber);
  const cropValue = crop && crop.width > 0 && crop.height > 0
    ? `${(crop.width / 200).toFixed(1)}″ × ${(crop.height / 200).toFixed(1)}″`
    : "";

  // Palette is only "done" once it has been decomposed into ink layers — an
  // extracted-but-unapplied palette is exactly the state the user still has
  // work to do in.  The ink count is the decomposition's, not the palette's:
  // several input colours can map to one output ink.
  const decomp = [...state.paletteDecompositions.values()][0];
  const inks = decomp?.layers.length ?? 0;
  const paletteValue = inks > 0 ? (inks === 1 ? "1 ink" : `${inks} inks`) : "";

  updateSteps({
    stepPages:   pagesValue,
    stepDenoise: denoiseValue,
    stepCrop:    cropValue,
    stepPalette: paletteValue,
  });
}

/** Crop mode takes over the sidebar: the phases step aside while it is on. */
function showCropSidebar(visible: boolean): void {
  for (const id of ["processSection", "vectorSection", "exportSection"]) {
    const el = document.getElementById(id);
    if (el) el.style.display = visible ? "none" : "";
  }
  const cropSection = document.getElementById("cropModeSection");
  if (cropSection) cropSection.style.display = visible ? "" : "none";
}

/** Update the crop size display in the sidebar. */
function updateCropSizeDisplay(): void {
  const el = document.getElementById("cropSizeDisplay");
  if (!el) return;

  // Show the crop rect dimensions for the active page (representative)
  const crop = state.cropRects.get(state.activePageNumber);
  if (!crop) {
    el.textContent = "";
    return;
  }

  // Convert pixels at 200 DPI to inches
  const wInches = crop.width / 200;
  const hInches = crop.height / 200;
  const isLandscape = wInches >= hInches;

  let text = `${wInches.toFixed(1)}" × ${hInches.toFixed(1)}"`;
  text += isLandscape ? " (landscape)" : " (portrait)";

  // Note common size
  const w = Math.max(wInches, hInches);
  const h = Math.min(wInches, hInches);
  if (Math.abs(w - 30) < 0.5 && Math.abs(h - 20) < 0.5) {
    text += "\n30×20 — standard foam board";
  } else {
    text += "\nCommon: 30\"×20\" foam board";
  }

  el.style.whiteSpace = "pre-line";
  el.textContent = text;
}

// ---------------------------------------------------------------------------
// Crop
// ---------------------------------------------------------------------------

/** Recompute the page layout from current state. */
function recomputeLayout(
  applyCrops: boolean,
): void {
  const sorted = [...state.selectedPages].sort((a, b) => a - b);
  const crops = applyCrops && state.cropRects.size > 0 ? state.cropRects : undefined;
  const layout = computePageLayout(sorted, state.pageSizes, 200, crops);
  updateLayout(layout);
}

/** Enter crop mode: load crop rects for all pages, show crop sidebar. */
async function enterCropMode(): Promise<void> {
  const layout = state.pageLayout;
  if (!layout || layout.pages.length === 0) return;

  state.cropMode = true;

  // Need full page dimensions for crop handle placement — use the full page sizes
  const sorted = [...state.selectedPages].sort((a, b) => a - b);
  const fullLayout = computePageLayout(sorted, state.pageSizes, 200);

  for (const page of fullLayout.pages) {
    if (state.cropRects.has(page.pageNumber)) continue;
    const rect = await loadOrInheritCropRect(page.fullWidth, page.fullHeight, page.pageNumber);
    state.cropRects.set(page.pageNumber, rect);
  }

  // Show full pages so crop handles are visible
  updateLayout(fullLayout);

  showCropSidebar(true);
  setCropEnabled(true);
  updateCropSizeDisplay();
  requestRedraw();
  setStatus("Adjust crop rectangles, then click Done Cropping");
}

/** Exit crop mode: apply crops and show cropped pages. */
function exitCropMode(): void {
  state.cropMode = false;
  setCropEnabled(false);
  showCropSidebar(false);

  // Recompute layout with crop rects applied
  recomputeLayout(true);

  requestRedraw();
  setStatus("Crop applied");
}

/** Persist crop rects — all pages if locked, otherwise just the given page. */
function persistAllCropRects(): void {
  if (!state.currentFileId) return;
  for (const [pageNum, rect] of state.cropRects) {
    saveCropRect({
      fileId: state.currentFileId,
      pageNumber: pageNum,
      ...rect,
    }).catch(() => {});
  }
}

// ---------------------------------------------------------------------------
// Auto-crop
// ---------------------------------------------------------------------------

/**
 * Auto-crop all selected pages using 50 DPI thumbnail images.
 * Uses the majority pixel color as background (no palette needed).
 */
async function runAutoCropAll(): Promise<void> {
  const tm = getTextureManager();
  if (!tm) return;

  const layout = state.pageLayout;
  if (!layout) return;

  setStatus("Auto-cropping all pages...");

  // Gather thumbnails and background colors for all pages
  const pageInputs: { image: RGBAImage; bgColor: [number, number, number] }[] = [];
  let thumbDpi = 50;
  for (const page of layout.pages) {
    setStatus(`Loading page ${page.pageNumber} thumbnail...`);
    const { image, dpi } = await tm.getThumbnailImage(page.pageNumber);
    thumbDpi = dpi;
    const bgColor = findMajorityColor(image);
    pageInputs.push({ image, bgColor });
  }

  const scale = 200 / thumbDpi;

  // Read target size from inputs (default 30×20)
  const targetWEl = document.getElementById("cropTargetWidth") as HTMLInputElement | null;
  const targetHEl = document.getElementById("cropTargetHeight") as HTMLInputElement | null;
  const targetW = parseFloat(targetWEl?.value ?? "30") || 30;
  const targetH = parseFloat(targetHEl?.value ?? "20") || 20;

  // ── Build content masks on the GPU (fall back to CPU on failure) ──────────
  let gpuMasks: PackedMask[] | null = null;
  try {
    const ctx = await getGPUContext();
    const gpuDevice = ctx.device;
    const masks: PackedMask[] = [];
    for (let i = 0; i < pageInputs.length; i++) {
      setStatus(`Building content mask (GPU) for page ${layout.pages[i].pageNumber}...`);
      const { image, bgColor } = pageInputs[i];
      const bgOklab = srgbToOklab(bgColor[0], bgColor[1], bgColor[2]);
      masks.push(await buildContentMaskGPU(gpuDevice, image, bgOklab, BG_THRESHOLD));
    }
    gpuMasks = masks;
  } catch (_e) {
    // GPU unavailable or device lost; CPU fallback below.
  }

  if (state.cropLocked) {
    // Multi-page: find single position that maximizes min margin across all pages
    setStatus("Computing optimal crop across all pages...");
    const result = gpuMasks !== null
      ? computeAutoCropFromMasks(gpuMasks, targetW, targetH, thumbDpi)
      : computeAutoCropMultiPage(pageInputs, targetW, targetH, thumbDpi);

    console.log(`[autocrop] multi-page: rect=${result.rect.x},${result.rect.y} ${result.rect.width}x${result.rect.height}, orient=${result.orientation}, bbox=${result.contentBBox.x},${result.contentBBox.y} ${result.contentBBox.width}x${result.contentBBox.height}`);

    const scaledRect = {
      x: Math.round(result.rect.x * scale),
      y: Math.round(result.rect.y * scale),
      width: Math.round(result.rect.width * scale),
      height: Math.round(result.rect.height * scale),
    };

    for (const page of layout.pages) {
      state.cropRects.set(page.pageNumber, { ...scaledRect });
    }
  } else {
    // Per-page: each page gets its own optimal crop
    for (let i = 0; i < layout.pages.length; i++) {
      const page = layout.pages[i];
      setStatus(`Auto-cropping page ${page.pageNumber}...`);
      const input = pageInputs[i];
      const result = gpuMasks !== null
        ? computeAutoCropFromMasks([gpuMasks[i]], targetW, targetH, thumbDpi)
        : computeAutoCrop(input.image, input.bgColor, targetW, targetH, thumbDpi);

      console.log(`[autocrop] page ${page.pageNumber}: img=${input.image.width}x${input.image.height} @${thumbDpi}dpi, bg=[${input.bgColor}], rect=${result.rect.x},${result.rect.y} ${result.rect.width}x${result.rect.height}, orient=${result.orientation}, bbox=${result.contentBBox.x},${result.contentBBox.y} ${result.contentBBox.width}x${result.contentBBox.height}`);

      const scaledRect = {
        x: Math.round(result.rect.x * scale),
        y: Math.round(result.rect.y * scale),
        width: Math.round(result.rect.width * scale),
        height: Math.round(result.rect.height * scale),
      };

      state.cropRects.set(page.pageNumber, scaledRect);
    }
  }

  persistAllCropRects();

  if (!state.cropMode) {
    state.cropMode = true;
    showCropSidebar(true);
    setCropEnabled(true);
  }

  updateCropSizeDisplay();
  requestRedraw();
  setStatus(`Auto-cropped ${layout.pages.length} pages`);
}

// ---------------------------------------------------------------------------
// Denoise
// ---------------------------------------------------------------------------

/** Returns true if the error looks like a WebGPU device-loss / AbortError. */
function isGPUDeviceLoss(err: unknown): boolean {
  if (err instanceof DOMException && err.name === "AbortError") return true;
  const msg = String(err);
  return msg.includes("valid external Instance") ||
         msg.includes("device lost") ||
         msg.includes("Device is lost");
}

/** Denoise all selected pages sequentially. */
async function runDenoise(): Promise<void> {
  if (state.isDenoising) return;

  const layout = state.pageLayout;
  if (!layout || layout.pages.length === 0) return;

  const tm = getTextureManager();
  if (!tm) return;

  try {
    await ensureOnnxSession();
  } catch {
    return;
  }

  state.isDenoising = true;
  setDenoiseButtonEnabled(false);

  // Always denoise all pages from PDF originals (never skip already-denoised)
  const pages = layout.pages;
  const total = pages.length;
  const failed: number[] = [];

  await perf.startProfile();
  perf.note(`denoise ${total} page(s)`);
  perf.beginStage("denoise");

  try {
    // Recreate the ONNX session every N pages so accumulated ORT GPU buffers are
    // released. Each tile inference holds an ORT GPU buffer until the session is
    // destroyed; at ~63 tiles/page the memory grows quickly without this refresh.
    const ONNX_REFRESH_PAGES = 5;

    for (let idx = 0; idx < pages.length; idx++) {
      // Periodic session refresh to flush accumulated ORT GPU buffers.
      if (idx > 0 && idx % ONNX_REFRESH_PAGES === 0) {
        console.log(`Refreshing ONNX session after page ${idx} to release GPU memory…`);
        state.onnxSession?.dispose();
        state.onnxSession = null;
        try {
          await ensureOnnxSession();
        } catch {
          break;
        }
      }

      // Yield to the event loop between pages — allows GC to reclaim CPU memory
      // and keeps the UI reponsive during long denoising runs.
      await new Promise<void>((r) => setTimeout(r, 0));

      const page = pages[idx];
      const pageNumber = page.pageNumber;
      const label = state.pageLabels[pageNumber - 1] ?? `Page ${pageNumber}`;

      setStatus(`Denoising ${label} (${idx + 1}/${total})...`);

      // Get full-resolution raw image (always denoise from raw, not previously denoised)
      const fullRawImage = await tm.getFullRawImage(pageNumber);

      let denoised: RGBAImage;
      let pageOk = false;

      // Up to two attempts: on GPU device loss, recreate the session and retry once.
      for (let attempt = 0; attempt < 2 && !pageOk; attempt++) {
        try {
          if (!state.onnxSession) {
            try {
              await ensureOnnxSession();
            } catch {
              failed.push(pageNumber);
              break;
            }
          }

          denoised = await denoise(
            fullRawImage,
            state.onnxSession!,
            undefined,
            (progress) => {
              const overall = (idx + progress) / total;
              updateDenoiseProgress(overall);
            },
          );
          pageOk = true;
        } catch (err) {
          if (isGPUDeviceLoss(err) && attempt === 0) {
            console.warn(`GPU device loss on page ${pageNumber}, recreating ONNX session…`);
            state.onnxSession?.dispose();
            state.onnxSession = null;
            continue;
          }
          console.error(`Denoise failed for page ${pageNumber}:`, err);
          failed.push(pageNumber);
          break;
        }
      }

      if (!pageOk) continue;

      // Encode to PNG blob once — shared between texture cache and IDB persistence
      const denoisedBlob = await rgbaImageToPngBlob(denoised!);

      // Update texture with full denoised image (+ caches blob + saves 100dpi overview)
      tm.updateDenoised(pageNumber, denoised!, denoisedBlob);

      // Persist full denoised image in IndexedDB (reuse pre-encoded blob)
      await saveDenoisedImage(
        state.currentFileId!,
        pageNumber,
        denoisedBlob,
        denoised!.width,
        denoised!.height,
      );
      state.denoisedPages.add(pageNumber);
    }

    onDenoiseComplete();
    refreshSidebar();
    if (failed.length === 0) {
      setStatus(`Denoised ${total} page${total !== 1 ? "s" : ""}`);
    } else {
      setStatus(`Denoised ${total - failed.length}/${total} pages — ${failed.length} failed (see console)`);
    }
  } catch (err) {
    console.error("Denoise failed:", err);
    setStatus("Denoise failed — check console");
  } finally {
    state.isDenoising = false;
    setDenoiseButtonEnabled(true);
    perf.stopProfile();
    refreshDiagnostics();
  }
}

// ---------------------------------------------------------------------------
// Initialization
// ---------------------------------------------------------------------------

function init(): void {
  // Initialize all screens
  initUpload({ onNewFile, onStoredFileSelected });

  const pageSelectCb = {
    onPageToggled,
  };

  attachPageGridClickHandler(pageSelectCb);

  // Select Pages button (in sidebar — returns to page picker from canvas)
  const selectPagesBtn = document.getElementById("selectPagesBtn");
  if (selectPagesBtn) {
    selectPagesBtn.addEventListener("click", () => {
      if (!document.getElementById("viewerScreen")?.classList.contains("page-picker-active")) {
        setPagePickerMode(true);
      }
    });
  }

  // Continue button (in page picker — proceeds to canvas/inspection)
  const continueToViewBtn = document.getElementById("continueToViewBtn");
  if (continueToViewBtn) {
    continueToViewBtn.addEventListener("click", async () => {
      if (state.selectedPages.size > 0) {
        await enterInspection();
      }
    });
  }

  // View layer radio list (event delegation).
  // When in page-picker mode, clicking a radio first enters inspection (canvas
  // view) for the selected pages, then switches to the chosen view.
  const viewRadioList = document.getElementById("viewRadioList");
  if (viewRadioList) {
    viewRadioList.addEventListener("change", async (e) => {
      const input = e.target as HTMLInputElement;
      if (input.type !== "radio" || input.name !== "viewLayer") return;
      const val = input.value;

      // If we're in page-picker mode, enter the canvas first.
      if (document.getElementById("viewerScreen")?.classList.contains("page-picker-active")) {
        if (state.selectedPages.size === 0) return;
        await enterInspection();
      }

      if (val === "raw" || val === "denoised") {
        setViewLayer(val);
      } else if (val.startsWith("layer:")) {
        selectLayer(parseInt(val.slice(6), 10));
      } else if (val === "combined") {
        selectCombinedLayer();
      }
    });
  }

  // Extract Palette button on viewer sidebar
  const viewerPaletteBtn = document.getElementById("viewerExtractPaletteBtn");
  if (viewerPaletteBtn) {
    viewerPaletteBtn.addEventListener("click", () => runProjectPalette());
  }

  // Vectorize button (Apply Palette → Thin → Simplify → Undash → Fit Curves)
  const vectorizeBtn = document.getElementById("vectorizeBtn");
  if (vectorizeBtn) {
    vectorizeBtn.addEventListener("click", () => { void runVectorize(); });
  }

  const exportSvgBtn = document.getElementById("exportSvgBtn");
  if (exportSvgBtn) exportSvgBtn.addEventListener("click", () => { void runExport("svg"); });
  const exportDxfBtn = document.getElementById("exportDxfBtn");
  if (exportDxfBtn) exportDxfBtn.addEventListener("click", () => { void runExport("dxf"); });
  // "Apply Palette" on its own: decompose + cleanup without going all the way
  // through Vectorize.  This is the step the clean-page export needs, and
  // running it alone lets a palette be checked (and the clean page exported)
  // without paying for thinning and fitting.
  const applyPaletteBtn = document.getElementById("applyPaletteBtn");
  if (applyPaletteBtn) {
    applyPaletteBtn.addEventListener("click", () => {
      void (async () => {
        const btn = applyPaletteBtn as HTMLButtonElement;
        btn.disabled = true;
        try {
          await runApplyPalette();
        } finally {
          btn.disabled = false;
        }
      })();
    });
  }
  const exportCleanPngBtn = document.getElementById("exportCleanPngBtn");
  if (exportCleanPngBtn) exportCleanPngBtn.addEventListener("click", () => { void runCleanExport("png"); });
  const exportCleanPdfBtn = document.getElementById("exportCleanPdfBtn");
  if (exportCleanPdfBtn) exportCleanPdfBtn.addEventListener("click", () => { void runCleanExport("pdf"); });
  const exportOverlayPdfBtn = document.getElementById("exportOverlayPdfBtn");
  if (exportOverlayPdfBtn) exportOverlayPdfBtn.addEventListener("click", () => { void runOverlayExport(); });

  const copyDiagnosticsBtn = document.getElementById("copyDiagnosticsBtn") as HTMLButtonElement | null;
  copyDiagnosticsBtn?.addEventListener("click", async () => {
    if (!lastDiagnosticsText) return;
    try {
      await navigator.clipboard.writeText(lastDiagnosticsText);
      copyDiagnosticsBtn.textContent = "Copied";
    } catch {
      // Insecure context, or permission refused.  Select the text instead so
      // the platform's own copy still works — better than a button that lies.
      const pre = document.getElementById("diagnosticsText");
      const details = document.getElementById("diagnosticsDetails") as HTMLDetailsElement | null;
      if (details) details.open = true;
      if (pre) {
        const range = document.createRange();
        range.selectNodeContents(pre);
        const sel = globalThis.getSelection();
        sel?.removeAllRanges();
        sel?.addRange(range);
      }
      copyDiagnosticsBtn.textContent = "Select + copy";
    }
    setTimeout(() => { copyDiagnosticsBtn.textContent = "Copy"; }, 2500);
  });

  const saveDiagnosticsBtn = document.getElementById("saveDiagnosticsBtn");
  saveDiagnosticsBtn?.addEventListener("click", () => {
    if (!lastDiagnosticsText) return;
    triggerDownload("cleanplans-diagnostics.txt", lastDiagnosticsText, "text/plain");
  });

  // Fitted-curve overlay toggle
  const showFitCb = document.getElementById("showFittedCurves") as HTMLInputElement | null;
  if (showFitCb) {
    showFitCb.addEventListener("change", () => setShowFittedCurves(showFitCb.checked));
  }

  // View layer radio list is handled above in the page-navigation block.
  // (handler intentionally omitted here — see 'viewRadioList' listener above)

  initPaletteEditor({
    onPaletteChanged(palette) {
      state.editablePalette = palette;
      persistPalette();
    },
  });

  // Palette reset button
  const resetBtn = document.getElementById("paletteResetBtn");
  if (resetBtn) {
    resetBtn.addEventListener("click", async () => {
      if (!confirm("Reset palette? Your color mappings will be lost.")) return;
      state.editablePalette = null;
      state.paletteEntries = null;
      state.bwCounts = null;
      clearPaletteEditor();
      if (state.currentFileId) {
        try { await deletePalette(state.currentFileId); } catch { /* ignore */ }
      }
      await runProjectPalette();
    });
  }

  // Denoise button — always operates on all pages
  const denoiseBtn = document.getElementById("denoiseBtn")!;
  denoiseBtn.addEventListener("click", runDenoise);

  // Crop button — enters crop mode
  const cropBtn = document.getElementById("cropBtn")!;
  cropBtn.addEventListener("click", enterCropMode);

  // Done Cropping button — exits crop mode
  const doneCroppingBtn = document.getElementById("doneCroppingBtn");
  if (doneCroppingBtn) doneCroppingBtn.addEventListener("click", exitCropMode);

  // Auto-crop button (in crop sidebar)
  const autoCropBtn = document.getElementById("autoCropBtn");
  if (autoCropBtn) autoCropBtn.addEventListener("click", runAutoCropAll);

  // Crop lock checkbox
  const cropLockCheckbox = document.getElementById("cropLockCheckbox") as HTMLInputElement | null;
  if (cropLockCheckbox) {
    cropLockCheckbox.checked = state.cropLocked;
    cropLockCheckbox.addEventListener("change", () => {
      state.cropLocked = cropLockCheckbox.checked;
    });
  }

  initViewer({
    onActivePageChanged,
    onCropChanged(_rect: CropRect) {
      // Persist all crop rects (the overlay already applied lock logic to state)
      persistAllCropRects();
      updateCropSizeDisplay();
    },
    onBackToPages() {
      if (document.getElementById("viewerScreen")?.classList.contains("page-picker-active")) {
        // Already on page picker — back goes all the way to file upload
        showScreen("upload");
      } else if (state.pdfPageCount > 1) {
        // Canvas mode — back goes to page picker
        setPagePickerMode(true);
      } else {
        showScreen("upload");
      }
    },
  });

  // Set up interactive hover fit overlay handler
  initSteps(() => refreshSidebar());
  initCursorReadout();

  // Start on upload screen
  showScreen("upload");
  setStatus("Ready — drop a PDF to begin");

  // The bundle has run.  Nothing in the app reads this; `serve_check.ts` does,
  // because every other sign of life on this page is static markup — the shell
  // renders identically whether `bundle.js` executed or was rejected by the
  // server's Content-Type, and a deploy check that cannot tell those apart is
  // checking nothing.
  (globalThis as unknown as { __cleanplansReady?: boolean }).__cleanplansReady = true;
}

// Run after DOM is ready
if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", init);
} else {
  init();
}
