/**
 * Responsiveness profiler.
 *
 * Wall-clock per stage tells you how long the work took. It tells you nothing
 * about whether the browser could draw a frame while it ran — and on a phone or
 * tablet those are completely different questions. A pipeline that takes 60 s
 * while yielding is a progress bar; one that takes 30 s without yielding is a
 * device that has stopped responding.
 *
 * So this measures being-unresponsive directly, by two instruments that fail in
 * different ways on purpose:
 *
 *   Long tasks — every uninterrupted turn of the main thread over 50 ms, from
 *     the Long Tasks API. This is the direct measure of "JavaScript is hogging
 *     the CPU", and it attributes to a stage.
 *
 *   Frame gaps — the longest interval between consecutive animation frames,
 *     from a rAF loop that runs for the whole profile. This catches what long
 *     tasks cannot: a stall inside the GPU process, a compositor blocked on a
 *     huge texture upload, or a driver taking its time. None of those are JS
 *     tasks, and all of them look to the user exactly like a freeze.
 *
 * Where the two disagree is itself the finding. Long tasks high and frame gaps
 * similar means the fix is to yield the main thread. Frame gaps far larger than
 * any long task means the main thread is fine and the GPU is the problem, and
 * yielding would achieve nothing.
 *
 * Everything here degrades quietly: an unsupported API costs its own metric and
 * nothing else.
 */

export interface StageRecord {
  name: string;
  startMs: number;
  endMs: number;
  /** Long tasks that began while this stage was running. */
  longTaskCount: number;
  longTaskTotalMs: number;
  longTaskMaxMs: number;
  /** Worst gap between animation frames observed during this stage. */
  worstFrameGapMs: number;
}

interface LongTask { start: number; duration: number }
interface FrameGap { at: number; gap: number }

/** Facts about the device that change what the numbers mean. */
export interface EnvSnapshot {
  userAgent: string;
  /** Device RAM in GB, coarsened by the browser. Chrome-only. */
  deviceMemoryGb: number | null;
  hardwareConcurrency: number | null;
  devicePixelRatio: number;
  screen: string;
  crossOriginIsolated: boolean;
  webgpu: {
    available: boolean;
    /** `GPUAdapterInfo` — the actual GPU, where the browser will say. */
    vendor?: string;
    architecture?: string;
    device?: string;
    description?: string;
    /** Limits that decide whether a full sheet fits at all. */
    maxTextureDimension2D?: number;
    maxBufferSize?: number;
    maxStorageBufferBindingSize?: number;
    maxComputeWorkgroupsPerDimension?: number;
    /** True when the adapter is a software rasteriser — 10-100x slower. */
    isFallbackAdapter?: boolean;
  };
  /** Filled in by the denoiser once it has chosen. */
  onnx?: { executionProvider: string; precision: string };
  /** Chrome-only heap figures, in MB. */
  heapUsedMb: number | null;
  heapLimitMb: number | null;
}

let profiling = false;
let t0 = 0;
const stages: StageRecord[] = [];
const longTasks: LongTask[] = [];
const frameGaps: FrameGap[] = [];
let observer: PerformanceObserver | null = null;
let rafHandle = 0;
let openStage: { name: string; startMs: number } | null = null;
let env: EnvSnapshot | null = null;
let notes: string[] = [];

const now = () => performance.now();

/** Record something worth seeing in the report (page size, page count, …). */
export function note(text: string): void {
  if (profiling) notes.push(text);
}

/** Let the denoiser tell the report which execution provider it picked. */
export function noteOnnx(executionProvider: string, precision: string): void {
  if (env) env.onnx = { executionProvider, precision };
  else pendingOnnx = { executionProvider, precision };
}
let pendingOnnx: { executionProvider: string; precision: string } | null = null;

async function snapshotEnv(): Promise<EnvSnapshot> {
  // deno-lint-ignore no-explicit-any
  const nav = navigator as any;
  // deno-lint-ignore no-explicit-any
  const mem = (performance as any).memory;
  const snap: EnvSnapshot = {
    userAgent: navigator.userAgent,
    deviceMemoryGb: typeof nav.deviceMemory === "number" ? nav.deviceMemory : null,
    hardwareConcurrency: navigator.hardwareConcurrency ?? null,
    devicePixelRatio: globalThis.devicePixelRatio ?? 1,
    screen: `${globalThis.screen?.width ?? 0}x${globalThis.screen?.height ?? 0}`,
    crossOriginIsolated: !!globalThis.crossOriginIsolated,
    webgpu: { available: false },
    heapUsedMb: mem ? Math.round(mem.usedJSHeapSize / 1e6) : null,
    heapLimitMb: mem ? Math.round(mem.jsHeapSizeLimit / 1e6) : null,
  };

  try {
    const gpu = nav.gpu as GPU | undefined;
    if (gpu) {
      const adapter = await gpu.requestAdapter();
      if (adapter) {
        // deno-lint-ignore no-explicit-any
        const a = adapter as any;
        const info = typeof a.requestAdapterInfo === "function"
          ? await a.requestAdapterInfo()
          : a.info;
        snap.webgpu = {
          available: true,
          vendor: info?.vendor || undefined,
          architecture: info?.architecture || undefined,
          device: info?.device || undefined,
          description: info?.description || undefined,
          maxTextureDimension2D: adapter.limits.maxTextureDimension2D,
          maxBufferSize: Number(adapter.limits.maxBufferSize),
          maxStorageBufferBindingSize: Number(adapter.limits.maxStorageBufferBindingSize),
          maxComputeWorkgroupsPerDimension: adapter.limits.maxComputeWorkgroupsPerDimension,
          isFallbackAdapter: a.isFallbackAdapter ?? a.info?.isFallbackAdapter ?? undefined,
        };
      }
    }
  } catch { /* leave available:false */ }

  return snap;
}

/** Begin profiling. Safe to call again; restarts from empty. */
export async function startProfile(): Promise<void> {
  stopProfile();
  stages.length = 0;
  longTasks.length = 0;
  frameGaps.length = 0;
  notes = [];
  profiling = true;
  t0 = now();

  env = await snapshotEnv();
  if (pendingOnnx) { env.onnx = pendingOnnx; pendingOnnx = null; }

  try {
    observer = new PerformanceObserver((list) => {
      for (const e of list.getEntries()) {
        longTasks.push({ start: e.startTime, duration: e.duration });
      }
    });
    observer.observe({ type: "longtask", buffered: true });
  } catch { observer = null; }

  // A frame gap is only meaningful while something is asking for frames, so
  // this loop runs for the whole profile and is the thing being starved.
  let last = now();
  const tick = () => {
    const t = now();
    const gap = t - last;
    last = t;
    // 50 ms matches the long-task threshold: three dropped frames at 60 Hz.
    //
    // Recorded at the gap's START, not at the frame that noticed it.  A frame
    // gap is only observable once it ends, and by then the stall has usually
    // carried the pipeline into the next stage — timestamping on arrival
    // credits every freeze to whatever ran after it.
    if (gap > 50) frameGaps.push({ at: t - gap, gap });
    rafHandle = requestAnimationFrame(tick);
  };
  rafHandle = requestAnimationFrame(tick);
}

/** Stop profiling. The collected report stays readable. */
export function stopProfile(): void {
  profiling = false;
  if (openStage) endStage();
  observer?.disconnect();
  observer = null;
  if (rafHandle) cancelAnimationFrame(rafHandle);
  rafHandle = 0;
}

export function isProfiling(): boolean { return profiling; }

/** Open a stage. Closes any stage still open. */
export function beginStage(name: string): void {
  if (!profiling) return;
  if (openStage) endStage();
  openStage = { name, startMs: now() };
}

/**
 * Close the open stage and attribute the blocking that happened inside it.
 *
 * Attribution is deliberately deferred to here rather than accumulated live:
 * long-task entries are delivered on a later turn of the event loop, so a
 * counter incremented as they arrive would credit each stage's worst blocking
 * to whatever ran next.
 */
export function endStage(): void {
  if (!openStage) return;
  const { name, startMs } = openStage;
  openStage = null;
  stages.push({
    name, startMs, endMs: now(),
    longTaskCount: 0, longTaskTotalMs: 0, longTaskMaxMs: 0, worstFrameGapMs: 0,
  });
}

/** Run `fn` as a named stage. */
export async function stage<T>(name: string, fn: () => Promise<T> | T): Promise<T> {
  beginStage(name);
  try {
    return await fn();
  } finally {
    endStage();
  }
}

/**
 * Attribute blocking to stages by OVERLAP, not by where the task started.
 *
 * The obvious rule — credit a task to the stage containing its start — reports
 * zero almost everywhere, because a stage boundary rarely coincides with a task
 * boundary. A stage typically begins part-way through the task that resumed the
 * awaiting caller, so its own blocking work sits in a task that started before
 * `beginStage` was ever called; and a single long synchronous run can span
 * several stages, which containment would credit entirely to the first.
 *
 * So `blockedMs` accumulates the overlapping milliseconds, which makes the
 * per-stage figures sum to the total, while the worst-single-block and the
 * count go wholly to the stage the task overlapped most — those answer "what
 * was the longest freeze, and where", which a split value would not.
 */
function attribute(): StageRecord[] {
  const out = stages.map((s) => ({ ...s }));
  const overlap = (aStart: number, aEnd: number, s: StageRecord) =>
    Math.max(0, Math.min(aEnd, s.endMs) - Math.max(aStart, s.startMs));

  for (const t of longTasks) {
    const end = t.start + t.duration;
    let best: StageRecord | null = null, bestOv = 0;
    for (const s of out) {
      const ov = overlap(t.start, end, s);
      if (ov <= 0) continue;
      s.longTaskTotalMs += ov;
      if (ov > bestOv) { bestOv = ov; best = s; }
    }
    if (best) {
      best.longTaskCount++;
      best.longTaskMaxMs = Math.max(best.longTaskMaxMs, t.duration);
    }
  }

  for (const g of frameGaps) {
    const end = g.at + g.gap;
    let best: StageRecord | null = null, bestOv = 0;
    for (const s of out) {
      const ov = overlap(g.at, end, s);
      if (ov > bestOv) { bestOv = ov; best = s; }
    }
    if (best) best.worstFrameGapMs = Math.max(best.worstFrameGapMs, g.gap);
  }
  return out;
}

export interface Report {
  env: EnvSnapshot | null;
  notes: string[];
  totalMs: number;
  stages: StageRecord[];
  longTaskCount: number;
  longTaskTotalMs: number;
  longTaskMaxMs: number;
  worstFrameGapMs: number;
  /** Fraction of wall-clock spent inside a long task. */
  blockedFraction: number;
}

export function getReport(): Report {
  const attributed = attribute();
  const totalMs = attributed.length
    ? attributed[attributed.length - 1].endMs - attributed[0].startMs
    : now() - t0;
  const longTaskTotalMs = longTasks.reduce((a, t) => a + t.duration, 0);
  return {
    env,
    notes,
    totalMs,
    stages: attributed,
    longTaskCount: longTasks.length,
    longTaskTotalMs,
    longTaskMaxMs: longTasks.reduce((a, t) => Math.max(a, t.duration), 0),
    worstFrameGapMs: frameGaps.reduce((a, g) => Math.max(a, g.gap), 0),
    blockedFraction: totalMs > 0 ? longTaskTotalMs / totalMs : 0,
  };
}

const secs = (ms: number) => `${(ms / 1000).toFixed(1)}s`;

/** The report as pasteable plain text. */
export function formatReport(): string {
  const r = getReport();
  const L: string[] = [];
  const e = r.env;

  L.push("cleanplans responsiveness report");
  L.push("=".repeat(60));
  if (e) {
    L.push(`UA           ${e.userAgent}`);
    L.push(`screen       ${e.screen} @ dpr ${e.devicePixelRatio}` +
      `   cores ${e.hardwareConcurrency ?? "?"}   RAM ${e.deviceMemoryGb ?? "?"}GB`);
    L.push(`crossOriginIsolated ${e.crossOriginIsolated}` +
      (e.heapLimitMb ? `   heap ${e.heapUsedMb}/${e.heapLimitMb}MB` : ""));
    if (e.webgpu.available) {
      const gpuName = [e.webgpu.vendor, e.webgpu.architecture, e.webgpu.device, e.webgpu.description]
        .filter(Boolean).join(" ") || "(browser withheld details)";
      L.push(`WebGPU       ${gpuName}` +
        (e.webgpu.isFallbackAdapter ? "   *** FALLBACK (software) ADAPTER ***" : ""));
      L.push(`  limits     maxTexture2D ${e.webgpu.maxTextureDimension2D}` +
        `  maxBuffer ${Math.round((e.webgpu.maxBufferSize ?? 0) / 1e6)}MB` +
        `  maxStorageBinding ${Math.round((e.webgpu.maxStorageBufferBindingSize ?? 0) / 1e6)}MB`);
    } else {
      L.push("WebGPU       NOT AVAILABLE");
    }
    if (e.onnx) L.push(`denoiser     ${e.onnx.executionProvider} / ${e.onnx.precision}`);
  }
  for (const n of r.notes) L.push(`note         ${n}`);
  L.push("");
  L.push(`total ${secs(r.totalMs)}   blocked ${secs(r.longTaskTotalMs)} ` +
    `(${(r.blockedFraction * 100).toFixed(0)}% of wall clock)`);
  L.push(`worst single block ${secs(r.longTaskMaxMs)}   ` +
    `worst frame gap ${secs(r.worstFrameGapMs)}`);
  L.push("");
  L.push(`${"stage".padEnd(34)}${"wall".padStart(8)}${"blocked".padStart(9)}` +
    `${"tasks".padStart(7)}${"worst".padStart(8)}${"frame".padStart(8)}`);
  L.push("-".repeat(74));
  for (const s of r.stages) {
    L.push(
      s.name.slice(0, 33).padEnd(34) +
      secs(s.endMs - s.startMs).padStart(8) +
      secs(s.longTaskTotalMs).padStart(9) +
      String(s.longTaskCount).padStart(7) +
      secs(s.longTaskMaxMs).padStart(8) +
      secs(s.worstFrameGapMs).padStart(8),
    );
  }
  L.push("-".repeat(74));
  L.push("");
  L.push("worst  = longest single uninterrupted main-thread task in that stage.");
  L.push("frame  = longest gap between animation frames; larger than `worst`");
  L.push("         means something outside JS (GPU, compositor) also stalled.");
  return L.join("\n");
}
