/**
 * GPU palette decomposition.
 *
 * Given an RGBA image and an EditablePalette, produces one 1-bit-per-pixel
 * monochrome layer per enabled non-background palette input.  All layers share
 * a single GPUBuffer for efficient further GPU processing.
 *
 * Buffer layout
 * ─────────────
 *   [layer 0 : rowStride × height × u32]
 *   [layer 1 : rowStride × height × u32]
 *   …
 *   [layer N : rowStride × height × u32]
 *
 *   rowStride = Math.ceil(width / 32)   (u32s per row)
 *
 * For pixel (x, y) in layer i:
 *   wordOffset = i * rowStride * height + y * rowStride + (x >>> 5)
 *   bit        = (x & 31)
 *
 * Shader algorithm (workgroup 32 × 1)
 * ─────────────────────────────────────
 * Each workgroup covers a 32-pixel-wide × 1-pixel-tall tile, which maps to
 * exactly one u32 column per row in the output buffer.
 *
 * 1. Zero workgroup-shared atomic<u32>[MAX_COLORS].
 * 2. Each thread converts its pixel to OKLab, nearest-neighbour matches
 *    against the palette cluster centres, then atomicOrs its bit (lid.x)
 *    into wg_bits[bestLayer].
 * 3. After the barrier, thread lid.x (= layerIdx) writes wg_bits[lid.x]
 *    directly to the output buffer — no inter-workgroup contention because
 *    each workgroup owns a unique (word column, row) slot.
 */

import type { RGBAImage } from "../formats/rgba_image.ts";
import type { EditablePalette } from "../color/palette_editor.ts";
import paletteDecomposeShader from "./shaders/palette_decompose.wgsl?raw";

// ---------------------------------------------------------------------------
// Public types (re-exported from the types-only module so callers that only
// need the interfaces don't transitively load the WGSL ?raw import above)
// ---------------------------------------------------------------------------

export type { PaletteLayer, PaletteDecomposition } from "./palette_decompose_types.ts";
import type { PaletteLayer, PaletteDecomposition } from "./palette_decompose_types.ts";

// ---------------------------------------------------------------------------
// Shader
// ---------------------------------------------------------------------------

const MAX_COLORS = 32;

// ---------------------------------------------------------------------------
// Pipeline cache
// ---------------------------------------------------------------------------

interface PipelineCache {
  device: GPUDevice;
  pipeline: GPUComputePipeline;
  bgl: GPUBindGroupLayout;
}

let cachedPipeline: PipelineCache | null = null;

function getOrCreatePipeline(device: GPUDevice): PipelineCache {
  // Invalidate if the cached pipeline belongs to a different (lost) device.
  if (cachedPipeline && cachedPipeline.device !== device) {
    cachedPipeline = null;
  }
  if (cachedPipeline) return cachedPipeline;

  const bgl = device.createBindGroupLayout({
    entries: [
      { binding: 0, visibility: GPUShaderStage.COMPUTE, texture: { sampleType: "float" } },
      { binding: 1, visibility: GPUShaderStage.COMPUTE, buffer:  { type: "uniform" } },
      { binding: 2, visibility: GPUShaderStage.COMPUTE, buffer:  { type: "read-only-storage" } },
      { binding: 3, visibility: GPUShaderStage.COMPUTE, buffer:  { type: "storage" } },
    ],
  });

  const module = device.createShaderModule({ code: paletteDecomposeShader });

  const pipeline = device.createComputePipeline({
    layout: device.createPipelineLayout({ bindGroupLayouts: [bgl] }),
    compute: { module, entryPoint: "main" },
  });

  cachedPipeline = { device, pipeline, bgl };
  return cachedPipeline;
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/**
 * Decompose `image` into one 1-bit-per-pixel layer per enabled
 * non-background palette input.
 *
 * At most {@link MAX_COLORS} layers are supported.  If the palette has more
 * eligible inputs than that, extras are silently ignored.
 *
 * @param device  Shared WebGPU device (from `getGPUContext()`).
 * @param image   Source image in CPU memory (typically the cropped denoised page).
 * @param palette The editable palette with input→output colour mappings.
 */
export async function decomposePalette(
  device: GPUDevice,
  image: RGBAImage,
  palette: EditablePalette,
): Promise<PaletteDecomposition> {
  const { pipeline, bgl } = getOrCreatePipeline(device);

  // ── Collect inputs for nearest-neighbour matching ──────────────────────────
  // ALL inputs (enabled or disabled) with a valid output enter the GPU palette.
  // This prevents disabled colours from causing fall-through: a pixel whose
  // nearest match is a disabled entry (e.g. orange that the user rejected) gets
  // layerSlot=255 and is discarded as background, instead of leaking into the
  // nearest *enabled* colour.
  //
  // Priority order when truncating to MAX_COLORS:
  //   0 — enabled, non-background (have real layer slots — must not be dropped)
  //   1 — enabled, background    (absorption sinks, high value)
  //   2 — disabled               (absorption sinks, lower priority)

  // Step 1: assign sequential layer indices to enabled non-background inputs.
  let layerCount = 0;
  const layerIndexOf = new Map<string, number>();   // inp.id → layer index
  for (const inp of palette.inputs) {
    if (!inp.enabled) continue;
    const out = palette.outputs.find(o => o.id === inp.outputId);
    if (out && !out.isBackground) layerIndexOf.set(inp.id, layerCount++);
  }

  // Step 2: collect all inputs that have a valid output, sorted by priority so
  // that enabled layer-slot entries are never truncated by MAX_COLORS.
  const allInputs = palette.inputs
    .filter(inp => palette.outputs.some(o => o.id === inp.outputId))
    .sort((a, b) => {
      const pa = layerIndexOf.has(a.id) ? 0 : (a.enabled ? 1 : 2);
      const pb = layerIndexOf.has(b.id) ? 0 : (b.enabled ? 1 : 2);
      return pa - pb;
    });

  // Stable layer-order metadata list (preserves original palette.inputs order).
  const eligibleInputs = palette.inputs.filter(inp => layerIndexOf.has(inp.id));

  if (layerCount === 0 || layerCount > MAX_COLORS) {
    const buffer = device.createBuffer({ size: 4, usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_SRC });
    return {
      width: image.width, height: image.height, rowStride: 0, layers: [], buffer,
      destroy() { buffer.destroy(); },
    };
  }

  const numPalette = Math.min(allInputs.length, MAX_COLORS);
  const numLayers  = layerCount;
  const rowStride  = Math.ceil(image.width / 32); // u32 words per row
  const layerWords = rowStride * image.height;
  const totalWords = numLayers * layerWords;

  // ── Input texture ───────────────────────────────────────────────────────────
  const texture = device.createTexture({
    size:   { width: image.width, height: image.height },
    format: "rgba8unorm",
    usage:  GPUTextureUsage.TEXTURE_BINDING | GPUTextureUsage.COPY_DST,
  });
  device.queue.writeTexture(
    { texture },
    image.data as unknown as Uint8ClampedArray<ArrayBuffer>,
    { bytesPerRow: image.width * 4 },
    { width: image.width, height: image.height },
  );

  // ── Uniform buffer (Dims) ────────────────────────────────────────────────────
  // 8 × u32 = 32 bytes (two 16-byte rows, required by WGSL uniform alignment).
  const dimsData = new Uint32Array([image.width, image.height, rowStride, numPalette, numLayers, 0, 0, 0]);
  const dimsBuffer = device.createBuffer({
    size:             dimsData.byteLength,
    usage:            GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST,
    mappedAtCreation: true,
  });
  new Uint32Array(dimsBuffer.getMappedRange()).set(dimsData);
  dimsBuffer.unmap();

  // ── Palette storage buffer  (u32 per entry, packed uint8: L,a,b,layerIndex) ──
  // Each u32 packs 4 bytes little-endian:
  //   bits  7:0  — L quantised  (0–255, maps [0,1])
  //   bits 15:8  — a quantised  (0–255, maps [-0.4,+0.4])
  //   bits 23:16 — b quantised  (0–255, maps [-0.4,+0.4])
  //   bits 31:24 — layer index  (0–31) or 255 = background/ignore
  const AB_RANGE = 0.4;
  const paletteData = new Uint32Array(numPalette);
  for (let i = 0; i < numPalette; i++) {
    const inp = allInputs[i];
    const [L, a, b] = inp.oklab;
    const lQ  = Math.max(0, Math.min(255, Math.round(L * 255)));
    const aQ  = Math.max(0, Math.min(255, Math.round((a + AB_RANGE) / (2 * AB_RANGE) * 255)));
    const bQ  = Math.max(0, Math.min(255, Math.round((b + AB_RANGE) / (2 * AB_RANGE) * 255)));
    const li  = layerIndexOf.get(inp.id);
    const lay = li !== undefined ? li : 255;
    paletteData[i] = (lQ) | (aQ << 8) | (bQ << 16) | (lay << 24);
  }
  const paletteBuffer = device.createBuffer({
    size:             paletteData.byteLength,
    usage:            GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_DST,
    mappedAtCreation: true,
  });
  new Uint32Array(paletteBuffer.getMappedRange()).set(paletteData);
  paletteBuffer.unmap();

  // ── Output buffer (pre-cleared to zero)  ────────────────────────────────────
  const outputBuffer = device.createBuffer({
    size:  totalWords * 4,
    usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_SRC | GPUBufferUsage.COPY_DST,
  });

  // ── Bind group ───────────────────────────────────────────────────────────────
  const bindGroup = device.createBindGroup({
    layout: bgl,
    entries: [
      { binding: 0, resource: texture.createView() },
      { binding: 1, resource: { buffer: dimsBuffer } },
      { binding: 2, resource: { buffer: paletteBuffer } },
      { binding: 3, resource: { buffer: outputBuffer } },
    ],
  });

  // ── Dispatch ─────────────────────────────────────────────────────────────────
  const encoder = device.createCommandEncoder();
  encoder.clearBuffer(outputBuffer);                        // zero before writing
  const pass = encoder.beginComputePass();
  pass.setPipeline(pipeline);
  pass.setBindGroup(0, bindGroup);
  pass.dispatchWorkgroups(
    Math.ceil(image.width / 32),  // one workgroup per u32-column
    image.height,                 // one workgroup per row
    1,
  );
  pass.end();
  device.queue.submit([encoder.finish()]);

  // Wait for GPU work to finish before releasing temp resources.
  await device.queue.onSubmittedWorkDone();

  // Clean up transient GPU objects.
  texture.destroy();
  dimsBuffer.destroy();
  paletteBuffer.destroy();

  // ── Build result metadata ────────────────────────────────────────────────────
  const layers: PaletteLayer[] = eligibleInputs.map(inp => {
    const out = palette.outputs.find(o => o.id === inp.outputId)!;
    return {
      inputId:   inp.id,
      rgb:       [...inp.rgb]       as [number, number, number],
      outputRgb: [...out.rgb]       as [number, number, number],
    };
  });

  return {
    width:     image.width,
    height:    image.height,
    rowStride,
    layers,
    buffer:    outputBuffer,
    destroy()  { outputBuffer.destroy(); },
  };
}

// ---------------------------------------------------------------------------
// CPU readback: extract one 1-bit layer as an RGBA image (black on white)
// ---------------------------------------------------------------------------

/**
 * Reads back a single 1-bit layer from the GPU buffer into an RGBAImage.
 * Pixels with bit=1 → black (0,0,0,255); bit=0 → white (255,255,255,255).
 */
export async function readLayerAsRGBA(
  device: GPUDevice,
  decomp: PaletteDecomposition,
  layerIndex: number,
): Promise<RGBAImage> {
  const { width, height, rowStride, buffer } = decomp;
  const layerWords  = rowStride * height;
  const layerBytes  = layerWords * 4;              // u32 = 4 bytes each
  const layerOffset = layerIndex * layerBytes;

  // Create a mappable staging buffer and copy the layer slice into it.
  const staging = device.createBuffer({
    size:  layerBytes,
    usage: GPUBufferUsage.COPY_DST | GPUBufferUsage.MAP_READ,
  });

  const encoder = device.createCommandEncoder();
  encoder.copyBufferToBuffer(buffer, layerOffset, staging, 0, layerBytes);
  device.queue.submit([encoder.finish()]);

  const rgba = new Uint8ClampedArray(width * height * 4);
  try {
    await staging.mapAsync(GPUMapMode.READ);
    const words = new Uint32Array(staging.getMappedRange());

    // Unpack bits → RGBA pixels.
    for (let y = 0; y < height; y++) {
      for (let x = 0; x < width; x++) {
        const wordIdx = y * rowStride + (x >>> 5);
        const bit     = (words[wordIdx] >>> (x & 31)) & 1;
        const px      = (y * width + x) * 4;
        const v       = bit ? 0 : 255;
        rgba[px]     = v;
        rgba[px + 1] = v;
        rgba[px + 2] = v;
        rgba[px + 3] = 255;
      }
    }

    staging.unmap();
  } finally {
    staging.destroy();
  }

  return { width, height, data: rgba };
}

// ---------------------------------------------------------------------------
// CPU readback: composite all 1-bit layers into a single colored RGBA image
// ---------------------------------------------------------------------------

/**
 * Reads back all layers from the GPU buffer and composites them into one
 * RGBAImage. Each pixel is colored with its layer's outputRgb; pixels that
 * belong to no layer are white.
 */
export async function readAllLayersAsRGBA(
  device: GPUDevice,
  decomp: PaletteDecomposition,
): Promise<RGBAImage> {
  const { width, height, rowStride, layers, buffer } = decomp;
  const numLayers  = layers.length;
  const layerWords = rowStride * height;
  const layerBytes = layerWords * 4; // u32 = 4 bytes each
  const totalBytes = numLayers * layerBytes;

  // Copy all layers in one GPU operation.
  const staging = device.createBuffer({
    size:  totalBytes,
    usage: GPUBufferUsage.COPY_DST | GPUBufferUsage.MAP_READ,
  });

  const encoder = device.createCommandEncoder();
  encoder.copyBufferToBuffer(buffer, 0, staging, 0, totalBytes);
  device.queue.submit([encoder.finish()]);

  // Start with a white background (255 for all channels).
  const rgba = new Uint8ClampedArray(width * height * 4).fill(255);
  try {
    await staging.mapAsync(GPUMapMode.READ);
    const words = new Uint32Array(staging.getMappedRange());

    for (let i = 0; i < numLayers; i++) {
      const [r, g, b] = layers[i].outputRgb;
      const layerWordOffset = i * layerWords;
      for (let y = 0; y < height; y++) {
        for (let x = 0; x < width; x++) {
          const wordIdx = layerWordOffset + y * rowStride + (x >>> 5);
          const bit     = (words[wordIdx] >>> (x & 31)) & 1;
          if (bit) {
            const px      = (y * width + x) * 4;
            rgba[px]     = r;
            rgba[px + 1] = g;
            rgba[px + 2] = b;
            rgba[px + 3] = 255;
          }
        }
      }
    }

    staging.unmap();
  } finally {
    staging.destroy();
  }

  return { width, height, data: rgba };
}
