/**
 * Multi-page WebGPU viewer.
 *
 * Renders multiple pages as quads in a virtual coordinate space, one draw call
 * per page.  A page is drawn one of two ways:
 *
 *   - **RGBA textures**, at three resolution levels (thumbnail / overview /
 *     full).  This is the path for the raw scan and the denoised page: they
 *     are photographic, every pixel an independent 24-bit colour, and the
 *     pre-downsampled levels are what keeps minification clean.
 *   - **Palette bit-planes** (`InkSource`), for the cleaned page and single
 *     inks.  Those are not photographs — a handful of colours, already on the
 *     GPU one bit per ink per pixel — so they are drawn straight from the
 *     decomposition buffer.  See shaders/page_ink.wgsl.
 *
 * An ink source, when set, takes priority over every texture level.
 *
 * Virtual space: all pages arranged vertically with gaps.
 * Screen mapping: screenPos = virtualPos * zoom + pan
 */

import type { GPUContext } from "./gpu_context.ts";
import type { RGBAImage } from "../formats/rgba_image.ts";
import type { LayoutResult } from "../../browser-app/ui/page_layout.ts";
import multiPageShader from "./shaders/multi_page_viewer.wgsl?raw";
import pageInkShader from "./shaders/page_ink.wgsl?raw";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

/**
 * A page drawn straight from its palette bit-planes instead of an RGBA
 * texture.  See shaders/page_ink.wgsl for why.
 */
export interface InkSource {
  /** Decomposition storage buffer: layer-major, then row-major u32 words. */
  buffer: GPUBuffer;
  /** Bit-plane extent in pixels — the cropped region, which is the page quad. */
  width: number;
  height: number;
  /** u32 words per row. */
  rowStride: number;
  /** Number of ink layers in the buffer. */
  layerCount: number;
  /** Ink to show, or -1 for all of them composited (the cleaned page). */
  activeLayer: number;
}

interface PageTextures {
  uniformBuffer: GPUBuffer;

  thumbnailTexture: GPUTexture | null;
  thumbnailBindGroupNearest: GPUBindGroup | null;
  thumbnailBindGroupLinear: GPUBindGroup | null;
  thumbnailScale: number; // thumbnail pixels / virtual pixels (e.g. 0.25)

  overviewTexture: GPUTexture | null;
  overviewBindGroupNearest: GPUBindGroup | null;
  overviewBindGroupLinear: GPUBindGroup | null;
  overviewScale: number; // overview pixels / virtual pixels (e.g. 0.5)

  fullTexture: GPUTexture | null;
  fullBindGroupNearest: GPUBindGroup | null;
  fullBindGroupLinear: GPUBindGroup | null;

  /** Set while this page is being drawn from bit-planes. */
  ink: InkSource | null;
  inkUniformBuffer: GPUBuffer | null;
  inkBindGroup: GPUBindGroup | null;
}

// ---------------------------------------------------------------------------
// Public interface
// ---------------------------------------------------------------------------

export interface MultiPageViewerHandle {
  /**
   * Upload a texture for a page.
   * overviewScale: ratio of texture pixels to virtual pixels (e.g. 0.5 for half-res).
   * For 'full' level, overviewScale should be 1.0.
   */
  uploadTexture(
    pageNumber: number,
    image: RGBAImage,
    level: "thumbnail" | "overview" | "full",
    overviewScale?: number,
  ): void;

  /**
   * Upload a pre-decoded ImageBitmap for a page.
   * Uses copyExternalImageToTexture — fully off-main-thread.
   */
  uploadBitmap(
    pageNumber: number,
    bitmap: ImageBitmap,
    level: "thumbnail" | "overview" | "full",
    overviewScale?: number,
  ): void;

  /** Evict a texture level for a page to free GPU memory. */
  evictTexture(pageNumber: number, level: "thumbnail" | "overview" | "full"): void;

  /**
   * Draw this page from palette bit-planes rather than an RGBA texture, or
   * pass null to go back to the texture path.  The ink source takes priority
   * over every texture level, so the textures can stay loaded (and stale)
   * without being seen.
   */
  setInkSource(pageNumber: number, source: InkSource | null): void;

  /** Drop every ink source — back to textures for all pages. */
  clearInkSources(): void;

  /** Ink colours, indexed by layer, plus the page background. */
  setInkPalette(colors: Array<[number, number, number]>, background: [number, number, number]): void;

  /** Check if a page has a full texture loaded. */
  hasFullTexture(pageNumber: number): boolean;

  /**
   * Render visible pages.
   *
   * @param layout - Page positions in virtual space.
   * @param visibleRange - [firstIndex, lastIndex] inclusive into layout.pages.
   * @param panX - Horizontal pan in CSS pixels.
   * @param panY - Vertical pan in CSS pixels.
   * @param zoom - Scale factor (virtual px → CSS px).
   * @param dpr - Device pixel ratio.
   */
  render(
    layout: LayoutResult,
    visibleRange: [number, number],
    panX: number,
    panY: number,
    zoom: number,
    dpr: number,
  ): void;

  /** Release all GPU resources. */
  destroy(): void;
}

// ---------------------------------------------------------------------------
// Implementation
// ---------------------------------------------------------------------------

export function createMultiPageViewer(
  canvas: HTMLCanvasElement,
  gpu: GPUContext,
): MultiPageViewerHandle {
  const { device } = gpu;

  // Configure canvas for WebGPU
  // deno-lint-ignore no-explicit-any
  const gpuCanvasCtx = (canvas as any).getContext("webgpu") as GPUCanvasContext;
  if (!gpuCanvasCtx) throw new Error("Failed to get WebGPU canvas context");

  // deno-lint-ignore no-explicit-any
  const navGpu = (navigator as any).gpu as GPU;
  const format = navGpu.getPreferredCanvasFormat();
  gpuCanvasCtx.configure({ device, format, alphaMode: "opaque" });

  let _lastConfigW = 0;
  let _lastConfigH = 0;

  // Shader + pipeline
  const shaderModule = device.createShaderModule({ code: multiPageShader });

  const bindGroupLayout = device.createBindGroupLayout({
    entries: [
      { binding: 0, visibility: GPUShaderStage.VERTEX | GPUShaderStage.FRAGMENT, buffer: { type: "uniform" } },
      { binding: 1, visibility: GPUShaderStage.FRAGMENT, texture: { sampleType: "float" } },
      { binding: 2, visibility: GPUShaderStage.FRAGMENT, sampler: { type: "filtering" } },
    ],
  });

  const pipeline = device.createRenderPipeline({
    layout: device.createPipelineLayout({ bindGroupLayouts: [bindGroupLayout] }),
    vertex: { module: shaderModule, entryPoint: "vs_main" },
    fragment: {
      module: shaderModule,
      entryPoint: "fs_main",
      targets: [{ format }],
    },
    primitive: { topology: "triangle-list" },
  });

  // ── Ink pipeline: draw a page from its palette bit-planes ────────────────
  const inkShaderModule = device.createShaderModule({ code: pageInkShader });

  const inkBindGroupLayout = device.createBindGroupLayout({
    entries: [
      { binding: 0, visibility: GPUShaderStage.VERTEX | GPUShaderStage.FRAGMENT, buffer: { type: "uniform" } },
      { binding: 1, visibility: GPUShaderStage.FRAGMENT, buffer: { type: "read-only-storage" } },
      { binding: 2, visibility: GPUShaderStage.FRAGMENT, buffer: { type: "uniform" } },
    ],
  });

  const inkPipeline = device.createRenderPipeline({
    layout: device.createPipelineLayout({ bindGroupLayouts: [inkBindGroupLayout] }),
    vertex: { module: inkShaderModule, entryPoint: "vs_main" },
    fragment: { module: inkShaderModule, entryPoint: "fs_main", targets: [{ format }] },
    primitive: { topology: "triangle-list" },
  });

  /** Shared across pages: 8 ink colours (vec4f each) then the background. */
  const MAX_INK_LAYERS = 8;
  const inkPaletteBuffer = device.createBuffer({
    size: (MAX_INK_LAYERS + 1) * 16,
    usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST,
  });
  const inkPaletteScratch = new Float32Array((MAX_INK_LAYERS + 1) * 4);
  // Default: white background, so a page is never drawn as black-on-black if
  // the palette has not been pushed yet.
  inkPaletteScratch[MAX_INK_LAYERS * 4 + 0] = 1;
  inkPaletteScratch[MAX_INK_LAYERS * 4 + 1] = 1;
  inkPaletteScratch[MAX_INK_LAYERS * 4 + 2] = 1;
  inkPaletteScratch[MAX_INK_LAYERS * 4 + 3] = 1;
  device.queue.writeBuffer(inkPaletteBuffer, 0, inkPaletteScratch);

  /** 48-byte ink uniform: see the Uniforms struct in page_ink.wgsl. */
  const inkUniformScratch = new ArrayBuffer(48);
  const inkUniformF32 = new Float32Array(inkUniformScratch);
  const inkUniformI32 = new Int32Array(inkUniformScratch);
  const inkUniformU32 = new Uint32Array(inkUniformScratch);

  // Samplers
  const nearestSampler = device.createSampler({
    magFilter: "nearest",
    minFilter: "nearest",
  });
  const linearSampler = device.createSampler({
    magFilter: "linear",
    minFilter: "linear",
  });

  // Per-page textures
  const pageTextures = new Map<number, PageTextures>();

  // Reusable scratch buffer for per-page uniform writes — avoids a new
  // Float32Array allocation per visible page per frame.
  const scratchUniforms = new Float32Array(16);

  // -------------------------------------------------------------------
  // Helpers
  // -------------------------------------------------------------------

  function createTextureFromImage(image: RGBAImage): GPUTexture {
    const tex = device.createTexture({
      size: [image.width, image.height],
      format: "rgba8unorm",
      usage: GPUTextureUsage.TEXTURE_BINDING | GPUTextureUsage.COPY_DST
        | GPUTextureUsage.RENDER_ATTACHMENT,
    });

    device.queue.writeTexture(
      { texture: tex },
      image.data as unknown as Uint8ClampedArray<ArrayBuffer>,
      { bytesPerRow: image.width * 4, rowsPerImage: image.height },
      [image.width, image.height],
    );

    return tex;
  }

  function createTextureFromBitmap(bitmap: ImageBitmap): GPUTexture {
    const tex = device.createTexture({
      size: [bitmap.width, bitmap.height],
      format: "rgba8unorm",
      usage: GPUTextureUsage.TEXTURE_BINDING | GPUTextureUsage.COPY_DST
        | GPUTextureUsage.RENDER_ATTACHMENT,
    });

    // deno-lint-ignore no-explicit-any
    (device.queue as any).copyExternalImageToTexture(
      { source: bitmap },
      { texture: tex },
      [bitmap.width, bitmap.height],
    );

    return tex;
  }

  function createBindGroups(
    tex: GPUTexture,
    ubuf: GPUBuffer,
  ): { nearest: GPUBindGroup; linear: GPUBindGroup } {
    const view = tex.createView();
    return {
      nearest: device.createBindGroup({
        layout: bindGroupLayout,
        entries: [
          { binding: 0, resource: { buffer: ubuf } },
          { binding: 1, resource: view },
          { binding: 2, resource: nearestSampler },
        ],
      }),
      linear: device.createBindGroup({
        layout: bindGroupLayout,
        entries: [
          { binding: 0, resource: { buffer: ubuf } },
          { binding: 1, resource: view },
          { binding: 2, resource: linearSampler },
        ],
      }),
    };
  }

  function getOrCreateEntry(pageNumber: number): PageTextures {
    let entry = pageTextures.get(pageNumber);
    if (!entry) {
      entry = {
        uniformBuffer: device.createBuffer({
          size: 64,
          usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST,
        }),
        thumbnailTexture: null,
        thumbnailBindGroupNearest: null,
        thumbnailBindGroupLinear: null,
        thumbnailScale: 1,
        overviewTexture: null,
        overviewBindGroupNearest: null,
        overviewBindGroupLinear: null,
        overviewScale: 1,
        fullTexture: null,
        fullBindGroupNearest: null,
        fullBindGroupLinear: null,
        ink: null,
        inkUniformBuffer: null,
        inkBindGroup: null,
      };
      pageTextures.set(pageNumber, entry);
    }
    return entry;
  }

  // -------------------------------------------------------------------
  // Public methods
  // -------------------------------------------------------------------

  function applyTextureToLevel(
    entry: PageTextures,
    tex: GPUTexture,
    bgs: { nearest: GPUBindGroup; linear: GPUBindGroup },
    level: "thumbnail" | "overview" | "full",
    scale: number,
  ): void {
    if (level === "thumbnail") {
      entry.thumbnailTexture?.destroy();
      entry.thumbnailTexture = tex;
      entry.thumbnailBindGroupNearest = bgs.nearest;
      entry.thumbnailBindGroupLinear = bgs.linear;
      entry.thumbnailScale = scale;
    } else if (level === "overview") {
      entry.overviewTexture?.destroy();
      entry.overviewTexture = tex;
      entry.overviewBindGroupNearest = bgs.nearest;
      entry.overviewBindGroupLinear = bgs.linear;
      entry.overviewScale = scale;
    } else {
      entry.fullTexture?.destroy();
      entry.fullTexture = tex;
      entry.fullBindGroupNearest = bgs.nearest;
      entry.fullBindGroupLinear = bgs.linear;
    }
  }

  function uploadTexture(
    pageNumber: number,
    image: RGBAImage,
    level: "thumbnail" | "overview" | "full",
    overviewScale = 1.0,
  ): void {
    const entry = getOrCreateEntry(pageNumber);
    const tex = createTextureFromImage(image);
    const bgs = createBindGroups(tex, entry.uniformBuffer);
    applyTextureToLevel(entry, tex, bgs, level, overviewScale);
  }

  function uploadBitmap(
    pageNumber: number,
    bitmap: ImageBitmap,
    level: "thumbnail" | "overview" | "full",
    overviewScale = 1.0,
  ): void {
    const entry = getOrCreateEntry(pageNumber);
    const tex = createTextureFromBitmap(bitmap);
    const bgs = createBindGroups(tex, entry.uniformBuffer);
    applyTextureToLevel(entry, tex, bgs, level, overviewScale);
  }

  function evictTexture(pageNumber: number, level: "thumbnail" | "overview" | "full"): void {
    const entry = pageTextures.get(pageNumber);
    if (!entry) return;
    if (level === "full" && entry.fullTexture) {
      entry.fullTexture.destroy();
      entry.fullTexture = null;
      entry.fullBindGroupNearest = null;
      entry.fullBindGroupLinear = null;
    } else if (level === "overview" && entry.overviewTexture) {
      entry.overviewTexture.destroy();
      entry.overviewTexture = null;
      entry.overviewBindGroupNearest = null;
      entry.overviewBindGroupLinear = null;
    } else if (level === "thumbnail" && entry.thumbnailTexture) {
      entry.thumbnailTexture.destroy();
      entry.thumbnailTexture = null;
      entry.thumbnailBindGroupNearest = null;
      entry.thumbnailBindGroupLinear = null;
    }
  }

  function setInkSource(pageNumber: number, source: InkSource | null): void {
    const entry = getOrCreateEntry(pageNumber);
    entry.ink = source;
    if (!source) {
      entry.inkBindGroup = null;
      return;
    }
    if (!entry.inkUniformBuffer) {
      entry.inkUniformBuffer = device.createBuffer({
        size: 48,
        usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST,
      });
    }
    entry.inkBindGroup = device.createBindGroup({
      layout: inkBindGroupLayout,
      entries: [
        { binding: 0, resource: { buffer: entry.inkUniformBuffer } },
        { binding: 1, resource: { buffer: source.buffer } },
        { binding: 2, resource: { buffer: inkPaletteBuffer } },
      ],
    });
  }

  function clearInkSources(): void {
    for (const entry of pageTextures.values()) {
      entry.ink = null;
      entry.inkBindGroup = null;
    }
  }

  function setInkPalette(
    colors: Array<[number, number, number]>,
    background: [number, number, number],
  ): void {
    inkPaletteScratch.fill(0);
    for (let i = 0; i < Math.min(colors.length, MAX_INK_LAYERS); i++) {
      const [r, g, b] = colors[i];
      inkPaletteScratch[i * 4 + 0] = r / 255;
      inkPaletteScratch[i * 4 + 1] = g / 255;
      inkPaletteScratch[i * 4 + 2] = b / 255;
      inkPaletteScratch[i * 4 + 3] = 1;
    }
    inkPaletteScratch[MAX_INK_LAYERS * 4 + 0] = background[0] / 255;
    inkPaletteScratch[MAX_INK_LAYERS * 4 + 1] = background[1] / 255;
    inkPaletteScratch[MAX_INK_LAYERS * 4 + 2] = background[2] / 255;
    inkPaletteScratch[MAX_INK_LAYERS * 4 + 3] = 1;
    device.queue.writeBuffer(inkPaletteBuffer, 0, inkPaletteScratch);
  }

  function hasFullTexture(pageNumber: number): boolean {
    const entry = pageTextures.get(pageNumber);
    return !!entry?.fullTexture;
  }

  function render(
    layout: LayoutResult,
    visibleRange: [number, number],
    panX: number,
    panY: number,
    zoom: number,
    dpr: number,
  ): void {
    const [firstIdx, lastIdx] = visibleRange;
    if (firstIdx < 0 || lastIdx < 0) return;

    const curW = canvas.width;
    const curH = canvas.height;
    if (curW === 0 || curH === 0) return;

    // Reconfigure swap chain if canvas size changed
    if (curW !== _lastConfigW || curH !== _lastConfigH) {
      gpuCanvasCtx.configure({ device, format, alphaMode: "opaque" });
      _lastConfigW = curW;
      _lastConfigH = curH;
    }

    const textureView = gpuCanvasCtx.getCurrentTexture().createView();
    const encoder = device.createCommandEncoder();
    const pass = encoder.beginRenderPass({
      colorAttachments: [{
        view: textureView,
        loadOp: "clear",
        storeOp: "store",
        clearValue: { r: 0.067, g: 0.067, b: 0.067, a: 1 }, // #111
      }],
    });

    pass.setPipeline(pipeline);

    const canvasW = curW;
    const canvasH = curH;

    // Draw each visible page
    for (let i = firstIdx; i <= lastIdx; i++) {
      const page = layout.pages[i];
      const entry = pageTextures.get(page.pageNumber);
      if (!entry) continue;

      // Screen-space rect for this page, in device pixels.
      const pageLeft = (layout.maxWidth - page.width) / 2; // centred horizontally
      const screenX = (pageLeft * zoom + panX) * dpr;
      const screenY = (page.yOffset * zoom + panY) * dpr;
      const screenW = page.width * zoom * dpr;
      const screenH = page.height * zoom * dpr;

      // Bit-planes win over every texture level: they are the source the
      // textures would have been built from, at full resolution, for a tenth
      // of the memory.
      if (entry.ink && entry.inkBindGroup && entry.inkUniformBuffer) {
        const ink = entry.ink;
        // One box-filter sample per ink pixel the fragment covers, capped so a
        // whole-document zoom-out stays a fixed cost per fragment.
        const perPixel = screenW > 0 ? ink.width / screenW : 1;
        const steps = Math.max(1, Math.min(4, Math.ceil(perPixel)));

        inkUniformF32[0] = canvasW;    inkUniformF32[1] = canvasH;
        inkUniformF32[2] = screenX;    inkUniformF32[3] = screenY;
        inkUniformF32[4] = screenW;    inkUniformF32[5] = screenH;
        inkUniformF32[6] = ink.width;  inkUniformF32[7] = ink.height;
        inkUniformU32[8] = ink.rowStride;
        inkUniformU32[9] = ink.layerCount;
        inkUniformI32[10] = ink.activeLayer;
        inkUniformU32[11] = steps;
        device.queue.writeBuffer(entry.inkUniformBuffer, 0, inkUniformScratch);

        pass.setPipeline(inkPipeline);
        pass.setBindGroup(0, entry.inkBindGroup);
        pass.draw(6);
        pass.setPipeline(pipeline); // restore for texture-path pages
        continue;
      }

      // Choose best available texture: full > overview > thumbnail
      let bindGroup: GPUBindGroup | null;
      if (entry.fullTexture && entry.fullBindGroupNearest && entry.fullBindGroupLinear) {
        bindGroup = zoom >= 1 ? entry.fullBindGroupNearest : entry.fullBindGroupLinear;
      } else if (entry.overviewTexture && entry.overviewBindGroupNearest && entry.overviewBindGroupLinear) {
        const effectiveZoom = zoom * entry.overviewScale;
        bindGroup = effectiveZoom >= 1 ? entry.overviewBindGroupNearest : entry.overviewBindGroupLinear;
      } else if (entry.thumbnailTexture && entry.thumbnailBindGroupNearest && entry.thumbnailBindGroupLinear) {
        const effectiveZoom = zoom * entry.thumbnailScale;
        bindGroup = effectiveZoom >= 1 ? entry.thumbnailBindGroupNearest : entry.thumbnailBindGroupLinear;
      } else {
        continue; // No texture available
      }

      // Get texture dimensions
      const tex = entry.fullTexture ?? entry.overviewTexture ?? entry.thumbnailTexture!;
      const texW = tex.width;
      const texH = tex.height;

      // UV crop region: map displayed quad to a sub-region of the texture
      const uvOffX = page.srcX / page.fullWidth;
      const uvOffY = page.srcY / page.fullHeight;
      const uvScaleX = page.width / page.fullWidth;
      const uvScaleY = page.height / page.fullHeight;

      // Write uniforms to this page's own buffer (reuse scratch to avoid allocation).
      scratchUniforms[0]  = canvasW;  scratchUniforms[1]  = canvasH;
      scratchUniforms[2]  = 0;        scratchUniforms[3]  = 0;
      scratchUniforms[4]  = screenX;  scratchUniforms[5]  = screenY;
      scratchUniforms[6]  = screenW;  scratchUniforms[7]  = screenH;
      scratchUniforms[8]  = texW;     scratchUniforms[9]  = texH;
      scratchUniforms[10] = uvOffX;   scratchUniforms[11] = uvOffY;
      scratchUniforms[12] = uvScaleX; scratchUniforms[13] = uvScaleY;
      scratchUniforms[14] = 0;        scratchUniforms[15] = 0;
      device.queue.writeBuffer(entry.uniformBuffer, 0, scratchUniforms);

      pass.setBindGroup(0, bindGroup);
      pass.draw(6);
    }

    pass.end();
    device.queue.submit([encoder.finish()]);
  }

  function destroy(): void {
    for (const entry of pageTextures.values()) {
      entry.thumbnailTexture?.destroy();
      entry.overviewTexture?.destroy();
      entry.fullTexture?.destroy();
      entry.uniformBuffer.destroy();
      entry.inkUniformBuffer?.destroy();
    }
    pageTextures.clear();
  }

  return {
    uploadTexture, uploadBitmap, evictTexture,
    setInkSource, clearInkSources, setInkPalette,
    hasFullTexture, render, destroy,
  };
}
