/**
 * Auto-crop algorithm for architectural plan pages.
 *
 * Detects the content bounding box by classifying pixels as background
 * or content, then positions a target-sized crop rectangle (e.g. 30×20"
 * for foam board) centered on the content.
 *
 * Multi-page strategy
 * ───────────────────
 * All pages are reduced to 1-bit-per-pixel packed masks (content = 1,
 * background = 0) and OR-merged into a single combined mask before any
 * bounding-box or position search.  Any location that has content on at
 * least one page appears as content in the combined mask, so the final
 * crop rectangle has clean background boundaries on every page.
 *
 * Packing 32 pixels per u32 lets the merge, bbox scan, and content
 * accumulation skip empty runs of 32 pixels with a single nonzero check.
 *
 * Constraints:
 * - The entire rectangle boundary must lie on background pixels.
 * - The rectangle is positioned to maximize the minimum distance
 *   from any content pixel to the boundary.
 */

import type { RGBAImage } from "../formats/rgba_image.ts";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface AutoCropResult {
  /** The computed crop rectangle in image pixels (at the input image's DPI). */
  rect: { x: number; y: number; width: number; height: number };
  /** Orientation chosen based on content aspect ratio. */
  orientation: "landscape" | "portrait";
  /** Content bounding box in image pixels. */
  contentBBox: { x: number; y: number; width: number; height: number };
}

// ---------------------------------------------------------------------------
// OKLab color distance
// ---------------------------------------------------------------------------

function srgbToLinear(c: number): number {
  const v = c / 255;
  return v <= 0.04045 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4);
}

function rgbToOklab(r: number, g: number, b: number): [number, number, number] {
  const lr = srgbToLinear(r);
  const lg = srgbToLinear(g);
  const lb = srgbToLinear(b);

  const l_ = Math.cbrt(0.4122214708 * lr + 0.5363325363 * lg + 0.0514459929 * lb);
  const m_ = Math.cbrt(0.2119034982 * lr + 0.6806995451 * lg + 0.1073969566 * lb);
  const s_ = Math.cbrt(0.0883024619 * lr + 0.2817188376 * lg + 0.6299787005 * lb);

  return [
    0.2104542553 * l_ + 0.7936177850 * m_ - 0.0040720468 * s_,
    1.9779984951 * l_ - 2.4285922050 * m_ + 0.4505937099 * s_,
    0.0259040371 * l_ + 0.7827717662 * m_ - 0.8086757660 * s_,
  ];
}

function oklabDistance(a: [number, number, number], b: [number, number, number]): number {
  const dL = a[0] - b[0];
  const da = a[1] - b[1];
  const db = a[2] - b[2];
  return Math.sqrt(dL * dL + da * da + db * db);
}

// ---------------------------------------------------------------------------
// Majority color detection
// ---------------------------------------------------------------------------

/**
 * Find the majority pixel color in an image.
 * Quantizes colors into buckets and returns the center of the most frequent bucket.
 * @param bucketSize - Quantization bucket size (default 8). Colors within this
 *   range are treated as the same color.
 */
export function findMajorityColor(
  image: RGBAImage,
  bucketSize = 8,
): [number, number, number] {
  const counts = new Map<number, { count: number; rSum: number; gSum: number; bSum: number }>();

  for (let i = 0; i < image.data.length; i += 4) {
    const r = image.data[i];
    const g = image.data[i + 1];
    const b = image.data[i + 2];
    const qr = Math.floor(r / bucketSize);
    const qg = Math.floor(g / bucketSize);
    const qb = Math.floor(b / bucketSize);
    const key = (qr << 16) | (qg << 8) | qb;

    const entry = counts.get(key);
    if (entry) {
      entry.count++;
      entry.rSum += r;
      entry.gSum += g;
      entry.bSum += b;
    } else {
      counts.set(key, { count: 1, rSum: r, gSum: g, bSum: b });
    }
  }

  let best = { count: 0, rSum: 0, gSum: 0, bSum: 0 };
  for (const entry of counts.values()) {
    if (entry.count > best.count) best = entry;
  }

  if (best.count === 0) return [255, 255, 255]; // fallback white

  return [
    Math.round(best.rSum / best.count),
    Math.round(best.gSum / best.count),
    Math.round(best.bSum / best.count),
  ];
}

// ---------------------------------------------------------------------------
// Packed 1-bpp content mask
// ---------------------------------------------------------------------------

/**
 * Threshold for classifying a pixel as background vs content.
 * This is in OKLab distance units. Typical background noise is < 0.05,
 * while even faint pencil lines are > 0.08.
 */
export const BG_THRESHOLD = 0.06;

/** 1-bit-per-pixel content mask packed into u32 words, row-major. */
export interface PackedMask {
  words: Uint32Array;
  width: number;
  height: number;
  /** u32 words per row = Math.ceil(width / 32). */
  rowStride: number;
}

/** Build a packed 1-bpp mask: bit set where pixel is non-background. */
function buildPackedMask(image: RGBAImage, bgOklab: [number, number, number]): PackedMask {
  const { width, height, data } = image;
  const rowStride = Math.ceil(width / 32);
  const words = new Uint32Array(rowStride * height);

  for (let y = 0; y < height; y++) {
    const rowBase = y * rowStride;
    for (let x = 0; x < width; x++) {
      const pidx = (y * width + x) * 4;
      const lab = rgbToOklab(data[pidx], data[pidx + 1], data[pidx + 2]);
      if (oklabDistance(lab, bgOklab) > BG_THRESHOLD) {
        words[rowBase + (x >>> 5)] |= 1 << (x & 31);
      }
    }
  }

  return { words, width, height, rowStride };
}

/**
 * OR-merge multiple packed masks into one combined mask.
 *
 * A pixel is set in the result if it is set in ANY source mask.
 * If pages have different sizes the merged mask uses the minimum
 * dimensions so the crop search stays within all pages.
 */
export function mergePackedMasks(masks: PackedMask[]): PackedMask {
  if (masks.length === 1) return masks[0];

  const width  = Math.min(...masks.map(m => m.width));
  const height = Math.min(...masks.map(m => m.height));
  const rowStride = Math.ceil(width / 32);
  const words = new Uint32Array(rowStride * height);

  for (const mask of masks) {
    for (let y = 0; y < height; y++) {
      const dBase = y * rowStride;
      const sBase = y * mask.rowStride;
      for (let w = 0; w < rowStride; w++) {
        words[dBase + w] |= mask.words[sBase + w];
      }
    }
  }

  // Clear any bits beyond width in the last word of each row that may have
  // leaked in from a source mask that was wider.
  if (width % 32 !== 0) {
    const lastBits = (1 << (width % 32)) - 1;
    for (let y = 0; y < height; y++) {
      words[(y + 1) * rowStride - 1] &= lastBits;
    }
  }

  return { words, width, height, rowStride };
}

// ---------------------------------------------------------------------------
// Bit utilities
// ---------------------------------------------------------------------------

/** Hamming weight of a 32-bit unsigned integer. */
function popcount32(n: number): number {
  n = n - ((n >>> 1) & 0x55555555);
  n = (n & 0x33333333) + ((n >>> 2) & 0x33333333);
  n = (n + (n >>> 4)) & 0x0f0f0f0f;
  return Math.imul(n, 0x01010101) >>> 24;
}

// ---------------------------------------------------------------------------
// Content detection on packed mask
// ---------------------------------------------------------------------------

/** Find the content bounding box from a packed 1-bpp mask. */
function findContentBBox(
  mask: PackedMask,
): { x: number; y: number; width: number; height: number } {
  const { words, width, height, rowStride } = mask;

  const rowCounts = new Uint32Array(height);
  const colCounts = new Uint32Array(width);

  // Single pass: accumulate row counts via popcount and column counts via
  // bit extraction, skipping empty 32-pixel blocks with the nonzero check.
  for (let y = 0; y < height; y++) {
    const base = y * rowStride;
    for (let w = 0; w < rowStride; w++) {
      const word = words[base + w];
      if (word === 0) continue;          // skip 32 pixels at once

      rowCounts[y] += popcount32(word);

      const xBase = w << 5;
      const xEnd  = Math.min(xBase + 32, width);
      for (let x = xBase; x < xEnd; x++) {
        if ((word >>> (x - xBase)) & 1) colCounts[x]++;
      }
    }
  }

  const minRowContent = Math.max(3, Math.round(width  * 0.001));
  const minColContent = Math.max(3, Math.round(height * 0.001));

  let top = 0;
  while (top < height && rowCounts[top] < minRowContent) top++;
  let bottom = height - 1;
  while (bottom > top && rowCounts[bottom] < minRowContent) bottom--;
  let left = 0;
  while (left < width && colCounts[left] < minColContent) left++;
  let right = width - 1;
  while (right > left && colCounts[right] < minColContent) right--;

  if (top > bottom || left > right) {
    return { x: 0, y: 0, width, height };
  }

  return { x: left, y: top, width: right - left + 1, height: bottom - top + 1 };
}

// ---------------------------------------------------------------------------
// Boundary constraint — prefix-sum based
// ---------------------------------------------------------------------------

interface PrefixSums {
  rowPre: Uint32Array[];
  colPre: Uint32Array[];
}

/**
 * Build row and column prefix sums directly from a packed 1-bpp mask.
 *
 * rowPre[y][x] = number of content pixels in mask[y][0..x-1]
 * colPre[x][y] = number of content pixels in mask[0..y-1][x]
 */
function buildPrefixSums(mask: PackedMask): PrefixSums {
  const { words, width, height, rowStride } = mask;

  const rowPre: Uint32Array[] = new Array(height);
  for (let y = 0; y < height; y++) {
    const rp = new Uint32Array(width + 1);
    const base = y * rowStride;
    for (let x = 0; x < width; x++) {
      rp[x + 1] = rp[x] + ((words[base + (x >>> 5)] >>> (x & 31)) & 1);
    }
    rowPre[y] = rp;
  }

  const colPre: Uint32Array[] = new Array(width);
  for (let x = 0; x < width; x++) {
    const cp = new Uint32Array(height + 1);
    const wi = x >>> 5;
    const bi = x & 31;
    for (let y = 0; y < height; y++) {
      cp[y + 1] = cp[y] + ((words[y * rowStride + wi] >>> bi) & 1);
    }
    colPre[x] = cp;
  }

  return { rowPre, colPre };
}

/** Check if all 4 edges of rect (rx, ry, rw, rh) are background-only. O(1). */
function isBoundaryClean(
  ps: PrefixSums, rx: number, ry: number, rw: number, rh: number,
): boolean {
  const { rowPre, colPre } = ps;
  if (rowPre[ry][rx + rw]       - rowPre[ry][rx]            > 0) return false;
  if (rowPre[ry + rh - 1][rx + rw] - rowPre[ry + rh - 1][rx] > 0) return false;
  if (colPre[rx][ry + rh]       - colPre[rx][ry]            > 0) return false;
  if (colPre[rx + rw - 1][ry + rh] - colPre[rx + rw - 1][ry] > 0) return false;
  return true;
}

/**
 * Compute the minimum distance from any content pixel to the nearest boundary
 * edge of the rect at (rx, ry, rw, rh).  Assumes boundary is clean.
 */
function computeMargin(
  ps: PrefixSums, rx: number, ry: number, rw: number, rh: number,
): number {
  const { rowPre, colPre } = ps;

  let topMargin = rh;
  for (let y = ry; y < ry + rh; y++) {
    if (rowPre[y][rx + rw] - rowPre[y][rx] > 0) { topMargin = y - ry; break; }
  }
  let bottomMargin = rh;
  for (let y = ry + rh - 1; y >= ry; y--) {
    if (rowPre[y][rx + rw] - rowPre[y][rx] > 0) { bottomMargin = ry + rh - 1 - y; break; }
  }
  let leftMargin = rw;
  for (let x = rx; x < rx + rw; x++) {
    if (colPre[x][ry + rh] - colPre[x][ry] > 0) { leftMargin = x - rx; break; }
  }
  let rightMargin = rw;
  for (let x = rx + rw - 1; x >= rx; x--) {
    if (colPre[x][ry + rh] - colPre[x][ry] > 0) { rightMargin = rx + rw - 1 - x; break; }
  }

  return Math.min(topMargin, bottomMargin, leftMargin, rightMargin);
}

// ---------------------------------------------------------------------------
// Optimal crop position search
// ---------------------------------------------------------------------------

/**
 * Find the rect position that maximises the content-to-boundary margin.
 *
 * Scans all valid positions within (width × height).  Among those with
 * equal best margin, picks the one closest to (initX, initY).
 */
function findMaxMarginPosition(
  ps: PrefixSums,
  width: number,
  height: number,
  initX: number,
  initY: number,
  rw: number,
  rh: number,
): [number, number] {
  const maxX = width  - rw;
  const maxY = height - rh;
  if (maxX < 0 || maxY < 0) return [Math.max(0, initX), Math.max(0, initY)];

  let bestX = initX;
  let bestY = initY;
  let bestMargin = -1;
  let bestDistSq = Infinity;

  for (let y = 0; y <= maxY; y++) {
    for (let x = 0; x <= maxX; x++) {
      if (!isBoundaryClean(ps, x, y, rw, rh)) continue;

      const margin = computeMargin(ps, x, y, rw, rh);
      const dSq = (x - initX) ** 2 + (y - initY) ** 2;
      if (margin > bestMargin || (margin === bestMargin && dSq < bestDistSq)) {
        bestMargin  = margin;
        bestX = x;
        bestY = y;
        bestDistSq = dSq;
      }
    }
  }

  return [bestX, bestY];
}

// ---------------------------------------------------------------------------
// Auto-crop computation
// ---------------------------------------------------------------------------

/**
 * Compute an auto-crop rectangle from pre-built packed content masks.
 *
 * This is the GPU-friendly entry point: build masks externally (e.g. on the
 * GPU via `buildContentMaskGPU`), then pass them here to run the position
 * search on the combined mask.  The CPU-only paths (`computeAutoCrop` and
 * `computeAutoCropMultiPage`) call this internally after building CPU masks.
 *
 * @param masks - One packed mask per page (content = 1, background = 0).
 * @param targetWidthInches - Target width in inches (e.g. 30).
 * @param targetHeightInches - Target height in inches (e.g. 20).
 * @param dpi - The DPI at which the images were rendered.
 */
export function computeAutoCropFromMasks(
  masks: PackedMask[],
  targetWidthInches: number,
  targetHeightInches: number,
  dpi: number,
): AutoCropResult {
  const combined = mergePackedMasks(masks);
  const contentBBox = findContentBBox(combined);

  const contentAspect = contentBBox.width / contentBBox.height;
  const landscape = contentAspect >= 1;
  const orientation: "landscape" | "portrait" = landscape ? "landscape" : "portrait";

  let targetW = landscape
    ? Math.round(targetWidthInches  * dpi)
    : Math.round(targetHeightInches * dpi);
  let targetH = landscape
    ? Math.round(targetHeightInches * dpi)
    : Math.round(targetWidthInches  * dpi);

  targetW = Math.min(targetW, combined.width);
  targetH = Math.min(targetH, combined.height);

  const contentCenterX = contentBBox.x + contentBBox.width  / 2;
  const contentCenterY = contentBBox.y + contentBBox.height / 2;
  const initX = Math.max(0, Math.min(combined.width  - targetW, Math.round(contentCenterX - targetW / 2)));
  const initY = Math.max(0, Math.min(combined.height - targetH, Math.round(contentCenterY - targetH / 2)));

  const ps = buildPrefixSums(combined);
  const [cropX, cropY] = findMaxMarginPosition(
    ps, combined.width, combined.height, initX, initY, targetW, targetH,
  );

  return {
    rect: { x: cropX, y: cropY, width: targetW, height: targetH },
    orientation,
    contentBBox,
  };
}

/**
 * Compute an auto-crop rectangle for a single page.
 *
 * @param image - The page image at any DPI.
 * @param bgColor - Background color as [R, G, B] (0-255).
 * @param targetWidthInches - Target width in inches (e.g. 30).
 * @param targetHeightInches - Target height in inches (e.g. 20).
 * @param dpi - The DPI at which the image was rendered (e.g. 50 or 200).
 */
export function computeAutoCrop(
  image: RGBAImage,
  bgColor: [number, number, number],
  targetWidthInches: number,
  targetHeightInches: number,
  dpi: number,
): AutoCropResult {
  return computeAutoCropMultiPage(
    [{ image, bgColor }],
    targetWidthInches,
    targetHeightInches,
    dpi,
  );
}

/**
 * Compute an auto-crop rectangle optimised across multiple pages.
 *
 * Each page is converted to a 1-bpp packed content mask (pixel set where
 * the OKLab distance from that page's background exceeds BG_THRESHOLD).
 * All masks are OR-merged into a single combined mask so that any pixel
 * that is non-background on ANY page is treated as content.
 *
 * The position search then operates on the single combined mask, which is
 * equivalent to requiring clean boundaries on every individual page while
 * being much faster than the per-page multi-structure approach.
 *
 * @param pages - Array of page images with their detected background colors.
 * @param targetWidthInches - Target width in inches (e.g. 30).
 * @param targetHeightInches - Target height in inches (e.g. 20).
 * @param dpi - The DPI at which the images were rendered.
 */
export function computeAutoCropMultiPage(
  pages: { image: RGBAImage; bgColor: [number, number, number] }[],
  targetWidthInches: number,
  targetHeightInches: number,
  dpi: number,
): AutoCropResult {
  const masks = pages.map(({ image, bgColor }) => {
    const bgOklab = rgbToOklab(bgColor[0], bgColor[1], bgColor[2]);
    return buildPackedMask(image, bgOklab);
  });
  return computeAutoCropFromMasks(masks, targetWidthInches, targetHeightInches, dpi);
}
