/**
 * Raster export: the cleaned page (denoised → cropped → palettised) as
 * lossless PNG and PDF.
 *
 * This is the hand-off between the two very different halves of the pipeline.
 * The raster stages (denoise, crop, palette, cleanup) are GPU/model heavy and
 * worth running once on capable hardware; the vector stages (thin, connect,
 * fit) are cheap and iterated on constantly. Exporting the clean page lets the
 * expensive half be done once and its result reused — or handed to someone else
 * — without re-running the denoiser or re-tuning the palette.
 *
 * Both formats are LOSSLESS, which matters because the whole point of the clean
 * page is that its colours are exact: every pixel is either the background or
 * one of the palette's output colours. Re-encoding it as JPEG would reintroduce
 * exactly the compression noise the denoiser was there to remove.
 *   - PNG: 8-bit indexed (`PLTE`) + zlib `IDAT`, or truecolour if a caller ever
 *     passes more than 256 colours.
 *   - PDF: an `/Indexed /DeviceRGB` image XObject with `/FlateDecode` — the same
 *     zlib stream PNG uses, so PDF is lossless here too. One page per image,
 *     sized in points from the render DPI so it prints at true scale.
 *
 * No dependencies: deflate comes from the platform `CompressionStream`.
 */

import type { RGBAImage } from "../formats/rgba_image.ts";

export interface RasterPage {
  image: RGBAImage;
  /** Pixels per inch of `image`, used to size the PDF page at true scale. */
  dpi: number;
  /**
   * Optional PDF content-stream fragment drawn ON TOP of the image, written in
   * the image's own PIXEL coordinates with Y down (see
   * `curveGraphToPdfOverlay`). This module installs the transform.
   *
   * Deliberately an opaque string rather than geometry: it keeps the raster
   * half from having to know what a `CurveGraph` is, and keeps the vector half
   * from having to know how a PDF is assembled. The one thing they must agree
   * on — where a pixel lands on the page — is decided here, once, from the same
   * width/height/DPI that place the image, so the overlay cannot drift out of
   * register with the ink it is drawn over.
   */
  overlay?: string;
}

// ---------------------------------------------------------------------------
// Primitives
// ---------------------------------------------------------------------------

/** zlib-wrapped deflate (RFC 1950) — what both PNG IDAT and PDF FlateDecode want. */
async function deflate(data: Uint8Array): Promise<Uint8Array> {
  const cs = new CompressionStream("deflate");
  const stream = new Blob([data as unknown as BlobPart]).stream().pipeThrough(cs);
  return new Uint8Array(await new Response(stream).arrayBuffer());
}

const CRC_TABLE = (() => {
  const t = new Uint32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xEDB88320 ^ (c >>> 1) : c >>> 1;
    t[n] = c >>> 0;
  }
  return t;
})();

function crc32(bytes: Uint8Array): number {
  let c = 0xFFFFFFFF;
  for (let i = 0; i < bytes.length; i++) c = CRC_TABLE[(c ^ bytes[i]) & 0xFF] ^ (c >>> 8);
  return (c ^ 0xFFFFFFFF) >>> 0;
}

function concat(parts: Uint8Array[]): Uint8Array {
  let n = 0;
  for (const p of parts) n += p.length;
  const out = new Uint8Array(n);
  let o = 0;
  for (const p of parts) { out.set(p, o); o += p.length; }
  return out;
}

const enc = new TextEncoder();
const ascii = (s: string) => enc.encode(s);
const be32 = (v: number) => new Uint8Array([(v >>> 24) & 255, (v >>> 16) & 255, (v >>> 8) & 255, v & 255]);

// ---------------------------------------------------------------------------
// Palette indexing
// ---------------------------------------------------------------------------

export interface IndexedImage {
  width: number;
  height: number;
  /** One palette index per pixel, row-major. */
  indices: Uint8Array;
  palette: Array<[number, number, number]>;
}

/**
 * Build an exact colour index for an already-palettised image.
 *
 * Returns null when the image holds more than 256 distinct colours, which a
 * clean page never should — it is the caller's signal to fall back to
 * truecolour rather than silently degrade the colours.
 */
export function indexColors(img: RGBAImage): IndexedImage | null {
  const { width, height, data } = img;
  const map = new Map<number, number>();
  const palette: Array<[number, number, number]> = [];
  const indices = new Uint8Array(width * height);

  for (let i = 0, p = 0; p < indices.length; p++, i += 4) {
    const key = (data[i] << 16) | (data[i + 1] << 8) | data[i + 2];
    let idx = map.get(key);
    if (idx === undefined) {
      if (palette.length >= 256) return null;
      idx = palette.length;
      palette.push([data[i], data[i + 1], data[i + 2]]);
      map.set(key, idx);
    }
    indices[p] = idx;
  }
  return { width, height, indices, palette };
}

// ---------------------------------------------------------------------------
// PNG
// ---------------------------------------------------------------------------

function pngChunk(type: string, data: Uint8Array): Uint8Array {
  const typeBytes = ascii(type);
  const body = concat([typeBytes, data]);
  return concat([be32(data.length), body, be32(crc32(body))]);
}

const PNG_SIG = new Uint8Array([0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A]);

/**
 * Encode a cleaned page as a lossless PNG: 8-bit indexed when the image has
 * ≤256 colours (which a palettised page always does — and which compresses to
 * a fraction of a truecolour encoding), truecolour RGB otherwise.
 */
export async function encodeCleanPng(img: RGBAImage): Promise<Uint8Array> {
  const idx = indexColors(img);
  const { width, height } = img;

  let ihdr: Uint8Array;
  let raw: Uint8Array;
  const chunks: Uint8Array[] = [];

  if (idx) {
    // colour type 3 = indexed
    ihdr = concat([be32(width), be32(height), new Uint8Array([8, 3, 0, 0, 0])]);
    // Each scanline is prefixed with filter byte 0 (None): the data is flat
    // index runs, which deflate already handles better than any PNG filter.
    raw = new Uint8Array(height * (width + 1));
    for (let y = 0; y < height; y++) {
      raw[y * (width + 1)] = 0;
      raw.set(idx.indices.subarray(y * width, (y + 1) * width), y * (width + 1) + 1);
    }
    const plte = new Uint8Array(idx.palette.length * 3);
    idx.palette.forEach(([r, g, b], i) => { plte[i * 3] = r; plte[i * 3 + 1] = g; plte[i * 3 + 2] = b; });
    chunks.push(pngChunk("IHDR", ihdr), pngChunk("PLTE", plte));
  } else {
    // colour type 2 = truecolour RGB
    ihdr = concat([be32(width), be32(height), new Uint8Array([8, 2, 0, 0, 0])]);
    raw = new Uint8Array(height * (width * 3 + 1));
    const stride = width * 3 + 1;
    for (let y = 0; y < height; y++) {
      raw[y * stride] = 0;
      for (let x = 0; x < width; x++) {
        const s = (y * width + x) * 4, d = y * stride + 1 + x * 3;
        raw[d] = img.data[s]; raw[d + 1] = img.data[s + 1]; raw[d + 2] = img.data[s + 2];
      }
    }
    chunks.push(pngChunk("IHDR", ihdr));
  }

  chunks.push(pngChunk("IDAT", await deflate(raw)));
  chunks.push(pngChunk("IEND", new Uint8Array(0)));
  return concat([PNG_SIG, ...chunks]);
}

// ---------------------------------------------------------------------------
// PDF
// ---------------------------------------------------------------------------

const hex = (b: number) => b.toString(16).padStart(2, "0");

/** Optional-content group names, as they appear in a viewer's layers panel. */
const OCG_SCAN = "Cleaned page";
const OCG_VECTORS = "Fitted vectors";

/**
 * Encode cleaned pages as a single lossless PDF — one image per page, sized in
 * points from each page's DPI so it prints at true physical scale.
 *
 * Images use `/FlateDecode`, the same zlib compression PNG uses, so nothing is
 * resampled or quantised on the way in. Indexed colour is used when possible;
 * that keeps a 6000x4000 mostly-white sheet small.
 *
 * When any page carries an `overlay`, the two are put in separate optional
 * content groups — "Cleaned page" and "Fitted vectors" — so a viewer can switch
 * either off. That is the whole ergonomic point of the overlay export: the
 * question it answers is "does the fit follow the ink", and being able to blink
 * the vectors on and off over the scan answers it far better than a flat
 * composite, which can only ever show you the two already on top of each other.
 */
export async function encodeCleanPdf(pages: RasterPage[]): Promise<Uint8Array> {
  if (pages.length === 0) throw new Error("encodeCleanPdf: no pages");

  const objects: Uint8Array[] = [];   // objects[i] is object number i+1
  const addObject = (body: Uint8Array): number => { objects.push(body); return objects.length; };

  // 1 = catalog, 2 = page tree; page objects follow.
  const catalogNum = 1, pagesNum = 2;
  objects.push(new Uint8Array(0), new Uint8Array(0)); // reserve 1 and 2

  // Optional content groups, allocated only when there is an overlay to toggle.
  const anyOverlay = pages.some((p) => p.overlay);
  const scanOcgNum = anyOverlay
    ? addObject(ascii(`<< /Type /OCG /Name (${OCG_SCAN}) >>`))
    : 0;
  const vectorOcgNum = anyOverlay
    ? addObject(ascii(`<< /Type /OCG /Name (${OCG_VECTORS}) >>`))
    : 0;

  const pageNums: number[] = [];
  for (const { image, dpi, overlay } of pages) {
    const idx = indexColors(image);
    const { width, height } = image;

    let colorSpace: string;
    let sampleBytes: Uint8Array;
    if (idx) {
      const lookup = idx.palette.map(([r, g, b]) => `${hex(r)}${hex(g)}${hex(b)}`).join("");
      colorSpace = `[/Indexed /DeviceRGB ${idx.palette.length - 1} <${lookup}>]`;
      sampleBytes = idx.indices;      // PDF images carry no per-row filter byte
    } else {
      colorSpace = "/DeviceRGB";
      sampleBytes = new Uint8Array(width * height * 3);
      for (let p = 0, s = 0; p < width * height; p++, s += 4) {
        sampleBytes[p * 3] = image.data[s];
        sampleBytes[p * 3 + 1] = image.data[s + 1];
        sampleBytes[p * 3 + 2] = image.data[s + 2];
      }
    }

    const compressed = await deflate(sampleBytes);
    const imgNum = addObject(concat([
      ascii(
        `<< /Type /XObject /Subtype /Image /Width ${width} /Height ${height} ` +
        `/ColorSpace ${colorSpace} /BitsPerComponent 8 /Filter /FlateDecode ` +
        `/Length ${compressed.length} >>\nstream\n`,
      ),
      compressed,
      ascii("\nendstream"),
    ]));

    // Physical size in PDF points (1/72"), so the sheet prints at true scale.
    const wPt = (width / dpi) * 72, hPt = (height / dpi) * 72;

    // The image fills the page: the unit square maps to the whole MediaBox.
    let stream = `q ${wPt.toFixed(4)} 0 0 ${hPt.toFixed(4)} 0 0 cm /Im0 Do Q\n`;
    if (anyOverlay) stream = `/OC /ocScan BDC\n${stream}EMC\n`;

    if (overlay) {
      // Pixels → points, with Y flipped: PDF's origin is bottom-left and its Y
      // grows upward, while image row 0 is the TOP.  Scaling by 72/dpi and
      // translating by the page height turns pixel (x, y) into the point on the
      // page that the image's pixel (x, y) was just drawn at — so the overlay
      // registers with the raster by construction rather than by agreement.
      const s = 72 / dpi;
      stream += `/OC /ocVec BDC\nq ${s.toFixed(6)} 0 0 ${(-s).toFixed(6)} 0 ${hPt.toFixed(4)} cm\n` +
        overlay + `Q\nEMC\n`;
    }

    const content = ascii(stream);
    const contentNum = addObject(concat([
      ascii(`<< /Length ${content.length} >>\nstream\n`), content, ascii("endstream"),
    ]));

    const properties = anyOverlay
      ? ` /Properties << /ocScan ${scanOcgNum} 0 R /ocVec ${vectorOcgNum} 0 R >>`
      : "";
    pageNums.push(addObject(ascii(
      `<< /Type /Page /Parent ${pagesNum} 0 R /MediaBox [0 0 ${wPt.toFixed(4)} ${hPt.toFixed(4)}] ` +
      `/Resources << /XObject << /Im0 ${imgNum} 0 R >>${properties} >> /Contents ${contentNum} 0 R >>`,
    )));
  }

  // Both groups start ON, so the file opens as a composite and the toggles are
  // there for whoever wants them.
  const ocProperties = anyOverlay
    ? ` /OCProperties << /OCGs [${scanOcgNum} 0 R ${vectorOcgNum} 0 R] ` +
      `/D << /Order [${scanOcgNum} 0 R ${vectorOcgNum} 0 R] ` +
      `/ON [${scanOcgNum} 0 R ${vectorOcgNum} 0 R] >> >>`
    : "";
  objects[catalogNum - 1] = ascii(
    `<< /Type /Catalog /Pages ${pagesNum} 0 R${ocProperties} >>`,
  );
  objects[pagesNum - 1] = ascii(
    `<< /Type /Pages /Kids [${pageNums.map((n) => `${n} 0 R`).join(" ")}] /Count ${pageNums.length} >>`,
  );

  // Serialise with a cross-reference table (byte offsets must be exact).
  const parts: Uint8Array[] = [];
  let offset = 0;
  const push = (b: Uint8Array) => { parts.push(b); offset += b.length; };
  const offsets: number[] = [];

  push(ascii("%PDF-1.4\n"));
  // Binary comment marks the file as containing binary data.
  push(new Uint8Array([0x25, 0xE2, 0xE3, 0xCF, 0xD3, 0x0A]));
  for (let i = 0; i < objects.length; i++) {
    offsets.push(offset);
    push(ascii(`${i + 1} 0 obj\n`));
    push(objects[i]);
    push(ascii("\nendobj\n"));
  }
  const xrefOffset = offset;
  let xref = `xref\n0 ${objects.length + 1}\n0000000000 65535 f \n`;
  for (const o of offsets) xref += `${String(o).padStart(10, "0")} 00000 n \n`;
  push(ascii(xref));
  push(ascii(`trailer\n<< /Size ${objects.length + 1} /Root ${catalogNum} 0 R >>\nstartxref\n${xrefOffset}\n%%EOF\n`));

  return concat(parts);
}
