/**
 * curve_fit_math.ts — pure geometry: line/circle fitting, window PCA, G1 continuity.
 *
 * No GPU, no PathGraph dependencies.  All functions are exported so that unit
 * tests can exercise them directly.
 */

// ---------------------------------------------------------------------------
// Primitive types (re-exported from curve_fit.ts for backwards-compat)
// ---------------------------------------------------------------------------

export interface LinePrimitive {
  type: "line";
  x1: number; y1: number;
  x2: number; y2: number;
}

export interface ArcPrimitive {
  type: "arc";
  cx: number; cy: number;
  r: number;
  /** Start angle in radians, measured CCW from +X axis. */
  startAngle: number;
  /** End angle in radians, measured CCW from +X axis. */
  endAngle: number;
  /** True if the arc sweeps counter-clockwise from startAngle to endAngle. */
  ccw: boolean;
  /**
   * Sweep angle in radians, in (0, MAX_SWEEP].  Freshly fitted arcs are
   * capped at π; G1 snapping may extend the sweep up to MAX_SWEEP (~207°).
   */
  sweep: number;
}

export interface CirclePrimitive {
  type: "circle";
  cx: number; cy: number;
  r: number;
}

export type CurvePrimitive = LinePrimitive | ArcPrimitive | CirclePrimitive;

// ---------------------------------------------------------------------------
// Fit result types
// ---------------------------------------------------------------------------

export interface LineFitResult {
  rmsError: number;
  cx: number; cy: number;     // centroid
  dirX: number; dirY: number; // unit principal direction (major axis)
}

export interface CircleFitResult {
  rmsError: number;
  cx: number; cy: number;
  r: number;
  valid: boolean;
}

// ---------------------------------------------------------------------------
// Distance helpers
// ---------------------------------------------------------------------------

export function dist2(ax: number, ay: number, bx: number, by: number): number {
  const dx = ax - bx, dy = ay - by;
  return dx * dx + dy * dy;
}

export function fitLine(xs: Float64Array, ys: Float64Array): LineFitResult {
  const n = xs.length;
  if (n < 2) return { rmsError: Infinity, cx: 0, cy: 0, dirX: 1, dirY: 0 };

  let mx = 0, my = 0;
  for (let i = 0; i < n; i++) { mx += xs[i]; my += ys[i]; }
  mx /= n; my /= n;

  let cxx = 0, cxy = 0, cyy = 0;
  for (let i = 0; i < n; i++) {
    const dx = xs[i] - mx, dy = ys[i] - my;
    cxx += dx * dx; cxy += dx * dy; cyy += dy * dy;
  }
  cxx /= n; cxy /= n; cyy /= n;

  // Closed-form eigenvector of 2×2 symmetric covariance matrix.
  const trace = cxx + cyy;
  const det   = cxx * cyy - cxy * cxy;
  const disc  = Math.sqrt(Math.max(0, trace * trace / 4 - det));
  const lam1  = trace / 2 + disc; // larger eigenvalue (most variance)

  let dirX: number, dirY: number;
  if (Math.abs(cxy) > 1e-12) {
    dirX = lam1 - cyy; dirY = cxy;
  } else {
    dirX = cxx >= cyy ? 1 : 0;
    dirY = cxx >= cyy ? 0 : 1;
  }
  const norm = Math.hypot(dirX, dirY);
  if (norm > 1e-12) { dirX /= norm; dirY /= norm; }

  // RMSE = RMS perpendicular distance.
  let sumErr2 = 0;
  for (let i = 0; i < n; i++) {
    const dx = xs[i] - mx, dy = ys[i] - my;
    const perp = dx * dirY - dy * dirX;
    sumErr2 += perp * perp;
  }
  return { rmsError: Math.sqrt(sumErr2 / n), cx: mx, cy: my, dirX, dirY };
}

// ---------------------------------------------------------------------------
// Circle fitting (algebraic least squares)
// ---------------------------------------------------------------------------

/**
 * Algebraic least-squares circle fit.
 * Solves 2xi·a + 2yi·b + c = xi²+yi² via normal equations.
 */
export function fitCircle(xs: Float64Array, ys: Float64Array): CircleFitResult {
  const n = xs.length;
  if (n < 3) return { rmsError: Infinity, cx: 0, cy: 0, r: 0, valid: false };

  let mx = 0, my = 0;
  for (let i = 0; i < n; i++) { mx += xs[i]; my += ys[i]; }
  mx /= n; my /= n;

  let A00 = 0, A01 = 0, A02 = 0, A11 = 0, A12 = 0, A22 = n;
  let b0  = 0, b1  = 0, b2  = 0;

  for (let i = 0; i < n; i++) {
    const xi = xs[i] - mx, yi = ys[i] - my;
    const zi = xi * xi + yi * yi;
    A00 += 4 * xi * xi; A01 += 4 * xi * yi; A02 += 2 * xi;
    A11 += 4 * yi * yi; A12 += 2 * yi;
    b0  += 2 * xi * zi; b1  += 2 * yi * zi; b2  += zi;
  }

  const det =
    A00 * (A11 * A22 - A12 * A12) -
    A01 * (A01 * A22 - A12 * A02) +
    A02 * (A01 * A12 - A11 * A02);

  if (Math.abs(det) < 1e-14) {
    return { rmsError: Infinity, cx: 0, cy: 0, r: 0, valid: false };
  }

  const inv = 1 / det;
  const a =
    (b0  * (A11 * A22 - A12 * A12) -
     A01 * (b1  * A22 - A12 * b2 ) +
     A02 * (b1  * A12 - A11 * b2 )) * inv;
  const b =
    (A00 * (b1  * A22 - A12 * b2 ) -
     b0  * (A01 * A22 - A12 * A02) +
     A02 * (A01 * b2  - b1  * A02)) * inv;
  const c =
    (A00 * (A11 * b2  - b1  * A12) -
     A01 * (A01 * b2  - b1  * A02) +
     b0  * (A01 * A12 - A11 * A02)) * inv;

  const cx = a + mx, cy = b + my;
  const r2 = a * a + b * b + c;
  if (r2 < 0) return { rmsError: Infinity, cx, cy, r: 0, valid: false };
  const r  = Math.sqrt(r2);

  let sumErr2 = 0;
  for (let i = 0; i < n; i++) {
    const d = Math.sqrt(dist2(xs[i], ys[i], cx, cy)) - r;
    sumErr2 += d * d;
  }
  return { rmsError: Math.sqrt(sumErr2 / n), cx, cy, r, valid: true };
}

// ---------------------------------------------------------------------------
// Primitive constructors
// ---------------------------------------------------------------------------

export function makeLinePrimitive(
  x1: number, y1: number,
  x2: number, y2: number,
): LinePrimitive {
  return { type: "line", x1, y1, x2, y2 };
}

/**
 * Returns the CCW angular span from `from` to `to`, in the range (0, 2π].
 * (Returns 2π when from === to, representing a full circle.)
 */
export function ccwSpan(from: number, to: number): number {
  let s = to - from;
  while (s <= 0) s += 2 * Math.PI;
  while (s >  2 * Math.PI) s -= 2 * Math.PI;
  return s;
}

export function makeArcPrimitive(
  fit:        CircleFitResult,
  startAngle: number,
  endAngle:   number,
  ccw:        boolean,
  sweep:      number,
): ArcPrimitive {
  return { type: "arc", cx: fit.cx, cy: fit.cy, r: fit.r,
           startAngle, endAngle, ccw, sweep };
}

// ---------------------------------------------------------------------------
// Incremental window PCA (used by computeHoverFit)
// ---------------------------------------------------------------------------

/**
 * Add the pixel stats for dense vertex `vi` to the running window accumulator.
 * `win` layout: [n, sumX, sumY, sumXX, sumXY, sumYY] (length 6).
 * `vs`  is the flat vertStats array (6 values per vertex).
 */
export function windowAdd(win: Float64Array, vs: Float64Array, vi: number): void {
  const b = vi * 6;
  win[0] += vs[b];     win[1] += vs[b + 1]; win[2] += vs[b + 2];
  win[3] += vs[b + 3]; win[4] += vs[b + 4]; win[5] += vs[b + 5];
}

/**
 * PCA principal direction, centroid, and per-pixel RMS from running window
 * moments — O(1).
 * `win` layout: [n, sumX, sumY, sumXX, sumXY, sumYY].
 * Returns the centroid (cx, cy), the unit PCA direction, and `rmsError` —
 * the RMS perpendicular distance of all pixels from the fitted PCA line.
 * `rmsError = sqrt(λ_min)` where λ_min is the minimum eigenvalue of the
 * 2×2 pixel covariance matrix.  This is independent of how pixels are
 * grouped into Voronoi cells, so it is not biased by skeleton offset.
 */
/**
 * Allocation-free variant of `dirFromWindow`: writes
 * [dirX, dirY, cx, cy, rmsError] into `out`.
 *
 * The DP calls this once per candidate window — tens of millions of times on a
 * full sheet — so returning a fresh object here is a measurable share of the
 * fit's cost.
 */
export function dirFromWindowInto(win: Float64Array, out: Float64Array): void {
  const n = win[0];
  if (n < 2) { out[0] = 1; out[1] = 0; out[2] = 0; out[3] = 0; out[4] = 0; return; }
  const cx  = win[1] / n, cy  = win[2] / n;
  const cxx = win[3] / n - cx * cx;
  const cxy = win[4] / n - cx * cy;
  const cyy = win[5] / n - cy * cy;
  const trace = cxx + cyy;
  const det   = cxx * cyy - cxy * cxy;
  const disc  = Math.sqrt(Math.max(0, trace * trace / 4 - det));
  const lam1  = trace / 2 + disc;
  const lam2  = trace / 2 - disc;
  let dirX: number, dirY: number;
  if (Math.abs(cxy) > 1e-12) {
    dirX = lam1 - cyy; dirY = cxy;
  } else {
    dirX = cxx >= cyy ? 1 : 0;
    dirY = cxx >= cyy ? 0 : 1;
  }
  const norm = Math.hypot(dirX, dirY);
  if (norm > 1e-12) { dirX /= norm; dirY /= norm; }
  out[0] = dirX; out[1] = dirY; out[2] = cx; out[3] = cy;
  out[4] = Math.sqrt(Math.max(0, lam2));
}

export function dirFromWindow(win: Float64Array): {
  dirX: number; dirY: number; cx: number; cy: number; rmsError: number;
} {
  const n = win[0];
  if (n < 2) return { dirX: 1, dirY: 0, cx: 0, cy: 0, rmsError: 0 };
  const cx  = win[1] / n, cy  = win[2] / n;
  const cxx = win[3] / n - cx * cx;
  const cxy = win[4] / n - cx * cy;
  const cyy = win[5] / n - cy * cy;
  const trace = cxx + cyy;
  const det   = cxx * cyy - cxy * cxy;
  const disc  = Math.sqrt(Math.max(0, trace * trace / 4 - det));
  const lam1  = trace / 2 + disc;
  // λ_min = mean squared perpendicular distance from the PCA line (per pixel).
  const lam2  = trace / 2 - disc;
  const rmsError = Math.sqrt(Math.max(0, lam2));
  let dirX: number, dirY: number;
  if (Math.abs(cxy) > 1e-12) {
    dirX = lam1 - cyy; dirY = cxy;
  } else {
    dirX = cxx >= cyy ? 1 : 0;
    dirY = cxx >= cyy ? 0 : 1;
  }
  const norm = Math.hypot(dirX, dirY);
  if (norm > 1e-12) { dirX /= norm; dirY /= norm; }
  return { dirX, dirY, cx, cy, rmsError };
}

/**
 * Fast line centering error from precomputed per-vertex first moments.
 *
 * For each dense vertex, measures how far its pixel cloud's centroid lies from
 * the fitted line (perpendicular distance).  Using the fitted line's own centroid
 * (cx, cy) — not the dense vertex position — as the reference ensures that vertices
 * whose pixel clouds are far from the fitted line contribute large errors even when
 * their pixels are locally symmetric around them (e.g., an arm of an L-shape).
 *
 * `vs` layout: 6 floats per vertex — [n, sumX, sumY, ...] (second moments unused here).
 * `vertEnd` is INCLUSIVE.  Bins with n < 2 are skipped.
 */
export function lineCEFast(
  vs:        Float64Array,
  vertStart: number,
  vertEnd:   number,
  cx:        number, cy: number,   // centroid of the fitted line (from dirFromWindow / fitLine)
  dirX:      number, dirY: number,
): number {
  const perpX = -dirY, perpY = dirX;
  let sumMean2 = 0, validVerts = 0;
  for (let vi = vertStart; vi <= vertEnd; vi++) {
    const b = vi * 6;
    const n = vs[b];
    if (n < 2) continue;
    // Mean signed perp of vertex i's pixel cloud from the fitted line:
    //   ((sumX_i - n_i * cx) * perpX + (sumY_i - n_i * cy) * perpY) / n_i
    // This equals (pixelMean_i - lineCentroid) · perp, which is large when
    // the vertex's pixel cloud is far from the fitted line.
    const mean = ((vs[b + 1] - n * cx) * perpX + (vs[b + 2] - n * cy) * perpY) / n;
    sumMean2 += mean * mean;
    validVerts++;
  }
  return validVerts > 0 ? Math.sqrt(sumMean2 / validVerts) : 0;
}

// ---------------------------------------------------------------------------
// G1 continuity helpers
// ---------------------------------------------------------------------------

/**
 * Compute the intersection of two infinite lines.
 * Line 0: point (x1,y1) + t·(dx0,dy0)
 * Line 1: point (x2,y2) + s·(dx1,dy1)
 * Returns null if lines are parallel.
 */
export function lineLineIntersect(
  x1: number, y1: number, dx0: number, dy0: number,
  x2: number, y2: number, dx1: number, dy1: number,
): { x: number; y: number } | null {
  const denom = dx0 * dy1 - dy0 * dx1;
  if (Math.abs(denom) < 1e-10) return null;
  const t = ((x2 - x1) * dy1 - (y2 - y1) * dx1) / denom;
  return { x: x1 + t * dx0, y: y1 + t * dy0 };
}

/**
 * Forward traversal tangent of a line or arc at its start (atStart=true) or end.
 * For a line this is always the direction start→end.
 * For an arc it is the velocity direction at the given angle (perpendicular to
 * radius, rotated 90° CCW for CCW arcs, 90° CW for CW arcs).
 */
export function primitiveTangentAt(
  p: LinePrimitive | ArcPrimitive,
  atStart: boolean,
): { tx: number; ty: number } {
  if (p.type === "line") {
    const dx = p.x2 - p.x1, dy = p.y2 - p.y1;
    const len = Math.hypot(dx, dy);
    if (len < 1e-10) return { tx: 1, ty: 0 };
    return { tx: dx / len, ty: dy / len };
  }
  const theta = atStart ? p.startAngle : p.endAngle;
  if (p.ccw) return { tx: -Math.sin(theta), ty:  Math.cos(theta) };
  else       return { tx:  Math.sin(theta), ty: -Math.cos(theta) };
}

/** Endpoint position of a line or arc at its start (atStart=true) or end. */
export function primitiveEndPoint(
  p: LinePrimitive | ArcPrimitive,
  atStart: boolean,
): { x: number; y: number } {
  if (p.type === "line") {
    return atStart ? { x: p.x1, y: p.y1 } : { x: p.x2, y: p.y2 };
  }
  const theta = atStart ? p.startAngle : p.endAngle;
  return { x: p.cx + p.r * Math.cos(theta), y: p.cy + p.r * Math.sin(theta) };
}

/**
 * For a CCW or CW arc, return the angle θ ∈ (−π, π] at which the traversal
 * tangent equals (tx, ty).
 *
 * CCW tangent at θ = (−sin θ, cos θ)  →  θ = atan2(−tx, ty)
 * CW  tangent at θ = ( sin θ,−cos θ)  →  θ = atan2( tx,−ty)
 */
/**
 * Snap an arc's endpoint (start or end) to the point on the arc circle that
 * corresponds to `theta`, and update its sweep accordingly.
 * Returns false if the resulting sweep is invalid (≤ 0 or > MAX_SWEEP) and
 * the snap should be skipped.
 */
export const MAX_SWEEP = Math.PI * 1.15; // ~207° — allows ~15° of G1 adjustment headroom

export function snapArcAngle(
  p:       ArcPrimitive,
  theta:   number,
  atStart: boolean,
): boolean {
  let spanCCW: number;
  if (atStart) {
    spanCCW = ccwSpan(theta, p.endAngle);
  } else {
    spanCCW = ccwSpan(p.startAngle, theta);
  }
  const sweep = p.ccw ? spanCCW : 2 * Math.PI - spanCCW;
  if (sweep <= 0 || sweep > MAX_SWEEP) return false;
  if (atStart) p.startAngle = theta; else p.endAngle = theta;
  p.sweep = sweep;
  return true;
}

/**
 * Parametric t values where the infinite line through (x0,y0) + t*(dx,dy)
 * intersects the circle (cx,cy,r).  Returns [] if no real intersection.
 * t=0 is (x0,y0); t=1 is (x0+dx, y0+dy).
 */
function lineCircleTs(
  x0: number, y0: number, dx: number, dy: number,
  cx: number, cy: number, r:  number,
): [number, number] | [] {
  const fx = x0 - cx, fy = y0 - cy;
  const a  = dx * dx + dy * dy;
  if (a < 1e-20) return [];
  const b    = 2 * (fx * dx + fy * dy);
  const c    = fx * fx + fy * fy - r * r;
  const disc = b * b - 4 * a * c;
  if (disc < 0) return [];
  const sq = Math.sqrt(disc);
  return [(-b - sq) / (2 * a), (-b + sq) / (2 * a)];
}

/**
 * The two intersection points of a pair of circles, or null when they do not
 * meet (separate, nested, or concentric).
 *
 * Used to join two arcs exactly: a point on BOTH circles can be adopted as the
 * shared endpoint of both arcs without moving either circle, so the joint is
 * watertight.  Averaging the two arc endpoints instead — the obvious approach —
 * leaves a residual gap whenever the circles differ, because each arc's
 * endpoint then lands on its own circle along the direction of the average.
 */
export function circleCircleIntersect(
  c0x: number, c0y: number, r0: number,
  c1x: number, c1y: number, r1: number,
): [{ x: number; y: number }, { x: number; y: number }] | null {
  const dx = c1x - c0x, dy = c1y - c0y;
  const d  = Math.hypot(dx, dy);
  if (d < 1e-9) return null;                            // concentric
  if (d > r0 + r1 || d < Math.abs(r0 - r1)) return null; // separate or nested
  const a  = (r0 * r0 - r1 * r1 + d * d) / (2 * d);
  const h2 = r0 * r0 - a * a;
  if (h2 < 0) return null;
  const h  = Math.sqrt(h2);
  const bx = c0x + a * dx / d, by = c0y + a * dy / d;
  const px = -dy / d * h,      py = dx / d * h;
  return [{ x: bx + px, y: by + py }, { x: bx - px, y: by - py }];
}

/** Max px a junction may be moved to adopt an exact circle-circle meeting. */
export const ARC_JOIN_MAX_MOVE = 3;

/**
 * Re-anchor an arc so that one endpoint lands EXACTLY on `J`, holding the
 * other endpoint — and the tangent there — completely fixed.
 *
 * This is the join primitive to reach for when two arcs must share a point and
 * no circle-circle intersection is available nearby.  The obvious alternative,
 * keeping the centre and changing the radius until the circle passes through
 * J, is a trap: it displaces the *entire* arc radially, including the far end,
 * which re-opens that end's joint.  Welding a chain left to right then carries
 * the correction forward and each arc is displaced by the running sum of every
 * upstream gap.  Measured on a real compound curve that reached 2 px of radius
 * inflation by the tenth arc, and tripled the chain's centering error (0.20 px
 * → 0.67 px) in the weld alone — the "arcs ride off the stroke" defect.
 *
 * Holding the far end pinned instead bounds the distortion by the size of the
 * single joint being closed, tapering to zero at the pinned end, so nothing
 * propagates and no previously-closed joint reopens.
 *
 * Geometry: preserving the tangent at the pinned point A means the new centre
 * must stay on the same normal ray, `C' = A + t·N` with `N = (C − A)/r`.
 * Requiring `|C' − J| = t` gives, with `w = J − A`,
 *
 *     t = |w|² / (2 · N·w)
 *
 * and `r' = t`.  The arc keeps its handedness; both end angles are recomputed
 * on the new circle.
 *
 * @param atStart which endpoint moves to J (`true` = the arc's start).
 * @returns false — arc untouched — when the solution is degenerate, flips the
 *          curvature, or distorts the arc beyond the sanity bounds below.
 */
export function reanchorArcThrough(
  p:       ArcPrimitive,
  Jx:      number,
  Jy:      number,
  atStart: boolean,
): boolean {
  // A: the endpoint that stays put (the opposite one to the one moving).
  const thetaA = atStart ? p.endAngle : p.startAngle;
  const Ax = p.cx + p.r * Math.cos(thetaA);
  const Ay = p.cy + p.r * Math.sin(thetaA);

  const Nx = (p.cx - Ax) / p.r, Ny = (p.cy - Ay) / p.r;
  const wx = Jx - Ax, wy = Jy - Ay;
  const nw = Nx * wx + Ny * wy;
  const w2 = wx * wx + wy * wy;
  // nw ≤ 0 puts J on the far side of the tangent line at A: the circle through
  // both would curve the other way.  w2 ≈ 0 means J *is* A — a zero-length arc.
  if (nw <= 1e-9 || w2 < 1e-12) return false;

  const t = w2 / (2 * nw);
  if (!(t >= 1) || !Number.isFinite(t)) return false;
  // A radius that has to change by more than 4× to reach a joint means the
  // joint is not where this arc thinks it is; leave it to the caller's fallback.
  if (t > p.r * 4 || t < p.r * 0.25) return false;

  const ncx = Ax + t * Nx, ncy = Ay + t * Ny;
  const aA = Math.atan2(Ay - ncy, Ax - ncx);
  const aJ = Math.atan2(Jy - ncy, Jx - ncx);
  const startA = atStart ? aJ : aA;
  const endA   = atStart ? aA : aJ;
  const spanCCW = ccwSpan(startA, endA);
  const sweep = p.ccw ? spanCCW : 2 * Math.PI - spanCCW;
  if (!(sweep > 0) || sweep > MAX_SWEEP) return false;
  // The joint moves by a pixel or two, so the sweep should barely change.  A
  // large change means the recomputed angles wrapped the wrong way round.
  if (Math.abs(sweep - p.sweep) > 0.35) return false;

  p.cx = ncx; p.cy = ncy; p.r = t;
  p.startAngle = startA; p.endAngle = endA; p.sweep = sweep;
  return true;
}

/**
 * Give two arcs an exactly-shared endpoint at their joint.
 *
 * Order of preference, best first:
 *   1. a point on BOTH circles (circle-circle intersection) near the natural
 *      joint — neither arc is distorted at all, only their end angles move;
 *   2. the midpoint of the two natural endpoints, reached by re-anchoring each
 *      arc about its own far end (`reanchorArcThrough`), so each absorbs half
 *      the gap and neither far end moves.
 *
 * Returns false when neither works and the caller must fall back.
 */
export function joinArcsExactly(
  a0: ArcPrimitive,
  a1: ArcPrimitive,
  maxMove = ARC_JOIN_MAX_MOVE,
): boolean {
  const E0 = primitiveEndPoint(a0, false);
  const E1 = primitiveEndPoint(a1, true);
  const mx = (E0.x + E1.x) * 0.5, my = (E0.y + E1.y) * 0.5;

  const xs = circleCircleIntersect(a0.cx, a0.cy, a0.r, a1.cx, a1.cy, a1.r);
  if (xs) {
    const d0 = Math.hypot(xs[0].x - mx, xs[0].y - my);
    const d1 = Math.hypot(xs[1].x - mx, xs[1].y - my);
    if (Math.min(d0, d1) <= maxMove) {
      const near = d0 <= d1 ? xs[0] : xs[1];
      // Snapshot: both snaps must succeed or neither may be kept.
      const s0 = { s: a0.startAngle, e: a0.endAngle, w: a0.sweep };
      if (snapArcAngle(a0, Math.atan2(near.y - a0.cy, near.x - a0.cx), false)) {
        if (snapArcAngle(a1, Math.atan2(near.y - a1.cy, near.x - a1.cx), true)) return true;
        a0.startAngle = s0.s; a0.endAngle = s0.e; a0.sweep = s0.w;
      }
    }
  }

  // Re-anchor both about their far ends, meeting in the middle.
  const b0 = { cx: a0.cx, cy: a0.cy, r: a0.r, s: a0.startAngle, e: a0.endAngle, w: a0.sweep };
  if (reanchorArcThrough(a0, mx, my, /*atStart=*/false)) {
    if (reanchorArcThrough(a1, mx, my, /*atStart=*/true)) return true;
    a0.cx = b0.cx; a0.cy = b0.cy; a0.r = b0.r;
    a0.startAngle = b0.s; a0.endAngle = b0.e; a0.sweep = b0.w;
  }
  // One side would not take it — let the other absorb the whole gap, anchored
  // on the point that already lies on the stubborn arc's circle.
  if (reanchorArcThrough(a1, E0.x, E0.y, /*atStart=*/true)) return true;
  if (reanchorArcThrough(a0, E1.x, E1.y, /*atStart=*/false)) return true;
  return false;
}

/**
 * Compute the best junction point between an infinite LINE and an ARC CIRCLE.
 * Returns the circle intersection point whose parameter t is closest to tRef,
 * or null if no intersection exists or the closest t is outside [tRef-maxDev, tRef+maxDev].
 */
export function lineArcJunction(
  lx1: number, ly1: number, lx2: number, ly2: number,
  cx: number,  cy: number,  r:  number,
  tRef: number, maxDev: number,
): { x: number; y: number; t: number } | null {
  const dx = lx2 - lx1, dy = ly2 - ly1;
  const ts = lineCircleTs(lx1, ly1, dx, dy, cx, cy, r);
  if (ts.length === 0) return null;
  const t = Math.abs(ts[0] - tRef) <= Math.abs(ts[1] - tRef) ? ts[0] : ts[1];
  if (Math.abs(t - tRef) > maxDev) return null;
  return { x: lx1 + t * dx, y: ly1 + t * dy, t };
}

/**
 * Longest gap between a line and an arc that is worth spanning with its own
 * short primitive rather than distorting one of them to close it.
 *
 * A fitted fillet's circle often stops a pixel or three short of the wall it
 * runs into.  Every way of closing that by moving something costs accuracy
 * somewhere: pull the line over and it pivots off its ink along its whole
 * length; bend the arc and its end leaves the stroke.  A short connector costs
 * one extra primitive and nothing else — both neighbours stay exactly where
 * their ink is, and the joint is watertight at both ends.
 *
 * Bounded because a large gap is not a fitting residue, it is a missing
 * feature, and inventing a long segment across one would be worse than the
 * distortion.  12 px is about two stroke widths at 200 dpi.
 */
const MAX_JOINT_CONNECTOR_PX = 12;

const bridgeable = (a: { x: number; y: number }, b: { x: number; y: number }): boolean => {
  const d = Math.hypot(b.x - a.x, b.y - a.y);
  return d > 1e-6 && d <= MAX_JOINT_CONNECTOR_PX;
};

/**
 * Where to put a line↔arc joint when the line misses the arc's circle entirely.
 *
 * The obvious fallback — drop the joint on the arc's own endpoint — moves the
 * line's end SIDEWAYS, and moving one end of a line pivots it about the other.
 * A fillet whose fitted circle stops 3 px short of the wall it runs into
 * therefore swings the whole wall off its ink: measured on a real sheet, a
 * 126 px slot wall that had been dead centre on its stroke came out 2 px off,
 * riding the stroke's edge for its whole length.  The line is the better-
 * determined of the two — it has far more ink behind it than a 17 px fillet —
 * so it is the arc that should yield.
 *
 * This projects the arc's endpoint onto the line's own axis, so the joint
 * slides ALONG the line and only trims or extends it.  The caller then
 * re-anchors the arc through that point, which keeps the arc's far end and its
 * tangent there and just bends it slightly to reach.
 *
 * `anchor` is the line's stationary end, `moving` the end being placed.
 */
function lineArcFallback(
  anchorX: number, anchorY: number,
  movingX: number, movingY: number,
  arcEnd:  { x: number; y: number },
): { x: number; y: number } {
  const dx = movingX - anchorX, dy = movingY - anchorY;
  const len = Math.hypot(dx, dy);
  if (len < 1e-9) return { x: arcEnd.x, y: arcEnd.y };
  const ux = dx / len, uy = dy / len;
  const t = (arcEnd.x - anchorX) * ux + (arcEnd.y - anchorY) * uy;
  return { x: anchorX + t * ux, y: anchorY + t * uy };
}

/**
 * Give consecutive segments a shared junction point — C0, not G1.
 *
 * Each adjacent pair is resolved by the geometry of the pair itself: line↔line
 * takes their intersection (so a real corner keeps its point), line↔arc takes
 * the line/circle intersection nearest the natural endpoint, and arc↔arc goes
 * through `joinArcsExactly`.  Positions are shared; tangents are never blended,
 * so corners stay sharp without needing a threshold to recognise them.
 *
 * There used to be a second, tangent-propagating pass here that re-fitted each
 * successor arc through the junction with its predecessor's tangent — true G1.
 * No production call site ever reached it, and enabling it on a full sheet was
 * measurably worse: smoother joints (arc→arc mismatch median 0.9° → 0.0°) paid
 * for with a 25 px hole in a contour and black p99 centering from 0.75 px to
 * 3.25 px, because the constrained refit swings the arc's far end. Cusps are
 * handled instead by `relaxCuspsToLine`, which cuts a false concavity down to a
 * short line and rolls back when the ink disagrees.
 *
 * Mutates the primitive objects in-place.
 */
export function snapAdjacentJunctions(
  segs: Array<{ wi: number; wj: number; prim: LinePrimitive | ArcPrimitive; frozen?: boolean }>,
): number[] {
  /**
   * Connectors to splice in after the loop — inserting mid-loop would shift
   * every later index out from under it.
   */
  const pending: Array<{ afterIdx: number; prim: LinePrimitive }> = [];

  // ── Junction adjustments ─────────────────────────────────────────────────
  for (let i = 0; i + 1 < segs.length; i++) {
    const p0 = segs[i].prim;
    const p1 = segs[i + 1].prim;

    const E0 = primitiveEndPoint(p0, false); // natural end of p0
    const E1 = primitiveEndPoint(p1, true);  // natural start of p1

    if (p0.type === "arc" && p1.type === "line") {
      const j = lineArcJunction(
        p1.x1, p1.y1, p1.x2, p1.y2, p0.cx, p0.cy, p0.r, 0, 2,
      );
      if (j) {
        p1.x1 = j.x; p1.y1 = j.y;
        snapArcAngle(p0, Math.atan2(j.y - p0.cy, j.x - p0.cx), false);
      } else if (bridgeable(E0, E1)) {
        pending.push({ afterIdx: i, prim: makeLinePrimitive(E0.x, E0.y, E1.x, E1.y) });
      } else {
        const J = lineArcFallback(p1.x2, p1.y2, p1.x1, p1.y1, E0);
        p1.x1 = J.x; p1.y1 = J.y;
        if (!reanchorArcThrough(p0, J.x, J.y, false)) {
          snapArcAngle(p0, Math.atan2(J.y - p0.cy, J.x - p0.cx), false);
        }
      }

    } else if (p0.type === "line" && p1.type === "arc") {
      const j = lineArcJunction(
        p0.x1, p0.y1, p0.x2, p0.y2, p1.cx, p1.cy, p1.r, 1, 2,
      );
      if (j) {
        p0.x2 = j.x; p0.y2 = j.y;
        snapArcAngle(p1, Math.atan2(j.y - p1.cy, j.x - p1.cx), true);
      } else if (bridgeable(E0, E1)) {
        pending.push({ afterIdx: i, prim: makeLinePrimitive(E0.x, E0.y, E1.x, E1.y) });
      } else {
        const J = lineArcFallback(p0.x1, p0.y1, p0.x2, p0.y2, E1);
        p0.x2 = J.x; p0.y2 = J.y;
        if (!reanchorArcThrough(p1, J.x, J.y, true)) {
          snapArcAngle(p1, Math.atan2(J.y - p1.cy, J.x - p1.cx), true);
        }
      }

    } else if (p0.type === "line" && p1.type === "line") {
      const dx0 = (p0 as LinePrimitive).x2 - (p0 as LinePrimitive).x1;
      const dy0 = (p0 as LinePrimitive).y2 - (p0 as LinePrimitive).y1;
      const dx1 = (p1 as LinePrimitive).x2 - (p1 as LinePrimitive).x1;
      const dy1 = (p1 as LinePrimitive).y2 - (p1 as LinePrimitive).y1;
      const len0 = Math.hypot(dx0, dy0), len1 = Math.hypot(dx1, dy1);
      let Jx: number, Jy: number;
      // Cross product magnitude ≈ len0·len1·|sin(angle)|.
      // Skip intersection when segments are nearly parallel: the intersection
      // would be very far away and numerically unreliable.  Also skip when
      // either segment is short: short PCA directions are unreliable.
      const cross = Math.abs(dx0 * dy1 - dy0 * dx1);
      const MIN_SIN = 0.035; // ~2° — guard against near-parallel lines
      const ix = (cross >= MIN_SIN * len0 * len1)
        ? lineLineIntersect(
            (p0 as LinePrimitive).x1, (p0 as LinePrimitive).y1, dx0, dy0,
            (p1 as LinePrimitive).x1, (p1 as LinePrimitive).y1, dx1, dy1,
          )
        : null;
      // Use the intersection only if it is near the natural gap between the
      // two endpoints.  For a clean corner the intersection lies within a few
      // pixels of where the segments naturally meet; for nearly-parallel
      // segments it can be hundreds of pixels away regardless of segment
      // length.  Basing the limit on gapDist (the natural endpoint separation)
      // rather than on segment length prevents long nearly-parallel segments
      // from pulling the junction far off the path.
      //   maxMove = 3 × gapDist + 10 px  (the floor handles gapDist ≈ 0).
      const gapDist = Math.hypot(E1.x - E0.x, E1.y - E0.y);
      const maxMove = 3.0 * gapDist + 10.0;
      if (ix !== null &&
          Math.hypot(ix.x - E0.x, ix.y - E0.y) <= maxMove &&
          Math.hypot(ix.x - E1.x, ix.y - E1.y) <= maxMove) {
        // The intersection lies on both infinite lines, so each endpoint only
        // slides along its own axis and neither direction changes.  This branch
        // is already safe for a frozen segment and needs no special case.
        Jx = ix.x; Jy = ix.y;
      } else {
        // The midpoint is not on either line, so it rotates both.  Where
        // exactly one side is frozen, put the joint on the frozen line's own
        // axis instead: it then slides along itself and only the unfrozen line
        // turns, which is the side with less evidence behind it.
        const mx = (E0.x + E1.x) * 0.5, my = (E0.y + E1.y) * 0.5;
        const f0 = segs[i].frozen === true, f1 = segs[i + 1].frozen === true;
        const onAxis = (p: LinePrimitive, dx: number, dy: number, len: number) => {
          const t = ((mx - p.x1) * dx + (my - p.y1) * dy) / (len * len);
          return { x: p.x1 + t * dx, y: p.y1 + t * dy };
        };
        let J = { x: mx, y: my };
        if (f0 && !f1 && len0 > 1e-9)      J = onAxis(p0 as LinePrimitive, dx0, dy0, len0);
        else if (f1 && !f0 && len1 > 1e-9) J = onAxis(p1 as LinePrimitive, dx1, dy1, len1);
        Jx = J.x; Jy = J.y;
      }
      (p0 as LinePrimitive).x2 = Jx; (p0 as LinePrimitive).y2 = Jy;
      (p1 as LinePrimitive).x1 = Jx; (p1 as LinePrimitive).y1 = Jy;

    } else {
      // Arc → Arc.  Prefer a genuine circle-circle intersection: it lies on
      // both circles, so snapping each arc to it closes the joint exactly.
      // Falling back to the endpoint average (the previous behaviour) leaves a
      // gap of up to ~1 px whenever the radii differ — which is precisely the
      // compound-curve case — and CAM reads any gap as an open contour.
      const a0 = p0 as ArcPrimitive, a1 = p1 as ArcPrimitive;
      if (!joinArcsExactly(a0, a1)) {
        // Neither an exact meeting point nor a re-anchor was available: snap
        // each arc's angle toward the midpoint.  That leaves a residual gap
        // (each endpoint lands on its own circle along the same ray, and the
        // radii differ), which the final weld will have to close.
        const Jx = (E0.x + E1.x) * 0.5, Jy = (E0.y + E1.y) * 0.5;
        snapArcAngle(a0, Math.atan2(Jy - a0.cy, Jx - a0.cx), false);
        snapArcAngle(a1, Math.atan2(Jy - a1.cy, Jx - a1.cx), true);
      }
    }
  }

  // Splice connectors in from the back so earlier indices stay valid.  A
  // connector claims no dense vertices of its own — it spans the gap BETWEEN
  // two segments' spans — so it carries a zero-width index range, the same
  // convention `snapJunctionEndpoints` uses for its slot connectors.
  const inserted: number[] = [];
  for (let k = pending.length - 1; k >= 0; k--) {
    const { afterIdx, prim } = pending[k];
    const w = segs[afterIdx].wj;
    segs.splice(afterIdx + 1, 0, { wi: w, wj: w, prim });
    // Earlier insertions shift these, so fix them up as we go.
    for (let m = 0; m < inserted.length; m++) inserted[m]++;
    inserted.push(afterIdx + 1);
  }
  return inserted;
}
