/**
 * Multi-resolution texture manager.
 *
 * Coordinates rendering PDF pages at different resolutions,
 * uploading textures to the GPU, and caching renders in IndexedDB.
 *
 * Three resolution levels per page:
 * - Thumbnail (~50 DPI): Always loaded for all pages. Very cheap.
 * - Overview (~100 DPI): Loaded on demand when zoomed in enough. Evicted when not visible.
 * - Full (200 DPI): Loaded on demand when zoomed in further. Evicted when not visible.
 *
 * GPU uploads from IndexedDB blobs use createImageBitmap + copyExternalImageToTexture
 * so the main thread never blocks on pixel extraction.  Pixel extraction (for denoise /
 * auto-crop) is done via a Web Worker in storage.ts.
 */

import type { CanvasBackend, PDFDocument } from "../../src/pdf/pdf_render.ts";
import { renderPdfPage, SCALE_200DPI } from "../../src/pdf/pdf_render.ts";
import type { RGBAImage } from "../../src/formats/rgba_image.ts";
import type { MultiPageViewerHandle } from "../../src/gpu/multi_page_viewer.ts";
import type { PageLayout } from "./page_layout.ts";
import {
  saveRenderCache,
  getRenderCache,
  rgbaImageToPngBlob,
  pngBlobToRgbaImage,
  getDenoisedImage,
  deleteDenoisedImage,
  type StoredRenderCache,
} from "../storage.ts";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface TextureManagerCallbacks {
  /** Called when a texture finishes loading, to trigger a redraw. */
  onTextureReady(pageNumber: number, level: "thumbnail" | "overview" | "full"): void;
}

export interface TextureManager {
  /**
   * Load thumbnail textures for all pages (fast, small images).
   * For denoised pages, loads the denoised thumbnail if available.
   * @param onDenoisedFailed - Called when a denoised image fails to decode.
   */
  loadAll(
    pages: PageLayout[],
    denoisedPages: Set<number>,
    onDenoisedFailed?: (pageNumber: number) => void,
  ): Promise<void>;

  /**
   * Request thumbnail texture for a page.
   * No-op if already loaded or loading.  Used to reload evicted thumbnails.
   */
  requestThumbnail(pageNumber: number): void;

  /**
   * Request overview-resolution texture for a page.
   * No-op if already loaded or loading. Async — calls onTextureReady when done.
   */
  requestOverview(pageNumber: number): void;

  /**
   * Request full-resolution texture for a page.
   * No-op if already loaded or loading. Async — calls onTextureReady when done.
   */
  requestFull(pageNumber: number): void;

  /**
   * Evict overview and full textures for pages not in the visible set.
   * Thumbnails are never evicted.
   */
  evictInvisible(visiblePages: Set<number>): void;

  /**
   * Check if an overview texture should be loaded for the current zoom level.
   */
  needsOverviewTexture(pageNumber: number, zoom: number): boolean;

  /**
   * Check if a full texture should be loaded for the current zoom level.
   */
  needsFullTexture(pageNumber: number, zoom: number): boolean;

  /**
   * Update a page's texture with a full denoised image.
   * Creates and uploads all three resolution levels.
   */
  updateDenoised(
    pageNumber: number,
    denoisedFull: RGBAImage,
    denoisedBlob?: Blob,
  ): void;

  /**
   * Switch the viewer display layer (raw / denoised).
   * Evicts all non-thumbnail textures so they reload from the appropriate cache.
   */
  setViewMode(mode: "raw" | "denoised"): void;

  /**
   * Stop loading textures.  Used while the viewer is drawing pages straight
   * from palette bit-planes, which needs no texture at all: resident textures
   * stay for the switch back, and `evictInvisible` still reclaims them.
   */
  setSuspended(suspended: boolean): void;

  /**
   * Get the overview scale for a page (overviewPixels / virtualPixels).
   */
  getOverviewScale(pageNumber: number): number;

  /**
   * Get the best available full-resolution image for a page.
   * Returns the denoised image if available, otherwise the raw PDF render.
   */
  getFullImage(pageNumber: number): Promise<RGBAImage>;

  /**
   * Get the raw (un-denoised) full-resolution image for a page.
   * Always returns the PDF render, never the denoised version.
   */
  getFullRawImage(pageNumber: number): Promise<RGBAImage>;

  /**
   * Get the thumbnail (50 DPI) image for a page.
   * Prefers denoised version if available, otherwise returns the raw thumbnail.
   * Returns the DPI of the thumbnail (THUMBNAIL_DPI = 50).
   */
  getThumbnailImage(pageNumber: number): Promise<{ image: RGBAImage; dpi: number }>;

  destroy(): void;
}

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

/** Thumbnail DPI — very small, always loaded for all pages. */
const THUMBNAIL_DPI = 50;

/** Overview DPI — sufficient for fit-to-width at ~1000px wide. */
const OVERVIEW_DPI = 100;

/**
 * Maximum number of thumbnail textures to keep in GPU memory simultaneously.
 * Each thumbnail is ~1 MB; 50 thumbnails ≈ 50 MB.  Pages beyond this cap are
 * evicted when off-screen and reloaded lazily when they become visible again.
 */
const MAX_THUMBNAILS = 50;

/**
 * Request overview when thumbnail texel density drops below this threshold.
 * zoom * thumbnailScale > OVERVIEW_THRESHOLD triggers overview loading.
 * With thumbnailScale=0.25: triggers at zoom > 0.48 (fit-to-width ~0.59 qualifies).
 */
const OVERVIEW_THRESHOLD = 0.12;

/**
 * Request full texture when overview texel density exceeds this threshold.
 * zoom * overviewScale > FULL_TEXTURE_THRESHOLD triggers full loading.
 * With overviewScale=0.5: triggers at zoom > 3.0 (significantly zoomed in).
 */
const FULL_TEXTURE_THRESHOLD = 1.5;

/**
 * Check whether two dimensions are close enough to be considered the same page.
 */
function dimsMatch(a: number, b: number): boolean {
  return Math.abs(a - b) <= 2;
}

// ---------------------------------------------------------------------------
// Implementation
// ---------------------------------------------------------------------------

/** Simple area-averaged downsample of an RGBA image. */
function downsample(src: RGBAImage, dstW: number, dstH: number): RGBAImage {
  const dst = new Uint8ClampedArray(dstW * dstH * 4);
  const sx = src.width / dstW;
  const sy = src.height / dstH;

  for (let dy = 0; dy < dstH; dy++) {
    for (let dx = 0; dx < dstW; dx++) {
      // Source region
      const x0 = Math.floor(dx * sx);
      const y0 = Math.floor(dy * sy);
      const x1 = Math.min(Math.floor((dx + 1) * sx), src.width);
      const y1 = Math.min(Math.floor((dy + 1) * sy), src.height);
      const count = (x1 - x0) * (y1 - y0);

      let r = 0, g = 0, b = 0, a = 0;
      for (let y = y0; y < y1; y++) {
        for (let x = x0; x < x1; x++) {
          const i = (y * src.width + x) * 4;
          r += src.data[i];
          g += src.data[i + 1];
          b += src.data[i + 2];
          a += src.data[i + 3];
        }
      }

      const di = (dy * dstW + dx) * 4;
      dst[di] = r / count;
      dst[di + 1] = g / count;
      dst[di + 2] = b / count;
      dst[di + 3] = a / count;
    }
  }

  return { width: dstW, height: dstH, data: dst };
}

/**
 * Maximum number of compressed PNG blobs to keep in memory.
 * Each 6800×4400 PNG is ~5 MB compressed, so 20 pages ≈ 100 MB.
 */
const BLOB_CACHE_MAX = 20;

interface BlobCacheEntry {
  blob: Blob;
  width: number;
  height: number;
}

export function createTextureManager(
  viewer: MultiPageViewerHandle,
  callbacks: TextureManagerCallbacks,
  doc: PDFDocument,
  backend: CanvasBackend,
  fileId: string,
): TextureManager {
  // Per-page state
  const thumbnailScales = new Map<number, number>(); // pageNum → thumbnail scale
  const overviewScales = new Map<number, number>(); // pageNum → overview scale
  const loadingThumbnail = new Set<number>(); // pages currently loading thumbnail textures
  const hasThumbnailLoaded = new Set<number>(); // pages with thumbnail textures in GPU
  const loadingOverview = new Set<number>(); // pages currently loading overview textures
  const hasOverviewLoaded = new Set<number>(); // pages with overview textures in GPU
  const loadingFull = new Set<number>(); // pages currently loading full textures
  const hasFullLoaded = new Set<number>(); // pages with full textures in GPU
  const pageDims = new Map<number, { width: number; height: number }>(); // expected page dimensions
  // Which view generation each uploaded texture was built for.  A texture whose
  // generation is behind `viewGeneration` is STALE, not missing: it still shows
  // the previous pipeline stage and stays on screen until its replacement is
  // uploaded.  This is the whole anti-pop mechanism — see setViewMode below.
  // Pages whose upload failed for a given view generation.  Without this the
  // render loop re-requests the failing level every frame forever.
  const fullFailed = new Map<number, number>();
  const thumbnailGen = new Map<number, number>();
  const overviewGen  = new Map<number, number>();
  const fullGen      = new Map<number, number>();

  // Current display layer
  let viewMode: "raw" | "denoised" = "denoised";
  /** While true nothing is loaded — the ink path owns the display. */
  let suspended = false;
  /**
   * Pages that have a denoised render.  In denoised view mode these must never
   * fall back to a raw source: a missing denoised level should degrade to a
   * lower-resolution DENOISED level, not to the raw scan at full resolution.
   */
  const denoisedPageSet = new Set<number>();
  let reportDenoisedFailed: ((pageNumber: number) => void) | undefined;

  /** True when this page must be shown denoised and only denoised. */
  function denoisedOnly(pageNumber: number): boolean {
    return viewMode === "denoised" && denoisedPageSet.has(pageNumber);
  }
  // Incremented on every mode/layer switch — lets in-flight loads detect staleness.
  let viewGeneration = 0;

  // In-memory LRU cache of compressed PNG blobs — avoids IDB round-trips
  // Keyed by page.  `kind` matters: the raw full render is cached here too, and
  // handing a raw blob back in denoised mode is exactly how the denoised view
  // used to show the raw scan at high zoom.
  const blobCache = new Map<number, BlobCacheEntry & { kind: "raw" | "denoised" }>();
  const blobCacheOrder: number[] = []; // LRU order: most-recent at end

  function blobCachePut(
    pageNumber: number,
    entry: BlobCacheEntry,
    kind: "raw" | "denoised",
  ): void {
    const idx = blobCacheOrder.indexOf(pageNumber);
    if (idx >= 0) blobCacheOrder.splice(idx, 1);
    blobCacheOrder.push(pageNumber);
    blobCache.set(pageNumber, { ...entry, kind });

    while (blobCacheOrder.length > BLOB_CACHE_MAX) {
      const evicted = blobCacheOrder.shift()!;
      blobCache.delete(evicted);
    }
  }

  /** True when a level has no texture, or one built for an older view. */
  function stale(gen: Map<number, number>, loaded: Set<number>, page: number): boolean {
    return !loaded.has(page) || gen.get(page) !== viewGeneration;
  }

  /**
   * Mark every uploaded texture as belonging to the previous view.
   *
   * Deliberately does NOT evict.  Evicting on a view switch was what made the
   * viewer pop: the page dropped to whatever texture was left — usually a
   * 50 DPI thumbnail of a completely different pipeline stage — and only
   * climbed back as the replacements arrived, once per level, per page.  The
   * old texture is a far better placeholder than the wrong one, and the upload
   * path already replaces a level in place, so leaving it on screen until its
   * replacement lands costs nothing and the switch reads as a crossfade.
   *
   * In-flight loads are dropped by the generation check they already carry.
   */
  function invalidateView(): void {
    viewGeneration++;
    if (suspended) return;
    loadingThumbnail.clear();
    loadingOverview.clear();
    loadingFull.clear();
    // Kick off the replacements straight away, for exactly the levels that are
    // currently on screen.  Without this the switch appeared not to take
    // effect: `render` prefers full > overview > thumbnail unconditionally, so
    // a stale full texture kept being drawn, and the render loop only asks for
    // a full texture when the zoom threshold says it needs one — which it does
    // not, at normal zoom, for a page that already had it.  So the old image
    // stayed until the user zoomed or scrolled the page off and back.
    for (const pageNum of [...hasFullLoaded]) {
      loadFull(pageNum).catch(err =>
        console.error(`view switch: full reload failed for page ${pageNum}:`, err));
    }
    for (const pageNum of [...hasOverviewLoaded]) {
      loadOverviewTexture(pageNum).catch(err =>
        console.error(`view switch: overview reload failed for page ${pageNum}:`, err));
    }
  }

  function blobCacheGet(
    pageNumber: number,
    kind: "raw" | "denoised",
  ): BlobCacheEntry | undefined {
    const entry = blobCache.get(pageNumber);
    if (entry && entry.kind !== kind) return undefined;
    if (entry) {
      const idx = blobCacheOrder.indexOf(pageNumber);
      if (idx >= 0) blobCacheOrder.splice(idx, 1);
      blobCacheOrder.push(pageNumber);
    }
    return entry;
  }

  /**
   * The denoised full-page render for a page, from memory or IDB.
   *
   * Used to derive a denoised thumbnail or overview when the pre-saved one is
   * missing.  Without this, forbidding the raw fallback would leave a denoised
   * page with nothing to draw at that level.
   */
  async function denoisedFullBlob(pageNumber: number): Promise<BlobCacheEntry | undefined> {
    const cached = blobCacheGet(pageNumber, "denoised");
    if (cached) return cached;
    try {
      const stored = await getDenoisedImage(fileId, pageNumber);
      if (!stored) return undefined;
      const entry = { blob: stored.pngBlob, width: stored.width, height: stored.height };
      blobCachePut(pageNumber, entry, "denoised");
      return entry;
    } catch {
      return undefined;
    }
  }

  // -------------------------------------------------------------------------
  // Thumbnail loading (50 DPI) — always loaded for all pages
  // -------------------------------------------------------------------------

  /**
   * Load the thumbnail for the CURRENT view.  The thumbnail is what a page
   * falls back to whenever the higher levels are missing, so if it ignored the
   * view mode — as it used to — selecting "Cleaned page" or an ink layer would
   * leave the raw scan showing at low zoom and flash it on every scroll.
   */
  async function loadThumbnail(page: PageLayout): Promise<void> {
    const pageNum = page.pageNumber;
    const thumbnailScale = THUMBNAIL_DPI / 200;
    const gen = viewGeneration; // capture before any await

    const accept = (upload: () => void): boolean => {
      if (gen !== viewGeneration) return true; // view moved on; drop this load
      upload();
      thumbnailScales.set(pageNum, thumbnailScale);
      hasThumbnailLoaded.add(pageNum);
      thumbnailGen.set(pageNum, gen);
      return true;
    };

    // Only levels whose CONTENT matches the selected view: a denoised page
    // must not drop back to the raw thumbnail just because its denoised one is
    // missing — render would then show raw at low zoom and denoised at high.
    const levels: Array<StoredRenderCache["level"]> = denoisedOnly(pageNum)
      ? ["denoisedThumbnail"]
      : viewMode === "raw"
      ? ["thumbnail"]
      : ["denoisedThumbnail", "thumbnail"];

    for (const level of levels) {
      try {
        const cached = await getRenderCache(fileId, pageNum, level);
        if (gen !== viewGeneration) return;
        if (cached) {
          const bitmap = await createImageBitmap(cached.pngBlob);
          if (gen !== viewGeneration) { bitmap.close(); return; }
          accept(() => viewer.uploadBitmap(pageNum, bitmap, "thumbnail", thumbnailScale));
          bitmap.close();
          return;
        }
      } catch { /* cache miss or decode error — try the next level */ }
    }

    // A denoised page with no saved denoised thumbnail: downsample its full
    // render rather than reaching for the raw scan.
    if (denoisedOnly(pageNum)) {
      const full = await denoisedFullBlob(pageNum);
      if (gen !== viewGeneration) return;
      if (full) {
        const tw = Math.max(1, Math.round(full.width * thumbnailScale));
        const th = Math.max(1, Math.round(full.height * thumbnailScale));
        const bitmap = await createImageBitmap(full.blob, {
          resizeWidth: tw, resizeHeight: th, resizeQuality: "high",
        });
        if (gen !== viewGeneration) { bitmap.close(); return; }
        accept(() => viewer.uploadBitmap(pageNum, bitmap, "thumbnail", thumbnailScale));
        bitmap.close();
        return;
      }
      // Marked denoised but nothing to show — see loadFull for why this clears.
      console.warn(`page ${pageNum} is marked denoised but has no denoised image; ` +
        `showing the raw scan and clearing the flag`);
      denoisedPageSet.delete(pageNum);
      reportDenoisedFailed?.(pageNum);
      const raw = await getRenderCache(fileId, pageNum, "thumbnail").catch(() => null);
      if (gen !== viewGeneration) return;
      if (raw) {
        const bitmap = await createImageBitmap(raw.pngBlob);
        if (gen !== viewGeneration) { bitmap.close(); return; }
        accept(() => viewer.uploadBitmap(pageNum, bitmap, "thumbnail", thumbnailScale));
        bitmap.close();
        return;
      }
    }

    // Nothing cached — render the raw page from the PDF at thumbnail DPI.
    const scale = THUMBNAIL_DPI / 72;
    const rendered = await renderPdfPage(doc, pageNum, backend, scale);
    if (gen !== viewGeneration) return;
    const image: RGBAImage = {
      width: rendered.width,
      height: rendered.height,
      data: rendered.data,
    };

    accept(() => viewer.uploadTexture(pageNum, image, "thumbnail", thumbnailScale));

    // Cache in IndexedDB (fire-and-forget)
    rgbaImageToPngBlob(image).then(blob => {
      saveRenderCache({
        fileId,
        pageNumber: pageNum,
        level: "thumbnail",
        pngBlob: blob,
        width: image.width,
        height: image.height,
      }).catch(() => {});
    }).catch(() => {});
  }

  /** Try to load a pre-saved denoised thumbnail for a page. */
  async function loadDenoisedThumbnail(page: PageLayout): Promise<boolean> {
    try {
      const cached = await getRenderCache(fileId, page.pageNumber, "denoisedThumbnail");
      if (!cached) return false;
      const thumbnailScale = THUMBNAIL_DPI / 200;
      const bitmap = await createImageBitmap(cached.pngBlob);
      viewer.uploadBitmap(page.pageNumber, bitmap, "thumbnail", thumbnailScale);
      bitmap.close();
      thumbnailScales.set(page.pageNumber, thumbnailScale);
      hasThumbnailLoaded.add(page.pageNumber);
      thumbnailGen.set(page.pageNumber, viewGeneration);
      return true;
    } catch {
      return false;
    }
  }

  // -------------------------------------------------------------------------
  // Overview loading (100 DPI) — on demand when zoomed in enough
  // -------------------------------------------------------------------------

  async function loadOverviewTexture(pageNumber: number): Promise<void> {
    if (loadingOverview.has(pageNumber)) return;
    if (!stale(overviewGen, hasOverviewLoaded, pageNumber)) return;
    loadingOverview.add(pageNumber);
    const gen = viewGeneration; // capture before any await

    const overviewScale = OVERVIEW_DPI / 200;

    try {
      // As in loadThumbnail: content must match the selected view.
      const levels: Array<StoredRenderCache["level"]> = denoisedOnly(pageNumber)
        ? ["denoisedOverview"]
        : viewMode === "raw"
        ? ["overview"]
        : ["denoisedOverview", "overview"];

      for (const level of levels) {
        try {
          const cached = await getRenderCache(fileId, pageNumber, level);
          if (gen !== viewGeneration) return;
          if (cached) {
            const bitmap = await createImageBitmap(cached.pngBlob);
            if (gen !== viewGeneration) { bitmap.close(); return; }
            viewer.uploadBitmap(pageNumber, bitmap, "overview", overviewScale);
            bitmap.close();
            overviewScales.set(pageNumber, overviewScale);
            hasOverviewLoaded.add(pageNumber);
            overviewGen.set(pageNumber, gen);
            callbacks.onTextureReady(pageNumber, "overview");
            return;
          }
        } catch { /* ignore */ }
      }

      // A denoised page with no saved denoised overview: downsample its full
      // render rather than reaching for the raw scan.
      if (denoisedOnly(pageNumber)) {
        const full = await denoisedFullBlob(pageNumber);
        if (gen !== viewGeneration) return;
        if (full) {
          const ow = Math.max(1, Math.round(full.width * overviewScale));
          const oh = Math.max(1, Math.round(full.height * overviewScale));
          const bitmap = await createImageBitmap(full.blob, {
            resizeWidth: ow, resizeHeight: oh, resizeQuality: "high",
          });
          if (gen !== viewGeneration) { bitmap.close(); return; }
          viewer.uploadBitmap(pageNumber, bitmap, "overview", overviewScale);
          bitmap.close();
          overviewScales.set(pageNumber, overviewScale);
          hasOverviewLoaded.add(pageNumber);
          overviewGen.set(pageNumber, gen);
          callbacks.onTextureReady(pageNumber, "overview");
          return;
        }
        console.warn(`page ${pageNumber} is marked denoised but has no denoised image; ` +
          `showing the raw scan and clearing the flag`);
        denoisedPageSet.delete(pageNumber);
        reportDenoisedFailed?.(pageNumber);
      }

      // Render fresh from PDF at overview DPI
      const scale = OVERVIEW_DPI / 72;
      const rendered = await renderPdfPage(doc, pageNumber, backend, scale);
      if (gen !== viewGeneration) return;
      const image: RGBAImage = {
        width: rendered.width,
        height: rendered.height,
        data: rendered.data,
      };

      viewer.uploadTexture(pageNumber, image, "overview", overviewScale);
      overviewScales.set(pageNumber, overviewScale);
      hasOverviewLoaded.add(pageNumber);
      overviewGen.set(pageNumber, gen);

      // Cache in IndexedDB (fire-and-forget)
      rgbaImageToPngBlob(image).then(blob => {
        saveRenderCache({
          fileId,
          pageNumber,
          level: "overview",
          pngBlob: blob,
          width: image.width,
          height: image.height,
        }).catch(() => {});
      }).catch(() => {});

      callbacks.onTextureReady(pageNumber, "overview");
    } finally {
      loadingOverview.delete(pageNumber);
    }
  }

  // -------------------------------------------------------------------------
  // Full loading (200 DPI) — on demand when zoomed in further
  // -------------------------------------------------------------------------

  async function loadFull(pageNumber: number): Promise<void> {
    if (loadingFull.has(pageNumber)) return;
    if (fullFailed.get(pageNumber) === viewGeneration) return;
    if (!stale(fullGen, hasFullLoaded, pageNumber)) return;
    loadingFull.add(pageNumber);
    const gen = viewGeneration; // capture before any await

    const dims = pageDims.get(pageNumber);

    try {
      let blobEntry: BlobCacheEntry | undefined;
      const wantDenoised = viewMode === "denoised";

      // 1. In-memory blob cache, matching the kind this view needs.
      blobEntry = blobCacheGet(pageNumber, wantDenoised ? "denoised" : "raw");

      // 2. Full denoised image in IDB.
      if (!blobEntry && wantDenoised) {
        try {
          const stored = await getDenoisedImage(fileId, pageNumber);
          if (gen !== viewGeneration) return;
          if (stored) {
            const isFullPage = !dims ||
              (dimsMatch(stored.width, dims.width) && dimsMatch(stored.height, dims.height));
            if (isFullPage) {
              blobEntry = { blob: stored.pngBlob, width: stored.width, height: stored.height };
            } else {
              console.warn(`Deleting stale denoised image for page ${pageNumber}: ` +
                `${stored.width}×${stored.height} vs expected ${dims.width}×${dims.height}`);
              await deleteDenoisedImage(fileId, pageNumber);
              denoisedPageSet.delete(pageNumber);
              reportDenoisedFailed?.(pageNumber);
            }
          }
        } catch { /* ignore */ }
      }

      // 3. Raw sources.  Only reachable when this view wants raw, or when the
      // page has no denoised render at all — a denoised page silently showing
      // the raw scan is the bug this guard exists to prevent.
      if (!blobEntry && denoisedOnly(pageNumber)) {
        // The page claims to be denoised but its image is gone.  Say so and
        // stop claiming it, rather than quietly serving the raw scan; the
        // lower texture levels are still denoised, so render degrades in
        // resolution instead of in content.
        console.warn(`page ${pageNumber} is marked denoised but has no denoised image; ` +
          `showing the raw scan and clearing the flag`);
        denoisedPageSet.delete(pageNumber);
        reportDenoisedFailed?.(pageNumber);
      }

      if (!blobEntry) {
        try {
          const cached = await getRenderCache(fileId, pageNumber, "full");
          if (gen !== viewGeneration) return;
          if (cached) {
            blobEntry = { blob: cached.pngBlob, width: cached.width, height: cached.height };
          }
        } catch { /* ignore */ }
      }

      if (gen !== viewGeneration) return;

      if (blobEntry) {
        blobCachePut(pageNumber, blobEntry, wantDenoised ? "denoised" : "raw");
        const bitmap = await createImageBitmap(blobEntry.blob);
        if (gen !== viewGeneration) { bitmap.close(); return; }
        try {
          viewer.uploadBitmap(pageNumber, bitmap, "full");
        } catch (err) {
          // `copyExternalImageToTexture` refuses a full-page (6000x4000)
          // ImageBitmap on SwiftShader.  Decoding to RGBA and uploading the
          // bytes goes through a different path that does work, and costs one
          // CPU decode — worth it to keep full resolution rather than falling
          // back to the overview.
          console.warn(`bitmap upload failed for page ${pageNumber}; decoding to RGBA instead:`, err);
          viewer.uploadTexture(
            pageNumber,
            await pngBlobToRgbaImage(blobEntry.blob, blobEntry.width, blobEntry.height),
            "full",
          );
        } finally {
          bitmap.close();
        }
      } else {
        // 5. Render from PDF at full DPI
        const rendered = await renderPdfPage(doc, pageNumber, backend, SCALE_200DPI);
        if (gen !== viewGeneration) return;
        const image: RGBAImage = {
          width: rendered.width,
          height: rendered.height,
          data: rendered.data,
        };
        viewer.uploadTexture(pageNumber, image, "full");

        // Encode to blob for cache + IDB (fire-and-forget)
        rgbaImageToPngBlob(image).then(blob => {
          blobCachePut(pageNumber, { blob, width: image.width, height: image.height }, "raw");
          saveRenderCache({
            fileId,
            pageNumber,
            level: "full",
            pngBlob: blob,
            width: image.width,
            height: image.height,
          }).catch(() => {});
        }).catch(() => {});
      }

      hasFullLoaded.add(pageNumber);
      fullGen.set(pageNumber, gen);
      callbacks.onTextureReady(pageNumber, "full");
    } catch (err) {
      // An upload that fails must not leave the previous view's texture in
      // place claiming to be current: `render` prefers full > overview > thumb
      // unconditionally, so a stale full texture would keep being drawn and the
      // background switch would look like it never happened.  Drop the level
      // and let the (fresh, correct) overview show instead.
      //
      // Seen for real: `copyExternalImageToTexture` refuses a 6000x4000
      // ImageBitmap on SwiftShader.
      console.error(`full texture upload failed for page ${pageNumber}; falling back to overview:`, err);
      viewer.evictTexture(pageNumber, "full");
      hasFullLoaded.delete(pageNumber);
      fullGen.delete(pageNumber);
      fullFailed.set(pageNumber, viewGeneration);
    } finally {
      loadingFull.delete(pageNumber);
    }
  }

  // -------------------------------------------------------------------------
  // Full image retrieval (for denoise / crop pipelines)
  // -------------------------------------------------------------------------

  async function getFullRawImageImpl(pageNumber: number): Promise<RGBAImage> {
    try {
      const cached = await getRenderCache(fileId, pageNumber, "full");
      if (cached) {
        return pngBlobToRgbaImage(cached.pngBlob, cached.width, cached.height);
      }
    } catch { /* ignore */ }

    const rendered = await renderPdfPage(doc, pageNumber, backend, SCALE_200DPI);
    const image: RGBAImage = {
      width: rendered.width,
      height: rendered.height,
      data: rendered.data,
    };

    rgbaImageToPngBlob(image).then(blob => {
      saveRenderCache({
        fileId,
        pageNumber,
        level: "full",
        pngBlob: blob,
        width: image.width,
        height: image.height,
      }).catch(() => {});
    }).catch(() => {});

    return image;
  }

  // -------------------------------------------------------------------------
  // Public API
  // -------------------------------------------------------------------------

  return {
    async loadAll(
      pages: PageLayout[],
      denoisedPages: Set<number>,
      onDenoisedFailed?: (pageNumber: number) => void,
    ): Promise<void> {
      denoisedPageSet.clear();
      for (const p of denoisedPages) denoisedPageSet.add(p);
      reportDenoisedFailed = onDenoisedFailed;

      // Register page dimensions and load thumbnails for all pages.
      // Thumbnails are tiny (~340×440 for letter-size) and load very quickly.
      for (const page of pages) {
        pageDims.set(page.pageNumber, { width: page.fullWidth, height: page.fullHeight });

        if (denoisedPages.has(page.pageNumber)) {
          // Try loading a pre-saved denoised thumbnail
          const loaded = await loadDenoisedThumbnail(page);
          if (loaded) {
            callbacks.onTextureReady(page.pageNumber, "thumbnail");
            continue;
          }
          // No cached denoised thumbnail — try loading denoised full to
          // create the thumbnail + overview (handles first-load after denoise)
          let denoisedHandled = false;
          try {
            const stored = await getDenoisedImage(fileId, page.pageNumber);
            if (stored) {
              if (!dimsMatch(stored.width, page.fullWidth) || !dimsMatch(stored.height, page.fullHeight)) {
                console.warn(`Deleting stale denoised image for page ${page.pageNumber}: ` +
                  `${stored.width}×${stored.height} vs expected ${page.fullWidth}×${page.fullHeight}`);
                await deleteDenoisedImage(fileId, page.pageNumber);
                denoisedPageSet.delete(page.pageNumber);
                onDenoisedFailed?.(page.pageNumber);
              } else {
                // Create and upload thumbnail from denoised full
                const thScale = THUMBNAIL_DPI / 200;
                const tw = Math.round(stored.width * thScale);
                const th = Math.round(stored.height * thScale);
                const thBitmap = await createImageBitmap(stored.pngBlob, {
                  resizeWidth: tw,
                  resizeHeight: th,
                  resizeQuality: "high",
                });
                viewer.uploadBitmap(page.pageNumber, thBitmap, "thumbnail", thScale);
                thumbnailScales.set(page.pageNumber, thScale);
                hasThumbnailLoaded.add(page.pageNumber);
                thumbnailGen.set(page.pageNumber, viewGeneration);

                // Save denoised thumbnail to IDB (fire-and-forget)
                const thCanvas = new OffscreenCanvas(tw, th);
                const thCtx = thCanvas.getContext("2d")!;
                thCtx.drawImage(thBitmap, 0, 0);
                thBitmap.close();
                thCanvas.convertToBlob({ type: "image/png" }).then(thBlob => {
                  saveRenderCache({
                    fileId,
                    pageNumber: page.pageNumber,
                    level: "denoisedThumbnail",
                    pngBlob: thBlob,
                    width: tw,
                    height: th,
                  }).catch(() => {});
                }).catch(() => {});

                // Cache blob for fast full re-upload
                blobCachePut(page.pageNumber, { blob: stored.pngBlob, width: stored.width, height: stored.height }, "denoised");

                denoisedHandled = true;
              }
            }
          } catch (err) {
            console.error(`Failed to load denoised image for page ${page.pageNumber}:`, err);
            try { await deleteDenoisedImage(fileId, page.pageNumber); } catch { /* ignore */ }
            denoisedPageSet.delete(page.pageNumber);
            onDenoisedFailed?.(page.pageNumber);
          }

          if (!denoisedHandled) {
            // Fall back to raw thumbnail
            await loadThumbnail(page);
          }
          callbacks.onTextureReady(page.pageNumber, "thumbnail");
        } else {
          await loadThumbnail(page);
          callbacks.onTextureReady(page.pageNumber, "thumbnail");
        }
      }
    },

    requestThumbnail(pageNumber: number): void {
      if (suspended || loadingThumbnail.has(pageNumber)) return;
      if (!stale(thumbnailGen, hasThumbnailLoaded, pageNumber)) return;
      if (!pageDims.has(pageNumber)) return; // page not registered yet
      loadingThumbnail.add(pageNumber);
      loadThumbnail({ pageNumber } as PageLayout)
        .then(() => {
          loadingThumbnail.delete(pageNumber);
          callbacks.onTextureReady(pageNumber, "thumbnail");
        })
        .catch(err => {
          loadingThumbnail.delete(pageNumber);
          console.error(`Failed to reload thumbnail for page ${pageNumber}:`, err);
        });
    },

    requestOverview(pageNumber: number): void {
      loadOverviewTexture(pageNumber).catch(err => {
        console.error(`Failed to load overview texture for page ${pageNumber}:`, err);
      });
    },

    requestFull(pageNumber: number): void {
      loadFull(pageNumber).catch(err => {
        console.error(`Failed to load full texture for page ${pageNumber}:`, err);
      });
    },

    evictInvisible(visiblePages: Set<number>): void {
      for (const pageNum of hasOverviewLoaded) {
        if (!visiblePages.has(pageNum)) {
          viewer.evictTexture(pageNum, "overview");
          hasOverviewLoaded.delete(pageNum);
          overviewGen.delete(pageNum);
        }
      }
      for (const pageNum of hasFullLoaded) {
        if (!visiblePages.has(pageNum)) {
          viewer.evictTexture(pageNum, "full");
          hasFullLoaded.delete(pageNum);
          fullGen.delete(pageNum);
          fullFailed.delete(pageNum);
        }
      }
      // Cap thumbnail GPU memory for large documents: evict off-screen thumbnails
      // when the total exceeds MAX_THUMBNAILS.  They are reloaded lazily via
      // requestThumbnail() in the render loop.
      if (hasThumbnailLoaded.size > MAX_THUMBNAILS) {
        for (const pageNum of hasThumbnailLoaded) {
          if (!visiblePages.has(pageNum)) {
            viewer.evictTexture(pageNum, "thumbnail");
            hasThumbnailLoaded.delete(pageNum);
            thumbnailGen.delete(pageNum);
          }
        }
      }
    },

    needsOverviewTexture(pageNumber: number, zoom: number): boolean {
      if (suspended || loadingOverview.has(pageNumber)) return false;
      if (!stale(overviewGen, hasOverviewLoaded, pageNumber)) return false;
      const scale = thumbnailScales.get(pageNumber) ?? 0.25;
      return zoom * scale > OVERVIEW_THRESHOLD;
    },

    needsFullTexture(pageNumber: number, zoom: number): boolean {
      if (suspended || loadingFull.has(pageNumber)) return false;
      if (fullFailed.get(pageNumber) === viewGeneration) return false;
      if (!stale(fullGen, hasFullLoaded, pageNumber)) return false;
      const scale = overviewScales.get(pageNumber) ?? 0.5;
      return zoom * scale > FULL_TEXTURE_THRESHOLD;
    },

    updateDenoised(
      pageNumber: number,
      denoisedFull: RGBAImage,
      denoisedBlob?: Blob,
    ): void {
      denoisedPageSet.add(pageNumber);
      // Do NOT eagerly upload the full-res (200 DPI) GPU texture here.
      // For batch operations that's 15 MB × N pages of GPU memory held simultaneously.
      // The blob is cached in blobCache below, so loadFull() will decode and upload
      // it instantly from memory when needed (first zoom-in to that page).

      // CPU downsample for overview (100 DPI) — small, needed for normal zoom
      const ovScale = OVERVIEW_DPI / 200;
      const ow = Math.round(denoisedFull.width * ovScale);
      const oh = Math.round(denoisedFull.height * ovScale);
      const overviewData = downsample(denoisedFull, ow, oh);
      viewer.uploadTexture(pageNumber, overviewData, "overview", ovScale);
      overviewScales.set(pageNumber, ovScale);
      hasOverviewLoaded.add(pageNumber);
      overviewGen.set(pageNumber, viewGeneration);

      // CPU downsample for thumbnail (50 DPI)
      const thScale = THUMBNAIL_DPI / 200;
      const tw = Math.round(denoisedFull.width * thScale);
      const th = Math.round(denoisedFull.height * thScale);
      const thumbnailData = downsample(denoisedFull, tw, th);
      viewer.uploadTexture(pageNumber, thumbnailData, "thumbnail", thScale);
      thumbnailScales.set(pageNumber, thScale);
      hasThumbnailLoaded.add(pageNumber);
      thumbnailGen.set(pageNumber, viewGeneration);

      // Evict any stale full texture (it will reload from blobCache lazily)
      viewer.evictTexture(pageNumber, "full");
      hasFullLoaded.delete(pageNumber);
      fullGen.delete(pageNumber);

      // Cache blob for fast re-upload after eviction
      if (denoisedBlob) {
        blobCachePut(pageNumber, { blob: denoisedBlob, width: denoisedFull.width, height: denoisedFull.height }, "denoised");
      } else {
        rgbaImageToPngBlob(denoisedFull).then(blob => {
          blobCachePut(pageNumber, { blob, width: denoisedFull.width, height: denoisedFull.height }, "denoised");
        }).catch(() => {});
      }

      // Save denoised thumbnail to IDB for fast reload (fire-and-forget)
      rgbaImageToPngBlob(thumbnailData).then(thBlob => {
        saveRenderCache({
          fileId,
          pageNumber,
          level: "denoisedThumbnail",
          pngBlob: thBlob,
          width: tw,
          height: th,
        }).catch(() => {});
      }).catch(() => {});

      // Save denoised overview to IDB for fast reload (fire-and-forget)
      rgbaImageToPngBlob(overviewData).then(ovBlob => {
        saveRenderCache({
          fileId,
          pageNumber,
          level: "denoisedOverview",
          pngBlob: ovBlob,
          width: ow,
          height: oh,
        }).catch(() => {});
      }).catch(() => {});
    },

    getOverviewScale(pageNumber: number): number {
      return overviewScales.get(pageNumber) ?? 0.5;
    },

    async getFullImage(pageNumber: number): Promise<RGBAImage> {
      const cached = blobCacheGet(pageNumber, "denoised");

      try {
        const stored = await getDenoisedImage(fileId, pageNumber);
        if (stored) {
          const raw = cached
            ? { width: cached.width, height: cached.height }
            : await getFullRawImageImpl(pageNumber);
          if (dimsMatch(stored.width, raw.width) && dimsMatch(stored.height, raw.height)) {
            return pngBlobToRgbaImage(stored.pngBlob, stored.width, stored.height);
          }
          if ('data' in raw) return raw as RGBAImage;
        }
      } catch { /* ignore */ }

      return getFullRawImageImpl(pageNumber);
    },

    async getFullRawImage(pageNumber: number): Promise<RGBAImage> {
      return getFullRawImageImpl(pageNumber);
    },

    async getThumbnailImage(pageNumber: number): Promise<{ image: RGBAImage; dpi: number }> {
      // Try denoised thumbnail first, then raw thumbnail from IDB
      for (const level of ["denoisedThumbnail", "thumbnail"] as const) {
        try {
          const cached = await getRenderCache(fileId, pageNumber, level);
          if (cached) {
            const image = await pngBlobToRgbaImage(cached.pngBlob, cached.width, cached.height);
            return { image, dpi: THUMBNAIL_DPI };
          }
        } catch { /* ignore */ }
      }

      // Render fresh from PDF at thumbnail DPI
      const scale = THUMBNAIL_DPI / 72;
      const rendered = await renderPdfPage(doc, pageNumber, backend, scale);
      return {
        image: { width: rendered.width, height: rendered.height, data: rendered.data },
        dpi: THUMBNAIL_DPI,
      };
    },

    setViewMode(mode: "raw" | "denoised"): void {
      if (viewMode === mode) return;
      viewMode = mode;
      invalidateView();
    },

    setSuspended(value: boolean): void {
      suspended = value;
    },

    destroy(): void {
      // Invalidate any in-flight loads so they don't upload to a stale viewer state.
      viewGeneration++;
      // Evict all GPU textures we own before clearing tracking state.
      for (const pageNum of hasThumbnailLoaded) viewer.evictTexture(pageNum, "thumbnail");
      for (const pageNum of hasOverviewLoaded) viewer.evictTexture(pageNum, "overview");
      for (const pageNum of hasFullLoaded) viewer.evictTexture(pageNum, "full");
      thumbnailScales.clear();
      overviewScales.clear();
      loadingThumbnail.clear();
      hasThumbnailLoaded.clear();
      loadingOverview.clear();
      hasOverviewLoaded.clear();
      loadingFull.clear();
      hasFullLoaded.clear();
      thumbnailGen.clear();
      overviewGen.clear();
      fullGen.clear();
      fullFailed.clear();
      pageDims.clear();
      blobCache.clear();
      denoisedPageSet.clear();
      blobCacheOrder.length = 0;
    },
  };
}
