/**
 * Palette extraction via local maxima in a smoothed 3D Oklab histogram.
 *
 * Given an RGBA image, extracts a small set of representative colors by:
 * 1. Converting all non-B/W pixels to Oklab and building a 3D voxel histogram
 * 2. Smoothing the histogram with a 3D Gaussian blur
 * 3. Finding local maxima (density peaks) in the smoothed histogram
 * 4. Assigning every voxel to its nearest peak
 * 5. Computing weighted median colors per cluster
 * 6. Merging near-duplicate entries
 * 7. Sorting by pixel count
 */

import type { RGBAImage } from "../formats/rgba_image.ts";

// ---------------------------------------------------------------------------
// Public types
// ---------------------------------------------------------------------------

export interface PaletteEntry {
  /** Oklab [L, a, b] in standard scale (L: 0–1, a/b: ~-0.4 to +0.4). */
  oklab: [number, number, number];
  /** sRGB [r, g, b] each 0–255. */
  rgb: [number, number, number];
  /** Number of pixels in this cluster. */
  count: number;
  /** Fraction of chromatic (non-B/W) pixels (0–1). */
  fraction: number;
}

export interface PaletteOptions {
  /** Gaussian blur radius for L axis (default: 6). */
  smoothRadiusL?: number;
  /** Gaussian blur radius for a,b axes (default: 2). */
  smoothRadiusAB?: number;
  /** Gaussian sigma for L (luminosity) axis — larger = more blur (default: 5.0). */
  smoothSigmaL?: number;
  /** Gaussian sigma for a,b (chromaticity) axes (default: 1.5). */
  smoothSigmaAB?: number;
  /** Discard clusters below this fraction of chromatic pixels (default: 0.005). */
  minClusterFraction?: number;
  /** Merge palette colors closer than this ΔE in scaled Oklab (default: 3.0). */
  mergeThreshold?: number;
}

// ---------------------------------------------------------------------------
// Internal constants
// ---------------------------------------------------------------------------

/** Multiply raw Oklab by this to get "scaled" values used for distance. */
const SCALE = 100;
/** Voxel bin width in scaled Oklab space. */
const BIN_W = 1.0;
/** Grid bins per dimension (L: 0–100, a/b: -50 to +50 offset to 0–100). */
const GRID_DIM = 101;
/** Offset added to a,b so all bin indices are non-negative. */
const AB_OFFSET = 50;
/** Scaled L below this is black (excluded). */
const L_BLACK_S = 5;
/** Scaled L above this is white (excluded). */
const L_WHITE_S = 95;

// ---------------------------------------------------------------------------
// Oklab conversion (self-contained)
// ---------------------------------------------------------------------------

/** Convert a single sRGB channel (0–255) to linear light. */
export function srgbToLinear(c: number): number {
  const cn = c / 255;
  return cn <= 0.04045 ? cn / 12.92 : ((cn + 0.055) / 1.055) ** 2.4;
}

/** Convert a linear-light channel to sRGB (0–255). */
export function linearToSrgb(c: number): number {
  const v = c <= 0.0031308 ? c * 12.92 : 1.055 * c ** (1 / 2.4) - 0.055;
  return Math.round(Math.max(0, Math.min(1, v)) * 255);
}

/** Convert sRGB (0–255 each) to Oklab [L, a, b]. */
export function srgbToOklab(r: number, g: number, b: number): [number, number, number] {
  const lr = srgbToLinear(r);
  const lg = srgbToLinear(g);
  const lb = srgbToLinear(b);

  const l_ = Math.cbrt(0.4122214708 * lr + 0.5363325363 * lg + 0.0514459929 * lb);
  const m_ = Math.cbrt(0.2119034982 * lr + 0.6806995451 * lg + 0.1073969566 * lb);
  const s_ = Math.cbrt(0.0883024619 * lr + 0.2024326553 * lg + 0.6892648829 * lb);

  return [
    0.2104542553 * l_ + 0.7936177850 * m_ - 0.0040720468 * s_,
    1.9779984951 * l_ - 2.4285922050 * m_ + 0.4505937099 * s_,
    0.0259040371 * l_ + 0.7827717662 * m_ - 0.8086757660 * s_,
  ];
}

/** Convert Oklab [L, a, b] to sRGB (0–255 each). */
export function oklabToSrgb(L: number, a: number, b: number): [number, number, number] {
  const l_ = L + 0.3963377774 * a + 0.2158037573 * b;
  const m_ = L - 0.1055613458 * a - 0.0638541728 * b;
  const s_ = L - 0.0894841775 * a - 1.2914855480 * b;

  const l = l_ * l_ * l_;
  const m = m_ * m_ * m_;
  const s = s_ * s_ * s_;

  return [
    linearToSrgb(4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s),
    linearToSrgb(-1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s),
    linearToSrgb(-0.0041960863 * l - 0.7034186147 * m + 1.7076147010 * s),
  ];
}

// ---------------------------------------------------------------------------
// Voxel grid
// ---------------------------------------------------------------------------

export interface Voxel {
  Lb: number;    // L bin index
  ab: number;    // a bin index (offset)
  bb: number;    // b bin index (offset)
  count: number; // pixel count
}

/** A sparse voxel histogram built from one or more images. */
export interface VoxelGrid {
  voxels: Map<number, Voxel>;
  totalChromatic: number;
}

function packKey(Lb: number, ab: number, bb: number): number {
  return Lb * GRID_DIM * GRID_DIM + ab * GRID_DIM + bb;
}

export function buildVoxelGrid(
  src: RGBAImage,
): VoxelGrid {
  const voxels = new Map<number, Voxel>();
  let totalChromatic = 0;
  const { data, width, height } = src;
  const n = width * height;

  for (let i = 0; i < n; i++) {
    const off = i * 4;
    const [L, a, b] = srgbToOklab(data[off], data[off + 1], data[off + 2]);
    const Ls = L * SCALE;

    if (Ls < L_BLACK_S || Ls > L_WHITE_S) continue;
    totalChromatic++;

    const Lb = Math.max(0, Math.min(GRID_DIM - 1, Math.floor(Ls / BIN_W)));
    const abI = Math.max(0, Math.min(GRID_DIM - 1, Math.floor((a * SCALE + AB_OFFSET) / BIN_W)));
    const bbI = Math.max(0, Math.min(GRID_DIM - 1, Math.floor((b * SCALE + AB_OFFSET) / BIN_W)));

    const key = packKey(Lb, abI, bbI);
    const existing = voxels.get(key);
    if (existing) {
      existing.count++;
    } else {
      voxels.set(key, { Lb, ab: abI, bb: bbI, count: 1 });
    }
  }

  return { voxels, totalChromatic };
}

/**
 * Merge multiple voxel grids into one by summing counts for each voxel.
 * Use this to accumulate pixel data across pages before a single smooth+extract pass.
 */
export function mergeVoxelGrids(grids: VoxelGrid[]): VoxelGrid {
  const merged = new Map<number, Voxel>();
  let totalChromatic = 0;
  for (const { voxels, totalChromatic: tc } of grids) {
    totalChromatic += tc;
    for (const [key, v] of voxels) {
      const existing = merged.get(key);
      if (existing) {
        existing.count += v.count;
      } else {
        merged.set(key, { Lb: v.Lb, ab: v.ab, bb: v.bb, count: v.count });
      }
    }
  }
  return { voxels: merged, totalChromatic };
}

// ---------------------------------------------------------------------------
// 3D Gaussian smoothing (sparse → sparse)
// ---------------------------------------------------------------------------

/**
 * Build a 1D Gaussian kernel of given radius and sigma.
 * Returns an array of length 2*radius+1, normalized to sum to 1.
 */
function gaussianKernel(radius: number, sigma: number): Float64Array {
  const size = 2 * radius + 1;
  const kernel = new Float64Array(size);
  let sum = 0;
  for (let i = 0; i < size; i++) {
    const x = i - radius;
    const w = Math.exp(-(x * x) / (2 * sigma * sigma));
    kernel[i] = w;
    sum += w;
  }
  for (let i = 0; i < size; i++) kernel[i] /= sum;
  return kernel;
}

/**
 * Smooth the sparse voxel grid with a separable anisotropic 3D Gaussian blur.
 * Uses sigmaL for the L (luminosity) axis and sigmaAB for the a,b (chromaticity) axes.
 * Returns a new Map with smoothed counts (as floats).
 */
function smoothVoxelGrid(
  voxels: Map<number, Voxel>,
  radiusL: number,
  sigmaL: number,
  radiusAB: number,
  sigmaAB: number,
): Map<number, number> {
  const kernelL = gaussianKernel(radiusL, sigmaL);
  const kernelAB = gaussianKernel(radiusAB, sigmaAB);

  // Pass 1: blur along L axis (wider radius + sigma)
  let current = new Map<number, number>();
  for (const [, v] of voxels) {
    for (let dL = -radiusL; dL <= radiusL; dL++) {
      const nL = v.Lb + dL;
      if (nL < 0 || nL >= GRID_DIM) continue;
      const key = packKey(nL, v.ab, v.bb);
      current.set(key, (current.get(key) ?? 0) + v.count * kernelL[dL + radiusL]);
    }
  }

  // Pass 2: blur along a axis (tighter radius + sigma)
  let next = new Map<number, number>();
  for (const [key, val] of current) {
    const Lb = Math.floor(key / (GRID_DIM * GRID_DIM));
    const rem = key - Lb * GRID_DIM * GRID_DIM;
    const ab = Math.floor(rem / GRID_DIM);
    const bb = rem - ab * GRID_DIM;

    for (let da = -radiusAB; da <= radiusAB; da++) {
      const na = ab + da;
      if (na < 0 || na >= GRID_DIM) continue;
      const nKey = packKey(Lb, na, bb);
      next.set(nKey, (next.get(nKey) ?? 0) + val * kernelAB[da + radiusAB]);
    }
  }

  // Pass 3: blur along b axis (tighter radius + sigma)
  current = next;
  next = new Map<number, number>();
  for (const [key, val] of current) {
    const Lb = Math.floor(key / (GRID_DIM * GRID_DIM));
    const rem = key - Lb * GRID_DIM * GRID_DIM;
    const ab = Math.floor(rem / GRID_DIM);
    const bb = rem - ab * GRID_DIM;

    for (let db = -radiusAB; db <= radiusAB; db++) {
      const nb = bb + db;
      if (nb < 0 || nb >= GRID_DIM) continue;
      const nKey = packKey(Lb, ab, nb);
      next.set(nKey, (next.get(nKey) ?? 0) + val * kernelAB[db + radiusAB]);
    }
  }

  return next;
}

// ---------------------------------------------------------------------------
// Local maxima detection
// ---------------------------------------------------------------------------

interface Peak {
  Lb: number;
  ab: number;
  bb: number;
  density: number;
}

/**
 * Find local maxima in the smoothed 3D histogram.
 * A voxel is a local maximum if its density is strictly greater than
 * all 26 face/edge/corner neighbors.
 */
function findLocalMaxima(smoothed: Map<number, number>): Peak[] {
  const peaks: Peak[] = [];

  for (const [key, density] of smoothed) {
    if (density <= 0) continue;

    const Lb = Math.floor(key / (GRID_DIM * GRID_DIM));
    const rem = key - Lb * GRID_DIM * GRID_DIM;
    const ab = Math.floor(rem / GRID_DIM);
    const bb = rem - ab * GRID_DIM;

    let isMax = true;
    outer:
    for (let dL = -1; dL <= 1; dL++) {
      const nL = Lb + dL;
      if (nL < 0 || nL >= GRID_DIM) continue;
      for (let da = -1; da <= 1; da++) {
        const na = ab + da;
        if (na < 0 || na >= GRID_DIM) continue;
        for (let db = -1; db <= 1; db++) {
          if (dL === 0 && da === 0 && db === 0) continue;
          const nb = bb + db;
          if (nb < 0 || nb >= GRID_DIM) continue;
          const nDensity = smoothed.get(packKey(nL, na, nb)) ?? 0;
          if (nDensity >= density) {
            isMax = false;
            break outer;
          }
        }
      }
    }

    if (isMax) {
      peaks.push({ Lb, ab, bb, density });
    }
  }

  return peaks;
}

// ---------------------------------------------------------------------------
// Assign voxels to nearest peak
// ---------------------------------------------------------------------------

function assignVoxelsToPeaks(
  voxels: Map<number, Voxel>,
  peaks: Peak[],
): Voxel[][] {
  const clusters: Voxel[][] = peaks.map(() => []);

  for (const [, v] of voxels) {
    let bestIdx = 0;
    let bestDist = Infinity;

    for (let i = 0; i < peaks.length; i++) {
      const p = peaks[i];
      const dL = v.Lb - p.Lb;
      const da = v.ab - p.ab;
      const db = v.bb - p.bb;
      const dist = dL * dL + da * da + db * db;
      if (dist < bestDist) {
        bestDist = dist;
        bestIdx = i;
      }
    }

    clusters[bestIdx].push(v);
  }

  return clusters;
}

// ---------------------------------------------------------------------------
// Cluster statistics
// ---------------------------------------------------------------------------

interface ScaledColor {
  L: number;
  a: number;
  b: number;
  count: number;
}

function weightedMedian(items: { value: number; weight: number }[]): number {
  if (items.length === 0) return 0;
  if (items.length === 1) return items[0].value;

  items.sort((a, b) => a.value - b.value);
  let total = 0;
  for (const item of items) total += item.weight;

  const half = total / 2;
  let cum = 0;
  for (const item of items) {
    cum += item.weight;
    if (cum >= half) return item.value;
  }
  return items[items.length - 1].value;
}

function clusterMedianColor(voxels: Voxel[]): ScaledColor {
  let count = 0;
  for (const v of voxels) count += v.count;

  const L = weightedMedian(
    voxels.map(v => ({ value: (v.Lb + 0.5) * BIN_W, weight: v.count })),
  );
  const a = weightedMedian(
    voxels.map(v => ({ value: (v.ab + 0.5) * BIN_W - AB_OFFSET, weight: v.count })),
  );
  const b = weightedMedian(
    voxels.map(v => ({ value: (v.bb + 0.5) * BIN_W - AB_OFFSET, weight: v.count })),
  );

  return { L, a, b, count };
}

// ---------------------------------------------------------------------------
// Consolidation
// ---------------------------------------------------------------------------

function scaledDeltaE(a: ScaledColor, b: ScaledColor): number {
  const dL = a.L - b.L;
  const da = a.a - b.a;
  const db = a.b - b.b;
  return Math.sqrt(dL * dL + da * da + db * db);
}

interface ClusterEntry {
  color: ScaledColor;
  voxels: Voxel[];
}

function consolidate(entries: ClusterEntry[], threshold: number): ClusterEntry[] {
  let merged = true;
  while (merged) {
    merged = false;
    for (let i = 0; i < entries.length && !merged; i++) {
      for (let j = i + 1; j < entries.length; j++) {
        if (scaledDeltaE(entries[i].color, entries[j].color) < threshold) {
          entries[i].voxels = entries[i].voxels.concat(entries[j].voxels);
          entries[i].color = clusterMedianColor(entries[i].voxels);
          entries.splice(j, 1);
          merged = true;
          break;
        }
      }
    }
  }
  return entries;
}

// ---------------------------------------------------------------------------
// Main API
// ---------------------------------------------------------------------------

/**
 * Extract a stable palette from a pre-built (and optionally pre-merged) voxel grid.
 * This is the smooth+extract half of `extractPalette`, separated so that callers
 * can bin multiple images first and run smoothing/extraction only once on the union.
 */
export function extractPaletteFromVoxels(
  grid: VoxelGrid,
  options?: PaletteOptions,
): PaletteEntry[] {
  const smoothRadiusL = options?.smoothRadiusL ?? 6;
  const smoothRadiusAB = options?.smoothRadiusAB ?? 2;
  const smoothSigmaL = options?.smoothSigmaL ?? 5.0;
  const smoothSigmaAB = options?.smoothSigmaAB ?? 1.5;
  const minClusterFrac = options?.minClusterFraction ?? 0.005;
  const mergeThresh = options?.mergeThreshold ?? 3.0;

  const { voxels, totalChromatic } = grid;
  if (totalChromatic === 0) return [];

  console.log(
    `[palette] ${totalChromatic} chromatic pixels, ${voxels.size} voxels`,
  );

  // 1. Smooth with anisotropic 3D Gaussian (more blur on L, less on a/b)
  const t0 = performance.now();
  const smoothed = smoothVoxelGrid(voxels, smoothRadiusL, smoothSigmaL, smoothRadiusAB, smoothSigmaAB);
  const t1 = performance.now();
  console.log(`[palette] smoothed to ${smoothed.size} voxels in ${(t1 - t0).toFixed(1)}ms (rL=${smoothRadiusL}, σL=${smoothSigmaL}, rAB=${smoothRadiusAB}, σab=${smoothSigmaAB})`);

  // 2. Find local maxima
  const peaks = findLocalMaxima(smoothed);
  const t2 = performance.now();
  console.log(`[palette] found ${peaks.length} local maxima in ${(t2 - t1).toFixed(1)}ms`);

  if (peaks.length === 0) return [];

  // 3. Assign every original voxel to nearest peak
  const clusters = assignVoxelsToPeaks(voxels, peaks);

  // 4. Compute median colors, discard small clusters
  const minClusterSize = Math.round(totalChromatic * minClusterFrac);
  let entries: ClusterEntry[] = [];
  for (const cluster of clusters) {
    if (cluster.length === 0) continue;
    const color = clusterMedianColor(cluster);
    if (color.count >= minClusterSize) {
      entries.push({ color, voxels: cluster });
    }
  }

  if (entries.length === 0) return [];

  console.log(`[palette] ${entries.length} clusters after size filter (min ${minClusterSize})`);

  // 5. Consolidation pass
  entries = consolidate(entries, mergeThresh);
  console.log(`[palette] ${entries.length} entries after consolidation (thresh ${mergeThresh})`);

  // 6. Sort by descending pixel count
  entries.sort((a, b) => b.color.count - a.color.count);

  // 7. Convert to output format
  return entries.map((e) => {
    const rawL = e.color.L / SCALE;
    const rawA = e.color.a / SCALE;
    const rawB = e.color.b / SCALE;
    const [r, g, bRgb] = oklabToSrgb(rawL, rawA, rawB);
    return {
      oklab: [rawL, rawA, rawB] as [number, number, number],
      rgb: [r, g, bRgb] as [number, number, number],
      count: e.color.count,
      fraction: e.color.count / totalChromatic,
    };
  });
}

/**
 * Extract a stable palette from an RGBA image using local maxima
 * in a smoothed 3D Oklab histogram.
 *
 * Black and white pixels (Oklab L < 0.05 or > 0.95) are excluded
 * automatically. Returns palette entries sorted by descending pixel count.
 */
export function extractPalette(
  src: RGBAImage,
  options?: PaletteOptions,
): PaletteEntry[] {
  return extractPaletteFromVoxels(buildVoxelGrid(src), options);
}

// ---------------------------------------------------------------------------
// Black / White pixel counts
// ---------------------------------------------------------------------------

export interface BWCounts {
  /** Pixels with OKLab L < 0.05 (scaled L < 5). */
  blackCount: number;
  /** Average sRGB of "black" pixels. */
  blackRgb: [number, number, number];
  /** Pixels with OKLab L > 0.95 (scaled L > 95). */
  whiteCount: number;
  /** Average sRGB of "white" pixels. */
  whiteRgb: [number, number, number];
  /** Total pixel count (black + white + chromatic). */
  totalPixels: number;
}

/**
 * Count black and white pixels that are excluded by `extractPalette()`.
 * Returns counts and average RGB for each band, plus the total pixel count.
 */
export function extractBWCounts(src: RGBAImage): BWCounts {
  const { data, width, height } = src;
  const n = width * height;
  let blackCount = 0;
  let whiteCount = 0;
  let bR = 0, bG = 0, bB = 0;
  let wR = 0, wG = 0, wB = 0;

  for (let i = 0; i < n; i++) {
    const off = i * 4;
    const r = data[off], g = data[off + 1], b = data[off + 2];
    const [L] = srgbToOklab(r, g, b);
    const Ls = L * SCALE;
    if (Ls < L_BLACK_S) {
      blackCount++;
      bR += r; bG += g; bB += b;
    } else if (Ls > L_WHITE_S) {
      whiteCount++;
      wR += r; wG += g; wB += b;
    }
  }

  return {
    blackCount,
    blackRgb: blackCount > 0
      ? [Math.round(bR / blackCount), Math.round(bG / blackCount), Math.round(bB / blackCount)]
      : [0, 0, 0],
    whiteCount,
    whiteRgb: whiteCount > 0
      ? [Math.round(wR / whiteCount), Math.round(wG / whiteCount), Math.round(wB / whiteCount)]
      : [255, 255, 255],
    totalPixels: n,
  };
}
/**
 * Merge BWCounts statistics from multiple pages into a single aggregate.
 * RGB averages are re-weighted by pixel count so they remain accurate.
 */
export function mergeBWCounts(counts: BWCounts[]): BWCounts {
  let blackCount = 0, whiteCount = 0, totalPixels = 0;
  let bR = 0, bG = 0, bB = 0;
  let wR = 0, wG = 0, wB = 0;

  for (const c of counts) {
    blackCount += c.blackCount;
    whiteCount += c.whiteCount;
    totalPixels += c.totalPixels;
    bR += c.blackRgb[0] * c.blackCount;
    bG += c.blackRgb[1] * c.blackCount;
    bB += c.blackRgb[2] * c.blackCount;
    wR += c.whiteRgb[0] * c.whiteCount;
    wG += c.whiteRgb[1] * c.whiteCount;
    wB += c.whiteRgb[2] * c.whiteCount;
  }

  return {
    blackCount,
    blackRgb: blackCount > 0
      ? [Math.round(bR / blackCount), Math.round(bG / blackCount), Math.round(bB / blackCount)]
      : [0, 0, 0],
    whiteCount,
    whiteRgb: whiteCount > 0
      ? [Math.round(wR / whiteCount), Math.round(wG / whiteCount), Math.round(wB / whiteCount)]
      : [255, 255, 255],
    totalPixels,
  };
}