/**
 * Virtual page layout for the multi-page viewer.
 *
 * Computes vertical arrangement of pages in a virtual coordinate space
 * measured in image pixels at a reference DPI (200). Pages are centered
 * horizontally within the widest page's width.
 */

import type { PageSize } from "../../src/pdf/pdf_render.ts";
import { snapToCleanUnit } from "../../src/pdf/pdf_render.ts";

/** Layout info for one page in virtual space. */
export interface PageLayout {
  pageNumber: number;
  /** Displayed width in virtual pixels (crop width if cropped). */
  width: number;
  /** Displayed height in virtual pixels (crop height if cropped). */
  height: number;
  /** Displayed width in inches. */
  widthInches: number;
  /** Displayed height in inches. */
  heightInches: number;
  /** Y offset of this page's top edge in virtual space. */
  yOffset: number;
  /** Full page width in virtual pixels (for UV mapping). */
  fullWidth: number;
  /** Full page height in virtual pixels (for UV mapping). */
  fullHeight: number;
  /** Source X offset within the full page (0 if not cropped). */
  srcX: number;
  /** Source Y offset within the full page (0 if not cropped). */
  srcY: number;
}

/** Result of layout computation. */
export interface LayoutResult {
  pages: PageLayout[];
  /** Total height of all pages + gaps in virtual pixels. */
  totalHeight: number;
  /** Maximum page width in virtual pixels. */
  maxWidth: number;
}

/** Gap between pages in virtual pixels. */
export const PAGE_GAP = 50;

/**
 * Compute layout for selected pages.
 *
 * @param selectedPages - 1-indexed page numbers, sorted ascending.
 * @param pageSizes - All page sizes from the PDF (0-indexed).
 * @param dpi - Reference DPI for virtual coordinates (typically 200).
 * @param cropRects - Optional crop rects (in virtual pixels at reference DPI).
 *   When provided, pages are laid out using crop dimensions.
 */
export function computePageLayout(
  selectedPages: number[],
  pageSizes: PageSize[],
  dpi: number,
  cropRects?: Map<number, { x: number; y: number; width: number; height: number }>,
): LayoutResult {
  const pages: PageLayout[] = [];
  let yOffset = 0;
  let maxWidth = 0;

  for (const pageNum of selectedPages) {
    const size = pageSizes[pageNum - 1]; // pageSizes is 0-indexed
    const fullWidthInches = size.widthPt / 72;
    const fullHeightInches = size.heightPt / 72;
    const fullWidth = Math.round(snapToCleanUnit(fullWidthInches, dpi) * dpi);
    const fullHeight = Math.round(snapToCleanUnit(fullHeightInches, dpi) * dpi);

    const crop = cropRects?.get(pageNum);
    const width = crop ? crop.width : fullWidth;
    const height = crop ? crop.height : fullHeight;
    const srcX = crop ? crop.x : 0;
    const srcY = crop ? crop.y : 0;
    const widthInches = width / dpi;
    const heightInches = height / dpi;

    pages.push({
      pageNumber: pageNum,
      width,
      height,
      widthInches,
      heightInches,
      yOffset,
      fullWidth,
      fullHeight,
      srcX,
      srcY,
    });

    maxWidth = Math.max(maxWidth, width);
    yOffset += height + PAGE_GAP;
  }

  // Total height: remove the trailing gap
  const totalHeight = yOffset > 0 ? yOffset - PAGE_GAP : 0;

  return { pages, totalHeight, maxWidth };
}

/**
 * Get the range of pages visible in the viewport.
 *
 * Returns [firstIndex, lastIndex] inclusive into layout.pages,
 * or [-1, -1] if no pages are visible.
 *
 * @param viewportTop - Top of viewport in virtual Y coordinates.
 * @param viewportBottom - Bottom of viewport in virtual Y coordinates.
 */
export function visiblePageRange(
  layout: LayoutResult,
  viewportTop: number,
  viewportBottom: number,
): [number, number] {
  let first = -1;
  let last = -1;

  for (let i = 0; i < layout.pages.length; i++) {
    const page = layout.pages[i];
    const pageTop = page.yOffset;
    const pageBottom = page.yOffset + page.height;

    // Page is visible if it overlaps the viewport
    if (pageBottom > viewportTop && pageTop < viewportBottom) {
      if (first === -1) first = i;
      last = i;
    }
  }

  return [first, last];
}

/**
 * Find which page a virtual-space point falls on.
 *
 * Returns null if the point is in a gap between pages or outside.
 * The X coordinate is checked against the page's centered position.
 */
export function pageAtVirtualPoint(
  layout: LayoutResult,
  vx: number,
  vy: number,
): PageLayout | null {
  for (const page of layout.pages) {
    const pageTop = page.yOffset;
    const pageBottom = page.yOffset + page.height;

    if (vy >= pageTop && vy < pageBottom) {
      // Check horizontal bounds (pages are centered)
      const pageLeft = (layout.maxWidth - page.width) / 2;
      const pageRight = pageLeft + page.width;
      if (vx >= pageLeft && vx < pageRight) {
        return page;
      }
    }
  }
  return null;
}

/**
 * Find the page closest to the viewport center.
 * Used for active page tracking.
 */
export function pageClosestToCenter(
  layout: LayoutResult,
  viewportCenterY: number,
): PageLayout | null {
  if (layout.pages.length === 0) return null;

  let closest: PageLayout | null = null;
  let closestDist = Infinity;

  for (const page of layout.pages) {
    const pageCenterY = page.yOffset + page.height / 2;
    const dist = Math.abs(pageCenterY - viewportCenterY);
    if (dist < closestDist) {
      closestDist = dist;
      closest = page;
    }
  }

  return closest;
}
