/**
 * GPU-accelerated OKLab histogram building.
 *
 * Replaces the CPU-side `buildVoxelGrid` + `extractBWCounts` pair with a
 * single WebGPU compute dispatch that:
 *   1. Converts every pixel to OKLab in the shader.
 *   2. Accumulates a dense 3D histogram (101×101×101 bins, ~4 MB) via
 *      atomic increments for chromatic pixels.
 *   3. Accumulates black / white pixel counts and shifted RGB sums (5-bit
 *      per channel, safe against u32 overflow up to ~88 Mpx per page).
 *
 * On readback the dense histogram is converted to the same sparse VoxelGrid
 * format that `extractPaletteFromVoxels` expects, so downstream code is
 * unchanged.
 */

import type { RGBAImage } from "../formats/rgba_image.ts";
import type { Voxel, VoxelGrid, BWCounts } from "../color/palette.ts";
import oklabHistogramShader from "./shaders/oklab_histogram.wgsl?raw";

// ---------------------------------------------------------------------------
// Constants — must match palette.ts and the WGSL shader
// ---------------------------------------------------------------------------

const GRID_DIM  = 101;
const HIST_SIZE = GRID_DIM * GRID_DIM * GRID_DIM; // 1,030,301

// ---------------------------------------------------------------------------
// Pipeline cache (invalidated on device loss)
// ---------------------------------------------------------------------------

interface PipelineCache {
  device:   GPUDevice;
  pipeline: GPUComputePipeline;
  bgl:      GPUBindGroupLayout;
}

let cachedPipeline: PipelineCache | null = null;

function getOrCreatePipeline(device: GPUDevice): PipelineCache {
  if (cachedPipeline && cachedPipeline.device !== device) {
    cachedPipeline = null;
  }
  if (cachedPipeline) return cachedPipeline;

  const bgl = device.createBindGroupLayout({
    entries: [
      { binding: 0, visibility: GPUShaderStage.COMPUTE, texture: { sampleType: "float" } },
      { binding: 1, visibility: GPUShaderStage.COMPUTE, buffer:  { type: "uniform" } },
      { binding: 2, visibility: GPUShaderStage.COMPUTE, buffer:  { type: "storage" } },
      { binding: 3, visibility: GPUShaderStage.COMPUTE, buffer:  { type: "storage" } },
    ],
  });

  const module = device.createShaderModule({ code: oklabHistogramShader });

  const pipeline = device.createComputePipeline({
    layout: device.createPipelineLayout({ bindGroupLayouts: [bgl] }),
    compute: { module, entryPoint: "main" },
  });

  cachedPipeline = { device, pipeline, bgl };
  return cachedPipeline;
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

export interface HistogramResult {
  grid: VoxelGrid;
  bw:   BWCounts;
}

/**
 * Build an OKLab voxel histogram and black/white counts for `image` on the GPU.
 *
 * This is a drop-in GPU replacement for calling both `buildVoxelGrid(image)`
 * and `extractBWCounts(image)` from palette.ts — cheaper because a single
 * pass over the image handles both, and the per-pixel OKLab math runs on the
 * GPU's parallel ALUs.
 *
 * @param device  Shared WebGPU device from `getGPUContext()`.
 * @param image   Source image in CPU memory (RGBA8, fully opaque).
 * @returns       Sparse VoxelGrid (compatible with `extractPaletteFromVoxels`)
 *                and BWCounts (compatible with `createEditablePalette`).
 */
export async function buildVoxelGridGPU(
  device: GPUDevice,
  image:  RGBAImage,
): Promise<HistogramResult> {
  const { pipeline, bgl } = getOrCreatePipeline(device);

  // ── Input texture ───────────────────────────────────────────────────────
  const texture = device.createTexture({
    size:   { width: image.width, height: image.height },
    format: "rgba8unorm",
    usage:  GPUTextureUsage.TEXTURE_BINDING | GPUTextureUsage.COPY_DST,
  });
  device.queue.writeTexture(
    { texture },
    image.data as unknown as Uint8ClampedArray<ArrayBuffer>,
    { bytesPerRow: image.width * 4 },
    { width: image.width, height: image.height },
  );

  // ── Uniform buffer ──────────────────────────────────────────────────────
  // 4 × u32 = 16 bytes (meets 16-byte uniform alignment).
  const dimsData = new Uint32Array([image.width, image.height, 0, 0]);
  const dimsBuffer = device.createBuffer({
    size:             dimsData.byteLength,
    usage:            GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST,
    mappedAtCreation: true,
  });
  new Uint32Array(dimsBuffer.getMappedRange()).set(dimsData);
  dimsBuffer.unmap();

  // ── Histogram storage buffer (101³ × u32 ≈ 4 MB) ───────────────────────
  const histBuffer = device.createBuffer({
    size:  HIST_SIZE * 4,
    usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_SRC | GPUBufferUsage.COPY_DST,
  });

  // ── BW stats buffer (8 × u32 = 32 bytes) ───────────────────────────────
  const bwBuffer = device.createBuffer({
    size:  8 * 4,
    usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_SRC | GPUBufferUsage.COPY_DST,
  });

  // ── Staging buffers for readback ────────────────────────────────────────
  const histStaging = device.createBuffer({
    size:  HIST_SIZE * 4,
    usage: GPUBufferUsage.COPY_DST | GPUBufferUsage.MAP_READ,
  });
  const bwStaging = device.createBuffer({
    size:  8 * 4,
    usage: GPUBufferUsage.COPY_DST | GPUBufferUsage.MAP_READ,
  });

  // ── Bind group ──────────────────────────────────────────────────────────
  const bindGroup = device.createBindGroup({
    layout: bgl,
    entries: [
      { binding: 0, resource: texture.createView() },
      { binding: 1, resource: { buffer: dimsBuffer } },
      { binding: 2, resource: { buffer: histBuffer } },
      { binding: 3, resource: { buffer: bwBuffer } },
    ],
  });

  // ── Single command encoder: clear → compute → copy to staging ──────────
  const encoder = device.createCommandEncoder();
  encoder.clearBuffer(histBuffer);
  encoder.clearBuffer(bwBuffer);

  const pass = encoder.beginComputePass();
  pass.setPipeline(pipeline);
  pass.setBindGroup(0, bindGroup);
  pass.dispatchWorkgroups(
    Math.ceil(image.width  / 8),
    Math.ceil(image.height / 8),
  );
  pass.end();

  encoder.copyBufferToBuffer(histBuffer, 0, histStaging, 0, HIST_SIZE * 4);
  encoder.copyBufferToBuffer(bwBuffer,   0, bwStaging,   0, 8 * 4);

  device.queue.submit([encoder.finish()]);

  // ── Map staging buffers (GPU signals completion implicitly) ─────────────
  // Wrap in try/finally so all transient GPU objects are released even if
  // mapAsync is aborted (e.g. device lost).
  let histData: Uint32Array;
  let bwData: Uint32Array;
  try {
    await Promise.all([
      histStaging.mapAsync(GPUMapMode.READ),
      bwStaging.mapAsync(GPUMapMode.READ),
    ]);

    // Slice out copies before unmapping so they remain valid.
    histData = new Uint32Array(histStaging.getMappedRange()).slice();
    bwData   = new Uint32Array(bwStaging.getMappedRange()).slice();

    histStaging.unmap();
    bwStaging.unmap();
  } finally {
    // ── Release transient GPU objects ─────────────────────────────────────
    texture.destroy();
    dimsBuffer.destroy();
    histBuffer.destroy();
    bwBuffer.destroy();
    histStaging.destroy();
    bwStaging.destroy();
  }

  // ── Dense histogram → sparse VoxelGrid ─────────────────────────────────
  // The histogram index equals packKey(Lb, ab, bb) from palette.ts, so we
  // can use it directly as the Map key — no re-encoding needed.
  const voxels = new Map<number, Voxel>();
  let totalChromatic = 0;

  for (let Lb = 0; Lb < GRID_DIM; Lb++) {
    for (let ab = 0; ab < GRID_DIM; ab++) {
      for (let bb = 0; bb < GRID_DIM; bb++) {
        const idx   = Lb * GRID_DIM * GRID_DIM + ab * GRID_DIM + bb;
        const count = histData[idx];
        if (count > 0) {
          voxels.set(idx, { Lb, ab, bb, count });
          totalChromatic += count;
        }
      }
    }
  }

  // ── BWCounts ────────────────────────────────────────────────────────────
  // Shader accumulated shifted (>> 3) channel values; multiply by 8 to recover.
  const blackCount = bwData[0];
  const whiteCount = bwData[4];

  const bw: BWCounts = {
    blackCount,
    blackRgb: blackCount > 0
      ? [
          Math.round(bwData[1] * 8 / blackCount),
          Math.round(bwData[2] * 8 / blackCount),
          Math.round(bwData[3] * 8 / blackCount),
        ]
      : [0, 0, 0],
    whiteCount,
    whiteRgb: whiteCount > 0
      ? [
          Math.round(bwData[5] * 8 / whiteCount),
          Math.round(bwData[6] * 8 / whiteCount),
          Math.round(bwData[7] * 8 / whiteCount),
        ]
      : [255, 255, 255],
    totalPixels: blackCount + whiteCount + totalChromatic,
  };

  return { grid: { voxels, totalChromatic }, bw };
}
