/**
 * Editable palette — types and pure state functions.
 *
 * The palette is modeled as two separate lists:
 *   - **Inputs**: colors detected in the image (from extraction). Fixed —
 *     the user can enable/disable them but cannot change their color.
 *   - **Outputs**: target colors for the final image. Editable — the user
 *     can add, remove, and change these.
 *
 * Each enabled input maps to exactly one output. Disabled inputs map to
 * the designated background output. Multiple inputs can map to the same
 * output (this is how "merge" works conceptually).
 *
 * All mutation functions return new objects (immutable pattern).
 */

import type { PaletteEntry, BWCounts } from "./palette.ts";
import { srgbToOklab } from "./palette.ts";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

/** Role hint for an input color. */
export type ColorRole = "background" | "stroke" | "chromatic";

/** An input color detected in the image. */
export interface PaletteInput {
  id: string;
  /** OKLab cluster center (for nearest-neighbor matching). */
  oklab: [number, number, number];
  /** sRGB for display. */
  rgb: [number, number, number];
  /** Pixel count from extraction (0 for user-added). */
  count: number;
  /** Fraction of total pixels (including B/W). */
  fraction: number;
  /** Whether this input is enabled (disabled → maps to background). */
  enabled: boolean;
  /** Auto-detected role hint. */
  role: ColorRole;
  /** ID of the output this input maps to. */
  outputId: string;
}

/** A user-editable output color. */
export interface PaletteOutput {
  id: string;
  /** sRGB color (user-editable). */
  rgb: [number, number, number];
  /** OKLab (derived from rgb). */
  oklab: [number, number, number];
  /** Whether this is the background output. */
  isBackground: boolean;
}

/** Full editable palette state. */
export interface EditablePalette {
  inputs: PaletteInput[];
  outputs: PaletteOutput[];
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

let _nextId = 0;
function genId(prefix: string): string {
  return `${prefix}-${_nextId++}`;
}

function rgbEqual(a: [number, number, number], b: [number, number, number]): boolean {
  return a[0] === b[0] && a[1] === b[1] && a[2] === b[2];
}

export { rgbEqual };

// ---------------------------------------------------------------------------
// Creation
// ---------------------------------------------------------------------------

/**
 * Build an editable palette from extracted palette entries and B/W counts.
 *
 * Each input gets a corresponding output with the same color. The majority
 * B/W color is designated as background.
 */
export function createEditablePalette(
  entries: PaletteEntry[],
  bw: BWCounts,
): EditablePalette {
  const inputs: PaletteInput[] = [];
  const outputs: PaletteOutput[] = [];

  const blackIsBg = bw.blackCount >= bw.whiteCount;

  // Helper to add an input+output pair
  function addPair(
    rgb: [number, number, number],
    oklab: [number, number, number],
    count: number,
    fraction: number,
    role: ColorRole,
  ): void {
    const inId = genId("in");
    const outId = genId("out");
    inputs.push({
      id: inId,
      oklab: [...oklab],
      rgb: [...rgb],
      count,
      fraction,
      enabled: true,
      role,
      outputId: outId,
    });
    outputs.push({
      id: outId,
      rgb: [...rgb],
      oklab: [...oklab],
      isBackground: role === "background",
    });
  }

  // Black
  if (bw.blackCount > 0) {
    const oklab = srgbToOklab(bw.blackRgb[0], bw.blackRgb[1], bw.blackRgb[2]);
    addPair(
      [...bw.blackRgb], oklab,
      bw.blackCount, bw.blackCount / bw.totalPixels,
      blackIsBg ? "background" : "stroke",
    );
  }

  // White
  if (bw.whiteCount > 0) {
    const oklab = srgbToOklab(bw.whiteRgb[0], bw.whiteRgb[1], bw.whiteRgb[2]);
    addPair(
      [...bw.whiteRgb], oklab,
      bw.whiteCount, bw.whiteCount / bw.totalPixels,
      blackIsBg ? "stroke" : "background",
    );
  }

  // Chromatic
  for (const e of entries) {
    addPair(
      [...e.rgb], [...e.oklab],
      e.count, e.count / bw.totalPixels,
      "chromatic",
    );
  }

  // Sort inputs: background first, then stroke, then chromatic by desc count
  const roleOrder: Record<ColorRole, number> = { background: 0, stroke: 1, chromatic: 2 };
  inputs.sort((a, b) => {
    const ro = roleOrder[a.role] - roleOrder[b.role];
    if (ro !== 0) return ro;
    return b.count - a.count;
  });

  // Sort outputs to match input order
  const outputOrder = new Map(inputs.map((inp, i) => [inp.outputId, i]));
  outputs.sort((a, b) => (outputOrder.get(a.id) ?? 999) - (outputOrder.get(b.id) ?? 999));

  return { inputs, outputs };
}

// ---------------------------------------------------------------------------
// Input mutations
// ---------------------------------------------------------------------------

export function toggleInput(palette: EditablePalette, id: string): EditablePalette {
  return {
    ...palette,
    inputs: palette.inputs.map((inp) =>
      inp.id === id ? { ...inp, enabled: !inp.enabled } : inp
    ),
  };
}

/**
 * Add a new user-defined input color with a corresponding output.
 * Returns [updatedPalette, newInputId].
 */
export function addInput(
  palette: EditablePalette,
  rgb: [number, number, number],
): [EditablePalette, string] {
  const oklab = srgbToOklab(rgb[0], rgb[1], rgb[2]);
  const inId = genId("in");
  const outId = genId("out");
  const input: PaletteInput = {
    id: inId,
    oklab,
    rgb: [...rgb],
    count: 0,
    fraction: 0,
    enabled: true,
    role: "chromatic",
    outputId: outId,
  };
  const output: PaletteOutput = {
    id: outId,
    rgb: [...rgb],
    oklab: [...oklab],
    isBackground: false,
  };
  return [{
    inputs: [...palette.inputs, input],
    outputs: [...palette.outputs, output],
  }, inId];
}

/** Remove an input. Also removes its output if no other input uses it. */
export function removeInput(
  palette: EditablePalette,
  inputId: string,
): EditablePalette {
  const removing = palette.inputs.find((i) => i.id === inputId);
  if (!removing) return palette;

  const newInputs = palette.inputs.filter((i) => i.id !== inputId);

  // Remove orphaned output (if no other input points to it)
  const outputStillUsed = newInputs.some((i) => i.outputId === removing.outputId);
  const newOutputs = outputStillUsed
    ? palette.outputs
    : palette.outputs.filter((o) => o.id !== removing.outputId);

  return { inputs: newInputs, outputs: newOutputs };
}

/** Reassign an input to map to a different output. */
export function assignInput(
  palette: EditablePalette,
  inputId: string,
  outputId: string,
): EditablePalette {
  return {
    ...palette,
    inputs: palette.inputs.map((inp) =>
      inp.id === inputId ? { ...inp, outputId } : inp
    ),
  };
}

// ---------------------------------------------------------------------------
// Output mutations
// ---------------------------------------------------------------------------

export function setOutputColor(
  palette: EditablePalette,
  outputId: string,
  rgb: [number, number, number],
): EditablePalette {
  const oklab = srgbToOklab(rgb[0], rgb[1], rgb[2]);
  return {
    ...palette,
    outputs: palette.outputs.map((out) =>
      out.id === outputId
        ? { ...out, rgb: [...rgb] as [number, number, number], oklab }
        : out
    ),
  };
}

export function setBackground(
  palette: EditablePalette,
  outputId: string,
): EditablePalette {
  return {
    ...palette,
    outputs: palette.outputs.map((out) => ({
      ...out,
      isBackground: out.id === outputId,
    })),
  };
}

/** Add a new output color. Returns [updatedPalette, newOutputId]. */
export function addOutput(
  palette: EditablePalette,
  rgb: [number, number, number],
): [EditablePalette, string] {
  const oklab = srgbToOklab(rgb[0], rgb[1], rgb[2]);
  const id = genId("out");
  const output: PaletteOutput = {
    id,
    rgb: [...rgb],
    oklab,
    isBackground: false,
  };
  return [{ ...palette, outputs: [...palette.outputs, output] }, id];
}

/** Remove an output. Inputs mapped to it get reassigned to the background output. */
export function removeOutput(
  palette: EditablePalette,
  outputId: string,
): EditablePalette {
  const removing = palette.outputs.find((o) => o.id === outputId);
  if (!removing || removing.isBackground) return palette; // can't remove background
  if (palette.outputs.length <= 1) return palette;

  const bgOutput = palette.outputs.find((o) => o.isBackground);
  const fallbackId = bgOutput?.id ?? palette.outputs[0].id;

  return {
    inputs: palette.inputs.map((inp) =>
      inp.outputId === outputId ? { ...inp, outputId: fallbackId } : inp
    ),
    outputs: palette.outputs.filter((o) => o.id !== outputId),
  };
}

// ---------------------------------------------------------------------------
// Merge (convenience: reassign all inputs of one output to another)
// ---------------------------------------------------------------------------

/**
 * Merge: reassign all inputs currently pointing at `fromOutputId` to
 * `toOutputId`, then remove the now-unused `fromOutputId`.
 */
export function mergeOutputs(
  palette: EditablePalette,
  fromOutputId: string,
  toOutputId: string,
): EditablePalette {
  if (fromOutputId === toOutputId) return palette;

  const updated: EditablePalette = {
    inputs: palette.inputs.map((inp) =>
      inp.outputId === fromOutputId ? { ...inp, outputId: toOutputId } : inp
    ),
    outputs: palette.outputs,
  };

  // Transfer background status if needed
  const fromOut = palette.outputs.find((o) => o.id === fromOutputId);
  if (fromOut?.isBackground) {
    updated.outputs = updated.outputs.map((o) => ({
      ...o,
      isBackground: o.id === toOutputId ? true : (o.id === fromOutputId ? false : o.isBackground),
    }));
  }

  // Remove the from-output if no inputs point to it anymore
  const stillUsed = updated.inputs.some((inp) => inp.outputId === fromOutputId);
  if (!stillUsed) {
    updated.outputs = updated.outputs.filter((o) => o.id !== fromOutputId);
  }

  return updated;
}

// ---------------------------------------------------------------------------
// Query helpers
// ---------------------------------------------------------------------------

/** Get the background output. */
export function getBackgroundOutput(palette: EditablePalette): PaletteOutput | undefined {
  return palette.outputs.find((o) => o.isBackground);
}

/** Get the output that an input maps to. */
export function getOutputForInput(palette: EditablePalette, inputId: string): PaletteOutput | undefined {
  const inp = palette.inputs.find((i) => i.id === inputId);
  if (!inp) return undefined;
  return palette.outputs.find((o) => o.id === inp.outputId);
}

/** Check if an input's output color differs from its input color. */
export function isRemapped(palette: EditablePalette, inputId: string): boolean {
  const inp = palette.inputs.find((i) => i.id === inputId);
  if (!inp) return false;
  const out = palette.outputs.find((o) => o.id === inp.outputId);
  if (!out) return false;
  return !rgbEqual(inp.rgb, out.rgb);
}

// ---------------------------------------------------------------------------
// Cross-page merge
// ---------------------------------------------------------------------------

/** Scale factor for OKLab distance (matches palette.ts SCALE=100). */
const OKLAB_SCALE = 100;

/** Distance threshold for considering two colors the same (matches consolidate threshold). */
const MERGE_THRESHOLD = 3.0;

/** Scaled Euclidean distance between two OKLab colors. */
function oklabDistance(a: [number, number, number], b: [number, number, number]): number {
  const dL = (a[0] - b[0]) * OKLAB_SCALE;
  const da = (a[1] - b[1]) * OKLAB_SCALE;
  const db = (a[2] - b[2]) * OKLAB_SCALE;
  return Math.sqrt(dL * dL + da * da + db * db);
}

/**
 * Merge newly extracted colors into an existing palette.
 *
 * - Colors close to an existing input (within MERGE_THRESHOLD) update
 *   counts/fractions but preserve the user's output mapping.
 * - Genuinely new colors are added as new input+output pairs.
 * - All fractions are recalculated from cumulative totals.
 */
export function mergePaletteWithExtraction(
  existing: EditablePalette,
  newEntries: PaletteEntry[],
  newBW: BWCounts,
): EditablePalette {
  // Build candidate list from the new extraction (same order as createEditablePalette)
  const blackIsBg = newBW.blackCount >= newBW.whiteCount;
  const candidates: {
    rgb: [number, number, number];
    oklab: [number, number, number];
    count: number;
    role: ColorRole;
  }[] = [];

  if (newBW.blackCount > 0) {
    const oklab = srgbToOklab(newBW.blackRgb[0], newBW.blackRgb[1], newBW.blackRgb[2]);
    candidates.push({
      rgb: [...newBW.blackRgb], oklab,
      count: newBW.blackCount,
      role: blackIsBg ? "background" : "stroke",
    });
  }
  if (newBW.whiteCount > 0) {
    const oklab = srgbToOklab(newBW.whiteRgb[0], newBW.whiteRgb[1], newBW.whiteRgb[2]);
    candidates.push({
      rgb: [...newBW.whiteRgb], oklab,
      count: newBW.whiteCount,
      role: blackIsBg ? "stroke" : "background",
    });
  }
  for (const e of newEntries) {
    candidates.push({
      rgb: [...e.rgb], oklab: [...e.oklab],
      count: e.count,
      role: "chromatic",
    });
  }

  // Clone existing inputs (will mutate counts)
  const inputs: PaletteInput[] = existing.inputs.map((inp) => ({ ...inp }));
  const outputs: PaletteOutput[] = [...existing.outputs];

  // Track which existing inputs got matched (to avoid double-matching)
  const matched = new Set<string>();

  for (const cand of candidates) {
    // Find closest existing input
    let bestIdx = -1;
    let bestDist = Infinity;
    for (let i = 0; i < inputs.length; i++) {
      if (matched.has(inputs[i].id)) continue;
      const d = oklabDistance(cand.oklab, inputs[i].oklab);
      if (d < bestDist) {
        bestDist = d;
        bestIdx = i;
      }
    }

    if (bestIdx >= 0 && bestDist < MERGE_THRESHOLD) {
      // Match: accumulate count, preserve mapping
      inputs[bestIdx].count += cand.count;
      matched.add(inputs[bestIdx].id);
    } else {
      // New color: add input+output pair
      const inId = genId("in");
      const outId = genId("out");
      inputs.push({
        id: inId,
        oklab: [...cand.oklab],
        rgb: [...cand.rgb],
        count: cand.count,
        fraction: 0, // recalculated below
        enabled: true,
        role: cand.role,
        outputId: outId,
      });
      outputs.push({
        id: outId,
        rgb: [...cand.rgb],
        oklab: [...cand.oklab],
        isBackground: false, // new outputs are not background by default
      });
    }
  }

  // Recalculate fractions from cumulative counts
  const totalCount = inputs.reduce((sum, inp) => sum + inp.count, 0);
  for (const inp of inputs) {
    inp.fraction = totalCount > 0 ? inp.count / totalCount : 0;
  }

  return { inputs, outputs };
}
