/**
 * IndexedDB storage for uploaded PDF files.
 *
 * Persists files across page reloads so users don't need to re-upload.
 * Each file is stored with its raw bytes, name, and upload timestamp.
 */

import type { RGBAImage } from "../src/formats/rgba_image.ts";

const DB_NAME = "CleanPlansDB";
const DB_VERSION = 5;
const STORE_NAME = "files";
const CROP_STORE = "cropRects";
const PALETTE_STORE = "palettes";
const DENOISED_STORE = "denoisedImages";
const PAGE_SEL_STORE = "pageSelections";
const RENDER_CACHE_STORE = "renderCache";

export interface StoredFile {
  id: string;
  name: string;
  type: string;
  data: Uint8Array;
  uploadedAt: number;
  thumbnail?: string; // base64 data URL for the file list
}

export interface StoredPalette {
  fileId: string;
  // deno-lint-ignore no-explicit-any
  palette: any; // EditablePalette — stored as plain JSON
}

export interface StoredDenoisedImage {
  fileId: string;
  pageNumber: number;
  pngBlob: Blob;
  width: number;
  height: number;
}

export interface StoredPageSelection {
  fileId: string;
  selectedPages: number[];
  coverPage: number;
}

export interface StoredCropRect {
  fileId: string;
  pageNumber: number;
  x: number;
  y: number;
  width: number;
  height: number;
}

export interface StoredRenderCache {
  fileId: string;
  pageNumber: number;
  level: "thumbnail" | "overview" | "full" | "denoisedThumbnail" | "denoisedOverview";
  pngBlob: Blob;
  width: number;
  height: number;
}

let db: IDBDatabase | null = null;

function openDB(): Promise<IDBDatabase> {
  if (db) return Promise.resolve(db);

  // Request persistent storage (fire-and-forget)
  if (navigator.storage?.persist) {
    navigator.storage.persist().catch(() => {});
  }

  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onerror = () => reject(request.error);
    request.onsuccess = () => {
      db = request.result;
      resolve(db);
    };

    request.onupgradeneeded = (event) => {
      const target = (event.target as IDBOpenDBRequest).result;
      if (!target.objectStoreNames.contains(STORE_NAME)) {
        const store = target.createObjectStore(STORE_NAME, { keyPath: "id" });
        store.createIndex("uploadedAt", "uploadedAt", { unique: false });
      }
      if (!target.objectStoreNames.contains(CROP_STORE)) {
        target.createObjectStore(CROP_STORE, {
          keyPath: ["fileId", "pageNumber"],
        });
      }
      if (!target.objectStoreNames.contains(PALETTE_STORE)) {
        target.createObjectStore(PALETTE_STORE, { keyPath: "fileId" });
      }
      if (!target.objectStoreNames.contains(DENOISED_STORE)) {
        target.createObjectStore(DENOISED_STORE, {
          keyPath: ["fileId", "pageNumber"],
        });
      }
      if (!target.objectStoreNames.contains(PAGE_SEL_STORE)) {
        target.createObjectStore(PAGE_SEL_STORE, { keyPath: "fileId" });
      }
      if (!target.objectStoreNames.contains(RENDER_CACHE_STORE)) {
        target.createObjectStore(RENDER_CACHE_STORE, {
          keyPath: ["fileId", "pageNumber", "level"],
        });
      }
    };
  });
}

/** Save a file to IndexedDB. Returns the generated ID. */
export async function saveFile(file: File, thumbnail?: string): Promise<string> {
  const database = await openDB();
  const id = crypto.randomUUID();
  const arrayBuffer = await file.arrayBuffer();

  const storedFile: StoredFile = {
    id,
    name: file.name,
    type: file.type,
    data: new Uint8Array(arrayBuffer),
    uploadedAt: Date.now(),
    thumbnail,
  };

  return new Promise((resolve, reject) => {
    const tx = database.transaction([STORE_NAME], "readwrite");
    const store = tx.objectStore(STORE_NAME);
    const request = store.add(storedFile);
    request.onsuccess = () => resolve(id);
    request.onerror = () => reject(request.error);
  });
}

/** Update fields on an existing stored file (e.g. add thumbnail). */
export async function updateFile(
  id: string,
  updates: Partial<StoredFile>,
): Promise<void> {
  const database = await openDB();
  const existing = await getFile(id);
  if (!existing) throw new Error(`File ${id} not found`);

  const updated = { ...existing, ...updates };

  return new Promise((resolve, reject) => {
    const tx = database.transaction([STORE_NAME], "readwrite");
    const store = tx.objectStore(STORE_NAME);
    const request = store.put(updated);
    request.onsuccess = () => resolve();
    request.onerror = () => reject(request.error);
  });
}

/** Retrieve a single file by ID. */
export async function getFile(id: string): Promise<StoredFile | null> {
  const database = await openDB();

  return new Promise((resolve, reject) => {
    const tx = database.transaction([STORE_NAME], "readonly");
    const store = tx.objectStore(STORE_NAME);
    const request = store.get(id);
    request.onsuccess = () => resolve(request.result || null);
    request.onerror = () => reject(request.error);
  });
}

/** List all stored files, most recent first. */
export async function listFiles(): Promise<StoredFile[]> {
  const database = await openDB();

  return new Promise((resolve, reject) => {
    const tx = database.transaction([STORE_NAME], "readonly");
    const store = tx.objectStore(STORE_NAME);
    const request = store.getAll();
    request.onsuccess = () => {
      const files = request.result as StoredFile[];
      files.sort((a, b) => b.uploadedAt - a.uploadedAt);
      resolve(files);
    };
    request.onerror = () => reject(request.error);
  });
}

/** Delete a file by ID. */
export async function deleteFile(id: string): Promise<void> {
  const database = await openDB();

  return new Promise((resolve, reject) => {
    const tx = database.transaction([STORE_NAME], "readwrite");
    const store = tx.objectStore(STORE_NAME);
    const request = store.delete(id);
    request.onsuccess = () => resolve();
    request.onerror = () => reject(request.error);
  });
}

/** Delete all stored files. */
export async function clearAllFiles(): Promise<void> {
  const database = await openDB();

  return new Promise((resolve, reject) => {
    const tx = database.transaction([STORE_NAME], "readwrite");
    const store = tx.objectStore(STORE_NAME);
    const request = store.clear();
    request.onsuccess = () => resolve();
    request.onerror = () => reject(request.error);
  });
}

