/** Get all crop rectangles for a file (for dimension-based inheritance). */
export async function getCropRectsForFile(
  fileId: string,
): Promise<StoredCropRect[]> {
  const database = await openDB();
  return new Promise((resolve, reject) => {
    const tx = database.transaction([CROP_STORE], "readonly");
    const store = tx.objectStore(CROP_STORE);
    const request = store.getAll();
    request.onsuccess = () => {
      const all = request.result as StoredCropRect[];
      resolve(all.filter((r) => r.fileId === fileId));
    };
    request.onerror = () => reject(request.error);
  });
}

