// ---------------------------------------------------------------------------
// PNG encode/decode helpers (Canvas API, no external deps)
// ---------------------------------------------------------------------------

/** Encode an RGBAImage to a PNG Blob (off-main-thread via OffscreenCanvas). */
export function rgbaImageToPngBlob(image: RGBAImage): Promise<Blob> {
  const canvas = new OffscreenCanvas(image.width, image.height);
  const ctx = canvas.getContext("2d")!;
  ctx.putImageData(
    new ImageData(new Uint8ClampedArray(image.data), image.width, image.height),
    0, 0,
  );
  return canvas.convertToBlob({ type: "image/png" });
}

// ---------------------------------------------------------------------------
// Off-main-thread PNG decode via Web Worker
// ---------------------------------------------------------------------------

const DECODE_WORKER_CODE = `
self.onmessage = async (e) => {
  const { id, blob, width, height } = e.data;
  try {
    const bitmap = await createImageBitmap(blob);
    const canvas = new OffscreenCanvas(width, height);
    const ctx = canvas.getContext("2d");
    ctx.drawImage(bitmap, 0, 0);
    bitmap.close();
    const imageData = ctx.getImageData(0, 0, width, height);
    self.postMessage(
      { id, width, height, data: imageData.data },
      [imageData.data.buffer],
    );
  } catch (err) {
    self.postMessage({ id, error: err.message || String(err) });
  }
};
`;

let decodeWorker: Worker | null = null;
let nextDecodeId = 0;
const decodePending = new Map<
  number,
  { resolve: (img: RGBAImage) => void; reject: (err: Error) => void }
>();

function getDecodeWorker(): Worker {
  if (!decodeWorker) {
    const src = new Blob([DECODE_WORKER_CODE], { type: "application/javascript" });
    decodeWorker = new Worker(URL.createObjectURL(src));
    decodeWorker.onmessage = (e) => {
      const { id, error, width, height, data } = e.data;
      const pending = decodePending.get(id);
      if (!pending) return;
      decodePending.delete(id);
      if (error) {
        pending.reject(new Error(error));
      } else {
        pending.resolve({ width, height, data });
      }
    };
  }
  return decodeWorker;
}

/**
 * Decode a PNG Blob to an RGBAImage **off the main thread**.
 *
 * Uses a dedicated Web Worker with OffscreenCanvas so the main thread
 * never blocks on drawImage / getImageData.
 */
export function pngBlobToRgbaImage(
  blob: Blob,
  width: number,
  height: number,
): Promise<RGBAImage> {
  const id = nextDecodeId++;
  return new Promise((resolve, reject) => {
    decodePending.set(id, { resolve, reject });
    getDecodeWorker().postMessage({ id, blob, width, height });
  });
}

// ---------------------------------------------------------------------------
// Render cache (multi-resolution page renders)
// ---------------------------------------------------------------------------

/** Save a cached page render (overview or full resolution). */
export async function saveRenderCache(entry: StoredRenderCache): Promise<void> {
  const database = await openDB();
  return new Promise((resolve, reject) => {
    const tx = database.transaction([RENDER_CACHE_STORE], "readwrite");
    const store = tx.objectStore(RENDER_CACHE_STORE);
    const request = store.put(entry);
    request.onsuccess = () => resolve();
    request.onerror = () => reject(request.error);
  });
}

/** Get a cached page render. */
export async function getRenderCache(
  fileId: string,
  pageNumber: number,
  level: StoredRenderCache["level"],
): Promise<StoredRenderCache | null> {
  const database = await openDB();
  return new Promise((resolve, reject) => {
    const tx = database.transaction([RENDER_CACHE_STORE], "readonly");
    const store = tx.objectStore(RENDER_CACHE_STORE);
    const request = store.get([fileId, pageNumber, level]);
    request.onsuccess = () => resolve(request.result || null);
    request.onerror = () => reject(request.error);
  });
}

/** Clear all cached renders for a file. */
export async function clearRenderCache(fileId: string): Promise<void> {
  const database = await openDB();
  return new Promise((resolve, reject) => {
    const tx = database.transaction([RENDER_CACHE_STORE], "readwrite");
    const store = tx.objectStore(RENDER_CACHE_STORE);
    const request = store.openCursor();
    request.onsuccess = () => {
      const cursor = request.result;
      if (cursor) {
        const entry = cursor.value as StoredRenderCache;
        if (entry.fileId === fileId) cursor.delete();
        cursor.continue();
      } else {
        resolve();
      }
    };
    request.onerror = () => reject(request.error);
  });
}
