/**
 * Upload screen: file selection via button or drag-and-drop,
 * plus a list of previously uploaded files from IndexedDB.
 */

import { state } from "../state.ts";
import type { StoredFile } from "../storage.ts";
import { listFiles, deleteFile, clearAllFiles } from "../storage.ts";

export interface UploadCallbacks {
  /** Called when the user selects a new file from disk. */
  onNewFile(file: File): void;
  /** Called when the user clicks a stored file to reopen it. */
  onStoredFileSelected(stored: StoredFile): void;
}

let callbacks: UploadCallbacks;

/**
 * Initialize the upload screen UI and event handlers.
 */
export function initUpload(cb: UploadCallbacks): void {
  callbacks = cb;
  const screen = document.getElementById("uploadScreen")!;
  const fileInput = document.getElementById("fileInput") as HTMLInputElement;
  const uploadBtn = document.getElementById("uploadBtn")!;
  const clearBtn = document.getElementById("clearAllBtn")!;

  uploadBtn.addEventListener("click", () => fileInput.click());

  fileInput.addEventListener("change", () => {
    const file = fileInput.files?.[0];
    if (file) handleFile(file);
    fileInput.value = "";
  });

  clearBtn.addEventListener("click", async () => {
    await clearAllFiles();
    await refreshFileList();
  });

  // Drag-and-drop
  screen.addEventListener("dragover", (e) => {
    e.preventDefault();
    screen.classList.add("drag-over");
  });

  screen.addEventListener("dragleave", () => {
    screen.classList.remove("drag-over");
  });

  screen.addEventListener("drop", (e) => {
    e.preventDefault();
    screen.classList.remove("drag-over");
    const file = e.dataTransfer?.files[0];
    if (file) handleFile(file);
  });

  // Initial file list load
  refreshFileList();
}

function handleFile(file: File): void {
  if (file.type !== "application/pdf") {
    state.statusMessage = "Please select a PDF file.";
    updateStatus();
    return;
  }
  callbacks.onNewFile(file);
}

/** Refresh the stored file list from IndexedDB. */
export async function refreshFileList(): Promise<void> {
  const container = document.getElementById("fileList")!;
  let files: StoredFile[];
  try {
    files = await listFiles();
  } catch {
    container.innerHTML = "";
    return;
  }

  if (files.length === 0) {
    container.innerHTML =
      '<div class="file-list-empty">No saved files</div>';
    return;
  }

  container.innerHTML = "";
  for (const f of files) {
    const row = document.createElement("div");
    row.className = "file-list-item";

    // Thumbnail (if available)
    if (f.thumbnail) {
      const thumb = document.createElement("img");
      thumb.className = "file-list-thumb";
      thumb.src = f.thumbnail;
      thumb.alt = "";
      row.appendChild(thumb);
    }

    const nameEl = document.createElement("span");
    nameEl.className = "file-list-name";
    nameEl.textContent = f.name;
    nameEl.title = f.name;

    const dateEl = document.createElement("span");
    dateEl.className = "file-list-date";
    dateEl.textContent = formatDate(f.uploadedAt);

    const deleteBtn = document.createElement("button");
    deleteBtn.className = "file-list-delete";
    deleteBtn.textContent = "\u00d7"; // ×
    deleteBtn.title = "Remove";
    deleteBtn.addEventListener("click", async (e) => {
      e.stopPropagation();
      await deleteFile(f.id);
      await refreshFileList();
    });

    row.appendChild(nameEl);
    row.appendChild(dateEl);
    row.appendChild(deleteBtn);

    row.addEventListener("click", () => {
      callbacks.onStoredFileSelected(f);
    });

    container.appendChild(row);
  }
}

function formatDate(timestamp: number): string {
  const d = new Date(timestamp);
  const month = d.toLocaleString("default", { month: "short" });
  const day = d.getDate();
  const time = d.toLocaleTimeString("default", {
    hour: "2-digit",
    minute: "2-digit",
  });
  return `${month} ${day}, ${time}`;
}

function updateStatus(): void {
  const el = document.getElementById("statusText");
  if (el) el.textContent = state.statusMessage;
}
