/**
 * Collapsing step list for the "Prepare" phase of the sidebar.
 *
 * The pipeline has two halves with very different rhythms.  The raster half —
 * choose pages, denoise, crop, pick a palette — is done once and then left
 * alone; the vector half is re-run constantly.  Showing both at full size all
 * the time makes the sidebar mostly controls nobody is going to touch again.
 *
 * So a prepare step renders one of two ways:
 *
 *   pending   its controls are shown, because you still have to do it
 *   done      collapsed to `name — value`, e.g. `Crop  30.0 × 20.0 in`
 *
 * Clicking a done step's header reopens its controls; clicking again closes
 * them.  A step never *becomes* uneditable — collapsing is about attention,
 * not about locking anything down, because re-tuning the palette after seeing
 * the fit is a normal thing to want.
 */

export interface StepState {
  /** Summary text shown when the step is collapsed. Empty ⇒ still pending. */
  value: string;
}

/** Steps in prepare order. The first one that is pending stays open. */
const STEP_IDS = ["stepPages", "stepDenoise", "stepCrop", "stepPalette"] as const;
export type StepId = typeof STEP_IDS[number];

/** Steps the user has explicitly re-opened by clicking a done header. */
const forcedOpen = new Set<string>();

/**
 * Wire the header click handlers.  Call once, after the DOM exists.
 * `onToggle` is invoked after a step opens or closes so the caller can redraw
 * anything that depends on the sidebar's height.
 */
export function initSteps(onToggle?: () => void): void {
  for (const id of STEP_IDS) {
    const el = document.getElementById(id);
    const head = el?.querySelector<HTMLButtonElement>(".step-head");
    if (!el || !head) continue;
    head.addEventListener("click", () => {
      // A pending step is already open and there is nothing to collapse to.
      if (el.dataset.state !== "done") return;
      if (forcedOpen.has(id)) forcedOpen.delete(id);
      else forcedOpen.add(id);
      applyOpenState(el, id);
      onToggle?.();
    });
  }
}

function applyOpenState(el: HTMLElement, id: string): void {
  const open = el.dataset.state !== "done" || forcedOpen.has(id);
  el.classList.toggle("open", open);
}

/**
 * Push the current pipeline state into the step list.
 *
 * Pass a summary string for every step that is done and `""` for one that is
 * not.  Steps are independent: a later step can be done while an earlier one
 * is not (re-cropping does not un-choose the pages).
 */
export function updateSteps(values: Record<StepId, string>): void {
  for (const id of STEP_IDS) {
    const el = document.getElementById(id);
    if (!el) continue;
    const value = values[id];
    const done  = value !== "";
    el.dataset.state = done ? "done" : "pending";
    const valueEl = document.getElementById(`${id}Value`);
    if (valueEl) valueEl.textContent = done ? value : "—";
    // A step that goes back to pending must not stay stuck in "forced open",
    // or it will re-collapse the moment it completes again.
    if (!done) forcedOpen.delete(id);
    applyOpenState(el, id);
  }
}
