/**
 * CPU fallbacks for the GPU raster stages.
 *
 * WebGPU is a hard requirement for the interactive app, but tests and batch
 * validation should not silently skip on machines without a GPU adapter
 * (headless CI, sandboxes). This module provides:
 *
 *   - `makeCpuDecomposition` — a `PaletteDecomposition` backed by a plain
 *     Uint32Array (`cpuWords`) instead of a GPU buffer.
 *   - `thinDecompositionCPU` — Guo-Hall thinning, a direct port of
 *     shaders/guo_hall_thin.wgsl (same phases, same predicates, same
 *     MAX_ROUNDS cap).
 *
 * Consumers that read bit-planes back (`readAllLayers`, `connectPaths`)
 * check `decomp.cpuWords` first and never touch the GPU when it is present,
 * so the entire vectorization pipeline from bit-planes onward can run
 * CPU-only. The GPU path remains the production path; keep the two thinning
 * implementations in sync when editing the shader.
 */

import type { PaletteDecomposition, PaletteLayer } from "./palette_decompose_types.ts";

const MAX_ROUNDS = 512; // matches the GPU implementation's hard cap

/** Wrap CPU bit-plane words in a PaletteDecomposition (no GPU resources). */
export function makeCpuDecomposition(
  words: Uint32Array,
  width: number,
  height: number,
  rowStride: number,
  layers: PaletteLayer[],
): PaletteDecomposition {
  return {
    width,
    height,
    rowStride,
    layers,
    // CPU-backed decomposition: `buffer` must never be dereferenced — every
    // reader is required to check `cpuWords` first.
    buffer: null as unknown as GPUBuffer,
    cpuWords: words,
    destroy() { /* no GPU resources */ },
  };
}

/**
 * Guo-Hall parallel thinning on CPU.
 *
 * Neighbor labeling (matches the WGSL):
 *   P9 P2 P3
 *   P8 P1 P4
 *   P7 P6 P5
 *
 * Phase 0 deletes P1 if: 2 ≤ N ≤ 6 ∧ C=1 ∧ P2·P4·P8=0 ∧ P2·P4·P6=0
 * Phase 1 deletes P1 if: 2 ≤ N ≤ 6 ∧ C=1 ∧ P2·P6·P8=0 ∧ P4·P6·P8=0
 *
 * Returns a NEW decomposition wrapping freshly thinned words; the input is
 * not modified.
 */
export function thinDecompositionCPU(decomp: PaletteDecomposition): PaletteDecomposition {
  const { width, height, rowStride, layers } = decomp;
  const src = decomp.cpuWords;
  if (!src) throw new Error("thinDecompositionCPU requires a CPU-backed decomposition");

  const layerWords = rowStride * height;
  const out = new Uint32Array(src); // working copy, thinned in place per phase

  for (let li = 0; li < layers.length; li++) {
    const base = li * layerWords;

    // Unpack the layer once; operate on bytes for simple neighbor access.
    const px = new Uint8Array(width * height);
    for (let y = 0; y < height; y++) {
      for (let x = 0; x < width; x++) {
        const w = out[base + y * rowStride + (x >>> 5)];
        if ((w >>> (x & 31)) & 1) px[y * width + x] = 1;
      }
    }

    const next = new Uint8Array(px);
    const get = (x: number, y: number): number =>
      x < 0 || y < 0 || x >= width || y >= height ? 0 : px[y * width + x];

    for (let round = 0; round < MAX_ROUNDS; round++) {
      let changed = false;
      for (let phase = 0; phase < 2; phase++) {
        next.set(px);
        for (let y = 0; y < height; y++) {
          for (let x = 0; x < width; x++) {
            if (!px[y * width + x]) continue;
            const p2 = get(x, y - 1),     p3 = get(x + 1, y - 1);
            const p4 = get(x + 1, y),     p5 = get(x + 1, y + 1);
            const p6 = get(x, y + 1),     p7 = get(x - 1, y + 1);
            const p8 = get(x - 1, y),     p9 = get(x - 1, y - 1);
            const n = p2 + p3 + p4 + p5 + p6 + p7 + p8 + p9;
            if (n < 2 || n > 6) continue;
            let c = 0;
            if (!p2 && p3) c++; if (!p3 && p4) c++;
            if (!p4 && p5) c++; if (!p5 && p6) c++;
            if (!p6 && p7) c++; if (!p7 && p8) c++;
            if (!p8 && p9) c++; if (!p9 && p2) c++;
            if (c !== 1) continue;
            const del = phase === 0
              ? (p2 * p4 * p8 === 0 && p2 * p4 * p6 === 0)
              : (p2 * p6 * p8 === 0 && p4 * p6 * p8 === 0);
            if (del) { next[y * width + x] = 0; changed = true; }
          }
        }
        px.set(next);
      }
      if (!changed) break;
    }

    // Repack the thinned layer.
    for (let y = 0; y < height; y++) {
      for (let wx = 0; wx < rowStride; wx++) {
        let w = 0;
        const x0 = wx << 5;
        const lim = Math.min(32, width - x0);
        for (let b = 0; b < lim; b++) {
          if (px[y * width + x0 + b]) w |= 1 << b;
        }
        out[base + y * rowStride + wx] = w >>> 0;
      }
    }
  }

  return makeCpuDecomposition(out, width, height, rowStride, layers);
}
