/**
 * Path undashing: join nearby collinear dash segments.
 *
 * Two phases:
 *
 * 1.  Endpoint burr trimming
 *     ──────────────────────
 *     Removes a short final edge at an endpoint when that edge deviates
 *     significantly from the chain's continuation direction.  These arise
 *     from staircase pixel artifacts at the tips of thinned skeleton dashes
 *     and are distinct from spurs (endpoint→junction) because both sides of
 *     the affected vertex have degree 2 or 1.
 *
 * 2.  Gap bridging
 *     ─────────────
 *     Connects pairs of same-layer endpoints that are close and collinear.
 *     Direction at each endpoint is estimated by tracing back along the
 *     segment interior, which naturally ignores any residual tip noise.
 *     Matching is greedy (shortest gap first, one-to-one per endpoint).
 */

import type { PathGraph, PathVertex, PathEdge } from "./path_connect.ts";

// ---------------------------------------------------------------------------
// Internal constants
// ---------------------------------------------------------------------------

/** Pixels to trace back from an endpoint to estimate its outward direction. */
const LOOK_BACK_DIST   = 20;
/** Pixels: a final endpoint edge shorter than this is a burr candidate. */
const BURR_MAX_LENGTH  = 6;
/**
 * dot-product threshold for burr detection.
 * For a perfectly straight chain, dot(dirNE, dirNP) = -1 (exactly opposite).
 * If the dot product is > this value the endpoint edge makes too sharp a turn.
 * -0.5 corresponds to the edge being more than ~60° away from straight.
 */
const BURR_DOT_THRESH  = -0.5;

// ---------------------------------------------------------------------------
// Utilities
// ---------------------------------------------------------------------------

function dist(ax: number, ay: number, bx: number, by: number): number {
  const dx = ax - bx, dy = ay - by;
  return Math.sqrt(dx * dx + dy * dy);
}

/** Rebuild vertex types from actual graph degrees. */
function recomputeTypes(verts: PathVertex[], adj: number[][]): void {
  for (let i = 0; i < verts.length; i++) {
    const d = adj[i].length;
    verts[i].type = d === 0 ? "isolated"
                  : d === 1 ? "endpoint"
                  : d === 2 ? "chain"
                  :           "junction";
  }
}

function buildAdj(n: number, edgs: PathEdge[]): number[][] {
  const adj: number[][] = Array.from({ length: n }, () => []);
  for (const e of edgs) {
    adj[e.from].push(e.to);
    adj[e.to].push(e.from);
  }
  return adj;
}

function remapEdges(edgs: PathEdge[], oldToNew: Int32Array): PathEdge[] {
  return edgs.map(e => ({ from: oldToNew[e.from], to: oldToNew[e.to], layer: e.layer }));
}

// ---------------------------------------------------------------------------
// Phase 1: Endpoint burr trimming
// ---------------------------------------------------------------------------

/**
 * Trim short burr edges at endpoints.
 *
 * A burr is detected at endpoint E when:
 *   • N = adj[E][0] has degree 2 (N is a chain vertex, not a junction).
 *   • dist(E, N) < BURR_MAX_LENGTH.
 *   • P = other neighbor of N exists.
 *   • dot(normalize(E−N), normalize(P−N)) > BURR_DOT_THRESH
 *     (the edge E−N is not going in the "straight" direction past N).
 *
 * In that case E is removed, and N becomes the new endpoint.
 * Iterates to stability so chained burrs are cleaned up.
 */
function trimBurrs(
  verts: PathVertex[],
  edgs:  PathEdge[],
): { verts: PathVertex[]; edgs: PathEdge[] } {
  let v = verts.map(x => ({ ...x }));
  let e = edgs.map(x => ({ ...x }));

  for (let pass = 0; pass < 100; pass++) {
    const adj = buildAdj(v.length, e);
    const removeVerts = new Set<number>();

    for (let i = 0; i < v.length; i++) {
      if (adj[i].length !== 1) continue; // only endpoints
      if (removeVerts.has(i)) continue;

      const n = adj[i][0];
      if (adj[n].length !== 2) continue; // N must be a chain vertex

      if (dist(v[i].x, v[i].y, v[n].x, v[n].y) >= BURR_MAX_LENGTH) continue;

      // P = the other neighbor of N
      const p = adj[n].find(x => x !== i);
      if (p === undefined) continue;

      // Direction from N toward E (the burr), and from N toward P (the chain).
      const nEx = v[i].x - v[n].x, nEy = v[i].y - v[n].y;
      const nPx = v[p].x - v[n].x, nPy = v[p].y - v[n].y;
      const lenNE = Math.sqrt(nEx * nEx + nEy * nEy);
      const lenNP = Math.sqrt(nPx * nPx + nPy * nPy);
      if (lenNE < 0.001 || lenNP < 0.001) continue;

      const dotProd = (nEx * nPx + nEy * nPy) / (lenNE * lenNP);
      if (dotProd <= BURR_DOT_THRESH) continue; // roughly straight — not a burr

      removeVerts.add(i);
    }

    if (removeVerts.size === 0) break;

    e = e.filter(edge => !removeVerts.has(edge.from) && !removeVerts.has(edge.to));

    const oldToNew = new Int32Array(v.length).fill(-1);
    let ni = 0;
    v = v.filter((_, idx) => {
      if (removeVerts.has(idx)) return false;
      oldToNew[idx] = ni++;
      return true;
    });
    e = remapEdges(e, oldToNew);

    const newAdj = buildAdj(v.length, e);
    recomputeTypes(v, newAdj);
  }

  return { verts: v, edgs: e };
}

// ---------------------------------------------------------------------------
// Phase 2: Gap bridging
// ---------------------------------------------------------------------------

/**
 * Walk from `from` into the chain via `via` and return the point exactly
 * LOOK_BACK_DIST along it — interpolating within the edge that crosses that
 * distance, and stopping early (at the far end) if the chain is shorter.
 *
 * The interpolation is the point of this function.  The obvious version keeps
 * the last vertex that fitted inside the budget and discards the one that
 * overshot, which silently makes the baseline as short as the first edge:
 * where a dash tip is a 2 px staircase step and the next skeleton vertex is
 * 20 px further on, the direction comes back estimated over those 2 px, which
 * is a 45 degree lie about a horizontal stroke.  That put a dash tip's outward
 * direction far enough off to miss its partner across the gap, which is one
 * source of a long dashed run arriving as several strokes with kinks between
 * them.  Interpolating gives every estimate the same 20 px baseline no matter
 * where the vertices happen to fall.
 */
function lookBackPoint(
  verts: PathVertex[],
  adj:   number[][],
  from:  number,
  via:   number,
): { x: number; y: number } {
  const sv = verts[from];
  let prev = from, curr = via;
  let px = sv.x, py = sv.y;                       // start of the current edge
  let traveled = 0;

  for (;;) {
    const cv = verts[curr];
    const step = dist(px, py, cv.x, cv.y);
    if (traveled + step >= LOOK_BACK_DIST) {
      const t = step > 1e-9 ? (LOOK_BACK_DIST - traveled) / step : 1;
      return { x: px + t * (cv.x - px), y: py + t * (cv.y - py) };
    }
    traveled += step;
    px = cv.x; py = cv.y;

    if (adj[curr].length !== 2) break;            // junction or far endpoint
    let next = -1;
    for (const n of adj[curr]) {
      if (n !== prev) { next = n; break; }
    }
    if (next === -1) break;
    prev = curr;
    curr = next;
  }

  return { x: px, y: py };                        // chain ended first
}

/**
 * Unit vector pointing AWAY from an endpoint's segment interior — the
 * direction a connection would be made in.
 */
function computeOutwardDir(
  verts: PathVertex[],
  adj:   number[][],
  epIdx: number,
): { x: number; y: number } {
  const first = adj[epIdx][0];
  if (first === undefined) return { x: 0, y: 0 };
  const ev  = verts[epIdx];
  const ref = lookBackPoint(verts, adj, epIdx, first);
  const dx = ev.x - ref.x, dy = ev.y - ref.y;
  const len = Math.sqrt(dx * dx + dy * dy);
  if (len < 0.01) return { x: 0, y: 0 };
  return { x: dx / len, y: dy / len };
}

/**
 * Direction the stroke leaves vertex `vi` along, heading first to `via` — the
 * same estimate seen from the other side, so it can be compared against a
 * chord arriving at `vi`.  Used to ask whether a stroke continues through a
 * vertex that is not a free end.
 */
function continuationDir(
  verts: PathVertex[],
  adj:   number[][],
  vi:    number,
  via:   number,
): { x: number; y: number } {
  const sv  = verts[vi];
  const ref = lookBackPoint(verts, adj, vi, via);
  const dx = ref.x - sv.x, dy = ref.y - sv.y;
  const len = Math.sqrt(dx * dx + dy * dy);
  if (len < 0.01) return { x: 0, y: 0 };
  return { x: dx / len, y: dy / len };
}

/**
 * Find and connect compatible endpoint pairs.
 *
 * A pair (A, B) is compatible if:
 *   1. same layer
 *   2. gap distance ≤ maxGap
 *   3. A's outward direction points toward B, within a tolerance that
 *      tightens as the gap grows
 *   4. B's outward direction points toward A, likewise
 *
 * Matching is greedy: candidates are sorted by gap distance; each endpoint
 * is matched to at most one other endpoint.
 */
function bridgeGaps(
  verts:       PathVertex[],
  edgs:        PathEdge[],
  maxGap:      number,
  loosestCos:  number,
): { verts: PathVertex[]; edgs: PathEdge[] } {
  /**
   * How far the bridge may bow away from the straight chord between the two
   * endpoints, in pixels.  This, not an angle, is the thing that decides
   * whether a bridge is believable.
   */
  const MAX_BOW_PX = 2.0;
  /**
   * Never bridge across a turn sharper than this, however short the gap —
   * `maxAngleDeg` from the caller.  A real corner has to survive.
   */
  const MAX_TURN = Math.acos(Math.max(-1, Math.min(1, loosestCos)));

  /**
   * Largest tangent-to-chord angle acceptable across a gap of this length.
   *
   * A single angle threshold for every gap is wrong in two different ways, and
   * this pipeline was visibly wrong in both:
   *
   *   too strict on short gaps — a 3.6 px break in an outline stayed open
   *     because a direction estimated over a 5 px stub missed a fixed 30
   *     degree threshold by 0.02.  Across a gap that
   *     short the direction estimate is mostly quantisation noise and the
   *     positions alone are near proof that this is one stroke.
   *
   *   too loose on long gaps — 30 px gaps bridged between strokes that were
   *     never the same stroke.
   *
   * What both cases have in common is the BOW: a bridge that continues the
   * stroke deviates from the chord by (gap/2)*tan(theta/2), which is what the
   * eye sees and what puts a primitive off its ink.  Cap the bow and the angle
   * tolerance falls out of the gap length.
   */
  const maxTangentAngle = (gap: number): number =>
    Math.min(MAX_TURN, 2 * Math.atan(2 * MAX_BOW_PX / Math.max(gap, 1e-6)));

  const adj = buildAdj(verts.length, edgs);

  // Collect endpoints and their outward directions.
  const epIndices: number[] = [];
  for (let i = 0; i < verts.length; i++) {
    if (adj[i].length === 1) epIndices.push(i);
  }

  const outDirs = epIndices.map(ep => computeOutwardDir(verts, adj, ep));

  // Build sorted candidate list.
  interface Candidate { ai: number; bi: number; gapDist: number; }
  const candidates: Candidate[] = [];

  for (let a = 0; a < epIndices.length; a++) {
    const ai  = epIndices[a];
    const va  = verts[ai];
    const da  = outDirs[a];
    if (da.x === 0 && da.y === 0) continue;

    for (let b = a + 1; b < epIndices.length; b++) {
      const bi = epIndices[b];
      if (verts[bi].layer !== va.layer) continue;

      const vb = verts[bi];
      const db = outDirs[b];
      if (db.x === 0 && db.y === 0) continue;

      const gapDist = dist(va.x, va.y, vb.x, vb.y);
      if (gapDist > maxGap || gapDist < 0.01) continue;

      // Unit gap vector from A to B.
      const gx = (vb.x - va.x) / gapDist;
      const gy = (vb.y - va.y) / gapDist;

      // Each endpoint's outward direction must point toward the other, and the
      // angle it makes with the chord must be small enough that a stroke
      // continuing through the gap stays within MAX_BOW_PX of it.
      //
      // Note there is deliberately NO "the two directions must be
      // anti-parallel" test.  On a dashed CURVE they are not: each tangent
      // leans off the chord by half the arc it subtends, symmetrically.  That
      // test is what left dashed circles as loose arcs — a 39 px radius circle
      // with 18 px gaps has a 13 degree tangent-chord angle purely from its own
      // curvature.  For a straight dashed line both
      // angles go to zero and the old condition is recovered anyway.
      const cosLimit = Math.cos(maxTangentAngle(gapDist));
      if (da.x * gx + da.y * gy < cosLimit) continue;
      if (db.x * (-gx) + db.y * (-gy) < cosLimit) continue;

      candidates.push({ ai: a, bi: b, gapDist });
    }
  }

  candidates.sort((x, y) => x.gapDist - y.gapDist);

  // Greedy one-to-one matching.
  const matched    = new Set<number>();
  const newVerts   = verts.map(v => ({ ...v }));
  const newEdges: PathEdge[] = [];

  for (const { ai, bi } of candidates) {
    if (matched.has(ai) || matched.has(bi)) continue;
    matched.add(ai); matched.add(bi);

    const epA = epIndices[ai];
    const epB = epIndices[bi];
    newEdges.push({
      from:  Math.min(epA, epB),
      to:    Math.max(epA, epB),
      layer: verts[epA].layer,
    });
    // Both endpoints become interior chain vertices after connection.
    newVerts[epA].type = "chain";
    newVerts[epB].type = "chain";
  }

  // ── Free end → a vertex that is not a free end ─────────────────────────────
  //
  // The pairing above needs a free end on BOTH sides of the gap, and a dashed
  // line crossing another stroke does not have one.  The dash that spans the
  // crossing is attached to it, and the 1-2 px of skeleton between its tip and
  // the crossing is an endpoint→junction branch, so `removeSpurs` prunes it.
  // What is left where that tip was is an interior vertex, and the dash on the
  // far side of the gap is then orphaned for good: nothing downstream looks at
  // an endpoint whose only possible partner is not an endpoint.  That is the
  // reported defect — a dashed line stopping in clear space a gap short of the
  // line it runs into.
  //
  // Bridging to an interior vertex is only safe because of the third test: the
  // stroke has to visibly CONTINUE through the target, i.e. some branch leaves
  // it going the same way the chord arrived.  Without that, this would happily
  // staple a dash end onto the flank of any stroke that passed nearby; with it,
  // the target is on the same line the dash was already on.
  const isFree = (i: number) => adj[i].length === 1;
  interface Attach { epIdx: number; target: number; gapDist: number }
  const attaches: Attach[] = [];

  for (let a = 0; a < epIndices.length; a++) {
    if (matched.has(a)) continue;
    const ai = epIndices[a];
    const va = verts[ai];
    const da = outDirs[a];
    if (da.x === 0 && da.y === 0) continue;

    for (let j = 0; j < verts.length; j++) {
      if (j === ai || isFree(j) || adj[j].length === 0) continue;
      const vj = verts[j];
      if (vj.layer !== va.layer) continue;

      const gapDist = dist(va.x, va.y, vj.x, vj.y);
      if (gapDist > maxGap || gapDist < 0.01) continue;

      const gx = (vj.x - va.x) / gapDist, gy = (vj.y - va.y) / gapDist;
      const cosLimit = Math.cos(maxTangentAngle(gapDist));

      // 1. the free end points at the target
      if (da.x * gx + da.y * gy < cosLimit) continue;

      // 2. the stroke carries on through the target in the same direction, and
      // 3. nothing at the target heads back toward the free end.
      //
      // (3) is what keeps this from firing along an ordinary dashed run.  Every
      // interior vertex of the next dash also satisfies (1) and (2), and
      // attaching to one of those staples the gap shut part-way along the dash
      // and leaves the stub before it as a separate chain — measurably worse
      // than leaving the gap alone.  A vertex with ink running back toward us
      // is not the far side of a gap: the tip of that run is, and if that tip
      // is a free end the pairing pass above has already dealt with it.
      let carriesOn = false, headsBack = false;
      for (const nb of adj[j]) {
        const dj = continuationDir(verts, adj, j, nb);
        if (dj.x === 0 && dj.y === 0) continue;
        if (dj.x * gx + dj.y * gy >= cosLimit) carriesOn = true;
        if (dj.x * -gx + dj.y * -gy >= cosLimit) headsBack = true;
      }
      if (!carriesOn || headsBack) continue;

      attaches.push({ epIdx: a, target: j, gapDist });
    }
  }

  attaches.sort((x, y) => x.gapDist - y.gapDist);
  const usedTargets = new Set<number>();
  for (const { epIdx, target } of attaches) {
    if (matched.has(epIdx) || usedTargets.has(target)) continue;
    matched.add(epIdx);
    usedTargets.add(target);
    const ep = epIndices[epIdx];
    newEdges.push({
      from:  Math.min(ep, target),
      to:    Math.max(ep, target),
      layer: verts[ep].layer,
    });
    newVerts[ep].type = "chain";
    newVerts[target].type = "junction";
  }

  return { verts: newVerts, edgs: [...edgs, ...newEdges] };
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/**
 * Join nearby collinear dash segments.
 *
 * Phase 1 — burr trimming: removes short endpoint edges that deviate
 * significantly from the chain direction (staircase pixel artifacts).
 *
 * Phase 2 — gap bridging: connects pairs of same-layer endpoints whose
 * look-back directions are collinear and whose gap is within `maxGap`.
 *
 * @param graph       Input graph (typically from `removeSpurs`).
 * @param maxGap      Maximum gap in pixels between dash endpoints to bridge.
 * @param maxAngleDeg Loosest allowed deviation from collinearity, in degrees,
 *                    used for the shortest gaps.  The tolerance actually
 *                    applied tightens as the gap grows — see `bridgeGaps`.
 */
export function undashPaths(
  graph:       PathGraph,
  maxGap:      number,
  maxAngleDeg: number,
): PathGraph {
  const maxAngleCos = Math.cos((maxAngleDeg * Math.PI) / 180);

  const { verts: trimmedV, edgs: trimmedE } = trimBurrs(
    graph.vertices.map(v => ({ ...v })),
    graph.edges.map(e => ({ ...e })),
  );

  const { verts: finalV, edgs: finalE } = bridgeGaps(
    trimmedV,
    trimmedE,
    maxGap,
    maxAngleCos,
  );

  return {
    width:      graph.width,
    height:     graph.height,
    layerCount: graph.layerCount,
    vertices:   finalV,
    edges:      finalE,
  };
}
