/**
 * GPU Guo-Hall skeletonization.
 *
 * Applies iterative parallel thinning (Guo & Hall 1989) to every layer in a
 * PaletteDecomposition.  Each round consists of two sub-iterations (phases 0
 * and 1); the process repeats until no pixel changes or a hard cap is reached.
 *
 * Buffer layout
 * ─────────────
 * Identical to PaletteDecomposition:
 *   [layer 0 : rowStride × height × u32]
 *   [layer 1 : rowStride × height × u32]
 *   …
 * rowStride = Math.ceil(width / 32)
 *
 * Ping-pong strategy
 * ──────────────────
 * Two full-size buffers A and B are kept:
 *   Phase 0: A → B  (reads A, writes B, deletes south-east group of pixels)
 *   Phase 1: B → A  (reads B, writes A, deletes north-west group)
 * After each complete round the result lives in A.
 *
 * Convergence detection
 * ─────────────────────
 * A 4-byte "changed" buffer is cleared before each batch of BATCH_SIZE rounds.
 * Any workgroup that deleted at least one pixel atomically ORs 1 into it.
 * If the flag is still 0 after the batch, the image is stable.
 *
 * Bind groups are created once; the `layerBase` uniform encodes which layer
 * slice each dispatch addresses, so all layers can share a single pipeline.
 */

import type { PaletteDecomposition } from "./palette_decompose.ts";
import guoHallShader from "./shaders/guo_hall_thin.wgsl?raw";
import { makeCpuDecomposition, thinDecompositionCPU } from "./cpu_fallback.ts";

// ---------------------------------------------------------------------------
// Pipeline cache
// ---------------------------------------------------------------------------

interface PipelineCache {
  device: GPUDevice;
  pipeline: GPUComputePipeline;
  bgl: GPUBindGroupLayout;
}

let cachedPipeline: PipelineCache | null = null;

function getOrCreatePipeline(device: GPUDevice): PipelineCache {
  if (cachedPipeline && cachedPipeline.device === device) return cachedPipeline;

  const bgl = device.createBindGroupLayout({
    entries: [
      { binding: 0, visibility: GPUShaderStage.COMPUTE, buffer: { type: "uniform" } },
      { binding: 1, visibility: GPUShaderStage.COMPUTE, buffer: { type: "read-only-storage" } },
      { binding: 2, visibility: GPUShaderStage.COMPUTE, buffer: { type: "storage" } },
      { binding: 3, visibility: GPUShaderStage.COMPUTE, buffer: { type: "storage" } },
    ],
  });

  const pipeline = device.createComputePipeline({
    layout: device.createPipelineLayout({ bindGroupLayouts: [bgl] }),
    compute: {
      module: device.createShaderModule({ code: guoHallShader }),
      entryPoint: "main",
    },
  });

  cachedPipeline = { device, pipeline, bgl };
  return cachedPipeline;
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/** Create a 32-byte uniform buffer for one Dims struct. */
function makeUniforms(
  device: GPUDevice,
  width: number,
  height: number,
  rowStride: number,
  phase: number,
  layerBase: number,
): GPUBuffer {
  // 8 × u32 = 32 bytes (satisfies WGSL uniform 16-byte alignment requirement).
  const data = new Uint32Array([width, height, rowStride, phase, layerBase, 0, 0, 0]);
  const buf = device.createBuffer({
    size: data.byteLength,
    usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST,
    mappedAtCreation: true,
  });
  new Uint32Array(buf.getMappedRange()).set(data);
  buf.unmap();
  return buf;
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/** Maximum full rounds (phase 0 + phase 1) before giving up. */
const MAX_ROUNDS = 512;

/**
 * Number of thinning rounds per GPU submission before checking convergence.
 * Higher values = fewer CPU↔GPU readbacks but slightly more redundant work
 * after the image stabilises within a batch.
 */
const BATCH_SIZE = 16;

/**
 * Skeletonize every layer of `decomp` using Guo-Hall parallel thinning.
 *
 * Returns a new `PaletteDecomposition` whose `buffer` contains the thinned
 * bit-planes but shares the same layer metadata as the input.  The caller
 * must call `.destroy()` on the returned object when done.
 *
 * The input `decomp` is not modified.
 */
export async function thinDecomposition(
  device: GPUDevice,
  decomp: PaletteDecomposition,
): Promise<PaletteDecomposition> {
  const { width, height, rowStride, layers, buffer } = decomp;
  const numLayers = layers.length;

  if (numLayers === 0) {
    const buf = device.createBuffer({
      size: 4,
      usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_SRC,
    });
    return {
      width, height, rowStride, layers: [], buffer: buf,
      destroy() { buf.destroy(); },
    };
  }

  const { pipeline, bgl } = getOrCreatePipeline(device);

  const layerWords = rowStride * height;        // u32 words per layer
  const totalBytes = numLayers * layerWords * 4; // bytes for all layers

  // ── Allocate ping-pong buffers ─────────────────────────────────────────────
  // bufA: holds the current thinned state (initialised from decomp.buffer).
  // bufB: intermediate result after phase 0 (A → B).
  const bufA = device.createBuffer({
    size:  totalBytes,
    usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_SRC | GPUBufferUsage.COPY_DST,
  });
  const bufB = device.createBuffer({
    size:  totalBytes,
    usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_SRC | GPUBufferUsage.COPY_DST,
  });

  // ── Changed-flag buffer ────────────────────────────────────────────────────
  // Cleared before each batch; any workgroup that deletes pixels ORs 1 in.
  // The storage buffer holds array<atomic<u32>, 1>.
  const changedBuf = device.createBuffer({
    size:  4,
    usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_SRC | GPUBufferUsage.COPY_DST,
  });
  const changedStaging = device.createBuffer({
    size:  4,
    usage: GPUBufferUsage.COPY_DST | GPUBufferUsage.MAP_READ,
  });

  // ── Copy input into bufA ───────────────────────────────────────────────────
  // No CPU-GPU sync needed here: all subsequent compute passes are submitted to
  // the same queue and the GPU executes queue submissions in order.
  {
    const enc = device.createCommandEncoder();
    enc.copyBufferToBuffer(buffer, 0, bufA, 0, totalBytes);
    device.queue.submit([enc.finish()]);
  }

  // ── Pre-create uniform buffers and bind groups ────────────────────────────
  // For each layer we need two sets:
  //   bgP0[li]: phase 0, A → B
  //   bgP1[li]: phase 1, B → A
  const unifP0: GPUBuffer[] = [];
  const unifP1: GPUBuffer[] = [];
  const bgP0:   GPUBindGroup[] = [];
  const bgP1:   GPUBindGroup[] = [];

  for (let li = 0; li < numLayers; li++) {
    const layerBase = li * layerWords;

    const u0 = makeUniforms(device, width, height, rowStride, 0, layerBase);
    const u1 = makeUniforms(device, width, height, rowStride, 1, layerBase);
    unifP0.push(u0);
    unifP1.push(u1);

    // Phase 0: read bufA, write bufB
    bgP0.push(device.createBindGroup({
      layout: bgl,
      entries: [
        { binding: 0, resource: { buffer: u0 } },
        { binding: 1, resource: { buffer: bufA } },
        { binding: 2, resource: { buffer: bufB } },
        { binding: 3, resource: { buffer: changedBuf } },
      ],
    }));

    // Phase 1: read bufB, write bufA
    bgP1.push(device.createBindGroup({
      layout: bgl,
      entries: [
        { binding: 0, resource: { buffer: u1 } },
        { binding: 1, resource: { buffer: bufB } },
        { binding: 2, resource: { buffer: bufA } },
        { binding: 3, resource: { buffer: changedBuf } },
      ],
    }));
  }

  const dispatchX = rowStride; // one workgroup per u32 column
  const dispatchY = height;    // one workgroup per row

  // ── Iterative thinning ────────────────────────────────────────────────────
  let totalRounds = 0;

  outer:
  for (;;) {
    const batchRounds = Math.min(BATCH_SIZE, MAX_ROUNDS - totalRounds);
    if (batchRounds <= 0) break;

    const enc = device.createCommandEncoder();
    enc.clearBuffer(changedBuf); // reset changed flag for this batch

    for (let r = 0; r < batchRounds; r++) {
      // Phase 0: A → B  (all layers in one compute pass)
      {
        const pass = enc.beginComputePass();
        pass.setPipeline(pipeline);
        for (let li = 0; li < numLayers; li++) {
          pass.setBindGroup(0, bgP0[li]);
          pass.dispatchWorkgroups(dispatchX, dispatchY, 1);
        }
        pass.end();
      }

      // Phase 1: B → A  (separate pass — implicit barrier between passes)
      {
        const pass = enc.beginComputePass();
        pass.setPipeline(pipeline);
        for (let li = 0; li < numLayers; li++) {
          pass.setBindGroup(0, bgP1[li]);
          pass.dispatchWorkgroups(dispatchX, dispatchY, 1);
        }
        pass.end();
      }
    }

    enc.copyBufferToBuffer(changedBuf, 0, changedStaging, 0, 4);
    device.queue.submit([enc.finish()]);

    await changedStaging.mapAsync(GPUMapMode.READ);
    const changedVal = new Uint32Array(changedStaging.getMappedRange())[0];
    changedStaging.unmap();

    totalRounds += batchRounds;

    if (changedVal === 0 || totalRounds >= MAX_ROUNDS) break outer;
  }

  // ── Clean up temporaries ───────────────────────────────────────────────────
  for (let li = 0; li < numLayers; li++) {
    unifP0[li].destroy();
    unifP1[li].destroy();
  }
  bufB.destroy();
  changedBuf.destroy();
  changedStaging.destroy();

  // Result lives in bufA.
  return {
    width,
    height,
    rowStride,
    layers,  // same metadata as input
    buffer: bufA,
    destroy() { bufA.destroy(); },
  };
}

// ---------------------------------------------------------------------------
// CPU fallback
// ---------------------------------------------------------------------------

/** Read a decomposition's bit-planes back from the GPU. */
async function readDecompositionWords(
  device: GPUDevice,
  decomp: PaletteDecomposition,
): Promise<Uint32Array> {
  const { rowStride, height, layers, buffer } = decomp;
  const totalBytes = layers.length * rowStride * height * 4;
  const staging = device.createBuffer({
    size:  totalBytes,
    usage: GPUBufferUsage.COPY_DST | GPUBufferUsage.MAP_READ,
  });
  try {
    const enc = device.createCommandEncoder();
    enc.copyBufferToBuffer(buffer, 0, staging, 0, totalBytes);
    device.queue.submit([enc.finish()]);
    await staging.mapAsync(GPUMapMode.READ);
    const words = new Uint32Array(staging.getMappedRange().slice(0));
    staging.unmap();
    return words;
  } finally {
    staging.destroy();
  }
}

/**
 * Thin a decomposition, choosing the GPU shader or the CPU port.
 *
 * Guo-Hall is iterative: each pass is a full-image dispatch and it runs until
 * the skeleton stops changing. On real hardware that is cheap. On a software
 * rasteriser every dispatch is a CPU round trip, and a 6000x4000 sheet takes
 * ~20 minutes — versus 1.8 s for the CPU port doing the same work directly.
 * So on a software adapter the "fallback" is not a compromise, it is simply
 * the fast path, and the algorithm is identical either way.
 *
 * Pass `forceCpu` to take the CPU path regardless (batch tooling, tests).
 */
export async function thinDecompositionAuto(
  device: GPUDevice,
  decomp: PaletteDecomposition,
  opts: { forceCpu?: boolean } = {},
): Promise<PaletteDecomposition> {
  if (!opts.forceCpu) return await thinDecomposition(device, decomp);

  const words = decomp.cpuWords ?? await readDecompositionWords(device, decomp);
  const cpuDecomp = makeCpuDecomposition(
    words, decomp.width, decomp.height, decomp.rowStride, decomp.layers,
  );
  return thinDecompositionCPU(cpuDecomp);
}
