/**
 * GPU palette cleanup — speckle removal and fringe absorption.
 *
 * After palette decomposition each 1-bpp layer still contains:
 *   • isolated stipple pixels that were misclassified (JPEG / print artefacts)
 *   • 1–3 pixel "fringe" bands at colour boundaries whose OKLab distance
 *     places them in the wrong layer
 *
 * A 5×5 neighbourhood vote decides the fate of every coloured pixel:
 *   myCount   = same-layer votes in the window (includes self)
 *   bestCount = highest vote count of any *other* layer
 *
 *   myCount <= 3  AND  bestCount >= 8  → reassign to dominant neighbour
 *   myCount <= 1                       → erase (truly isolated)
 *   otherwise                          → keep
 *
 * Background pixels (no bit set in any layer) are always kept as background.
 */

import type { PaletteDecomposition } from "./palette_decompose.ts";
import paletteCleanupShader from "./shaders/palette_cleanup.wgsl?raw";

// ---------------------------------------------------------------------------
// Pipeline cache
// ---------------------------------------------------------------------------

interface PipelineCache {
  device: GPUDevice;
  pipeline: GPUComputePipeline;
  bgl: GPUBindGroupLayout;
}

let cachedPipeline: PipelineCache | null = null;

function getOrCreatePipeline(device: GPUDevice): PipelineCache {
  if (cachedPipeline && cachedPipeline.device === device) return cachedPipeline;

  const bgl = device.createBindGroupLayout({
    entries: [
      { binding: 0, visibility: GPUShaderStage.COMPUTE, buffer: { type: "uniform" } },
      { binding: 1, visibility: GPUShaderStage.COMPUTE, buffer: { type: "read-only-storage" } },
      { binding: 2, visibility: GPUShaderStage.COMPUTE, buffer: { type: "storage" } },
    ],
  });

  const pipeline = device.createComputePipeline({
    layout: device.createPipelineLayout({ bindGroupLayouts: [bgl] }),
    compute: {
      module: device.createShaderModule({ code: paletteCleanupShader }),
      entryPoint: "main",
    },
  });

  cachedPipeline = { device, pipeline, bgl };
  return cachedPipeline;
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/**
 * Apply speckle-removal and fringe-absorption to every layer in `decomp`.
 *
 * Returns a new {@link PaletteDecomposition} with the same metadata but a
 * fresh GPU buffer holding the cleaned bit-planes.  The caller is responsible
 * for destroying the returned object when done; the original `decomp` is NOT
 * destroyed here.
 */
export async function cleanupPalette(
  device: GPUDevice,
  decomp: PaletteDecomposition,
): Promise<PaletteDecomposition> {
  const { pipeline, bgl } = getOrCreatePipeline(device);

  const { width, height, rowStride, layers } = decomp;
  const numLayers  = layers.length;
  const layerWords = rowStride * height;
  const totalWords = numLayers * layerWords;

  if (numLayers === 0) {
    // Nothing to do — return a cheap empty buffer.
    const buf = device.createBuffer({
      size: 4,
      usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_SRC,
    });
    return { width, height, rowStride, layers, buffer: buf, destroy() { buf.destroy(); } };
  }

  // ── Uniform buffer ─────────────────────────────────────────────────────────
  // 8 × u32 = 32 bytes (padded to 16-byte alignment boundary).
  const dimsData = new Uint32Array([width, height, rowStride, numLayers, 0, 0, 0, 0]);
  const dimsBuffer = device.createBuffer({
    size:             dimsData.byteLength,
    usage:            GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST,
    mappedAtCreation: true,
  });
  new Uint32Array(dimsBuffer.getMappedRange()).set(dimsData);
  dimsBuffer.unmap();

  // ── Output buffer (pre-cleared so any unwritten tile words are 0) ─────────
  const dstBuffer = device.createBuffer({
    size:  totalWords * 4,
    usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_SRC | GPUBufferUsage.COPY_DST,
  });

  // ── Bind group ────────────────────────────────────────────────────────────
  const bindGroup = device.createBindGroup({
    layout: bgl,
    entries: [
      { binding: 0, resource: { buffer: dimsBuffer } },
      { binding: 1, resource: { buffer: decomp.buffer } },
      { binding: 2, resource: { buffer: dstBuffer } },
    ],
  });

  // ── Dispatch ──────────────────────────────────────────────────────────────
  const encoder = device.createCommandEncoder();
  encoder.clearBuffer(dstBuffer);
  const pass = encoder.beginComputePass();
  pass.setPipeline(pipeline);
  pass.setBindGroup(0, bindGroup);
  pass.dispatchWorkgroups(
    Math.ceil(width / 32), // one workgroup per u32-column
    height,                // one workgroup per row
    1,
  );
  pass.end();
  device.queue.submit([encoder.finish()]);

  await device.queue.onSubmittedWorkDone();

  dimsBuffer.destroy();

  return {
    width,
    height,
    rowStride,
    layers,
    buffer: dstBuffer,
    destroy() { dstBuffer.destroy(); },
  };
}
