/**
 * Douglas-Peucker simplification of a PathGraph.
 *
 * Chain vertices (degree-2 interior pixels) along each polyline segment are
 * reduced so that no removed point lies more than `tolerance` pixels from the
 * simplified line.  Anchor vertices (endpoints, junctions, isolated) are
 * always preserved.
 *
 * Algorithm overview
 * ──────────────────
 * 1. Build an undirected adjacency list from PathGraph.edges.
 * 2. Walk every maximal run of consecutive "chain" vertices that lies between
 *    two anchor vertices (endpoint / junction / isolated).  Circular chains
 *    (pure rings with no anchors) are handled by closing the ring into an
 *    open polyline that starts and ends at the same vertex.
 * 3. Apply recursive Douglas-Peucker to each run.
 * 4. Rebuild the graph retaining only anchor vertices + DP-selected chain
 *    vertices, with new direct edges between consecutive kept vertices in
 *    each run.
 */

import type { PathGraph, PathVertex, PathEdge } from "./path_connect.ts";

// ---------------------------------------------------------------------------
// Douglas-Peucker core
// ---------------------------------------------------------------------------

/** Perpendicular distance from point P to the line through A→B. */
function perpDist(
  px: number, py: number,
  ax: number, ay: number,
  bx: number, by: number,
): number {
  const dx = bx - ax;
  const dy = by - ay;
  const len2 = dx * dx + dy * dy;
  if (len2 === 0) {
    const ex = px - ax, ey = py - ay;
    return Math.sqrt(ex * ex + ey * ey);
  }
  const t  = ((px - ax) * dx + (py - ay) * dy) / len2;
  const fx = ax + t * dx - px;
  const fy = ay + t * dy - py;
  return Math.sqrt(fx * fx + fy * fy);
}

/**
 * Recursive DP: marks keep[i]=1 for points between keep[start] and keep[end]
 * whose perpendicular distance from the chord exceeds `tolerance`.
 * Both keep[start] and keep[end] must already be set to 1 by the caller.
 */
function dpRecurse(
  xs: Float64Array,
  ys: Float64Array,
  keep: Uint8Array,
  start: number,
  end: number,
  tolerance: number,
): void {
  if (end <= start + 1) return;

  let maxDist = 0;
  let maxIdx  = start;

  for (let i = start + 1; i < end; i++) {
    const d = perpDist(xs[i], ys[i], xs[start], ys[start], xs[end], ys[end]);
    if (d > maxDist) { maxDist = d; maxIdx = i; }
  }

  if (maxDist > tolerance) {
    keep[maxIdx] = 1;
    dpRecurse(xs, ys, keep, start, maxIdx, tolerance);
    dpRecurse(xs, ys, keep, maxIdx, end, tolerance);
  }
}

// ---------------------------------------------------------------------------
// Internal types
// ---------------------------------------------------------------------------

interface Run {
  /** Vertex indices in traversal order. */
  path: number[];
  /**
   * True if this is a circular ring (all vertices are "chain", no anchors).
   * For circular runs the first vertex is repeated logically at the end.
   */
  circular: boolean;
}

/** Euclidean distance between two vertices in pixel space. */
function vertexDist(a: { x: number; y: number }, b: { x: number; y: number }): number {
  const dx = a.x - b.x, dy = a.y - b.y;
  return Math.sqrt(dx * dx + dy * dy);
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/**
 * Simplify a `PathGraph` using Douglas-Peucker.
 *
 * Each maximal chain of degree-2 ("chain") vertices between two anchor
 * vertices (endpoint, junction, isolated) is treated as a polyline and
 * reduced so that no removed point is more than `tolerance` pixels from the
 * simplified segment.  Circular chains (rings with no anchors) are handled
 * by treating the ring as an open path that closes back on the first vertex.
 *
 * Anchor vertices are always preserved.
 *
 * @param graph     Source path graph (typically the raw pixel-adjacency graph).
 * @param tolerance Maximum allowed perpendicular error in pixels (e.g. 1.5).
 * @returns         A new `PathGraph` with simplified vertices and edges.
 */
export function simplifyPathGraph(graph: PathGraph, tolerance: number): PathGraph {
  const { width, height, layerCount, vertices, edges } = graph;

  if (vertices.length === 0) {
    return { width, height, layerCount, vertices: [], edges: [] };
  }

  // ── Build undirected adjacency list ──────────────────────────────────────

  const adj: number[][] = Array.from({ length: vertices.length }, () => []);
  for (const edge of edges) {
    adj[edge.from].push(edge.to);
    adj[edge.to].push(edge.from);
  }

  // ── Phase 1: Collect chain runs ──────────────────────────────────────────

  const runs: Run[]  = [];
  const chainVisited = new Uint8Array(vertices.length);

  // Seed runs from anchor → chain adjacencies.
  for (let i = 0; i < vertices.length; i++) {
    if (vertices[i].type === "chain") continue;

    for (const n of adj[i]) {
      if (vertices[n].type !== "chain" || chainVisited[n]) continue;

      const path: number[] = [i, n];
      chainVisited[n] = 1;
      let prev = i, curr = n;

      while (true) {
        const next = adj[curr].find(x => x !== prev);
        if (next === undefined) break;  // dead-end (shouldn't occur in valid graph)

        if (vertices[next].type !== "chain" || chainVisited[next]) {
          path.push(next);             // arrived at anchor (or loop back to visited chain)
          break;
        }
        chainVisited[next] = 1;
        path.push(next);
        prev = curr;
        curr = next;
      }

      runs.push({ path, circular: false });
    }
  }

  // Collect remaining unvisited chain vertices → circular rings.
  for (let i = 0; i < vertices.length; i++) {
    if (vertices[i].type !== "chain" || chainVisited[i]) continue;

    const ring: number[] = [i];
    chainVisited[i] = 1;
    let prev = -1, curr = i;

    while (true) {
      const next = adj[curr].find(x => x !== prev && !chainVisited[x]);
      if (next === undefined) break;
      chainVisited[next] = 1;
      ring.push(next);
      prev = curr;
      curr = next;
    }

    runs.push({ path: ring, circular: true });
  }

  // ── Phase 2: Determine kept vertices via DP ──────────────────────────────

  const keepVertex = new Uint8Array(vertices.length);

  // Non-chain vertices are always kept.
  for (let i = 0; i < vertices.length; i++) {
    if (vertices[i].type !== "chain") keepVertex[i] = 1;
  }

  for (const { path, circular } of runs) {
    const n = path.length;

    if (n <= 2) {
      // Degenerate run: keep every vertex as-is.
      for (const idx of path) keepVertex[idx] = 1;
      continue;
    }

    if (circular) {
      // Close the ring by duplicating path[0] at the end so DP sees a closed
      // polyline from ring[0] back to ring[0].
      const rn  = n + 1;
      const rxs = new Float64Array(rn);
      const rys = new Float64Array(rn);
      for (let j = 0; j < n; j++) {
        rxs[j] = vertices[path[j]].x;
        rys[j] = vertices[path[j]].y;
      }
      rxs[n] = rxs[0];
      rys[n] = rys[0];

      const rKeep = new Uint8Array(rn);
      rKeep[0] = 1;
      rKeep[n] = 1;
      dpRecurse(rxs, rys, rKeep, 0, n, tolerance);

      for (let j = 0; j < n; j++) {
        if (rKeep[j]) keepVertex[path[j]] = 1;
      }
      keepVertex[path[0]] = 1; // ring origin always kept as the join point

    } else {
      const xs = new Float64Array(n);
      const ys = new Float64Array(n);
      for (let j = 0; j < n; j++) {
        xs[j] = vertices[path[j]].x;
        ys[j] = vertices[path[j]].y;
      }

      const keep = new Uint8Array(n);
      keep[0]     = 1;
      keep[n - 1] = 1;
      dpRecurse(xs, ys, keep, 0, n - 1, tolerance);

      for (let j = 0; j < n; j++) {
        if (keep[j]) keepVertex[path[j]] = 1;
      }
    }
  }

  // ── Phase 3: Build simplified graph ──────────────────────────────────────

  const oldToNew = new Int32Array(vertices.length).fill(-1);
  const newVertices: PathVertex[] = [];

  for (let i = 0; i < vertices.length; i++) {
    if (keepVertex[i]) {
      oldToNew[i] = newVertices.length;
      newVertices.push({ ...vertices[i] });
    }
  }

  const newEdges: PathEdge[] = [];

  // Emit simplified edges for each chain run (consecutive kept vertices).
  for (const { path, circular } of runs) {
    const kept: number[] = [];
    for (const idx of path) {
      const ni = oldToNew[idx];
      if (ni >= 0) kept.push(ni);
    }

    if (circular) {
      for (let j = 0; j < kept.length; j++) {
        const a     = kept[j];
        const b     = kept[(j + 1) % kept.length];
        const layer = vertices[path[j]].layer;
        newEdges.push({ from: Math.min(a, b), to: Math.max(a, b), layer });
      }
    } else {
      for (let j = 0; j < kept.length - 1; j++) {
        const a     = kept[j];
        const b     = kept[j + 1];
        const layer = vertices[path[j]].layer;
        newEdges.push({ from: Math.min(a, b), to: Math.max(a, b), layer });
      }
    }
  }

  // Keep direct anchor↔anchor edges (edges whose both endpoints are anchors).
  for (const edge of edges) {
    if (vertices[edge.from].type !== "chain" && vertices[edge.to].type !== "chain") {
      const from = oldToNew[edge.from];
      const to   = oldToNew[edge.to];
      if (from >= 0 && to >= 0) {
        newEdges.push({ from: Math.min(from, to), to: Math.max(from, to), layer: edge.layer });
      }
    }
  }

  return { width, height, layerCount, vertices: newVertices, edges: newEdges };
}

// ---------------------------------------------------------------------------
// Spur removal
// ---------------------------------------------------------------------------

/**
 * Does the stroke arriving at `junction` from `armEnd` carry on out the other
 * side?
 *
 * "Carry on" means some other branch at the junction leaves roughly opposite —
 * within ~35 degrees of straight through.  Only branches that stay short are
 * considered: a tick crossing a line has two stubby arms, whereas a long
 * stroke leaving the junction is the line being crossed, not the continuation.
 */
function continuesThrough(
  verts:     PathVertex[],
  adj:       number[][],
  junction:  number,
  armEnd:    number,
  maxLength: number,
): boolean {
  const j = verts[junction];
  const inX = j.x - verts[armEnd].x, inY = j.y - verts[armEnd].y;
  const inLen = Math.hypot(inX, inY);
  if (inLen < 1e-9) return false;
  const ux = inX / inLen, uy = inY / inLen;

  for (const nb of adj[junction]) {
    if (nb === armEnd) continue;
    // Walk this branch to its own end, giving up once it is clearly long.
    let prev = junction, curr = nb, run = vertexDist(j, verts[nb]);
    while (adj[curr].length === 2 && run <= maxLength) {
      let next = -1;
      for (const n of adj[curr]) if (n !== prev) { next = n; break; }
      if (next === -1) break;
      run += vertexDist(verts[curr], verts[next]);
      prev = curr; curr = next;
    }
    if (run > maxLength) continue;          // the line being crossed
    const ox = verts[curr].x - j.x, oy = verts[curr].y - j.y;
    const oLen = Math.hypot(ox, oy);
    if (oLen < 1e-9) continue;
    // ~18 degrees.  Loose enough for a hand-drawn tick that is not quite
    // square to the line it crosses, tight enough that a whisker happening to
    // point back across the junction is not mistaken for one — at 35 degrees a
    // marginal case survived and left an unpartnered endpoint 3.8 px from its
    // neighbour, which is a watertightness leak and never worth a stub.
    if ((ux * ox + uy * oy) / oLen >= 0.95) return true;
  }
  return false;
}

/**
 * Remove spur branches from a PathGraph.
 *
 * A "spur" is a short dangling branch that:
 *   - Starts at a leaf vertex (degree 1 in the current graph), and
 *   - Terminates at a junction vertex (degree ≥ 3), with only degree-2
 *     chain vertices in between, and
 *   - Has a total Euclidean arc length ≤ `maxLength` pixels.
 *
 * Only endpoint→junction paths qualify.  Endpoint→endpoint paths (e.g.
 * individual dashes of a dashed line) are intentionally preserved.
 *
 * The removal is iterated until no further spurs are found, so chained spurs
 * are handled: removing one spur can expose another (e.g. if a junction
 * loses all but one branch it becomes a new leaf whose remaining branch may
 * itself qualify as a spur in the next pass).
 *
 * Vertex types are recomputed after each pass to reflect the updated graph.
 * Isolated vertices (degree 0) that arise from complete spur removal are
 * discarded in a final cleanup step.
 *
 * @param graph     Input path graph (typically output of `simplifyPathGraph`).
 * @param maxLength Maximum Euclidean arc length in pixels for a spur.
 * @returns         A new `PathGraph` with spurs removed.
 */
/**
 * Is there ink of `layer` at this pixel of the PRE-thinning raster?
 *
 * Supplied by the caller because `removeSpurs` works on a skeleton, which by
 * construction has thrown stroke width away — and stroke width is precisely
 * what the length threshold is being fooled by.  See `removeSpurs`.
 */
export type InkProbe = (x: number, y: number, layer: number) => boolean;

/** Build a probe over a decomposition's raw bit-planes. */
export function inkProbeFromWords(
  words: Uint32Array, width: number, height: number, rowStride: number,
): InkProbe {
  const layerWords = rowStride * height;
  return (x, y, layer) => {
    if (x < 0 || y < 0 || x >= width || y >= height) return false;
    const i = layer * layerWords + y * rowStride + (x >>> 5);
    return ((words[i] >>> (x & 31)) & 1) === 1;
  };
}

/**
 * A decoration lifted out of the skeleton: a stroke that is not part of any
 * contour, carried straight to the output rather than fitted.
 */
export interface StrokeMark {
  x1: number; y1: number; x2: number; y2: number; layer: number;
}

/**
 * How far this branch's own INK reaches from the junction, in pixels.
 *
 * The spur threshold is applied to a SKELETON arc, and thinning shortens a
 * branch's skeleton by roughly half its own stroke width — it eats in from the
 * free tip until the medial axis is reached.  That penalty is proportional to
 * how thick the branch is, so the measurement is biased against exactly the
 * branches that are most obviously real strokes.
 *
 * Measured on two plan sets: centre-point marks 10-11 px of solid ink long, as
 * thick as any stroke on the page, arrive at this test as 7-8 px skeleton arcs
 * and are deleted as whiskers.  Their ink, walked from the junction, reaches
 * 9-11.5 px.  A genuine whisker's ink stops at the edge of the stroke it is a
 * bump on, a pixel or two out.
 *
 * Note what does NOT separate the two populations, both measured over the same
 * 358 branches: the branch's thickness (a two-pixel whisker at a wide junction
 * measures 13 px "thick", because the scan at its tip is still inside the
 * parent stroke), and its length-to-thickness ratio (a continuous 0.1 to 3.9
 * with real marks scattered through it — which looked like a clean gap on ONE
 * page, and is this project's one-sheet warning collected first-hand).
 */
function inkReach(
  ink:       InkProbe | undefined,
  verts:     PathVertex[],
  tipIdx:    number,
  junctIdx:  number,
  maxWalk:   number,
): number {
  if (!ink) return 0;
  const tip = verts[tipIdx], jv = verts[junctIdx];
  const bx = tip.x - jv.x, by = tip.y - jv.y;
  const bl = Math.hypot(bx, by);
  if (bl < 1e-9) return 0;
  const ux = bx / bl, uy = by / bl;
  let reach = 0;
  for (let d = 0.5; d <= maxWalk; d += 0.5) {
    if (!ink(Math.round(jv.x + ux * d), Math.round(jv.y + uy * d), tip.layer)) break;
    reach = d;
  }
  return reach;
}

/**
 * Does this branch leave the stroke it is attached to, or run along it?
 *
 * `inkReach` walks the raster outward from the junction, and a branch pointing
 * ALONG its parent never leaves the parent's ink — so it reaches as far as the
 * parent is long and passes a test meant for something else.  Measured: a stub
 * at the end of a dash, nearly collinear with the dashed line it belongs to,
 * came out as a 9 px "mark" lying on top of geometry the fitter had already
 * covered.  Not a watertightness problem, but a second primitive cutting ink
 * that is cut once already.
 *
 * A centre-point mark crosses the stroke it marks; that is what makes it a
 * mark.  So a branch within ~25 degrees of any other branch at the junction, in
 * either sense, is a continuation rather than a decoration.
 */
function leavesTheStroke(
  verts:    PathVertex[],
  adj:      number[][],
  junction: number,
  armEnd:   number,
): boolean {
  const jv = verts[junction], av = verts[armEnd];
  const ax = av.x - jv.x, ay = av.y - jv.y;
  const al = Math.hypot(ax, ay);
  if (al < 1e-9) return false;
  const COS_LIMIT = Math.cos(25 * Math.PI / 180);
  for (const n of adj[junction]) {
    if (n === armEnd) continue;
    const nv = verts[n];
    const nx = nv.x - jv.x, ny = nv.y - jv.y;
    const nl = Math.hypot(nx, ny);
    if (nl < 1e-9) continue;
    const cos = (ax * nx + ay * ny) / (al * nl);
    if (Math.abs(cos) >= COS_LIMIT) return false;
  }
  return true;
}

export function removeSpurs(
  graph: PathGraph, maxLength: number, ink?: InkProbe, outMarks?: StrokeMark[],
): PathGraph {
  // Work on mutable copies so the original graph is not modified.
  let verts: PathVertex[] = graph.vertices.map(v => ({ ...v }));
  let edgs: PathEdge[]    = graph.edges.map(e => ({ ...e }));

  // Iteratively remove spurs until none remain.
  for (let pass = 0; pass < 1000; pass++) {
    // ── Build adjacency for current graph ──────────────────────────────────
    const adj: number[][] = Array.from({ length: verts.length }, () => []);
    for (const e of edgs) {
      adj[e.from].push(e.to);
      adj[e.to].push(e.from);
    }

    // ── Find spur vertices to remove ───────────────────────────────────────
    const removeVerts = new Set<number>();

    for (let i = 0; i < verts.length; i++) {
      if (adj[i].length !== 1) continue;   // Only start from leaves
      if (removeVerts.has(i)) continue;     // Already marked in this pass

      // Trace from leaf toward the first junction or second endpoint.
      const spurPath: number[] = [i];
      let prev = -1, curr = i;
      let arcLen = 0;
      let endsAtJunction = false;

      traceLoop: while (true) {
        // Find the one forward neighbor (exclude where we came from).
        let next = -1;
        for (const n of adj[curr]) {
          if (n !== prev) { next = n; break; }
        }
        if (next === -1) break; // dead end

        arcLen += vertexDist(verts[curr], verts[next]);
        spurPath.push(next);

        const nextDeg = adj[next].length;
        if (nextDeg === 1) {
          // Endpoint → endpoint: this is a dashed segment, not a spur.
          endsAtJunction = false;
          break traceLoop;
        }
        if (nextDeg >= 3) {
          // Endpoint → junction: confirmed spur.
          endsAtJunction = true;
          break traceLoop;
        }
        // nextDeg === 2: degree-2 chain vertex — continue tracing.
        if (arcLen > maxLength) {
          // Already exceeded threshold — definitely not a spur.
          endsAtJunction = false;
          break traceLoop;
        }
        prev = curr;
        curr = next;
      }

      if (endsAtJunction && arcLen <= maxLength) {
        // …unless the stroke carries on out the far side of the junction.
        //
        // A thinning whisker is a two-pixel bump on the SIDE of a stroke: it
        // has one arm and nothing opposite it.  A tick mark crossing a line
        // has two, roughly collinear through the junction, and the length
        // threshold cannot tell them apart — on one sheet the surviving
        // whiskers stop at 5.8 px, on another a real tick has 8 px arms, so no
        // single number serves both.  Symmetry does: ask whether the branch
        // continues, and short arms of a crossing stroke are kept at any
        // length while a lone whisker is still pruned.
        const junction = spurPath[spurPath.length - 1];
        const armEnd   = spurPath[spurPath.length - 2];
        if (!continuesThrough(verts, adj, junction, armEnd, maxLength)) {
          // A branch whose own ink runs well past the threshold is a stroke,
          // not a whisker — a centre-point mark, a tick, a witness line.  It is
          // still pruned from the graph: attaching it would turn a degree-2
          // vertex into a junction, which splits chains, opens closed contours
          // and re-segments everything downstream.  Measured, that cost three
          // watertightness leaks across 16 pages, one of them a 26.9 px hole
          // inside a chain nowhere near any spared branch.
          //
          // So it leaves as a DECORATION instead: its own stroke, carried
          // straight to the output, exactly as a centreline on another ink is
          // its own stroke.  It is not part of any contour and does not need to
          // be joined to one — and taking its extent from the ink rather than
          // the skeleton gives the whole mark rather than the eroded remainder,
          // which is the point, since these are what the parts are aligned by.
          if (outMarks && ink && leavesTheStroke(verts, adj, junction, armEnd)) {
            const reach = inkReach(ink, verts, spurPath[0], junction, maxLength * 3);
            if (reach > maxLength) {
              const tip = verts[spurPath[0]], jv = verts[junction];
              const bl = Math.hypot(tip.x - jv.x, tip.y - jv.y) || 1;
              const ux = (tip.x - jv.x) / bl, uy = (tip.y - jv.y) / bl;
              outMarks.push({
                x1: jv.x, y1: jv.y,
                x2: jv.x + ux * reach, y2: jv.y + uy * reach,
                layer: tip.layer,
              });
            }
          }
          // Mark all spur vertices except the terminal junction for removal.
          for (let k = 0; k < spurPath.length - 1; k++) {
            removeVerts.add(spurPath[k]);
          }
        }
      }
    }

    if (removeVerts.size === 0) break; // Stable — no more spurs.

    // ── Remove marked vertices and their incident edges ────────────────────
    edgs = edgs.filter(e => !removeVerts.has(e.from) && !removeVerts.has(e.to));

    const oldToNew = new Int32Array(verts.length).fill(-1);
    let nextIdx = 0;
    verts = verts.filter((_, i) => {
      if (removeVerts.has(i)) return false;
      oldToNew[i] = nextIdx++;
      return true;
    });
    edgs = edgs.map(e => ({ from: oldToNew[e.from], to: oldToNew[e.to], layer: e.layer }));

    // ── Recompute vertex types from new degrees ────────────────────────────
    const newAdj: number[][] = Array.from({ length: verts.length }, () => []);
    for (const e of edgs) {
      newAdj[e.from].push(e.to);
      newAdj[e.to].push(e.from);
    }
    for (let i = 0; i < verts.length; i++) {
      const d = newAdj[i].length;
      verts[i].type = d === 0 ? "isolated"
                    : d === 1 ? "endpoint"
                    : d === 2 ? "chain"
                    :           "junction";
    }
  }

  // ── Final cleanup: discard isolated vertices (degree 0) ───────────────────
  const finalAdj: number[][] = Array.from({ length: verts.length }, () => []);
  for (const e of edgs) {
    finalAdj[e.from].push(e.to);
    finalAdj[e.to].push(e.from);
  }
  const finalOToN = new Int32Array(verts.length).fill(-1);
  let fi = 0;
  const finalVerts = verts.filter((_, i) => {
    if (finalAdj[i].length === 0) return false;
    finalOToN[i] = fi++;
    return true;
  });
  const finalEdgs = edgs.map(e => ({
    from:  finalOToN[e.from],
    to:    finalOToN[e.to],
    layer: e.layer,
  }));

  return { width: graph.width, height: graph.height, layerCount: graph.layerCount,
           vertices: finalVerts, edges: finalEdgs };
}
