/**
 * Application state.
 *
 * Single mutable state object for the cleanplans-web app.
 * UI modules read and write this; the main module coordinates transitions.
 */

import type { RGBAImage } from "../src/formats/rgba_image.ts";
import type { RenderedPage } from "../src/pdf/pdf_render.ts";
import type { OnnxSession } from "../src/denoise/onnx_session.ts";
import type { PDFDocument } from "../src/pdf/pdf_render.ts";
import type { PaletteEntry, BWCounts } from "../src/color/palette.ts";
import type { EditablePalette } from "../src/color/palette_editor.ts";
import type { PaletteDecomposition } from "../src/gpu/palette_decompose.ts";
import type { PaletteLayer } from "../src/gpu/palette_decompose_types.ts";
import type { PathGraph } from "../src/gpu/path_connect.ts";
import type { StrokeMark } from "../src/gpu/path_simplify.ts";
import type { CurveGraph } from "../src/gpu/curve_fit.ts";
import type { LayoutResult } from "./ui/page_layout.ts";
import type { PageSize } from "../src/pdf/pdf_render.ts";

/** Which screen is currently visible. */
export type AppScreen = "upload" | "viewer";

/** Which image the viewer is displaying. */
/**
 * Which raster the viewer draws.  "combined" recomposes every ink layer over
 * white — byte-for-byte the clean PNG/PDF export — and is labelled
 * "Cleaned page" in the UI.
 */
export type ViewerLayer = "raw" | "denoised" | "layer" | "combined";

export interface AppState {
  // --- Screen navigation ---
  currentScreen: AppScreen;

  // --- PDF state ---
  currentFileId: string | null; // IndexedDB file ID
  pdfDoc: PDFDocument | null;
  pdfFileName: string;
  pdfPageCount: number;
  selectedPage: number; // 1-indexed; 0 = none selected

  // --- Rendered images ---
  rawImage: RenderedPage | null;
  croppedRawImage: RGBAImage | null;
  denoisedImage: RGBAImage | null;

  // --- Crop ---
  cropRect: { x: number; y: number; width: number; height: number } | null;
  cropMode: boolean; // true = crop handles interactive (before denoise)

  // --- Viewer ---
  viewerLayer: ViewerLayer;
  activeLayerIndex: number;   // index into paletteDecomposition.layers; -1 = none
  zoom: number;
  panX: number;
  panY: number;

  // --- Denoise session ---
  onnxSession: OnnxSession | null;
  isDenoising: boolean;
  denoiseProgress: number; // 0..1
  isPaletteExtracting: boolean;

  // --- Project-level page selection ---
  selectedPages: Set<number>;     // pages toggled for processing (1-indexed)
  coverPage: number;              // page used as file list thumbnail (default: 1)
  denoisedPages: Set<number>;     // which pages have denoised images in IDB
  pageLabels: string[];           // cached page labels from PDF
  pageSizes: PageSize[];          // cached page sizes from PDF

  // --- Multi-page layout ---
  pageLayout: LayoutResult | null;
  activePageNumber: number;       // which page is centered in viewport (1-indexed)
  cropRects: Map<number, { x: number; y: number; width: number; height: number }>;
  cropLocked: boolean;            // true = same crop rect applied to all pages

  // --- Palette ---
  paletteEntries: PaletteEntry[] | null;
  bwCounts: BWCounts | null;
  editablePalette: EditablePalette | null;
  /** GPU decomposition results, one per page (keyed by 1-indexed page number). */
  paletteDecompositions: Map<number, PaletteDecomposition>;
  /** Guo-Hall thinned versions of paletteDecompositions. */
  /**
   * Thinned bit-planes.  Transient: `runPathConnect` releases each page's GPU
   * buffer as soon as its path graph exists, because nothing downstream reads
   * the skeleton bitmap again — only the ink colours, which live in
   * `inkLayers`.  A 6000x4000 page costs ~9 MB of GPU per decomposition, so on
   * a 20-page plan holding these for the whole session was hundreds of MB of
   * GPU memory doing nothing.
   */
  thinnedDecompositions: Map<number, PaletteDecomposition>;
  /** Ink metadata (colours) per page — outlives thinnedDecompositions. */
  inkLayers: Map<number, PaletteLayer[]>;
  isThinning: boolean;
  isVectorizing: boolean;
  /** Path graphs extracted from thinnedDecompositions (keyed by 1-indexed page number). */
  pathGraphs: Map<number, PathGraph>;
  /** Douglas-Peucker simplified + spur-removed versions of pathGraphs. */
  simplifiedPathGraphs: Map<number, PathGraph>;
  /** Undashed versions of simplifiedPathGraphs (burr-trimmed + gap-bridged). */
  undashedPathGraphs: Map<number, PathGraph>;
  /**
   * Decorations lifted out of the skeleton by spur removal — centre-point
   * marks and the like, which are strokes rather than contour, and are carried
   * to the output without being fitted.  See `removeSpurs`.
   */
  strokeMarks: Map<number, StrokeMark[]>;
  /** Fitted geometric primitives (lines/arcs/circles) from curve fitting pass. */
  curveGraphs: Map<number, CurveGraph>;
  /** Tessellated PathGraphs for rendering curveGraphs in the graph overlay. */
  curvePathGraphs: Map<number, PathGraph>;
  /** Whether the fitted lines/arcs/circles are drawn over the raster. */
  showFittedCurves: boolean;

  // --- Status ---
  statusMessage: string;
}

export const state: AppState = {
  currentScreen: "upload",
  currentFileId: null,
  pdfDoc: null,
  pdfFileName: "",
  pdfPageCount: 0,
  selectedPage: 0,
  rawImage: null,
  croppedRawImage: null,
  denoisedImage: null,
  cropRect: null,
  cropMode: true,
  viewerLayer: "raw",
  activeLayerIndex: -1,
  zoom: 1,
  panX: 0,
  panY: 0,
  onnxSession: null,
  isDenoising: false,
  denoiseProgress: 0,
  isPaletteExtracting: false,
  selectedPages: new Set(),
  coverPage: 1,
  denoisedPages: new Set(),
  pageLabels: [],
  pageSizes: [],
  pageLayout: null,
  activePageNumber: 0,
  cropRects: new Map(),
  cropLocked: true,
  paletteEntries: null,
  bwCounts: null,
  editablePalette: null,
  paletteDecompositions: new Map(),
  thinnedDecompositions: new Map(),
  inkLayers: new Map(),
  isThinning: false,
  isVectorizing: false,
  pathGraphs: new Map(),
  simplifiedPathGraphs: new Map(),
  undashedPathGraphs: new Map(),
  strokeMarks: new Map(),
  curveGraphs: new Map(),
  curvePathGraphs: new Map(),
  showFittedCurves: true,
  statusMessage: "Ready",
};
