/**
 * Vector export: CurveGraph → SVG, DXF (R12 ASCII), and PDF content streams.
 *
 * Consumes the fitted `CurveGraph` (lines, arcs, circles) directly, so exported
 * geometry matches the fit exactly — no re-tessellation. One SVG `<path>` per
 * chain (lines as `L`, arcs as `A`), full circles as `<circle>`; DXF emits
 * LINE / ARC / CIRCLE entities.
 *
 * Coordinate conventions:
 *   - CurveGraph coordinates are continuous pixels at a known render DPI.
 *   - SVG keeps image orientation (Y down) and declares physical size in
 *     inches so consumers get correct real-world scale.
 *   - DXF is emitted in millimetres with Y flipped (DXF Y grows upward); arc
 *     sweep sense is flipped accordingly (DXF arcs are always CCW start→end).
 *   - The PDF overlay stays in PIXELS, Y down; `encodeCleanPdf` installs the
 *     transform that puts those pixels on the page. See `curveGraphToPdfOverlay`.
 */

import type { CurveGraph, CurveSegment } from "../gpu/curve_fit.ts";
import type {
  LinePrimitive,
  ArcPrimitive,
  CirclePrimitive,
} from "../gpu/curve_fit_math.ts";

// ---------------------------------------------------------------------------
// Public types
// ---------------------------------------------------------------------------

export interface ExportLayer {
  /** Human-readable layer name (sanitized for DXF). */
  name: string;
  /** Stroke colour, sRGB 0-255. */
  rgb: [number, number, number];
}

export interface ExportOptions {
  /** Pixels per inch of the graph's coordinate space (e.g. 200). */
  dpi: number;
  /** Per-layer styling, indexed by CurveSegment.layer. */
  layers: ExportLayer[];
}

// ---------------------------------------------------------------------------
// Formatting helpers
// ---------------------------------------------------------------------------

/** Compact numeric formatting: up to `digits` decimals, no trailing zeros. */
function fmt(n: number, digits = 4): string {
  return String(Number(n.toFixed(digits)));
}

function hexColor([r, g, b]: [number, number, number]): string {
  const h = (v: number) => v.toString(16).padStart(2, "0");
  return `#${h(r)}${h(g)}${h(b)}`;
}

/** DXF layer names: uppercase alphanumerics and underscores only. */
export function sanitizeDxfName(name: string, fallback: string): string {
  const s = name.toUpperCase().replace(/[^A-Z0-9_]+/g, "_").replace(/^_+|_+$/g, "");
  return s.length > 0 ? s : fallback;
}

/** Standard ACI colours 1-9 for broad reader compatibility. */
const ACI_TABLE: [number, [number, number, number]][] = [
  [1, [255, 0, 0]],     // red
  [2, [255, 255, 0]],   // yellow
  [3, [0, 255, 0]],     // green
  [4, [0, 255, 255]],   // cyan
  [5, [0, 0, 255]],     // blue
  [6, [255, 0, 255]],   // magenta
  [7, [0, 0, 0]],       // black/white
  [8, [128, 128, 128]], // dark gray
  [9, [192, 192, 192]], // light gray
];

/** Nearest ACI (AutoCAD Color Index) for an sRGB colour. */
export function nearestAci([r, g, b]: [number, number, number]): number {
  let best = 7;
  let bestDist = Infinity;
  for (const [aci, [ar, ag, ab]] of ACI_TABLE) {
    const d = (r - ar) ** 2 + (g - ag) ** 2 + (b - ab) ** 2;
    if (d < bestDist) { bestDist = d; best = aci; }
  }
  return best;
}

// ---------------------------------------------------------------------------
// Primitive endpoint geometry
// ---------------------------------------------------------------------------

function lineStart(p: LinePrimitive) { return { x: p.x1, y: p.y1 }; }
function lineEnd(p: LinePrimitive) { return { x: p.x2, y: p.y2 }; }
function arcStart(p: ArcPrimitive) {
  return { x: p.cx + p.r * Math.cos(p.startAngle), y: p.cy + p.r * Math.sin(p.startAngle) };
}
function arcEnd(p: ArcPrimitive) {
  return { x: p.cx + p.r * Math.cos(p.endAngle), y: p.cy + p.r * Math.sin(p.endAngle) };
}

/** Angular span magnitude (radians) of an arc, from its endpoints and ccw. */
function arcSweepMag(p: ArcPrimitive): number {
  // Prefer the primitive's own sweep field; fall back to angle difference.
  if (typeof p.sweep === "number" && p.sweep > 0) return p.sweep;
  const twoPi = 2 * Math.PI;
  const d = p.ccw ? (p.endAngle - p.startAngle) : (p.startAngle - p.endAngle);
  return ((d % twoPi) + twoPi) % twoPi;
}

/**
 * A drawable segment oriented for path traversal. `sweepFlag` is only
 * meaningful for arcs: it is the SVG sweep flag for the chosen traversal
 * direction (reversing an arc flips it).
 */
interface Oriented {
  sx: number; sy: number;
  ex: number; ey: number;
  prim: LinePrimitive | ArcPrimitive;
  sweepFlag: 0 | 1;
}

function orient(prim: LinePrimitive | ArcPrimitive, reversed: boolean): Oriented {
  const s = prim.type === "line" ? lineStart(prim) : arcStart(prim);
  const e = prim.type === "line" ? lineEnd(prim) : arcEnd(prim);
  const fwdSweep: 0 | 1 = prim.type === "arc" && prim.ccw ? 1 : 0;
  return reversed
    ? { sx: e.x, sy: e.y, ex: s.x, ey: s.y, prim, sweepFlag: fwdSweep === 1 ? 0 : 1 }
    : { sx: s.x, sy: s.y, ex: e.x, ey: e.y, prim, sweepFlag: fwdSweep };
}

/**
 * Orient a chain's segments for continuous traversal.
 *
 * The fitter emits segments in chain-flow order with matching endpoints, but
 * this is defensive: each segment is flipped if its far endpoint is the one
 * nearer the current pen (validation tracks "backward" segments as a known
 * failure class, and reversed arcs would otherwise render on the wrong side).
 * The first segment is oriented toward whichever of the *next* segment's
 * endpoints is nearest.
 */
function orientChain(prims: (LinePrimitive | ArcPrimitive)[]): Oriented[] {
  const d2 = (ax: number, ay: number, bx: number, by: number) =>
    (ax - bx) ** 2 + (ay - by) ** 2;

  const out: Oriented[] = [];
  for (let i = 0; i < prims.length; i++) {
    const fwd = orient(prims[i], false);
    const rev = orient(prims[i], true);
    if (i === 0) {
      if (prims.length === 1) { out.push(fwd); continue; }
      // Choose the orientation whose end is nearest the next segment.
      const next = orient(prims[1], false);
      const score = (o: Oriented) =>
        Math.min(d2(o.ex, o.ey, next.sx, next.sy), d2(o.ex, o.ey, next.ex, next.ey));
      out.push(score(fwd) <= score(rev) ? fwd : rev);
    } else {
      const pen = out[i - 1];
      out.push(
        d2(fwd.sx, fwd.sy, pen.ex, pen.ey) <= d2(rev.sx, rev.sy, pen.ex, pen.ey)
          ? fwd : rev,
      );
    }
  }
  return out;
}

/** Max gap (px) between consecutive segments before starting a new subpath. */
const CHAIN_JOIN_EPS = 1.0;

/** Group a graph's segments by chainId, preserving segment order. */
function groupByChain(segments: CurveSegment[]): CurveSegment[][] {
  const byChain = new Map<number, CurveSegment[]>();
  for (const seg of segments) {
    const arr = byChain.get(seg.chainId);
    if (arr) arr.push(seg);
    else byChain.set(seg.chainId, [seg]);
  }
  return [...byChain.values()];
}

// ---------------------------------------------------------------------------
// SVG
// ---------------------------------------------------------------------------

export function curveGraphToSvg(graph: CurveGraph, options: ExportOptions): string {
  const { dpi, layers } = options;
  const wIn = fmt(graph.width / dpi, 3);
  const hIn = fmt(graph.height / dpi, 3);

  const chainsByLayer = new Map<number, CurveSegment[][]>();
  for (const chain of groupByChain(graph.segments)) {
    const layer = chain[0].layer;
    let list = chainsByLayer.get(layer);
    if (!list) chainsByLayer.set(layer, list = []);
    list.push(chain);
  }

  const parts: string[] = [];
  parts.push(
    `<svg xmlns="http://www.w3.org/2000/svg" width="${wIn}in" height="${hIn}in" ` +
    `viewBox="0 0 ${graph.width} ${graph.height}">`,
  );
  parts.push(`<g fill="none" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">`);

  for (const layerIdx of [...chainsByLayer.keys()].sort((a, b) => a - b)) {
    const rgb = layers[layerIdx]?.rgb ?? [0, 0, 0];
    parts.push(`<g stroke="${hexColor(rgb)}">`);
    for (const chain of chainsByLayer.get(layerIdx)!) {
      // Lone full circle → <circle>.
      if (chain.length === 1 && chain[0].primitive.type === "circle") {
        const c = chain[0].primitive as CirclePrimitive;
        parts.push(`<circle cx="${fmt(c.cx, 2)}" cy="${fmt(c.cy, 2)}" r="${fmt(c.r, 3)}"/>`);
        continue;
      }

      // One path per chain: pen-tracking traversal with defensive orientation.
      // A gap larger than CHAIN_JOIN_EPS starts a new subpath rather than
      // silently drawing a connector that isn't in the fit.
      const prims = chain
        .map((seg) => seg.primitive)
        .filter((p): p is LinePrimitive | ArcPrimitive => p.type !== "circle");
      if (prims.length === 0) continue;

      const oriented = orientChain(prims);
      const d: string[] = [];
      let penX = NaN, penY = NaN;
      for (const o of oriented) {
        const disconnected = !Number.isFinite(penX) ||
          Math.hypot(o.sx - penX, o.sy - penY) > CHAIN_JOIN_EPS;
        if (disconnected) d.push(`M ${fmt(o.sx, 2)} ${fmt(o.sy, 2)}`);
        if (o.prim.type === "line") {
          d.push(`L ${fmt(o.ex, 2)} ${fmt(o.ey, 2)}`);
        } else {
          const r = fmt(o.prim.r, 3);
          const largeArc = arcSweepMag(o.prim) > Math.PI ? 1 : 0;
          d.push(`A ${r} ${r} 0 ${largeArc} ${o.sweepFlag} ${fmt(o.ex, 2)} ${fmt(o.ey, 2)}`);
        }
        penX = o.ex; penY = o.ey;
      }
      if (chain[0].isClosed) d.push("Z");
      parts.push(`<path d="${d.join(" ")}"/>`);
    }
    parts.push(`</g>`);
  }

  parts.push(`</g>`);
  parts.push(`</svg>`);
  return parts.join("\n") + "\n";
}

// ---------------------------------------------------------------------------
// PDF content stream (the vector overlay on a cleaned page)
// ---------------------------------------------------------------------------

/**
 * Overlay stroke colours, cycled by layer index.
 *
 * Deliberately NOT the ink colours. The overlay exists to be compared against
 * the ink underneath it, and a fit drawn in the same colour as the stroke it is
 * fitting hides exactly the disagreement you opened the file to look for.
 * These are ordered so the first layers get hues that are rare in a scanned
 * drawing, and each stays legible over black.
 */
export const OVERLAY_COLORS: Array<[number, number, number]> = [
  [230, 0, 200],   // magenta
  [0, 120, 255],   // blue
  [255, 130, 0],   // orange
  [0, 170, 90],    // green
  [150, 60, 255],  // violet
];

export interface PdfOverlayOptions extends ExportOptions {
  /**
   * Stroke width in PIXELS of the graph's own coordinate space, so the overlay
   * keeps the same weight relative to the ink at any DPI. Thin on purpose: the
   * ink either side of the fitted centreline is the evidence being checked, and
   * a fat overlay covers it up.
   */
  strokeWidthPx?: number;
  /** Per-layer stroke colours; defaults to `OVERLAY_COLORS`, cycled. */
  colors?: Array<[number, number, number]>;
}

/** Hard cap on radians per Bézier section: the approximation degrades past 90°. */
const MAX_BEZIER_ARC = Math.PI / 2;

/**
 * How far a flattened arc may stray from the fitted circle, in pixels.
 *
 * The fitter's own tolerances are in hundredths of a pixel (a line is frozen at
 * CE ≤ 0.25 px), so an overlay meant for judging that fit has to be an order of
 * magnitude tighter still, or what you see is the flattening error rather than
 * the fit.
 */
const ARC_TOL_PX = 0.01;

/**
 * Worst-case radial error of the k = 4/3·tan(θ/4) cubic arc approximation,
 * as a coefficient in `err ≈ ERR_COEFF · r · θ⁶`.
 *
 * Measured by sampling the Bézier against the unit circle: the ratio is
 * 1.81e-5 from 15° to 90°, and gives 2.7e-4·r at 90° — the familiar "a quarter
 * circle is good to 0.027%". That is NOT small enough here by itself: a plan
 * sheet at 200 dpi routinely carries arcs of 2000 px radius, where 90°
 * sections would sit 0.54 px off the fit — worse than the fitter's own
 * thresholds, and visible. Hence a section count derived from the radius.
 */
const ERR_COEFF = 1.81e-5;

/**
 * Append cubic Béziers tracing `radius` about (cx,cy) from `a0` through `delta`
 * radians (signed), assuming the pen is already at the start point.
 *
 * PDF has no arc operator — `m l c v y re h` is the whole path vocabulary — so
 * every arc and circle becomes cubics. Sections are sized so the result stays
 * within ARC_TOL_PX of the true circle at any radius: inverting the error law
 * gives θ ≤ (tol / (ERR_COEFF·r))^(1/6). The sixth root makes this cheap — a
 * 2000 px arc needs 46° sections, so even a full circle costs eight cubics.
 */
function arcToBeziers(
  out: string[], cx: number, cy: number, r: number, a0: number, delta: number,
): void {
  const maxTheta = r > 0
    ? Math.min(MAX_BEZIER_ARC, Math.pow(ARC_TOL_PX / (ERR_COEFF * r), 1 / 6))
    : MAX_BEZIER_ARC;
  const n = Math.max(1, Math.ceil(Math.abs(delta) / maxTheta));
  const theta = delta / n;
  const k = (4 / 3) * Math.tan(theta / 4);
  let a = a0;
  for (let i = 0; i < n; i++) {
    const b = a + theta;
    const cosA = Math.cos(a), sinA = Math.sin(a);
    const cosB = Math.cos(b), sinB = Math.sin(b);
    // Tangents are the derivative of (cos,sin), scaled by k·r.
    const x1 = cx + r * (cosA - k * sinA), y1 = cy + r * (sinA + k * cosA);
    const x2 = cx + r * (cosB + k * sinB), y2 = cy + r * (sinB - k * cosB);
    const x3 = cx + r * cosB, y3 = cy + r * sinB;
    out.push(
      `${fmt(x1, 3)} ${fmt(y1, 3)} ${fmt(x2, 3)} ${fmt(y2, 3)} ` +
      `${fmt(x3, 3)} ${fmt(y3, 3)} c`,
    );
    a = b;
  }
}

/**
 * Render a fitted graph as a PDF content-stream fragment: the vectors alone,
 * stroked, with no page setup around them.
 *
 * The fragment is written in the graph's own PIXEL coordinates with Y pointing
 * DOWN — the same space `curveGraphToSvg` uses, and the space the fit itself
 * lives in. It is `encodeCleanPdf` that installs the `cm` mapping pixels onto
 * the page, which is what keeps the overlay in exact register with the cleaned
 * raster underneath: both are placed by the same page geometry, from the same
 * width/height/DPI, rather than each converting to points on its own and
 * agreeing only to within rounding.
 *
 * Returns "" for a graph with nothing drawable, which callers can treat as
 * "no overlay" without special-casing.
 */
export function curveGraphToPdfOverlay(
  graph: CurveGraph, options: PdfOverlayOptions,
): string {
  const colors = options.colors ?? OVERLAY_COLORS;
  const width = options.strokeWidthPx ?? 1;

  const chainsByLayer = new Map<number, CurveSegment[][]>();
  for (const chain of groupByChain(graph.segments)) {
    const layer = chain[0].layer;
    let list = chainsByLayer.get(layer);
    if (!list) chainsByLayer.set(layer, list = []);
    list.push(chain);
  }
  if (chainsByLayer.size === 0) return "";

  const ops: string[] = [];
  // Round caps and joins, matching the SVG export, so a chain's corners look
  // the same in both and neither invents a mitre spike the fit does not have.
  ops.push(`${fmt(width, 3)} w 1 J 1 j`);

  for (const layerIdx of [...chainsByLayer.keys()].sort((a, b) => a - b)) {
    const [r, g, b] = colors[layerIdx % colors.length];
    ops.push(`${fmt(r / 255, 4)} ${fmt(g / 255, 4)} ${fmt(b / 255, 4)} RG`);

    for (const chain of chainsByLayer.get(layerIdx)!) {
      // Lone full circle: start at angle 0 and sweep all the way round.
      if (chain.length === 1 && chain[0].primitive.type === "circle") {
        const c = chain[0].primitive as CirclePrimitive;
        ops.push(`${fmt(c.cx + c.r, 3)} ${fmt(c.cy, 3)} m`);
        arcToBeziers(ops, c.cx, c.cy, c.r, 0, 2 * Math.PI);
        ops.push("h S");
        continue;
      }

      const prims = chain
        .map((seg) => seg.primitive)
        .filter((p): p is LinePrimitive | ArcPrimitive => p.type !== "circle");
      if (prims.length === 0) continue;

      // Same pen-tracking traversal as the SVG path builder: a gap wider than
      // CHAIN_JOIN_EPS lifts the pen rather than drawing a connector the fit
      // never produced.
      const oriented = orientChain(prims);
      let penX = NaN, penY = NaN;
      let open = false;
      for (const o of oriented) {
        if (!Number.isFinite(penX) || Math.hypot(o.sx - penX, o.sy - penY) > CHAIN_JOIN_EPS) {
          if (open) ops.push("S");
          ops.push(`${fmt(o.sx, 3)} ${fmt(o.sy, 3)} m`);
          open = true;
        }
        if (o.prim.type === "line") {
          ops.push(`${fmt(o.ex, 3)} ${fmt(o.ey, 3)} l`);
        } else {
          // sweepFlag is the SVG flag for the chosen traversal direction, and
          // matches the graph's angle sense: 1 = increasing angle.
          const mag = arcSweepMag(o.prim);
          const a0 = Math.atan2(o.sy - o.prim.cy, o.sx - o.prim.cx);
          arcToBeziers(ops, o.prim.cx, o.prim.cy, o.prim.r, a0, o.sweepFlag === 1 ? mag : -mag);
        }
        penX = o.ex; penY = o.ey;
      }
      if (open) {
        if (chain[0].isClosed) ops.push("h");
        ops.push("S");
      }
    }
  }

  return ops.join("\n") + "\n";
}

// ---------------------------------------------------------------------------
// DXF (R12 ASCII)
// ---------------------------------------------------------------------------

/**
 * Minimal AutoCAD R12 (AC1009) ASCII DXF: a LAYER table plus LINE / ARC /
 * CIRCLE entities. R12 is the most universally supported DXF flavour.
 *
 * Units are MILLIMETRES ($INSUNITS=4, $MEASUREMENT=1) — machines run in mm, and
 * inches appear in this project only because the foam-board stock is sold as
 * 20x30". The drawing origin is the bottom-left corner of the page area.
 */
export function curveGraphToDxf(graph: CurveGraph, options: ExportOptions): string {
  const { dpi } = options;

  // Ensure the LAYER table covers every layer index referenced by a segment,
  // even when caller-supplied styling is missing or short — entities must not
  // reference layer names absent from the table.
  let maxLayer = options.layers.length - 1;
  for (const seg of graph.segments) if (seg.layer > maxLayer) maxLayer = seg.layer;
  const layers: ExportLayer[] = [];
  for (let i = 0; i <= maxLayer; i++) {
    layers.push(options.layers[i] ?? { name: `Layer ${i + 1}`, rgb: [0, 0, 0] });
  }

  const layerNames = layers.map((l, i) => sanitizeDxfName(l.name, `LAYER_${i + 1}`));
  const nameFor = (idx: number) => layerNames[idx] ?? `LAYER_${idx + 1}`;

  const rows: string[] = [];
  const tag = (code: number, value: string | number) => { rows.push(String(code), String(value)); };

  // Image → DXF coordinate helpers (Y-up, millimetres).
  // Pixels are converted via the render DPI, then inches → mm.  Millimetres are
  // the unit machines actually run in; inches appear here only because the
  // foam-board stock is sold as 20x30".
  const MM_PER_IN = 25.4;
  const X = (x: number) => x / dpi * MM_PER_IN;
  const Y = (y: number) => (graph.height - y) / dpi * MM_PER_IN;
  /** Lengths (radius etc.) share the same scale but no origin flip. */
  const S = (v: number) => v / dpi * MM_PER_IN;
  /** DXF-space angle (deg, [0,360)) of an image point about an image center. */
  const angDeg = (cx: number, cy: number, px: number, py: number): number => {
    const a = Math.atan2(cy - py, px - cx) * 180 / Math.PI; // Y-flip folded in
    return ((a % 360) + 360) % 360;
  };

  // ── HEADER ────────────────────────────────────────────────────────────────
  tag(0, "SECTION"); tag(2, "HEADER");
  tag(9, "$ACADVER"); tag(1, "AC1009");
  // Declare the units explicitly.  Coordinates below are inches, but a DXF that
  // states no units is imported as "unitless" by most CAM/CAD, which commonly
  // defaults to millimetres — silently scaling a 30" part to 30 mm (or 25.4x
  // the other way) on the machine.  $INSUNITS is nominally R13+ and
  // $MEASUREMENT R12-era; unknown header variables are skipped by readers, so
  // emitting both is safe and makes the intent unambiguous either way.
  tag(9, "$INSUNITS"); tag(70, 4);     // 4 = millimetres
  tag(9, "$MEASUREMENT"); tag(70, 1);  // 1 = metric
  tag(9, "$LUNITS"); tag(70, 2);       // 2 = decimal
  tag(9, "$EXTMIN"); tag(10, 0); tag(20, 0); tag(30, 0);
  tag(9, "$EXTMAX"); tag(10, fmt(S(graph.width))); tag(20, fmt(S(graph.height))); tag(30, 0);
  tag(0, "ENDSEC");

  // ── TABLES: layers ────────────────────────────────────────────────────────
  tag(0, "SECTION"); tag(2, "TABLES");
  tag(0, "TABLE"); tag(2, "LAYER"); tag(70, layers.length);
  for (let i = 0; i < layers.length; i++) {
    tag(0, "LAYER"); tag(2, nameFor(i)); tag(70, 0);
    tag(62, nearestAci(layers[i].rgb)); tag(6, "CONTINUOUS");
  }
  tag(0, "ENDTAB"); tag(0, "ENDSEC");

  // ── ENTITIES ──────────────────────────────────────────────────────────────
  tag(0, "SECTION"); tag(2, "ENTITIES");
  for (const seg of graph.segments) {
    const layerName = nameFor(seg.layer);
    const p = seg.primitive;

    if (p.type === "line") {
      tag(0, "LINE"); tag(8, layerName);
      tag(10, fmt(X(p.x1))); tag(20, fmt(Y(p.y1))); tag(30, 0);
      tag(11, fmt(X(p.x2))); tag(21, fmt(Y(p.y2))); tag(31, 0);
    } else if (p.type === "circle") {
      tag(0, "CIRCLE"); tag(8, layerName);
      tag(10, fmt(X(p.cx))); tag(20, fmt(Y(p.cy))); tag(30, 0);
      tag(40, fmt(S(p.r)));
    } else {
      // Arc. Y-flip reverses rotation sense: an image-ccw arc is DXF-clockwise,
      // so to express it as DXF-ccw (start→end) we swap endpoints.
      const s = arcStart(p), e = arcEnd(p);
      const [sx, sy, ex, ey] = p.ccw ? [e.x, e.y, s.x, s.y] : [s.x, s.y, e.x, e.y];
      tag(0, "ARC"); tag(8, layerName);
      tag(10, fmt(X(p.cx))); tag(20, fmt(Y(p.cy))); tag(30, 0);
      tag(40, fmt(S(p.r)));
      tag(50, fmt(angDeg(p.cx, p.cy, sx, sy), 3));
      tag(51, fmt(angDeg(p.cx, p.cy, ex, ey), 3));
    }
  }
  tag(0, "ENDSEC");
  tag(0, "EOF");

  return rows.join("\r\n") + "\r\n";
}
