/**
 * ONNX Runtime session management.
 *
 * Loads the best available model variant and provides a typed inference
 * interface.  Three model variants are supported, selected automatically
 * based on detected GPU capabilities:
 *
 *   f16   — WebGPU EP + shader-f16 + Float16Array (fastest on supported hardware)
 *   f32   — WebGPU EP, float32 (works on any WebGPU-capable browser)
 *   uint8 — WASM EP, int8-quantized weights + uint8 I/O (CPU fallback)
 *           The model has built-in DequantizeLinear/QuantizeLinear nodes so the
 *           JS caller passes Uint8Array [0,255] directly — no float allocation.
 *
 * Selection logic
 * ───────────────
 *   navigator.gpu present?
 *     Yes → requestAdapter()
 *       Adapter has shader-f16 AND browser has Float16Array? → f16 model, WebGPU EP
 *       WebGPU only (no f16)?                                → f32 model, WebGPU EP
 *     No adapter / error                                     → uint8 model, WASM EP
 *   No navigator.gpu                                         → uint8 model, WASM EP
 *
 * ONNX Runtime Web is loaded from CDN (see index.html) and exposed
 * as `window.ort`.
 */

// deno-lint-ignore no-explicit-any
import { isSoftwareAdapter } from "../gpu/software_adapter.ts";

declare const ort: any;

const LOG = "[ONNX]";

/** URLs for the three precision variants of the denoiser model. */
export interface ModelVariants {
  /** Float32 model — WebGPU EP, works wherever WebGPU is supported. */
  f32: string;
  /** Float16 model — WebGPU EP + shader-f16; native float16 I/O (no Cast nodes).
   *  Requires Float16Array support (Chrome 133+) and the shader-f16 GPU feature. */
  f16: string;
  /** INT8 quantized model with uint8 I/O — WASM EP only.
   *  Weights are int8; built-in DequantizeLinear/QuantizeLinear nodes handle
   *  the [0,255] ↔ [0,1] conversion inside WASM, so the JS caller passes
   *  Uint8Array directly. */
  int8: string;
  /**
   * Receptive field of the model in pixels.
   *
   * ORT Web 1.x does not expose ONNX `metadata_props` via its session API
   * (`session.modelMetadata` is undefined at runtime), so this must be passed
   * explicitly.  It matches the `receptive_field` written to ONNX metadata by
   * export_onnx.py (e.g. 45 for DilatedDnCNNSmall).
   *
   * Used by the tiled denoiser to compute per-tile padding so that inference
   * at tile edges matches full-image results.
   */
  receptiveField: number;
}

export interface OnnxSession {
  /**
   * Run inference on a single input tensor.
   *
   * The array type must match `session.precision`:
   *   f16   → Float16Array in/out  (WebGPU + shader-f16)
   *   f32   → Float32Array in/out  (WebGPU)
   *   uint8 → Uint8Array   in/out  (WASM; values in [0, 255])
   *
   * @param inputName  Name of the input node (e.g. "input").
   * @param data       CHW tensor in the session's native type.
   * @param dims       Tensor dimensions, e.g. [1, 3, H, W].
   * @returns          CHW output in the same type.
   */
  run(
    inputName: string,
    data: Float32Array | Float16Array | Uint8Array,
    dims: number[],
  ): Promise<Float32Array | Float16Array | Uint8Array>;

  /** Release session resources. */
  dispose(): void;

  /** I/O type: 'f16', 'f32', or 'uint8'. */
  readonly precision: "f16" | "f32" | "uint8";

  /**
   * Which ORT execution provider is actually running the model.
   *
   * Reported rather than assumed: "webgpu" and "wasm" differ by more than
   * speed here — the WASM EP runs inference on the calling thread, so on a
   * device that falls back to it the denoiser blocks the main thread for the
   * whole page. A responsiveness report that does not say which one ran cannot
   * be interpreted.
   */
  readonly executionProvider: string;

  /** Receptive field of the model in pixels (passed via ModelVariants). */
  readonly receptiveField: number;
}

interface GpuCapabilities {
  webgpu: boolean;
  shaderF16: boolean;
  /** True when the browser exposes a native Float16Array global (Chrome 133+). */
  float16Array: boolean;
}

async function detectGpuCapabilities(): Promise<GpuCapabilities> {
  console.log(`${LOG} Detecting GPU capabilities...`);

  const float16Array = typeof Float16Array !== "undefined";
  console.log(`${LOG}   Float16Array: ${float16Array ? "YES ✓" : "no"}`);

  // deno-lint-ignore no-explicit-any
  const gpu = (navigator as any).gpu as GPU | undefined;
  if (!gpu) {
    console.log(`${LOG}   navigator.gpu not present → WASM fallback`);
    return { webgpu: false, shaderF16: false, float16Array };
  }
  console.log(`${LOG}   navigator.gpu present`);

  let adapter: GPUAdapter | null;
  try {
    adapter = await gpu.requestAdapter();
  } catch (err) {
    console.warn(`${LOG}   requestAdapter() threw:`, err);
    return { webgpu: false, shaderF16: false, float16Array };
  }

  if (!adapter) {
    console.warn(`${LOG}   requestAdapter() returned null → WASM fallback`);
    return { webgpu: false, shaderF16: false, float16Array };
  }

  // GPUAdapter.info is available in Chrome 113+ / spec; fall back gracefully
  // deno-lint-ignore no-explicit-any
  const info = (adapter as any).info ?? {};
  const adapterDesc = info.description ?? "(unknown adapter)";
  const shaderF16 = adapter.features.has("shader-f16");

  console.log(`${LOG}   Adapter: ${adapterDesc}`);
  console.log(`${LOG}   shader-f16 feature: ${shaderF16 ? "YES ✓" : "no"}`);

  // Log all adapter features at debug verbosity
  const features: string[] = [];
  adapter.features.forEach((f: string) => features.push(f));
  console.log(`${LOG}   All adapter features: [${features.sort().join(", ")}]`);

  // A software (CPU-emulated) adapter satisfies navigator.gpu but is far slower
  // for ONNX than the WASM EP, because the WebGPU EP issues many small dispatches
  // that a rasteriser like SwiftShader executes serially on the CPU.  Measured on
  // SwiftShader: 47.8 s vs 0.18 s for one 400x400 denoise tile — a 260x penalty
  // that reads as a hung app on a full sheet.  Outputs agree to float32 precision
  // (mean abs diff ~1e-7), so falling back costs accuracy nothing.
  //
  // Chrome reports these via adapter.info; `isFallbackAdapter` covers the spec'd
  // case and the vendor/architecture/description strings cover the common
  // software rasterisers (SwiftShader, Mesa lavapipe/llvmpipe, WARP).
  const infoStr = [info.vendor, info.architecture, info.description, info.device]
    .filter(Boolean).join(" ").toLowerCase();
  const isSoftware = isSoftwareAdapter(adapter);
  if (isSoftware) {
    console.log(
      `${LOG}   Adapter is a software rasteriser ("${infoStr.trim() || "unknown"}") → ` +
      `using WASM EP instead (much faster for this model; identical output)`,
    );
    return { webgpu: false, shaderF16: false, float16Array };
  }

  return { webgpu: true, shaderF16, float16Array };
}

/**
 * Create an ONNX inference session, automatically selecting the best model
 * variant and execution provider for the current browser/hardware.
 *
 * @param models  URLs for the f32, f16, and int8 model variants plus receptive field.
 * @returns       A session object for running inference.
 */
export async function createOnnxSession(models: ModelVariants): Promise<OnnxSession> {
  if (typeof ort === "undefined") {
    throw new Error(
      "ONNX Runtime Web is not loaded. Ensure ort.min.js is included in index.html.",
    );
  }

  const caps = await detectGpuCapabilities();

  // Pick variant and execution provider.
  // f16 requires both shader-f16 (GPU) and Float16Array (JS runtime).
  let modelUrl: string;
  let executionProviders: string[];
  let precision: "f16" | "f32" | "uint8";
  let selectionReason: string;

  if (caps.webgpu && caps.shaderF16 && caps.float16Array) {
    modelUrl = models.f16;
    executionProviders = ["webgpu"];
    precision = "f16";
    selectionReason = "WebGPU + shader-f16 + Float16Array → f16 model (fastest)";
  } else if (caps.webgpu) {
    modelUrl = models.f32;
    executionProviders = ["webgpu"];
    precision = "f32";
    selectionReason = caps.shaderF16
      ? "WebGPU + shader-f16 (no Float16Array) → f32 model"
      : "WebGPU (no shader-f16) → f32 model";
  } else {
    // WASM EP: use the f32 model, not int8.  The int8 variant's
    // DequantizeLinear/QuantizeLinear nodes are not well optimised in ORT-web,
    // so it is markedly SLOWER than plain f32 despite the smaller weights —
    // measured at the 512 px tile size this denoiser actually uses: f32 299 ms
    // vs int8 1788 ms per tile (6x).  All three model variants are served
    // locally and are 29-53 KB, so int8's download-size edge is irrelevant here.
    modelUrl = models.f32;
    executionProviders = ["wasm"];
    precision = "f32";
    selectionReason = "No usable WebGPU → WASM EP + f32 model (6x faster than int8 here)";
  }

  console.log(`${LOG} Selected: ${selectionReason}`);
  console.log(`${LOG} Model URL: ${modelUrl}`);
  console.log(`${LOG} Execution providers: [${executionProviders.join(", ")}]`);
  console.log(`${LOG} Creating session...`);

  // For WebGPU EP, request gpu-buffer output location so ORT keeps the output
  // tensor on the GPU without an extra internal copy.  We retrieve it via
  // getData() when we need the CPU-side values.
  // deno-lint-ignore no-explicit-any
  const sessionOptions: any = { executionProviders };
  if (caps.webgpu) {
    sessionOptions.preferredOutputLocation = "gpu-buffer";
  }

  const t0 = performance.now();
  const session = await ort.InferenceSession.create(modelUrl, sessionOptions);
  const elapsed = (performance.now() - t0).toFixed(0);

  console.log(
    `${LOG} Session ready in ${elapsed} ms.` +
      `  Inputs: [${session.inputNames}]` +
      `  Outputs: [${session.outputNames}]`,
  );

  const receptiveField = models.receptiveField;
  console.log(`${LOG} receptive_field=${receptiveField}`);

  return {
    precision,
    executionProvider: executionProviders[0],
    receptiveField,

    async run(
      inputName: string,
      data: Float32Array | Float16Array | Uint8Array,
      dims: number[],
    ): Promise<Float32Array | Float16Array | Uint8Array> {
      // Infer ORT tensor type from the array's runtime type.
      const tensorType = data instanceof Float16Array ? "float16"
        : data instanceof Uint8Array ? "uint8"
        : "float32";
      const tensor = new ort.Tensor(tensorType, data, dims);

      const feeds: Record<string, unknown> = { [inputName]: tensor };
      const results = await session.run(feeds);

      // deno-lint-ignore no-explicit-any
      const output: any = results[session.outputNames[0]];

      // For WebGPU sessions output.location is 'gpu-buffer'; call getData() to
      // transfer back to CPU.  For WASM sessions output.data is already CPU.
      let rawData: Float32Array | Float16Array | Uint8Array;
      if (output.location === "gpu-buffer") {
        rawData = await output.getData();
      } else {
        rawData = output.data;
      }

      output.dispose?.();
      tensor.dispose?.();

      return rawData;
    },

    dispose() {
      session.release();
    },
  };
}
