/**
 * Multi-page crop rectangle overlay.
 *
 * Draws crop rectangles with interactive drag handles on ALL visible pages.
 * When crop lock is enabled (state.cropLocked), editing any page's crop
 * applies the same rect to all pages (clamped to page bounds).
 *
 * Crop rects are in page-local image coordinates (at reference DPI).
 * Coordinate transforms go: screen ↔ virtual ↔ page-local.
 */

import { state } from "../state.ts";
import type { LayoutResult, PageLayout } from "./page_layout.ts";
import { visiblePageRange } from "./page_layout.ts";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface CropRect {
  x: number;
  y: number;
  width: number;
  height: number;
}

type DragMode =
  | "none"
  | "move"
  | "nw" | "ne" | "sw" | "se"
  | "n" | "s" | "e" | "w";

// ---------------------------------------------------------------------------
// State
// ---------------------------------------------------------------------------

let overlayCanvas: HTMLCanvasElement;
let ctx: CanvasRenderingContext2D;
let containerEl: HTMLElement;

let enabled = false;
let dragMode: DragMode = "none";
let dragStartImgX = 0;
let dragStartImgY = 0;
let dragStartRect: CropRect = { x: 0, y: 0, width: 0, height: 0 };
let dragPageNumber = 0;

// Callback for when crop changes (called on drag end)
let onCropChanged: ((rect: CropRect) => void) | null = null;

const HANDLE_SIZE = 8;
const HIT_TOLERANCE = 10;

// ---------------------------------------------------------------------------
// Initialization
// ---------------------------------------------------------------------------

export function initCropOverlay(
  container: HTMLElement,
  canvas: HTMLCanvasElement,
  onChange?: (rect: CropRect) => void,
): void {
  containerEl = container;
  overlayCanvas = canvas;
  ctx = canvas.getContext("2d")!;
  onCropChanged = onChange ?? null;

  overlayCanvas.addEventListener("mousedown", onMouseDown);
  window.addEventListener("mousemove", onMouseMove);
  window.addEventListener("mouseup", onMouseUp);
}

export function setCropEnabled(value: boolean): void {
  enabled = value;
  overlayCanvas.style.pointerEvents = value ? "auto" : "none";
}

// ---------------------------------------------------------------------------
// Coordinate transforms (virtual ↔ screen ↔ page-local)
// ---------------------------------------------------------------------------

function screenToVirtual(screenX: number, screenY: number): [number, number] {
  const rect = containerEl.getBoundingClientRect();
  const mx = screenX - rect.left;
  const my = screenY - rect.top;
  return [
    (mx - state.panX) / state.zoom,
    (my - state.panY) / state.zoom,
  ];
}

function pageImageToScreen(
  imgX: number,
  imgY: number,
  page: PageLayout,
  layout: LayoutResult,
): [number, number] {
  const pageLeft = (layout.maxWidth - page.width) / 2;
  const vx = pageLeft + imgX;
  const vy = page.yOffset + imgY;
  return [
    vx * state.zoom + state.panX,
    vy * state.zoom + state.panY,
  ];
}

function screenToPageImage(
  screenX: number,
  screenY: number,
  page: PageLayout,
  layout: LayoutResult,
): [number, number] {
  const [vx, vy] = screenToVirtual(screenX, screenY);
  const pageLeft = (layout.maxWidth - page.width) / 2;
  return [vx - pageLeft, vy - page.yOffset];
}

// ---------------------------------------------------------------------------
// Drawing
// ---------------------------------------------------------------------------

export function resizeOverlayCanvas(cssW: number, cssH: number, dpr: number): void {
  const w = Math.round(cssW * dpr);
  const h = Math.round(cssH * dpr);
  if (overlayCanvas.width !== w || overlayCanvas.height !== h) {
    overlayCanvas.width = w;
    overlayCanvas.height = h;
    overlayCanvas.style.width = `${Math.round(cssW)}px`;
    overlayCanvas.style.height = `${Math.round(cssH)}px`;
  }
}

export function drawCropOverlay(): void {
  const layout = state.pageLayout;
  if (!layout || layout.pages.length === 0) return;
  if (state.cropRects.size === 0) {
    ctx.clearRect(0, 0, overlayCanvas.width, overlayCanvas.height);
    return;
  }

  const dpr = window.devicePixelRatio || 1;
  const cw = overlayCanvas.width;
  const ch = overlayCanvas.height;

  ctx.clearRect(0, 0, cw, ch);

  if (!enabled && dragMode === "none") return;

  // Determine visible pages
  const viewportTop = -state.panY / state.zoom;
  const viewportBottom = (ch / dpr - state.panY) / state.zoom;
  const [firstIdx, lastIdx] = visiblePageRange(layout, viewportTop, viewportBottom);
  if (firstIdx < 0) return;

  // Draw crop rects for all visible pages — all interactive
  for (let i = firstIdx; i <= lastIdx; i++) {
    const page = layout.pages[i];
    const crop = state.cropRects.get(page.pageNumber);
    if (!crop) continue;

    drawPageCropRect(page, crop, layout, dpr, cw, ch);
  }
}

function drawPageCropRect(
  page: PageLayout,
  crop: CropRect,
  layout: LayoutResult,
  dpr: number,
  _cw: number,
  _ch: number,
): void {
  // Convert crop rect to screen coordinates (in device pixels for canvas)
  const [sx1, sy1] = pageImageToScreen(crop.x, crop.y, page, layout);
  const [sx2, sy2] = pageImageToScreen(crop.x + crop.width, crop.y + crop.height, page, layout);

  const left = sx1 * dpr;
  const top = sy1 * dpr;
  const right = sx2 * dpr;
  const bottom = sy2 * dpr;

  // Draw crop border — all pages are interactive
  ctx.strokeStyle = "rgba(74, 158, 255, 0.9)";
  ctx.lineWidth = 2 * dpr;
  ctx.strokeRect(left, top, right - left, bottom - top);

  // Semi-transparent fill outside crop
  const [psx1, psy1] = pageImageToScreen(0, 0, page, layout);
  const [psx2, psy2] = pageImageToScreen(page.width, page.height, page, layout);
  const pLeft = psx1 * dpr;
  const pTop = psy1 * dpr;
  const pRight = psx2 * dpr;
  const pBottom = psy2 * dpr;

  ctx.fillStyle = "rgba(0, 0, 0, 0.35)";
  // Top strip
  ctx.fillRect(pLeft, pTop, pRight - pLeft, top - pTop);
  // Bottom strip
  ctx.fillRect(pLeft, bottom, pRight - pLeft, pBottom - bottom);
  // Left strip
  ctx.fillRect(pLeft, top, left - pLeft, bottom - top);
  // Right strip
  ctx.fillRect(right, top, pRight - right, bottom - top);

  // Draw handles
  const hs = HANDLE_SIZE * dpr;
  const half = hs / 2;
  const midX = (left + right) / 2;
  const midY = (top + bottom) / 2;

  ctx.fillStyle = "rgba(74, 158, 255, 1)";
  ctx.strokeStyle = "#fff";
  ctx.lineWidth = 1 * dpr;

  const handles: [number, number][] = [
    [left, top], [right, top], [left, bottom], [right, bottom],
    [midX, top], [midX, bottom], [left, midY], [right, midY],
  ];

  for (const [hx, hy] of handles) {
    ctx.fillRect(hx - half, hy - half, hs, hs);
    ctx.strokeRect(hx - half, hy - half, hs, hs);
  }
}

// ---------------------------------------------------------------------------
// Hit testing — checks ALL pages
// ---------------------------------------------------------------------------

function hitTestAnyPage(
  screenX: number,
  screenY: number,
): { mode: DragMode; pageNumber: number } {
  const layout = state.pageLayout;
  if (!layout) return { mode: "none", pageNumber: 0 };

  const rect = containerEl.getBoundingClientRect();
  const mx = screenX - rect.left;
  const my = screenY - rect.top;
  const t = HIT_TOLERANCE;

  // Check all pages with crop rects
  for (const page of layout.pages) {
    const crop = state.cropRects.get(page.pageNumber);
    if (!crop) continue;

    const [sx1, sy1] = pageImageToScreen(crop.x, crop.y, page, layout);
    const [sx2, sy2] = pageImageToScreen(crop.x + crop.width, crop.y + crop.height, page, layout);
    const midX = (sx1 + sx2) / 2;
    const midY = (sy1 + sy2) / 2;

    // Corners
    if (Math.abs(mx - sx1) < t && Math.abs(my - sy1) < t) return { mode: "nw", pageNumber: page.pageNumber };
    if (Math.abs(mx - sx2) < t && Math.abs(my - sy1) < t) return { mode: "ne", pageNumber: page.pageNumber };
    if (Math.abs(mx - sx1) < t && Math.abs(my - sy2) < t) return { mode: "sw", pageNumber: page.pageNumber };
    if (Math.abs(mx - sx2) < t && Math.abs(my - sy2) < t) return { mode: "se", pageNumber: page.pageNumber };

    // Edge midpoints
    if (Math.abs(mx - midX) < t && Math.abs(my - sy1) < t) return { mode: "n", pageNumber: page.pageNumber };
    if (Math.abs(mx - midX) < t && Math.abs(my - sy2) < t) return { mode: "s", pageNumber: page.pageNumber };
    if (Math.abs(mx - sx1) < t && Math.abs(my - midY) < t) return { mode: "w", pageNumber: page.pageNumber };
    if (Math.abs(mx - sx2) < t && Math.abs(my - midY) < t) return { mode: "e", pageNumber: page.pageNumber };

    // Interior (move)
    if (mx >= sx1 && mx <= sx2 && my >= sy1 && my <= sy2) return { mode: "move", pageNumber: page.pageNumber };
  }

  return { mode: "none", pageNumber: 0 };
}

function getCursorForMode(mode: DragMode): string {
  switch (mode) {
    case "nw": case "se": return "nwse-resize";
    case "ne": case "sw": return "nesw-resize";
    case "n": case "s": return "ns-resize";
    case "e": case "w": return "ew-resize";
    case "move": return "move";
    default: return "";
  }
}

// ---------------------------------------------------------------------------
// Crop lock: apply rect to all pages
// ---------------------------------------------------------------------------

function clampRectToPage(rect: CropRect, pageW: number, pageH: number): CropRect {
  let { x, y, width, height } = rect;
  if (x < 0) x = 0;
  if (y < 0) y = 0;
  if (x + width > pageW) {
    if (width > pageW) { x = 0; width = pageW; }
    else x = pageW - width;
  }
  if (y + height > pageH) {
    if (height > pageH) { y = 0; height = pageH; }
    else y = pageH - height;
  }
  return { x, y, width, height };
}

function applyRectToAllPages(rect: CropRect): void {
  const layout = state.pageLayout;
  if (!layout) return;

  for (const page of layout.pages) {
    state.cropRects.set(page.pageNumber, clampRectToPage(rect, page.width, page.height));
  }
}

// ---------------------------------------------------------------------------
// Mouse interaction
// ---------------------------------------------------------------------------

function onMouseDown(e: MouseEvent): void {
  if (!enabled || e.button !== 0) return;

  const layout = state.pageLayout;
  if (!layout) return;

  const { mode, pageNumber } = hitTestAnyPage(e.clientX, e.clientY);
  if (mode === "none") return;

  e.preventDefault();
  e.stopPropagation();

  const page = layout.pages.find(p => p.pageNumber === pageNumber);
  if (!page) return;

  dragMode = mode;
  dragPageNumber = pageNumber;
  const [imgX, imgY] = screenToPageImage(e.clientX, e.clientY, page, layout);
  dragStartImgX = imgX;
  dragStartImgY = imgY;
  dragStartRect = { ...state.cropRects.get(pageNumber)! };
  overlayCanvas.style.cursor = getCursorForMode(mode);
}

function onMouseMove(e: MouseEvent): void {
  if (!enabled) return;

  if (dragMode === "none") {
    const { mode } = hitTestAnyPage(e.clientX, e.clientY);
    overlayCanvas.style.cursor = getCursorForMode(mode);
    return;
  }

  e.preventDefault();

  const layout = state.pageLayout;
  if (!layout) return;

  const page = layout.pages.find(p => p.pageNumber === dragPageNumber);
  if (!page) return;

  const [imgX, imgY] = screenToPageImage(e.clientX, e.clientY, page, layout);
  const dx = imgX - dragStartImgX;
  const dy = imgY - dragStartImgY;
  const r = dragStartRect;
  const minSize = 50;

  let nx = r.x;
  let ny = r.y;
  let nw = r.width;
  let nh = r.height;

  switch (dragMode) {
    case "move":
      nx = r.x + dx;
      ny = r.y + dy;
      break;
    case "nw":
      nx = r.x + dx; ny = r.y + dy; nw = r.width - dx; nh = r.height - dy;
      break;
    case "ne":
      ny = r.y + dy; nw = r.width + dx; nh = r.height - dy;
      break;
    case "sw":
      nx = r.x + dx; nw = r.width - dx; nh = r.height + dy;
      break;
    case "se":
      nw = r.width + dx; nh = r.height + dy;
      break;
    case "n":
      ny = r.y + dy; nh = r.height - dy;
      break;
    case "s":
      nh = r.height + dy;
      break;
    case "w":
      nx = r.x + dx; nw = r.width - dx;
      break;
    case "e":
      nw = r.width + dx;
      break;
  }

  // Enforce minimum size
  if (nw < minSize) {
    if (dragMode === "nw" || dragMode === "w" || dragMode === "sw") {
      nx = r.x + r.width - minSize;
    }
    nw = minSize;
  }
  if (nh < minSize) {
    if (dragMode === "nw" || dragMode === "n" || dragMode === "ne") {
      ny = r.y + r.height - minSize;
    }
    nh = minSize;
  }

  // Clamp to page image bounds
  const pageW = page.width;
  const pageH = page.height;
  if (nx < 0) { if (dragMode === "move") nw = r.width; nx = 0; }
  if (ny < 0) { if (dragMode === "move") nh = r.height; ny = 0; }
  if (nx + nw > pageW) {
    if (dragMode === "move") nx = pageW - nw;
    else nw = pageW - nx;
  }
  if (ny + nh > pageH) {
    if (dragMode === "move") ny = pageH - nh;
    else nh = pageH - ny;
  }

  const newRect: CropRect = {
    x: Math.round(nx),
    y: Math.round(ny),
    width: Math.round(nw),
    height: Math.round(nh),
  };

  // Apply to dragged page, and to all pages if locked
  if (state.cropLocked) {
    applyRectToAllPages(newRect);
  } else {
    state.cropRects.set(dragPageNumber, newRect);
  }

  drawCropOverlay();
}

function onMouseUp(_e: MouseEvent): void {
  if (dragMode === "none") return;

  dragMode = "none";
  dragPageNumber = 0;
  overlayCanvas.style.cursor = "";

  // Notify that crop changed (main.ts handles persistence for all pages if locked)
  if (onCropChanged) {
    // Pass the rect that was just edited (main.ts will check cropLocked)
    const firstRect = state.cropRects.values().next().value;
    if (firstRect) onCropChanged({ ...firstRect });
  }
}
