/**
 * Unified multi-page viewer with WebGPU rendering.
 *
 * Renders all selected pages as textured quads in a virtual coordinate space.
 * Supports two resolution levels (overview + full) per page.
 *
 * Controls:
 *   - Wheel (no modifier) → vertical pan
 *   - Ctrl+wheel / pinch → zoom toward cursor
 *   - Left-click drag → pan
 *
 * Virtual space: pages arranged vertically with gaps.
 * Screen mapping: screenPos = virtualPos * zoom + pan
 */

import { getGPUContext } from "../../src/gpu/gpu_context.ts";
import { createMultiPageViewer } from "../../src/gpu/multi_page_viewer.ts";
import type { MultiPageViewerHandle } from "../../src/gpu/multi_page_viewer.ts";
import { createGraphOverlay } from "../../src/gpu/graph_overlay.ts";
import type { GraphOverlayHandle, GraphPageInput } from "../../src/gpu/graph_overlay.ts";
import type { InkSource } from "../../src/gpu/multi_page_viewer.ts";
export type { GraphPageInput };
import { createTextureManager } from "./texture_manager.ts";
import type { TextureManager } from "./texture_manager.ts";
import type { LayoutResult } from "./page_layout.ts";
import { visiblePageRange, pageClosestToCenter } from "./page_layout.ts";
import type { PDFDocument, CanvasBackend } from "../../src/pdf/pdf_render.ts";
import { state } from "../state.ts";
import {
  initCropOverlay,
  drawCropOverlay,
  resizeOverlayCanvas,
  setCropEnabled,
} from "./crop_overlay.ts";
import type { CropRect } from "./crop_overlay.ts";

// ---------------------------------------------------------------------------
// Public interface
// ---------------------------------------------------------------------------

export interface ViewerCallbacks {
  onActivePageChanged(pageNumber: number): void;
  onCropChanged(rect: CropRect): void;
  onBackToPages(): void;
}

export type { CropRect };

// ---------------------------------------------------------------------------
// Module state
// ---------------------------------------------------------------------------

let canvas: HTMLCanvasElement;
let graphOverlayCanvas: HTMLCanvasElement;
let container: HTMLElement;

// GPU
let multiPageViewer: MultiPageViewerHandle | null = null;
let graphOverlay: GraphOverlayHandle | null = null;
let texManager: TextureManager | null = null;
let gpuReady: Promise<void>;

// Cached DOM elements
let elZoomLevel: HTMLElement | null = null;

// Cached container size (from ResizeObserver)
let containerW = 0;
let containerH = 0;

// Pan state
let isPanning = false;
let panStartX = 0;
let panStartY = 0;

// Touch state
let touchPrevDist = 0;
let touchPrevMidX = 0;
let touchPrevMidY = 0;
let isTouchPanning = false;
let touchLastX = 0;
let touchLastY = 0;

// Callbacks
let viewerCallbacks: ViewerCallbacks;

// Minimap
let minimapCanvas: HTMLCanvasElement;
let minimapCtx: CanvasRenderingContext2D;
let minimapContainer: HTMLElement;
const MINIMAP_MAX_DIM = 160;

// Scroll debouncing — defer texture loads during active scrolling
let isUserScrolling = false;
let scrollIdleTimer: ReturnType<typeof setTimeout> | undefined;
const SCROLL_IDLE_MS = 200;

function markScrollActive(): void {
  isUserScrolling = true;
  clearTimeout(scrollIdleTimer);
  scrollIdleTimer = setTimeout(() => {
    isUserScrolling = false;
    scheduleRedraw();
  }, SCROLL_IDLE_MS);
}

// ---------------------------------------------------------------------------
// Animated zoom interpolation
// ---------------------------------------------------------------------------

let targetZoom = 1;
let targetPanX = 0;
let targetPanY = 0;
let animating = false;
let lastInputTime = 0;

const ANIM_LERP = 0.25;
const KEEP_ALIVE_MS = 200;
const ANIM_EPS_PX = 0.1;
const ANIM_EPS_ZOOM = 0.0005;

function startAnimationLoop(): void {
  lastInputTime = performance.now();
  if (animating) return;
  animating = true;
  requestAnimationFrame(animationTick);
}

function animationTick(): void {
  const now = performance.now();

  const dZoom = targetZoom - state.zoom;
  const dPanX = targetPanX - state.panX;
  const dPanY = targetPanY - state.panY;

  const converged = Math.abs(dZoom) < ANIM_EPS_ZOOM &&
                    Math.abs(dPanX) < ANIM_EPS_PX &&
                    Math.abs(dPanY) < ANIM_EPS_PX;

  if (converged) {
    state.zoom = targetZoom;
    state.panX = targetPanX;
    state.panY = targetPanY;
  } else {
    state.zoom += dZoom * ANIM_LERP;
    state.panX += dPanX * ANIM_LERP;
    state.panY += dPanY * ANIM_LERP;
  }

  redraw();

  if (!converged || (now - lastInputTime) < KEEP_ALIVE_MS) {
    requestAnimationFrame(animationTick);
  } else {
    animating = false;
    redraw();
  }
}

// ---------------------------------------------------------------------------
// Container size
// ---------------------------------------------------------------------------

function ensureContainerSize(): void {
  if (containerW > 0 && containerH > 0) return;
  const r = container.getBoundingClientRect();
  containerW = r.width;
  containerH = r.height;
}

// ---------------------------------------------------------------------------
// Zoom helpers
// ---------------------------------------------------------------------------

const MAX_ZOOM = 256;

function minZoom(): number {
  const layout = state.pageLayout;
  if (!layout || layout.pages.length === 0) return 0.01;
  ensureContainerSize();
  const padding = 40;
  const scaleX = (containerW - padding) / layout.maxWidth;
  const scaleY = (containerH - padding) / layout.totalHeight;
  return Math.min(scaleX, scaleY);
}

function clampPan(px: number, py: number, zoom: number): [number, number] {
  const layout = state.pageLayout;
  if (!layout) return [px, py];
  ensureContainerSize();
  if (containerW < 1 || containerH < 1) return [px, py];

  const margin = 0.5;
  const contentW = layout.maxWidth * zoom;
  const contentH = layout.totalHeight * zoom;

  const maxX = containerW * margin;
  const minX = containerW * (1 - margin) - contentW;
  const maxY = containerH * margin;
  const minY = containerH * (1 - margin) - contentH;

  return [
    Math.max(minX, Math.min(maxX, px)),
    Math.max(minY, Math.min(maxY, py)),
  ];
}

function applyZoom(factor: number, clientX: number, clientY: number): void {
  const newZoom = Math.max(minZoom(), Math.min(MAX_ZOOM, targetZoom * factor));
  const rect = container.getBoundingClientRect();
  const mx = clientX - rect.left;
  const my = clientY - rect.top;

  targetPanX = mx - (mx - targetPanX) * (newZoom / targetZoom);
  targetPanY = my - (my - targetPanY) * (newZoom / targetZoom);
  targetZoom = newZoom;

  [targetPanX, targetPanY] = clampPan(targetPanX, targetPanY, targetZoom);

  startAnimationLoop();
}

// ---------------------------------------------------------------------------
// GPU initialization
// ---------------------------------------------------------------------------

async function initGPU(): Promise<void> {
  const gpuCtx = await getGPUContext();
  multiPageViewer = createMultiPageViewer(canvas, gpuCtx);
  graphOverlay = createGraphOverlay(graphOverlayCanvas, gpuCtx);
  // Start hidden; shown when a graph is uploaded
  graphOverlay.setVisible(false);
}

// ---------------------------------------------------------------------------
// Initialization
// ---------------------------------------------------------------------------

export function initViewer(callbacks: ViewerCallbacks): void {
  canvas = document.getElementById("viewerCanvas") as HTMLCanvasElement;
  graphOverlayCanvas = document.getElementById("graphOverlayCanvas") as HTMLCanvasElement;
  container = document.getElementById("viewerContainer")!;;
  viewerCallbacks = callbacks;

  minimapCanvas = document.getElementById("minimapCanvas") as HTMLCanvasElement;
  minimapCtx = minimapCanvas.getContext("2d")!;
  minimapContainer = document.getElementById("minimapContainer")!;

  // Crop overlay
  const cropCanvas = document.getElementById("cropOverlayCanvas") as HTMLCanvasElement;
  initCropOverlay(container, cropCanvas, (rect) => callbacks.onCropChanged(rect));

  // Cache DOM refs
  elZoomLevel = document.getElementById("viewerZoomLevel");

  // GPU init
  gpuReady = initGPU();

  // Back button
  const backBtn = document.getElementById("backToPagesBtn")!;
  backBtn.addEventListener("click", callbacks.onBackToPages);

  // -----------------------------------------------------------------------
  // Wheel: pinch-zoom vs two-finger-scroll
  // -----------------------------------------------------------------------
  container.addEventListener("wheel", (e) => {
    e.preventDefault();
    markScrollActive();

    if (e.ctrlKey) {
      const zoomFactor = e.deltaY < 0 ? 1.08 : 1 / 1.08;
      applyZoom(zoomFactor, e.clientX, e.clientY);
    } else {
      // Two-finger scroll → pan
      state.panX -= e.deltaX;
      state.panY -= e.deltaY;
      [state.panX, state.panY] = clampPan(state.panX, state.panY, state.zoom);
      targetPanX = state.panX;
      targetPanY = state.panY;
      startAnimationLoop();
    }
  }, { passive: false });

  // -----------------------------------------------------------------------
  // Touch → pinch-zoom and single-finger pan
  // -----------------------------------------------------------------------
  container.addEventListener("touchstart", (e) => {
    e.preventDefault();
    if (e.touches.length === 2) {
      const t0 = e.touches[0];
      const t1 = e.touches[1];
      touchPrevDist = Math.hypot(t1.clientX - t0.clientX, t1.clientY - t0.clientY);
      touchPrevMidX = (t0.clientX + t1.clientX) / 2;
      touchPrevMidY = (t0.clientY + t1.clientY) / 2;
      isTouchPanning = false;
    } else if (e.touches.length === 1) {
      isTouchPanning = true;
      touchLastX = e.touches[0].clientX;
      touchLastY = e.touches[0].clientY;
    }
  }, { passive: false });

  container.addEventListener("touchmove", (e) => {
    e.preventDefault();
    markScrollActive();
    if (e.touches.length === 2) {
      const t0 = e.touches[0];
      const t1 = e.touches[1];
      const dist = Math.hypot(t1.clientX - t0.clientX, t1.clientY - t0.clientY);
      const midX = (t0.clientX + t1.clientX) / 2;
      const midY = (t0.clientY + t1.clientY) / 2;
      if (touchPrevDist > 0) {
        // Apply translation from midpoint movement first, then zoom
        targetPanX += midX - touchPrevMidX;
        targetPanY += midY - touchPrevMidY;
        applyZoom(dist / touchPrevDist, midX, midY);
      }
      touchPrevDist = dist;
      touchPrevMidX = midX;
      touchPrevMidY = midY;
    } else if (e.touches.length === 1 && isTouchPanning) {
      const tx = e.touches[0].clientX;
      const ty = e.touches[0].clientY;
      state.panX += tx - touchLastX;
      state.panY += ty - touchLastY;
      [state.panX, state.panY] = clampPan(state.panX, state.panY, state.zoom);
      targetPanX = state.panX;
      targetPanY = state.panY;
      touchLastX = tx;
      touchLastY = ty;
      scheduleRedraw();
    }
  }, { passive: false });

  container.addEventListener("touchend", (e) => {
    e.preventDefault();
    if (e.touches.length < 2) {
      touchPrevDist = 0;
    }
    if (e.touches.length === 0) {
      isTouchPanning = false;
    } else if (e.touches.length === 1) {
      // Lift one finger during pinch → transition to single-finger pan
      isTouchPanning = true;
      touchLastX = e.touches[0].clientX;
      touchLastY = e.touches[0].clientY;
    }
  }, { passive: false });

  container.addEventListener("touchcancel", () => {
    touchPrevDist = 0;
    isTouchPanning = false;
  });

  // -----------------------------------------------------------------------
  // Mouse drag → pan
  // -----------------------------------------------------------------------
  container.addEventListener("mousedown", (e) => {
    if (e.button === 0 || e.button === 1) {
      e.preventDefault();
      isPanning = true;
      panStartX = e.clientX - state.panX;
      panStartY = e.clientY - state.panY;
      container.style.cursor = "grabbing";
    }
  });

  window.addEventListener("mousemove", (e) => {
    if (!isPanning) return;
    markScrollActive();
    state.panX = e.clientX - panStartX;
    state.panY = e.clientY - panStartY;
    [state.panX, state.panY] = clampPan(state.panX, state.panY, state.zoom);
    targetPanX = state.panX;
    targetPanY = state.panY;
    scheduleRedraw();
  });

  window.addEventListener("mouseup", () => {
    if (isPanning) {
      isPanning = false;
      container.style.cursor = "";
      scheduleRedraw();
    }
  });

  // -----------------------------------------------------------------------
  // Resize handling
  // -----------------------------------------------------------------------
  const resizeObserver = new ResizeObserver((entries) => {
    for (const entry of entries) {
      if (entry.contentBoxSize?.length) {
        containerW = entry.contentBoxSize[0].inlineSize;
        containerH = entry.contentBoxSize[0].blockSize;
      } else {
        const r = container.getBoundingClientRect();
        containerW = r.width;
        containerH = r.height;
      }
    }
    scheduleRedraw();
  });
  resizeObserver.observe(container);
}

// ---------------------------------------------------------------------------
// Enter multi-page view
// ---------------------------------------------------------------------------

export async function enterMultiPageView(
  layout: LayoutResult,
  doc: PDFDocument,
  backend: CanvasBackend,
  fileId: string,
  denoisedPages: Set<number>,
  onDenoisedFailed?: (pageNumber: number) => void,
): Promise<void> {
  state.pageLayout = layout;

  await gpuReady;

  // Clean up previous texture manager (evicts tracked GPU textures) then clear
  // all remaining per-page GPU resources (uniform buffers, any untracked state).
  texManager?.destroy();
  multiPageViewer?.destroy();

  texManager = createTextureManager(
    multiPageViewer!,
    {
      onTextureReady(_pageNumber: number, _level: "overview" | "full") {
        scheduleRedraw();
      },
    },
    doc,
    backend,
    fileId,
  );

  // Compute initial zoom: fit widest page to container width
  ensureContainerSize();
  const padding = 40;
  state.zoom = Math.min((containerW - padding) / layout.maxWidth, 1);
  state.panX = (containerW - layout.maxWidth * state.zoom) / 2;
  state.panY = padding / 2;
  targetZoom = state.zoom;
  targetPanX = state.panX;
  targetPanY = state.panY;

  scheduleRedraw();

  // Load overview textures for all pages (non-blocking — each triggers redraw via onTextureReady).
  // For denoised pages, the composite is loaded right after the overview (no race condition).
  texManager.loadAll(layout.pages, denoisedPages, onDenoisedFailed).catch((err: unknown) => {
    console.error("Failed to load thumbnails:", err);
  });
}

/**
 * Draw these pages from their palette bit-planes instead of RGBA textures.
 * Pass an empty map to go back to textures for every page.
 *
 * Only the cleaned page and single-ink views use this.  The raw scan and the
 * denoised page are photographic — full 24-bit colour, with no small palette to
 * exploit — and keep the RGBA texture path.
 */
export function setInkSources(
  sources: Map<number, InkSource>,
  palette: { colors: Array<[number, number, number]>; background: [number, number, number] } | null,
): void {
  if (!multiPageViewer) return;
  multiPageViewer.clearInkSources();
  if (palette) multiPageViewer.setInkPalette(palette.colors, palette.background);
  for (const [pageNumber, src] of sources) multiPageViewer.setInkSource(pageNumber, src);
  scheduleRedraw();
}

export function getTextureManager(): TextureManager | null {
  return texManager;
}

/**
 * Update the page layout without re-creating textures.
 * Used when applying/removing crops to change page dimensions and UV mapping.
 */
export function updateLayout(layout: LayoutResult): void {
  state.pageLayout = layout;

  // Recompute zoom to fit the new layout
  ensureContainerSize();
  const padding = 40;
  const newZoom = Math.min((containerW - padding) / layout.maxWidth, 1);
  state.zoom = newZoom;
  state.panX = (containerW - layout.maxWidth * newZoom) / 2;
  state.panY = padding / 2;
  targetZoom = newZoom;
  targetPanX = state.panX;
  targetPanY = state.panY;

  scheduleRedraw();
}

// ---------------------------------------------------------------------------
// Redraw
// ---------------------------------------------------------------------------

let redrawScheduled = false;

function scheduleRedraw(): void {
  if (redrawScheduled) return;
  redrawScheduled = true;
  requestAnimationFrame(() => {
    redrawScheduled = false;
    redraw();
  });
}

/** Trigger a redraw from outside (e.g. after texture update). */
export function requestRedraw(): void {
  scheduleRedraw();
}

let _lastDomUpdateTime = 0;
let _lastZoomText = "";
let _lastMinimapTime = 0;

function redraw(): void {
  if (!multiPageViewer) return;
  const layout = state.pageLayout;
  if (!layout || layout.pages.length === 0) return;
  if (containerW < 1 || containerH < 1) return;

  const dpr = window.devicePixelRatio || 1;
  const cssW = Math.round(containerW);
  const cssH = Math.round(containerH);
  const cw = Math.round(containerW * dpr);
  const ch = Math.round(containerH * dpr);

  if (canvas.width !== cw || canvas.height !== ch) {
    canvas.width = cw;
    canvas.height = ch;
    canvas.style.width = `${cssW}px`;
    canvas.style.height = `${cssH}px`;
  }

  // Compute viewport in virtual space
  const viewportTop = -state.panY / state.zoom;
  const viewportBottom = (containerH - state.panY) / state.zoom;

  const [firstIdx, lastIdx] = visiblePageRange(layout, viewportTop, viewportBottom);

  // Render all visible pages
  multiPageViewer.render(layout, [firstIdx, lastIdx], state.panX, state.panY, state.zoom, dpr);

  // Texture management: always build visible set and maintain thumbnails;
  // defer higher-res loads until scroll is idle.
  if (texManager && firstIdx >= 0) {
    const visibleSet = new Set<number>();
    for (let i = firstIdx; i <= lastIdx; i++) {
      const pageNum = layout.pages[i].pageNumber;
      visibleSet.add(pageNum);
      // Re-request thumbnails that may have been evicted (no-op if still loaded).
      texManager.requestThumbnail(pageNum);
      if (!isUserScrolling) {
        if (texManager.needsOverviewTexture(pageNum, state.zoom)) {
          texManager.requestOverview(pageNum);
        }
        if (texManager.needsFullTexture(pageNum, state.zoom)) {
          texManager.requestFull(pageNum);
        }
      }
    }
    texManager.evictInvisible(visibleSet);
  }

  // Active page tracking: page closest to viewport center
  const viewportCenterY = (containerH / 2 - state.panY) / state.zoom;
  const closest = pageClosestToCenter(layout, viewportCenterY);
  if (closest && closest.pageNumber !== state.activePageNumber) {
    state.activePageNumber = closest.pageNumber;
    state.selectedPage = closest.pageNumber;
    viewerCallbacks.onActivePageChanged(closest.pageNumber);
  }

  // DOM text updates (throttled)
  const t0 = performance.now();
  if (t0 - _lastDomUpdateTime > 100) {
    const zoomText = `${Math.round(state.zoom * 100)}%`;
    if (elZoomLevel && zoomText !== _lastZoomText) {
      elZoomLevel.textContent = zoomText;
      _lastZoomText = zoomText;
    }
    _lastDomUpdateTime = t0;
  }

  // Minimap (throttled)
  if (t0 - _lastMinimapTime > 50) {
    updateMinimap(layout);
    _lastMinimapTime = t0;
  }

  // Graph overlay — keep canvas size in sync with viewer canvas
  if (graphOverlay) {
    if (graphOverlayCanvas.width !== cw || graphOverlayCanvas.height !== ch) {
      graphOverlayCanvas.width = cw;
      graphOverlayCanvas.height = ch;
      graphOverlayCanvas.style.width  = `${cssW}px`;
      graphOverlayCanvas.style.height = `${cssH}px`;
    }
    graphOverlay.render(state.panX, state.panY, state.zoom, dpr);
  }

  // Crop overlay
  resizeOverlayCanvas(containerW, containerH, dpr);
  drawCropOverlay();
}

// ---------------------------------------------------------------------------
// Minimap
// ---------------------------------------------------------------------------

function updateMinimap(layout: LayoutResult): void {
  if (layout.pages.length === 0) {
    minimapContainer.style.display = "none";
    return;
  }

  const virtW = layout.maxWidth;
  const virtH = layout.totalHeight;

  // Viewport in virtual space
  const visLeft = -state.panX / state.zoom;
  const visTop = -state.panY / state.zoom;
  const visWidth = containerW / state.zoom;
  const visHeight = containerH / state.zoom;

  // Hide minimap if everything is visible
  if (visLeft <= 0 && visTop <= 0 &&
      visLeft + visWidth >= virtW && visTop + visHeight >= virtH) {
    minimapContainer.style.display = "none";
    return;
  }

  minimapContainer.style.display = "block";

  // Compute minimap size
  const aspect = virtW / virtH;
  let mmW: number, mmH: number;
  if (aspect > 1) {
    mmW = MINIMAP_MAX_DIM;
    mmH = MINIMAP_MAX_DIM / aspect;
  } else {
    mmH = MINIMAP_MAX_DIM;
    mmW = MINIMAP_MAX_DIM * aspect;
  }

  minimapCanvas.width = Math.round(mmW);
  minimapCanvas.height = Math.round(mmH);
  minimapCanvas.style.width = `${Math.round(mmW)}px`;
  minimapCanvas.style.height = `${Math.round(mmH)}px`;

  const scaleX = mmW / virtW;
  const scaleY = mmH / virtH;

  // Draw page rectangles
  minimapCtx.clearRect(0, 0, mmW, mmH);
  minimapCtx.fillStyle = "rgba(255, 255, 255, 0.12)";
  minimapCtx.strokeStyle = "rgba(255, 255, 255, 0.25)";
  minimapCtx.lineWidth = 0.5;

  for (const page of layout.pages) {
    const px = ((virtW - page.width) / 2) * scaleX;
    const py = page.yOffset * scaleY;
    const pw = page.width * scaleX;
    const ph = page.height * scaleY;
    minimapCtx.fillRect(px, py, pw, ph);
    minimapCtx.strokeRect(px, py, pw, ph);
  }

  // Draw viewport rectangle
  const rx = Math.max(0, visLeft * scaleX);
  const ry = Math.max(0, visTop * scaleY);
  const rw = Math.min(mmW - rx, visWidth * scaleX);
  const rh = Math.min(mmH - ry, visHeight * scaleY);

  minimapCtx.strokeStyle = "rgba(74, 158, 255, 0.8)";
  minimapCtx.lineWidth = 1.5;
  minimapCtx.strokeRect(rx, ry, rw, rh);
}

// ---------------------------------------------------------------------------
// Public helpers
// ---------------------------------------------------------------------------

export function updateDenoiseProgress(progress: number): void {
  const bar = document.getElementById("denoiseProgress") as HTMLElement | null;
  if (bar) {
    bar.style.width = `${Math.round(progress * 100)}%`;
  }

  const statusEl = document.getElementById("viewerStatus");
  if (statusEl) {
    if (progress < 1) {
      statusEl.textContent = `Denoising: ${Math.round(progress * 100)}%`;
    } else {
      statusEl.textContent = "Denoising complete";
    }
  }
}

export function setDenoiseButtonEnabled(enabled: boolean): void {
  const btn = document.getElementById("denoiseBtn") as HTMLButtonElement | null;
  if (btn) btn.disabled = !enabled;
}

export function updatePaletteProgress(progress: number): void {
  // Update every progress bar with id "paletteProgress" (there may be one in
  // the viewer sidebar and one in the page-select screen).
  for (const bar of document.querySelectorAll<HTMLElement>(".palette-progress-bar")) {
    bar.style.width = `${Math.round(progress * 100)}%`;
    const container = bar.parentElement;
    if (container) {
      container.style.display = progress > 0 && progress < 1 ? "" : "none";
    }
  }
}

export function setPaletteButtonsEnabled(enabled: boolean): void {
  for (const id of ["extractPaletteBtn", "viewerExtractPaletteBtn"]) {
    const btn = document.getElementById(id) as HTMLButtonElement | null;
    if (btn) {
      btn.disabled = !enabled;
      btn.textContent = enabled ? "Extract Palette" : "Extracting…";
    }
  }
}

export function setCropButtonEnabled(enabled: boolean): void {
  const btn = document.getElementById("cropBtn") as HTMLButtonElement | null;
  if (btn) btn.disabled = !enabled;
}

/** After denoise completes: update UI state for the active page. */
export function onDenoiseComplete(): void {
  // Note: do NOT disable crop mode here — this is called for each page
  // change when loading active page state. Crop mode is managed by
  // the crop button toggle in main.ts.
  drawCropOverlay();

  const statusEl = document.getElementById("viewerStatus");
  if (statusEl) statusEl.textContent = "Denoising complete";
}

/** Reset viewer controls to fresh-page state. */
export function showFreshPageControls(): void {
  setDenoiseButtonEnabled(true);
}

// ---------------------------------------------------------------------------
// Graph overlay public API
// ---------------------------------------------------------------------------

/**
 * Upload graph data to the overlay renderer.
 * Call this after computing path graphs so they render on subsequent frames.
 *
 * @param activeLayer  Layer index to display, or -1 to show all layers.
 */
export function updateGraphOverlay(pages: GraphPageInput[], activeLayer: number): void {
  if (!graphOverlay) return;
  graphOverlay.upload(pages, activeLayer);
}

/**
 * Show or hide the graph overlay without discarding GPU data.
 * Does not touch `state`; callers are responsible for keeping state in sync.
 */
export function setGraphOverlayVisible(visible: boolean): void {
  if (graphOverlay) graphOverlay.setVisible(visible);
  scheduleRedraw();
}

// Re-exports for crop overlay
export {
  setCropEnabled as setViewerCropEnabled,
};
