/**
 * Page selection screen: displays PDF page thumbnails in a grid.
 *
 * - Click the checkbox (on the label line) to toggle page selection.
 * - "Inspect Selected" button enters the multi-page inspection view.
 */

import type { CanvasBackend, PDFDocument } from "../../src/pdf/pdf_render.ts";
import { renderPdfThumbnail, getPageSizes } from "../../src/pdf/pdf_render.ts";

export interface PageSelectCallbacks {
  onPageToggled(pageNumber: number): void;
}

let callbacks: PageSelectCallbacks | null = null;

/**
 * Populate the page grid with thumbnails for all pages in the PDF.
 *
 * Creates all page slots immediately with placeholder rectangles
 * (proportional to actual page sizes), then renders thumbnails
 * asynchronously in the background.
 */
export async function populatePageGrid(
  doc: PDFDocument,
  pageCount: number,
  backend: CanvasBackend,
  selectedPages: Set<number>,
  denoisedPages: Set<number>,
  pageLabels?: string[],
): Promise<void> {
  const grid = document.getElementById("pageGrid")!;
  grid.innerHTML = "";

  const statusText = document.getElementById("pageStatusText")!;

  // Get page sizes to compute proportional thumbnail dimensions
  const pageSizes = await getPageSizes(doc);
  const maxArea = Math.max(...pageSizes.map(s => s.widthPt * s.heightPt));
  const MIN_THUMB = 100;
  const MAX_THUMB = 240;

  // Phase 1: Create all placeholders immediately
  const thumbContainers: HTMLDivElement[] = [];

  for (let i = 1; i <= pageCount; i++) {
    const ps = pageSizes[i - 1];
    const area = ps.widthPt * ps.heightPt;
    const ratio = Math.sqrt(area / maxArea);
    const maxDim = Math.round(MIN_THUMB + ratio * (MAX_THUMB - MIN_THUMB));

    // Compute placeholder dimensions matching the page aspect ratio
    const aspect = ps.widthPt / ps.heightPt;
    let placeholderW: number, placeholderH: number;
    if (aspect >= 1) {
      placeholderW = maxDim;
      placeholderH = Math.round(maxDim / aspect);
    } else {
      placeholderH = maxDim;
      placeholderW = Math.round(maxDim * aspect);
    }

    const wrapper = document.createElement("div");
    wrapper.className = "page-thumb-wrapper";
    wrapper.dataset.page = String(i);
    if (selectedPages.has(i)) wrapper.classList.add("selected");
    if (denoisedPages.has(i)) wrapper.classList.add("denoised");

    // Label row: [checkbox] [page label]
    const labelRow = document.createElement("div");
    labelRow.className = "page-label-row";

    const check = document.createElement("div");
    check.className = "page-check";
    check.textContent = "\u2713"; // ✓

    const pageLabel = pageLabels?.[i - 1] ?? String(i);
    const label = document.createElement("span");
    label.className = "page-thumb-label";
    label.textContent = pageLabel;
    label.title = pageLabel;

    labelRow.appendChild(check);
    labelRow.appendChild(label);

    // Thumbnail container with placeholder
    const thumbContainer = document.createElement("div");
    thumbContainer.className = "page-thumb-container";

    const placeholder = document.createElement("div");
    placeholder.className = "page-thumb-placeholder";
    placeholder.style.width = `${placeholderW}px`;
    placeholder.style.height = `${placeholderH}px`;

    const badge = document.createElement("div");
    badge.className = "page-denoised-badge";
    badge.textContent = "denoised";

    thumbContainer.appendChild(placeholder);
    thumbContainer.appendChild(badge);

    wrapper.appendChild(labelRow);
    wrapper.appendChild(thumbContainer);
    grid.appendChild(wrapper);

    thumbContainers.push(thumbContainer);
  }

  statusText.textContent = `${pageCount} page${pageCount !== 1 ? "s" : ""} — select pages, then Inspect Selected`;

  // Phase 2: Render thumbnails asynchronously (non-blocking)
  renderThumbnailsAsync(doc, pageCount, backend, pageSizes, maxArea, MIN_THUMB, MAX_THUMB, thumbContainers, pageLabels, statusText);
}

/** Render thumbnails in the background, replacing placeholders as they complete. */
async function renderThumbnailsAsync(
  doc: PDFDocument,
  pageCount: number,
  backend: CanvasBackend,
  pageSizes: { widthPt: number; heightPt: number }[],
  maxArea: number,
  minThumb: number,
  maxThumb: number,
  thumbContainers: HTMLDivElement[],
  pageLabels: string[] | undefined,
  statusText: HTMLElement,
): Promise<void> {
  for (let i = 1; i <= pageCount; i++) {
    const area = pageSizes[i - 1].widthPt * pageSizes[i - 1].heightPt;
    const ratio = Math.sqrt(area / maxArea);
    const maxDim = Math.round(minThumb + ratio * (maxThumb - minThumb));

    try {
      const thumb = await renderPdfThumbnail(doc, i, backend, maxDim);

      const canvas = document.createElement("canvas");
      canvas.width = thumb.width;
      canvas.height = thumb.height;
      canvas.className = "page-thumb";
      canvas.dataset.page = String(i);
      const pageLabel = pageLabels?.[i - 1] ?? String(i);
      canvas.title = `Page ${pageLabel}`;

      const ctx = canvas.getContext("2d")!;
      const imageData = new ImageData(thumb.data as unknown as Uint8ClampedArray<ArrayBuffer>, thumb.width, thumb.height);
      ctx.putImageData(imageData, 0, 0);

      // Replace placeholder with rendered thumbnail
      const container = thumbContainers[i - 1];
      const placeholder = container.querySelector(".page-thumb-placeholder");
      if (placeholder) {
        container.replaceChild(canvas, placeholder);
      }
    } catch (err) {
      console.error(`Failed to render thumbnail for page ${i}:`, err);
    }

    statusText.textContent = `Rendered ${i}/${pageCount} thumbnails`;
  }
}


/**
 * Attach click delegation to the page grid.
 * Clicking anywhere on a page wrapper toggles its selection.
 */
export function attachPageGridClickHandler(
  cb: PageSelectCallbacks,
): void {
  callbacks = cb;
  const grid = document.getElementById("pageGrid")!;

  grid.addEventListener("click", (e) => {
    const page = getPageFromEvent(e);
    if (page) callbacks?.onPageToggled(page);
  });
}

function getPageFromEvent(e: Event): number | null {
  const target = (e.target as HTMLElement).closest(".page-thumb-wrapper");
  if (!target) return null;
  const page = Number((target as HTMLElement).dataset.page);
  return page > 0 ? page : null;
}

/**
 * Update visual state of the page grid without re-rendering thumbnails.
 */
export function updatePageGridState(
  selectedPages: Set<number>,
  denoisedPages: Set<number>,
): void {
  const grid = document.getElementById("pageGrid");
  if (!grid) return;

  const wrappers = grid.querySelectorAll(".page-thumb-wrapper");
  for (const w of wrappers) {
    const page = Number((w as HTMLElement).dataset.page);
    w.classList.toggle("selected", selectedPages.has(page));
    w.classList.toggle("denoised", denoisedPages.has(page));
  }

  // Update info text
  updateSelectionInfo(selectedPages.size, denoisedPages.size);
}

/**
 * Update the selection info text and button state.
 */
export function updateSelectionInfo(selectedCount: number, denoisedCount: number): void {
  const info = document.getElementById("pageSelectionInfo");
  if (info) {
    const parts: string[] = [];
    parts.push(`${selectedCount} page${selectedCount !== 1 ? "s" : ""} selected`);
    if (denoisedCount > 0) {
      parts.push(`${denoisedCount} denoised`);
    }
    info.textContent = parts.join(" · ");
  }
}
