/**
 * Curve fitting: lines, arcs, and circles.
 *
 * Fits geometric primitives to each chain in an undashed PathGraph by
 * reconciling against the pre-thinning palettized pixel data.
 *
 * Pipeline
 * ────────
 * 1. Read all layer bit-planes back from the GPU (one staging copy).
 * 2. Walk the PathGraph to extract maximal chains and closed rings.
 * 3. For each chain edge, collect pre-thinning pixels within BAND_WIDTH.
 * 4. Recursively split each chain into sub-ranges and fit the best primitive
 *    (line or arc/circle) using PCA line fitting + algebraic circle fitting.
 *    If no pixels are collected, fall back to fitting the skeleton vertices.
 * 5. Emit a CurveGraph.  A companion function tessellates it back to a
 *    PathGraph for rendering in the existing overlay system.
 *
 * Pure math (fitting, PCA, G1 continuity) lives in curve_fit_math.ts.
 */

import type { PathGraph, PathVertex, PathEdge } from "./path_connect.ts";
import { inkProbeFromWords, type InkProbe, type StrokeMark } from "./path_simplify.ts";
import type { PaletteDecomposition } from "./palette_decompose_types.ts";

export type {
  LinePrimitive,
  ArcPrimitive,
  CirclePrimitive,
  CurvePrimitive,
} from "./curve_fit_math.ts";

import {
  type LinePrimitive,
  type ArcPrimitive,
  type CirclePrimitive,
  fitCircle,
  makeLinePrimitive,
  makeArcPrimitive,
  ccwSpan,
  primitiveEndPoint,
  primitiveTangentAt,
  reanchorArcThrough,
  snapArcAngle,
  joinArcsExactly,
  lineLineIntersect,
  windowAdd,
  dirFromWindow,
  dirFromWindowInto,
  lineCEFast,
  lineArcJunction,
  snapAdjacentJunctions,
} from "./curve_fit_math.ts";

// ---------------------------------------------------------------------------
// Public types
// ---------------------------------------------------------------------------

export interface CurveSegment {
  layer: number;
  primitive: import("./curve_fit_math.ts").CurvePrimitive;
  /** Source chain index (used to group consecutive segments in one chain). */
  chainId: number;
  /** True if this segment belongs to a closed ring. */
  isClosed: boolean;
}

export interface CurveGraph {
  width: number;
  height: number;
  layerCount: number;
  segments: CurveSegment[];
}

// ---------------------------------------------------------------------------
// Validation
// ---------------------------------------------------------------------------

export interface FitValidationWarning {
  ci:      number;
  layer:   number;
  type:    "dropped" | "coverage" | "backward" | "junction-gap";
  /** Human-readable description. */
  message: string;
  /** Position in graph space (for locating in the viewer). */
  x?: number;
  y?: number;
}

export interface FitValidationResult {
  /**
   * Chains with N≥2 dense vertices that produced no output AND were not
   * intentionally absorbed by postFitUndash.  Non-zero means data loss.
   */
  droppedChains: number;
  /**
   * Chains absorbed (merged) by postFitUndash.  These are intentional nulls
   * whose data lives in the absorbing chain.
   */
  absorbedChains: number;
  /** Total chains with N≥2 dense vertices. */
  totalChains: number;
  /**
   * Maximum perpendicular distance from any dense vertex to the fitted segment
   * that is supposed to cover it.  Ideally << 1 px for well-fitted data.
   */
  maxCoverageError: number;
  /** Mean perpendicular distance across all covered dense vertices. */
  meanCoverageError: number;
  /** Dense vertices checked for coverage. */
  coveredVertices: number;
  /**
   * Segments whose direction (p1→p2) is backward relative to the chain's
   * overall direction (first dense vertex → last).  Non-zero indicates a
   * zigzag or DP reversal.
   */
  backwardSegments: number;
  /**
   * Adjacent segment pairs whose shared junction has a gap larger than
   * 2×denseSeg.  Non-zero means snapAdjacentJunctions failed to close the junction.
   */
  disconnectedJunctions: number;
  /** Per-warning detail list for chains that exceeded the coverage threshold. */
  warnings: FitValidationWarning[];
}

/**
 * One observation of a chain's fit, taken between two repair passes.
 *
 * Supplied by a diagnostic harness; production callers leave `passProbe`
 * undefined and the pipeline carries no instrumentation cost.
 */
export interface PassObservation {
  /** Pass that just finished, or "fitDenseChain" for the state before any. */
  name: string;
  /** Chain index this observation is for. */
  chain: number;
  /** The chain's fitted primitives as they stand right now. */
  recon: ReadonlyArray<{ wi: number; wj: number; prim: LinePrimitive | ArcPrimitive; ce: number }>;
  /** The dense skeleton vertices the chain was fitted to. */
  denseVerts: ReadonlyArray<{ x: number; y: number }>;
}

export interface CurveFitOptions {
  /**
   * Maximum allowed centering error (px) for accepting a fitted primitive.
   *
   * The centering error is the RMS of per-skeleton-edge (fitCurves) or
   * per-dense-vertex (computeHoverFit tryFit acceptance) mean signed
   * perpendicular (line) or radial (arc/circle) deviations of the pre-thinning
   * pixel cloud from the fitted primitive.  It measures how well-centred the
   * fit is *locally* — not the stroke-width-dependent RMS point distance.
   *
   * For a stroke of any width whose fitted centerline is exactly in the
   * middle, this metric is ≈ 0.  A diagonal cut across a straight stroke
   * produces a large centering error at each local bin, making the metric
   * robust against the "dilution" problem where globally averaged RMSE can
   * hide locally bad fits.
   *
   * Note: the hoverFit *expansion* criterion uses the per-pixel RMS
   * (sqrt(λ_min) of the pixel covariance), which is independent of Voronoi
   * grouping and thus not biased by skeleton offset.  Only the final
   * acceptance check in tryFit uses the per-vertex-mean metric against this
   * threshold.
   *
   * Typical range: 0.0 (perfectly centered only) – 2.0 (noisy/curved strokes).
   */
  maxCenteringError: number;
  /** Fitted arc radius below this (px) is treated as a line (open arcs only). */
  minArcRadius: number;
  /**
   * Arc RMSE must be ≤ this fraction of line RMSE to be preferred over a line.
   */
  arcBenefit: number;
  /** Maximum distance (px) from a skeleton edge for a pre-thinning pixel. */
  bandWidth: number;
  /** Minimum pixel-cloud size to attempt fitting (below = use skeleton vertices). */
  minPoints: number;
  /** Arc-length step (px) when tessellating arcs/circles for display. */
  arcStep: number;
  /**
   * MDL penalty added to the DP cost for each segment.  Higher values favour
   * fewer, longer segments; lower values allow finer splits.  Units match the
   * fitting cost (centeringError × numVerts), so a value of 5.0 means a split
   * is only worthwhile if it saves at least 5 px·vertex of centering error.
   */
  mdlPenalty: number;
  /**
   * Dense-vertex spacing (px) used when densifying skeleton chains before
   * DP fitting.  Smaller values give finer resolution but more DP work.
   * Used by both `fitCurves` and `buildFitCache`.  Defaults to 2.
   */
  denseSeg?: number;
  /**
   * Post-fit undash: maximum gap (px) between collinear endpoint pairs to
   * bridge.  If omitted (or 0), the post-fit undash pass is skipped.
   */
  postUndashMaxGap?: number;
  /**
   * Post-fit undash: maximum angular deviation (degrees) from perfect
   * collinearity.  Defaults to 30 if postUndashMaxGap is set.
   */
  postUndashMaxAngleDeg?: number;
  /**
   * Maximum length (px) of short stub segments at junction ends to remove
   * and replace with the intersection of the neighboring main segments.
   * Defaults to 0 (disabled).
   */
  junctionStubMaxPx?: number;
  /** Snap line segments whose perpendicular endpoint spread is within this
   *  many pixels of horizontal/vertical to exact axis alignment.  Defaults to 1. */
  axisSnapPx?: number;
  /** Fit circular arcs in the DP (compound curves become G1 arc chains).
   *  Defaults to true; set false for lines-only output. */
  fitArcs?: boolean;
  /**
   * Minimum fitted length (px) for a line to be frozen — its direction settled,
   * so that later passes closing a junction move the other side.  See
   * `freezeConfidentLines`.  0 (the default) disables freezing entirely, which
   * is what makes the whole mechanism ablatable in one option.
   *
   * Lines only.  "Long and straight with low error" is unambiguous; "confident
   * arc" is not, and a compound curve is a run of arcs that only makes sense
   * together — no arc in it is individually certain, so the global DP keeps
   * them.
   */
  freezeMinLenPx?: number;
  /** Maximum re-measured centring error (px) for a line to be frozen.
   *  Defaults to 0.25 — the quantisation floor used elsewhere in the fitter. */
  freezeMaxCE?: number;
  /**
   * Run a free chain end forward, along its own tangent, on to geometry of a
   * DIFFERENT ink that it crosses within this many pixels.  A centreline drawn
   * up to an outline stops where its own ink stops — at the edge of the other
   * stroke — so it lands about a stroke half-width short.  0 disables.
   */
  extendToOtherInkPx?: number;

  /**
   * Optional diagnostic hook, called after every repair pass on every chain.
   * Undefined in production; `browser-app/e2e/pass_report.ts` uses it to
   * measure which passes improve the fit and which undo each other.
   */
  passProbe?: (o: PassObservation) => void;

  /**
   * Optional pass filter, consulted once per repair pass per chain.  Return
   * false to skip that pass entirely.
   *
   * Exists for ablation: the per-pass deltas `passProbe` reports are local, and
   * a pass that looks break-even there can still be worth keeping if the harm
   * it does is repairable downstream and the good it does is not.  The only way
   * to know is to remove it and measure the FINAL result, which is what
   * `vecfit.ts --without <pass>` does.  Undefined in production.
   */
  passFilter?: (name: string) => boolean;
  /**
   * Taper-junction collapse: maximum fitted length (px) of a "stub" chain
   * at a 3-way junction for it to be considered a taper stub and collapsed.
   * Collapsing removes the stub and extends the two parallel side chains to
   * meet at the stub's far tip, converting T-junction topology to a closed-loop
   * sharp corner.  Set to 0 (or omit) to disable.
   */
  taperCollapseMaxStubPx?: number;
  /**
   * Taper-junction collapse: maximum sine of the angle between the two side
   * chains for them to be considered "nearly parallel".  Defaults to 0.15
   * (≈ 8.6°).
   */
  taperCollapseMaxParallelSin?: number;
}


// ---------------------------------------------------------------------------
// Chain extraction
// ---------------------------------------------------------------------------

interface Chain {
  /** Vertex indices in traversal order. For closed rings, does NOT repeat v0. */
  vertices: number[];
  layer: number;
  isClosed: boolean;
}

/** Mutable endpoint tracking for a fitted chain (updated by post-fit undash). */
interface ChainInfo {
  startVi:  number;   // graph vertex index at the chain's start (recon[0] end)
  endVi:    number;   // graph vertex index at the chain's end   (recon[last] end)
  layer:    number;
  isClosed: boolean;
}

function buildAdj(n: number, edges: PathEdge[]): number[][] {
  const adj: number[][] = Array.from({ length: n }, () => []);
  for (const e of edges) {
    adj[e.from].push(e.to);
    adj[e.to].push(e.from);
  }
  return adj;
}

function extractChains(graph: PathGraph): Chain[] {
  const { vertices, edges } = graph;
  const n   = vertices.length;
  const adj = buildAdj(n, edges);

  const chains: Chain[] = [];
  const edgeVisited = new Set<string>();

  function edgeKey(a: number, b: number): string {
    return a < b ? `${a},${b}` : `${b},${a}`;
  }

  // --- Anchor-seeded chains ---
  for (let start = 0; start < n; start++) {
    if (vertices[start].type === "chain") continue;

    for (const next of adj[start]) {
      const key = edgeKey(start, next);
      if (edgeVisited.has(key)) continue;

      const path: number[] = [start, next];
      edgeVisited.add(key);
      let prev = start, curr = next;

      while (vertices[curr].type === "chain") {
        const nextN = adj[curr].find(x => x !== prev);
        if (nextN === undefined) break;
        const nk = edgeKey(curr, nextN);
        if (edgeVisited.has(nk)) break;
        edgeVisited.add(nk);
        path.push(nextN);
        prev = curr;
        curr = nextN;
      }

      const layer = vertices[path[0]].layer ?? vertices[path[1]].layer;
      chains.push({ vertices: path, layer, isClosed: false });
    }
  }

  // --- Unvisited degree-2 vertices → closed rings ---
  const inRing = new Uint8Array(n);
  for (const ch of chains) {
    for (const vi of ch.vertices) inRing[vi] = 1;
  }

  for (let start = 0; start < n; start++) {
    if (inRing[start] || vertices[start].type !== "chain") continue;

    const ring: number[] = [start];
    inRing[start] = 1;
    let prev = -1, curr = start;

    while (true) {
      const nextN = adj[curr].find(x => x !== prev && !inRing[x]);
      if (nextN === undefined) break;
      inRing[nextN] = 1;
      ring.push(nextN);
      prev = curr;
      curr = nextN;
    }

    if (ring.length >= 3) {
      chains.push({ vertices: ring, layer: vertices[ring[0]].layer, isClosed: true });
    }
  }

  return chains;
}

// ---------------------------------------------------------------------------
// Pixel collection
// ---------------------------------------------------------------------------

/**
 * An `InkProbe` over the PRE-thinning bit-planes, for `removeSpurs`.
 *
 * Kept beside `readAllLayers` because it is the same readback, and shared by
 * every entry point so the CPU harness and the browser cannot drift on what
 * counts as a spur — the pipeline defaults exist for the same reason.
 */
/**
 * Add the decorations `removeSpurs` lifted out of the skeleton to a fitted
 * graph, each as its own single-segment chain.
 *
 * They bypass the fitter deliberately.  A centre-point mark is 10 px of
 * straight ink whose exact extent was already measured off the raster, so there
 * is nothing for the DP to decide — and going round the fitter is what keeps
 * the contours it does fit byte-identical to a run without marks, which is the
 * whole reason these are decorations rather than geometry.
 */
export function appendStrokeMarks(curves: CurveGraph, marks: StrokeMark[]): void {
  if (marks.length === 0) return;
  let nextChain = 0;
  for (const s of curves.segments) nextChain = Math.max(nextChain, s.chainId + 1);
  for (const m of marks) {
    curves.segments.push({
      layer: m.layer, chainId: nextChain++, isClosed: false,
      primitive: makeLinePrimitive(m.x1, m.y1, m.x2, m.y2),
    });
  }
}

export async function readInkProbe(
  device: GPUDevice | null,
  decomp: PaletteDecomposition,
): Promise<InkProbe> {
  const { width, height, rowStride, layers } = decomp;
  if (decomp.cpuWords) {
    return inkProbeFromWords(decomp.cpuWords, width, height, rowStride);
  }
  if (!device) throw new Error("readInkProbe: no GPU device and no cpuWords fallback");

  const totalBytes = layers.length * rowStride * height * 4;
  const staging = device.createBuffer({
    size:  totalBytes,
    usage: GPUBufferUsage.COPY_DST | GPUBufferUsage.MAP_READ,
  });
  const encoder = device.createCommandEncoder();
  encoder.copyBufferToBuffer(decomp.buffer, 0, staging, 0, totalBytes);
  device.queue.submit([encoder.finish()]);
  await staging.mapAsync(GPUMapMode.READ);
  // Copy out before unmapping: the mapped range is only valid until then.
  const words = new Uint32Array(staging.getMappedRange().slice(0));
  staging.unmap();
  staging.destroy();
  return inkProbeFromWords(words, width, height, rowStride);
}

export async function readAllLayers(
  device: GPUDevice | null,
  decomp: PaletteDecomposition,
): Promise<Uint8Array[]> {
  const { width, height, rowStride, layers } = decomp;
  const numLayers  = layers.length;
  const layerWords = rowStride * height;
  const layerBytes = layerWords * 4;
  const totalBytes = numLayers * layerBytes;

  // CPU-backed decomposition: unpack directly, no GPU round-trip.
  if (decomp.cpuWords) {
    const allWords = decomp.cpuWords;
    const result: Uint8Array[] = [];
    for (let li = 0; li < numLayers; li++) {
      const offset = li * layerWords;
      const pixels = new Uint8Array(width * height);
      for (let y = 0; y < height; y++) {
        for (let x = 0; x < width; x++) {
          const wordIdx = offset + y * rowStride + (x >>> 5);
          if ((allWords[wordIdx] >>> (x & 31)) & 1) {
            pixels[y * width + x] = 1;
          }
        }
      }
      result.push(pixels);
    }
    return result;
  }

  if (!device) {
    throw new Error("readAllLayers: no GPU device and no cpuWords fallback");
  }

  const staging = device.createBuffer({
    size:  totalBytes,
    usage: GPUBufferUsage.COPY_DST | GPUBufferUsage.MAP_READ,
  });
  const encoder = device.createCommandEncoder();
  encoder.copyBufferToBuffer(decomp.buffer, 0, staging, 0, totalBytes);
  device.queue.submit([encoder.finish()]);

  await staging.mapAsync(GPUMapMode.READ);
  const allWords = new Uint32Array(staging.getMappedRange());

  const result: Uint8Array[] = [];
  for (let li = 0; li < numLayers; li++) {
    const offset = li * layerWords;
    const pixels = new Uint8Array(width * height);
    for (let y = 0; y < height; y++) {
      for (let x = 0; x < width; x++) {
        const wordIdx = offset + y * rowStride + (x >>> 5);
        if ((allWords[wordIdx] >>> (x & 31)) & 1) {
          pixels[y * width + x] = 1;
        }
      }
    }
    result.push(pixels);
  }

  staging.unmap();
  staging.destroy();
  return result;
}

// ---------------------------------------------------------------------------
// DP primitive fitting (shared by fitCurves and computeHoverFit)
// ---------------------------------------------------------------------------

/**
 * Run the O(W²) DP fitting pass over a dense-vertex window.
 * Returns the reconstructed segment list (wi/wj are 0-based within wdv).
 * Does NOT apply G1 junction adjustment — the caller should call snapAdjacentJunctions.
 */
/**
 * Longest span, in dense vertices, that one DP segment may cover (~512 px at
 * denseSeg = 2).
 *
 * The DP is O(W²) in chain length, and on a full sheet the longest chains run
 * to 2000–3400 vertices — 51 M window evaluations, 85% of the whole fit. Nearly
 * all of that is spent on very long windows that no primitive ever wins with.
 * Capping the span makes it O(W·cap); a run longer than the cap comes out as
 * consecutive collinear pieces and `mergeCollinearSegments` (which already runs
 * twice, for exactly this) joins them back up.
 *
 * Measured on a full sheet, sweeping the cap: centering (bias, median, p90,
 * p99, max), watertightness and chains-over-2px are IDENTICAL at every value;
 * only the segment count drifts, by +2 at 256 and +5 at 128, where the merge
 * does not quite recover a split. 256 keeps the fit 1.7× faster (15.2 s → 9.0 s)
 * with the arc count unchanged, and still allows a single arc of 512 px — well
 * past the 386 px longest arc on that sheet.
 */
const DEFAULT_MAX_SEG_VERTS = 256;

/**
 * A wholly unattached fitted stroke shorter than this (px) is discarded as
 * noise.  Same value and same argument as spur removal: 8 px at 200 dpi is
 * 0.04 inch, well below any feature that means anything on a plan.
 */
const DEFAULT_SPECK_MAX_PX = 8;

export function fitDenseChain(
  wdv:     Array<{ x: number; y: number }>,
  wpverts: Array<Array<{ x: number; y: number }>>,
  wvs:     Float64Array,
  opts:    CurveFitOptions,
): ReconEntry[] {
  const W       = wdv.length;
  const MIN_SEG = 4;
  if (W < MIN_SEG) return [];

  // Pre-compute per-vertex centroids once (fallback to skeleton when < 2 pixels).
  const centX  = new Float64Array(W);
  const centY  = new Float64Array(W);
  const validV = new Uint8Array(W); // 1 if vertex has ≥ 2 pixels
  for (let vi = 0; vi < W; vi++) {
    const pxs = wpverts[vi];
    if (pxs.length >= 2) {
      let sx = 0, sy = 0;
      for (const p of pxs) { sx += p.x; sy += p.y; }
      centX[vi] = sx / pxs.length;
      centY[vi] = sy / pxs.length;
      validV[vi] = 1;
    } else {
      centX[vi] = wdv[vi].x;
      centY[vi] = wdv[vi].y;
    }
  }

  // Scratch, hoisted out of the O(W·cap) loops: allocating per candidate
  // window is a measurable share of the fit on a full sheet.
  const dirOut = new Float64Array(5);
  /** Pixel count per dense vertex, so the hot loop never walks nested arrays. */
  const pxN = new Int32Array(W);
  for (let vi = 0; vi < W; vi++) pxN[vi] = wpverts[vi].length;
  /** Mean pixel count over vertices [c-1, c+1], clamped — gate 1b's probe. */
  let probeLo = 0, probeHi = 0;
  const probe = (c: number): number => {
    let sum = 0, cnt = 0;
    for (let k = Math.max(probeLo, c - 1); k <= Math.min(probeHi, c + 1); k++) {
      sum += pxN[k]; cnt++;
    }
    return cnt > 0 ? sum / cnt : 0;
  };

  const MDL = opts.mdlPenalty;
  const INF = Infinity;
  const dpCost = new Float64Array(W + 1).fill(INF);
  const dpFrom = new Int32Array(W + 1).fill(-1);
  const dpPrim: Array<LinePrimitive | ArcPrimitive | null> = new Array(W + 1).fill(null);
  const dpCE   = new Float64Array(W + 1);
  dpCost[0] = 0;

  const minArcVerts  = 6;       // dense verts (~12 px at denseSeg=2) before arcs considered
  const ARC_CE_SAMPLES = 24;    // fixed sample count keeps arc CE O(1) per window
  // Hard cap on how many dense vertices ONE segment may span.  The DP is
  // O(W²) in the chain length and the page's longest chains are 2000–3400
  // vertices, so the tail of very long windows costs most of the time while
  // producing candidates no primitive ever wins with.  A run longer than the
  // cap is emitted as consecutive collinear pieces and `mergeCollinearSegments`
  // — which already runs twice, precisely for this — joins them back up.
  //
  // This also subsumes the separate arc-window cap that used to bound arc
  // bookkeeping to 512 dense verts: at 256 the segment cap is always the
  // tighter of the two, so the arc cap could never fire.  If MAX_SEG_VERTS is
  // ever raised above ~512, reinstate an arc-specific cap — the arc
  // bookkeeping is what made long windows expensive in the first place.
  const MAX_SEG_VERTS = DEFAULT_MAX_SEG_VERTS;

  // Per-chain curviness pre-pass: a chain whose dense vertices never deviate
  // ≥ 1.5 px from the whole-chain chord cannot contain an acceptable arc
  // (the sagitta gate requires ≥ 1.5 px of bow), so all arc bookkeeping is
  // skipped. This keeps long straight chains — the DP's dominant cost on
  // real pages — at line-only speed.
  let fitArcs = opts.fitArcs !== false;
  if (fitArcs && W >= 2) {
    const ax = wdv[0].x, ay = wdv[0].y;
    const cdx = wdv[W - 1].x - ax, cdy = wdv[W - 1].y - ay;
    const cl = Math.hypot(cdx, cdy);
    if (cl > 1e-6) {
      let curvy = false;
      for (let i = 1; i < W - 1; i++) {
        const d = Math.abs((wdv[i].x - ax) * cdy - (wdv[i].y - ay) * cdx) / cl;
        if (d >= 1.5) { curvy = true; break; }
      }
      fitArcs = curvy;
    }
    // cl ≈ 0 (folded/near-closed chain): keep arcs enabled.
  }

  for (let wi = 0; wi < W; wi++) {
    if (dpCost[wi] === INF) continue;

    let pxCount = 0;
    const win = new Float64Array(6);

    // Running sums for valid centroids (lineCE) — O(1) per step.
    // lineCE = sqrt(perpX²·Vxx + 2·perpX·perpY·Vxy + perpY²·Vyy)
    // where Vxx/Vxy/Vyy are 2nd central moments of valid centroids
    // relative to the global pixel centroid (cx,cy) from dirFromWindow.
    let vN = 0, vSX = 0, vSY = 0, vSX2 = 0, vSY2 = 0, vSXY = 0;
    // The same moments over the window's UNSUPPORTED vertices — the ones with
    // no ink under them, whose position falls back to the dense vertex itself.
    let gN = 0, gSX = 0, gSY = 0, gSX2 = 0, gSY2 = 0, gSXY = 0;

    // Arc fitting: running raw sums up to CUBIC order over valid centroids in
    // a window-local frame (shifted by the window's first centroid) so the
    // cubic terms stay well inside double precision. These feed an O(1)
    // incremental Kåsa circle fit — the DP stays O(1) per window, which is
    // what made the line-only version fast (the original arc attempt re-ran
    // an O(n) circle fit per window and was a performance gotcha).
    const sx0 = centX[wi], sy0 = centY[wi];
    let aSx = 0, aSy = 0, aSxx = 0, aSyy = 0, aSxy = 0;
    let aSxxx = 0, aSyyy = 0, aSxxy = 0, aSxyy = 0;

    const wjEnd = Math.min(W, wi + MAX_SEG_VERTS);
    for (let wj = wi; wj < wjEnd; wj++) {
      windowAdd(win, wvs, wj);
      pxCount += pxN[wj];

      const cxj = centX[wj], cyj = centY[wj];
      if (!validV[wj]) {
        // Unsupported vertex: no ink under it, so `centX/centY` gave us the
        // dense vertex itself.  Across a bridged dash gap those vertices are
        // the chord between the two tips — weaker evidence than a pixel
        // centroid, but not nothing, and they are accumulated separately so
        // they can be charged without touching the ink term.
        gN++;
        gSX  += cxj; gSY  += cyj;
        gSX2 += cxj * cxj; gSY2 += cyj * cyj; gSXY += cxj * cyj;
      }
      if (validV[wj]) {
        vN++;
        vSX  += cxj; vSY  += cyj;
        vSX2 += cxj * cxj; vSY2 += cyj * cyj; vSXY += cxj * cyj;
        if (fitArcs) {
          const u = cxj - sx0, v = cyj - sy0;
          aSx += u; aSy += v;
          aSxx += u * u; aSyy += v * v; aSxy += u * v;
          aSxxx += u * u * u; aSyyy += v * v * v;
          aSxxy += u * u * v; aSxyy += u * v * v;
        }
      }

      const nv = wj - wi + 1;
      if (nv < MIN_SEG) continue;

      const usePixels = pxCount >= opts.minPoints;

      // O(1): direction + centroid from incremental pixel moments.
      dirFromWindowInto(win, dirOut);
      let dirX = dirOut[0], dirY = dirOut[1], lcx = dirOut[2], lcy = dirOut[3];

      // With too little ink to orient a line, `dirFromWindow` has nothing to
      // work from.  Take the direction from the unsupported vertices instead —
      // the chain still knows where it goes even where the ink does not.
      // Leaving the pixel-derived direction here is what let a window spanning
      // a bridged gap point anywhere at all.
      if (!usePixels && gN >= 2) {
        const mx = gSX / gN, my = gSY / gN;
        const Cxx = gSX2 / gN - mx * mx;
        const Cyy = gSY2 / gN - my * my;
        const Cxy = gSXY / gN - mx * my;
        const th = 0.5 * Math.atan2(2 * Cxy, Cxx - Cyy);
        dirX = Math.cos(th); dirY = Math.sin(th);
        lcx = mx; lcy = my;
      }
      const perpX = -dirY, perpY = dirX;

      /** RMS offset of a set of accumulated points from the fitted line. */
      const rmsAbout = (
        n: number, sx: number, sy: number, sxx: number, syy: number, sxy: number,
      ): number => {
        const Vxx = sxx / n - 2 * lcx * (sx / n) + lcx * lcx;
        const Vyy = syy / n - 2 * lcy * (sy / n) + lcy * lcy;
        const Vxy = sxy / n - lcx * (sy / n) - lcy * (sx / n) + lcx * lcy;
        return Math.sqrt(Math.max(0,
          perpX * perpX * Vxx + 2 * perpX * perpY * Vxy + perpY * perpY * Vyy));
      };

      // O(1): lineCE as RMS of per-vertex centroid offsets from the fitted
      // line.  Equivalent to lineCEFast but derived from incremental sums.
      let lineCE = 0;
      if (usePixels && vN >= 2) {
        lineCE = rmsAbout(vN, vSX, vSY, vSX2, vSY2, vSXY);
      }

      // How far the window's UNSUPPORTED vertices sit off the same line.
      //
      // Without this a window with no ink in it scored `lineCE = 0` — the best
      // result achievable — so a segment spanning a bridged dash gap cost only
      // its MDL penalty no matter which way it pointed.  Where a few pixels at
      // one end of such a window nudged the direction, the DP ran a segment out
      // at an angle for free: on a straight dashed line that showed up as the
      // fit leaving the ink by several pixels and coming back.  "No evidence"
      // must not score better than "fits perfectly".
      //
      // It is charged as an ADDITION to the cost rather than mixed into
      // `lineCE`, so a fully supported window (gN = 0, which is nearly all of
      // them) scores exactly what it scored before.  Mixing the two instead
      // makes the chord as authoritative as the ink, and the chord is only an
      // interpolation between two eroded dash tips — scored that way, the fit
      // starts tracking the chord's own kinks.
      // Charged only beyond a slack, and the slack is `bridgeGaps`' own bow
      // cap: a bridge may bow up to MAX_BOW_PX off its chord, so a primitive
      // staying within that of the chord is doing nothing the bridge did not
      // already license.  Beyond it, the primitive is inventing geometry.
      //
      // Without the slack this fires on chord noise.  Where a crossing stroke
      // nicks a dashed line, the chord spans two freshly eroded tips and sits
      // a fraction of a pixel off the true line; charged from zero, the DP
      // splits a straight run to track that fraction.  Measured on the
      // synthetic dashed scenes, any slack from 1 px up holds both cases —
      // this is a plateau, not a knife-edge.
      const UNSUPPORTED_SLACK_PX = 2.0;
      const gapCE = gN >= 2
        ? Math.max(0, rmsAbout(gN, gSX, gSY, gSX2, gSY2, gSXY) - UNSUPPORTED_SLACK_PX)
        : 0;

      // O(1): line endpoints — project skeleton boundary vertices onto the
      // fitted PCA direction, anchored to the pixel centroid (lcx, lcy).
      // The centroid correctly centers thick strokes.  Parallel-line
      // contamination is prevented by the CE quality gate in mergeCollinearSegments
      // rather than by forcing skeleton-midpoint positioning here.
      // The primitive itself is NOT built here.  Only one window in many wins,
      // and building a line object for every candidate is millions of dead
      // allocations per sheet; the winner is constructed after the DP test.
      let bestCE = lineCE;
      let arcHit = false;
      let aCx = 0, aCy = 0, aR = 0, aSa = 0, aEa = 0, aCCW = false, aSweep = 0, aCE = 0;

      // ── Arc candidate ────────────────────────────────────────────────────
      // Cheap O(1) screening gates first (learned from the earlier arc
      // attempt), then an O(1) incremental Kåsa circle fit, then a
      // fixed-sample radial CE. An arc must beat the line by `arcBenefit`.
      arcAttempt:
      if (fitArcs && usePixels && vN >= minArcVerts && lineCE >= 0.1) {
        // Gate 1 — consistent bow. The mean centroid and the mid-window
        // centroid must bulge to the SAME side of the chord by comparable
        // amounts; this rejects straight-with-noise windows (which would
        // become huge-radius arcs) and S-shaped windows spanning an
        // inflection (whose net bow cancels).
        const ax = centX[wi], ay = centY[wi];
        const bx = centX[wj], by = centY[wj];
        const chordDx = bx - ax, chordDy = by - ay;
        const chordLen = Math.hypot(chordDx, chordDy);
        if (chordLen < 1e-6) break arcAttempt;
        const cnx = -chordDy / chordLen, cny = chordDx / chordLen;
        const netBow = ((vSX / vN) - ax) * cnx + ((vSY / vN) - ay) * cny;
        const midVi  = (wi + wj) >> 1;
        const midBow = (centX[midVi] - ax) * cnx + (centY[midVi] - ay) * cny;
        if (Math.abs(netBow) < 0.6 * lineCE) break arcAttempt;
        if (midBow * netBow <= 0 || Math.abs(midBow) < 0.5 * Math.abs(netBow)) break arcAttempt;

        // Gate 1b — constant stroke width. A real curved stroke keeps its
        // width along the window; a large swing means the window is either a
        // taper or contaminated by a junction (band pixels from a crossing
        // stroke inflate counts AND pull centroids sideways, faking a bow —
        // the tapered_junction case). Both belong to the line + junction
        // repair machinery, not to an arc. Probe 5 points, each averaged
        // over 3 verts.
        probeLo = wi; probeHi = wj;
        const w0 = probe(wi);
        const wq = probe(wi + ((wj - wi) >> 2));
        const wm = probe(midVi);
        const w3 = probe(wi + (3 * (wj - wi) >> 2));
        const w1 = probe(wj);
        const wMin = Math.max(1, Math.min(w0, wq, wm, w3, w1));
        const wMax = Math.max(w0, wq, wm, w3, w1);
        if (wMax / wMin > 1.5) break arcAttempt;

        // Gate 2 — incremental Kåsa circle fit (window-local frame, centered
        // at the running mean for numerical stability).
        const mx = aSx / vN, my = aSy / vN;
        const Mxx = aSxx / vN - mx * mx;
        const Myy = aSyy / vN - my * my;
        const Mxy = aSxy / vN - mx * my;
        const det = Mxx * Myy - Mxy * Mxy;
        if (Math.abs(det) < 1e-10) break arcAttempt; // collinear
        // Centered third moments from raw sums.
        const Exxx = aSxxx / vN, Exyy = aSxyy / vN, Exxy = aSxxy / vN, Eyyy = aSyyy / vN;
        const Exx = aSxx / vN, Eyy = aSyy / vN, Exy = aSxy / vN;
        const Mxz = (Exxx - 3 * mx * Exx + 2 * mx * mx * mx) +
                    (Exyy - 2 * my * Exy - mx * Eyy + 2 * mx * my * my);
        const Myz = (Eyyy - 3 * my * Eyy + 2 * my * my * my) +
                    (Exxy - 2 * mx * Exy - my * Exx + 2 * my * mx * mx);
        const ocx = (Mxz * Myy - Myz * Mxy) / (2 * det);
        const ocy = (Myz * Mxx - Mxz * Mxy) / (2 * det);
        const r2 = ocx * ocx + ocy * ocy + Mxx + Myy;
        if (!(r2 > 0)) break arcAttempt;
        const r = Math.sqrt(r2);
        // World-frame centre.
        const ccx = ocx + mx + sx0;
        const ccy = ocy + my + sy0;

        // Gate 3 — radius sanity: small radii are corners, not curves; a
        // radius far beyond the chord is a nearly-straight window that the
        // line should own.
        if (r < opts.minArcRadius || r > chordLen * 10) break arcAttempt;

        // Gate 4 — direction and sweep from window endpoints, with the
        // mid-window centroid choosing the traversal side. Sweeps above π are
        // rejected: at that size the direction inference becomes unreliable
        // (the historical wrong-way-arc gotcha) and the DP composes several
        // shorter arcs instead.
        const sa = Math.atan2(ay - ccy, ax - ccx);
        const ea = Math.atan2(by - ccy, bx - ccx);
        const pma = Math.atan2(centY[midVi] - ccy, centX[midVi] - ccx);
        const spanCCW = ccwSpan(sa, ea);
        const midCCW  = ccwSpan(sa, pma);
        const arcCCW  = midCCW < spanCCW;
        const arcSweep = arcCCW ? spanCCW : 2 * Math.PI - spanCCW;
        if (arcSweep <= 0.02 || arcSweep > Math.PI) break arcAttempt;

        // Gate 4b — meaningful curvature. The arc's sagitta (bow depth from
        // its own chord) must be super-pixel; otherwise the "arc" is visually
        // a line and is just modelling sub-pixel skeleton wobble (the noise
        // arcs that plagued the first arc attempt had sagittas ≈ 0.6 px).
        const sagitta = r * (1 - Math.cos(arcSweep / 2));
        if (sagitta < 1.5) break arcAttempt;

        // Gate 5 — fixed-sample radial centering error (O(1): ≤ 24 samples).
        const step = Math.max(1, Math.floor(nv / ARC_CE_SAMPLES));
        let ceSum = 0, ceN = 0;
        for (let k = wi; k <= wj; k += step) {
          if (!validV[k]) continue;
          const d = Math.hypot(centX[k] - ccx, centY[k] - ccy) - r;
          ceSum += d * d;
          ceN++;
        }
        if (ceN < 3) break arcAttempt;
        const arcCE = Math.sqrt(ceSum / ceN);

        // Accept only when the arc beats the line by the relative benefit
        // factor AND a small absolute margin (a 0.03 px improvement is noise).
        if (arcCE <= lineCE * opts.arcBenefit && lineCE - arcCE >= 0.05) {
          arcHit = true;
          aCx = ccx; aCy = ccy; aR = r; aSa = sa; aEa = ea;
          aCCW = arcCCW; aSweep = arcSweep; aCE = arcCE;
          bestCE = arcCE;
        }
      }

      const totalCost = dpCost[wi] + bestCE * nv + gapCE * gN + MDL;
      if (totalCost < dpCost[wj + 1]) {
        const tVi = (wdv[wi].x - lcx) * dirX + (wdv[wi].y - lcy) * dirY;
        const tVj = (wdv[wj].x - lcx) * dirX + (wdv[wj].y - lcy) * dirY;
        dpCost[wj + 1] = totalCost;
        dpFrom[wj + 1] = wi;
        dpPrim[wj + 1] = arcHit
          ? makeArcPrimitive({ rmsError: aCE, cx: aCx, cy: aCy, r: aR, valid: true },
                             aSa, aEa, aCCW, aSweep)
          : makeLinePrimitive(lcx + tVi * dirX, lcy + tVi * dirY,
                              lcx + tVj * dirX, lcy + tVj * dirY);
        dpCE[wj + 1]   = bestCE;
      }
    }
  }

  // Reconstruct
  let coverEnd = W;
  while (coverEnd > 0 && dpCost[coverEnd] === INF) coverEnd--;
  if (coverEnd === 0) return [];

  const recon: ReconEntry[] = [];
  {
    let j = coverEnd;
    while (j > 0) {
      const i = dpFrom[j];
      if (i < 0) break;
      recon.unshift({ wi: i, wj: j - 1, prim: dpPrim[j]!, ce: dpCE[j] });
      j = i;
    }
  }
  return recon;
}

// ---------------------------------------------------------------------------
// Closed-chain seam closure
// ---------------------------------------------------------------------------

/**
 * For a closed chain after DP fitting, extend the first and last segments to
 * their mutual intersection rather than leaving a gap that the renderer would
 * close with a diagonal.  Only handles line–line seams; silently skips arcs.
 * The intersection must be within `maxExtend` pixels of both adjusted endpoints.
 */
function closeChainSeam(
  recon: Array<{ wi: number; wj: number; prim: LinePrimitive | ArcPrimitive; ce: number }>,
  maxExtend: number,
): void {
  if (recon.length < 2) return;
  const first = recon[0].prim;
  const last  = recon[recon.length - 1].prim;
  if (first.type !== "line" || last.type !== "line") return;

  // Direction vectors of the two lines.
  const dax = first.x2 - first.x1, day = first.y2 - first.y1;
  const dbx = last.x2  - last.x1,  dby = last.y2  - last.y1;

  // Solve for s and t: (first.x1 + s*dax, first.y1 + s*day) = (last.x1 + t*dbx, last.y1 + t*dby)
  const cross = dax * dby - day * dbx;
  if (Math.abs(cross) < 1e-10) return; // parallel or coincident

  const dx = last.x1 - first.x1, dy = last.y1 - first.y1;
  const s  = (dx * dby - dy * dbx) / cross;

  // Only close if we are genuinely EXTENDING both segments outward past their
  // gap endpoints — not truncating them inward toward a shared junction.
  // s <= 0: intersection is behind first.x1 (extend the first segment backward).
  // t >= 1: intersection is beyond last.x2  (extend the last segment forward).
  if (s > 0) return;

  const ix = first.x1 + s * dax;
  const iy = first.y1 + s * day;

  // Reject if the intersection is too far from either endpoint being moved.
  if (Math.hypot(ix - first.x1, iy - first.y1) > maxExtend) return;
  if (Math.hypot(ix - last.x2,  iy - last.y2)  > maxExtend) return;

  first.x1 = ix; first.y1 = iy;
  last.x2  = ix; last.y2  = iy;
}

// ---------------------------------------------------------------------------
// Junction endpoint snapping
// ---------------------------------------------------------------------------

/**
 * For each junction vertex (degree ≥ 3) in the skeleton graph, collect the
 * terminal segments from every open chain that ends there and snap all those
 * endpoints to one shared point.
 *
 * This is the *cross-chain* half of watertightness. `weldChainJunctions` closes
 * joints between consecutive segments of one chain; a junction where three
 * chains meet is only closed here, and nothing downstream will catch it if this
 * pass declines to act.
 *
 * The shared point is the least-squares best-fit intersection of the terminal
 * directions, which recovers a crisp corner where the branches genuinely cross.
 * Two things about that solve need care, and both were live defects:
 *
 * **A sharp inward Y is ill-conditioned.** When two of the branches leave the
 * junction nearly parallel — the two sides of a narrow V — the intersection of
 * their infinite lines is barely determined along their shared direction. On a
 * real sheet the solve landed 40 px up the V, was rejected by the distance
 * guard, and the pass then did *nothing*, leaving a 3.8 px hole in the
 * outline. The conditioning number is right there in the normal matrix, so a
 * poorly-determined solve now falls back to the centroid of the terminal
 * endpoints, which is always within a pixel or two of the real junction.
 * Falling back beats declining: an approximate shared point is still watertight,
 * and a missing one is not.
 *
 * **Arc-terminated chains must not be skipped.** An earlier version only
 * collected terminals whose primitive was a line, so a chain arriving on an arc
 * was silently left out of its own junction, measured at 1.4 px.
 * Arcs contribute their tangent line to the solve and are moved onto the shared
 * point with `reanchorArcThrough`, which pins the arc's far end so snapping the
 * junction cannot slide the rest of the arc off its ink.
 */
function snapJunctionEndpoints(
  graph:        PathGraph,
  chainInfos:   ChainInfo[],
  reconByChain: Array<ReconEntry[] | null>,
  maxExtend:    number,
  stubMaxPx:    number = 0,
): void {
  const { vertices } = graph;

  /**
   * How far a junction may sit off a terminal LINE's own axis before snapping
   * the endpoint would be a translation rather than a pivot.  Beyond this the
   * line is trimmed and a short connector runs out to the junction instead.
   */
  const MAX_PIVOT_PX = 0.8;

  // Map from junction-vertex index → terminal segments meeting there.
  // mainIdx: index of the first non-stub segment (counting from chain end).
  type Entry = {
    prim: LinePrimitive | ArcPrimitive;
    isStart: boolean;
    ci: number;
    mainIdx: number;
  };
  const jmap = new Map<number, Entry[]>();

  /** The terminal endpoint of an entry's primitive. */
  const entryPoint = (e: Entry) => primitiveEndPoint(e.prim, e.isStart);

  for (let ci = 0; ci < chainInfos.length; ci++) {
    const recon = reconByChain[ci];
    if (!recon || recon.length === 0) continue;
    const info = chainInfos[ci];
    if (info.isClosed) continue;

    const startVi = info.startVi;
    const endVi   = info.endVi;

    if (vertices[startVi]?.type === "junction") {
      // Walk forward from 0, skipping short stubs, keeping at least 1 segment.
      let mi = 0;
      while (mi + 1 < recon.length && stubMaxPx > 0) {
        const p = recon[mi].prim;
        if (p.type !== "line" || Math.hypot(p.x2 - p.x1, p.y2 - p.y1) >= stubMaxPx) break;
        mi++;
      }
      const e = jmap.get(startVi) ?? [];
      e.push({ prim: recon[mi].prim, isStart: true, ci, mainIdx: mi });
      jmap.set(startVi, e);
    }
    if (vertices[endVi]?.type === "junction") {
      // Walk backward from last, skipping short stubs, keeping at least 1 segment.
      let mi = recon.length - 1;
      while (mi - 1 >= 0 && stubMaxPx > 0) {
        const p = recon[mi].prim;
        if (p.type !== "line" || Math.hypot(p.x2 - p.x1, p.y2 - p.y1) >= stubMaxPx) break;
        mi--;
      }
      const e = jmap.get(endVi) ?? [];
      e.push({ prim: recon[mi].prim, isStart: false, ci, mainIdx: mi });
      jmap.set(endVi, e);
    }
  }

  const pendingConnectors: Array<{ ci: number; isStart: boolean; prim: LinePrimitive }> = [];

  for (const [, entries] of jmap.entries()) {
    if (entries.length < 2) continue;

    // Centroid and spread of where the terminals currently sit.  This is the
    // robust reference: every terminal was fitted to ink that runs up to the
    // junction, so the true junction is within a pixel or two of the centroid.
    let sx = 0, sy = 0;
    for (const e of entries) { const q = entryPoint(e); sx += q.x; sy += q.y; }
    const mxp = sx / entries.length, myp = sy / entries.length;
    let spread = 0;
    for (const a of entries) {
      const qa = entryPoint(a);
      for (const b of entries) {
        const qb = entryPoint(b);
        spread = Math.max(spread, Math.hypot(qa.x - qb.x, qa.y - qb.y));
      }
    }

    // Least-squares closest point to all terminal directions (an arc supplies
    // its tangent).  Minimises Σ (nᵢ · (x − pᵢ))² where nᵢ ⊥ direction.
    let a00 = 0, a01 = 0, a11 = 0, b0 = 0, b1 = 0;
    for (const e of entries) {
      const q = entryPoint(e);
      const t = primitiveTangentAt(e.prim, e.isStart);
      const nx = -t.ty, ny = t.tx;              // unit normal
      const c  = nx * q.x + ny * q.y;
      a00 += nx * nx; a01 += nx * ny; a11 += ny * ny;
      b0  += c * nx;  b1  += c * ny;
    }
    const det = a00 * a11 - a01 * a01;

    // Where to put the shared point.  Prefer the LS intersection, but only when
    // the system is well conditioned AND the answer is near the terminals; a
    // narrow V satisfies neither and would otherwise drag the junction far up
    // the vee (or, as before, make the pass give up entirely).
    let jx = mxp, jy = myp;
    if (Math.abs(det) >= 1e-3 * Math.max(1, a00 + a11)) {
      const ix = (a11 * b0 - a01 * b1) / det;
      const iy = (a00 * b1 - a01 * b0) / det;
      const near = Math.hypot(ix - mxp, iy - myp) <= 2 * spread + 4;
      let reachable = true;
      for (const e of entries) {
        const q = entryPoint(e);
        if (Math.hypot(ix - q.x, iy - q.y) > maxExtend) { reachable = false; break; }
      }
      if (near && reachable) { jx = ix; jy = iy; }
    }

    // Snap terminal endpoints and remove leading/trailing stubs.
    for (const { prim, isStart, ci, mainIdx } of entries) {
      const recon = reconByChain[ci]!;
      let connector: LinePrimitive | null = null;

      if (prim.type === "line") {
        // Moving one endpoint of a line pivots it about the other — harmless
        // when the junction is close to its axis.  But when a chain runs from
        // one junction to another, BOTH ends get moved and the pivot becomes a
        // TRANSLATION of the whole segment.  A narrow slot is the case that
        // breaks: its two long sides leave their end junctions ~2.5 px
        // off-axis, and moving both ends slid 900 px of line sideways until the
        // slot closed up and the part lost its cut-out.
        //
        // So a far-off junction gets a short connector instead: the line keeps
        // its body exactly where the ink is, is trimmed back a little, and a
        // new segment runs from there out to the junction.  Watertight either
        // way, and the geometry is what the drawing shows — a slot with a
        // pointed end, not a slot that has been squeezed shut.
        const dx = prim.x2 - prim.x1, dy = prim.y2 - prim.y1;
        const len = Math.hypot(dx, dy);
        const off = len > 1e-9
          ? Math.abs((jx - prim.x1) * dy - (jy - prim.y1) * dx) / len
          : Infinity;

        if (!(off > MAX_PIVOT_PX) || len < 8 * off) {
          if (isStart) { prim.x1 = jx; prim.y1 = jy; }
          else         { prim.x2 = jx; prim.y2 = jy; }
        } else {
          // Foot of the junction on the line's axis, pulled inward so the
          // connector leaves at roughly 45° rather than square across.
          const ux = dx / len, uy = dy / len;
          const inward = isStart ? 1 : -1;
          const t = ((jx - prim.x1) * ux + (jy - prim.y1) * uy) + inward * off;
          const px = prim.x1 + t * ux, py = prim.y1 + t * uy;
          if (isStart) { prim.x1 = px; prim.y1 = py; connector = makeLinePrimitive(jx, jy, px, py); }
          else         { prim.x2 = px; prim.y2 = py; connector = makeLinePrimitive(px, py, jx, jy); }
        }
      } else if (!reanchorArcThrough(prim, jx, jy, isStart)) {
        // The arc will not take the junction without distorting badly — leave
        // it rather than sliding the whole arc off its ink.  The other chains
        // still share a point; the audit reports what is left.
        continue;
      }

      if (isStart && mainIdx > 0) {
        recon.splice(0, mainIdx);
      } else if (!isStart && mainIdx < recon.length - 1) {
        recon.splice(mainIdx + 1);
      }
      // Deferred: inserting now would invalidate the mainIdx of the entry for
      // this chain's OTHER junction, which was computed before any splicing.
      if (connector) pendingConnectors.push({ ci, isStart, prim: connector });
    }
  }

  for (const { ci, isStart, prim } of pendingConnectors) {
    const recon = reconByChain[ci];
    if (!recon || recon.length === 0) continue;
    if (isStart) {
      recon.unshift({ wi: recon[0].wi, wj: recon[0].wi, ce: 0, prim });
    } else {
      const last = recon[recon.length - 1];
      recon.push({ wi: last.wj, wj: last.wj, ce: 0, prim });
    }
  }
}

// ---------------------------------------------------------------------------
// Interior corner-stub removal
// ---------------------------------------------------------------------------

/**
 * Scan each chain for short interior segments (< stubMaxPx) that are flanked
 * by longer segments.  Replace the triplet [prev, stub, next] with a single
 * corner vertex at the intersection of the prev and next lines, eliminating
 * the off-angle stub.  Repeats until stable.
 */
// ---------------------------------------------------------------------------
// Converging endpoint-pair snapping — implementation in snap_endpoint_pairs.ts
// ---------------------------------------------------------------------------

import { snapEndpointPairs } from "./snap_endpoint_pairs.ts";

// ---------------------------------------------------------------------------
// Junction taper collapse
// ---------------------------------------------------------------------------

/**
 * Detect and collapse T-junction "taper" patterns into sharp-angle closed loops.
 *
 * When two nearly-parallel "side" chains meet a short "stub" chain at a
 * T-junction vertex (degree-3), the stub represents the converging tip of the
 * two sides.  Collapsing removes the stub and redirects the sides to meet at
 * the tip, forming a proper pointed corner instead of a T-branch.
 *
 * Two topology variants:
 *
 *   TOP (stub arrives at junction, sides depart from it):
 *     The stub's far endpoint is the convergence tip above the junction.
 *     Both side chains start at the junction → move their first segment's
 *     start-point to the stub tip and remove the stub.
 *
 *   BOTTOM (stub departs from junction, sides arrive at it):
 *     The stub's far endpoint is the convergence tip below the junction.
 *     Both side chains end at the junction → append a new convergence segment
 *     from each side's current far-end to the stub tip, then remove the stub.
 *
 * Guard conditions (all must hold):
 *   - Exactly three chains meet at the junction vertex.
 *   - Exactly one chain is a "stub" (fitted length ≤ maxStubPx AND far endpoint
 *     is an endpoint-type vertex, not another junction).
 *   - The two sides are nearly parallel (sin of angle < maxParallelSin).
 *   - Stub length < 0.5 × the shorter side's fitted length.
 */

// ---------------------------------------------------------------------------
// Skeleton-centroid recentering for long segments
// ---------------------------------------------------------------------------

/**
 * When two roughly parallel strokes run close together, the pixel-collection
 * band (bandWidth) can reach across to the adjacent stroke, contaminating the
 * PCA centroid and pulling fitted lines inward.  The skeleton dense-vertex
 * positions are immune to this cross-talk because they come from the Guo-Hall
 * medial axis rather than from the pixel cloud.
 *
 * For every long segment (≥ minVerts dense vertices), compute the mean
 * perpendicular offset of the skeleton vertices from the fitted line and shift
 * the line to centre on those vertices.  The line direction is preserved —
 * only the perpendicular position changes.  Short segments keep the PCA
 * centroid (more accurate for isolated thick strokes where the integer-grid
 * skeleton induces sub-pixel bias).
 *
 * Junction-pinning: when `chainInfos` and `graph` are provided, the first
 * (resp. last) endpoint of a chain that meets a junction vertex is pinned in
 * place.  Only the opposite endpoint shifts, pivoting the segment around the
 * shared junction.  This preserves the closure established by
 * collapseJunctionTapers / snapJunctionEndpoints.
 */
function recenterOnSkeleton(
  reconByChain: Array<ReconEntry[] | null>,
  cache:        FitCache,
  minVerts:     number,
  chainInfos?:  ChainInfo[],
  graph?:       PathGraph,
): void {
  for (let ci = 0; ci < reconByChain.length; ci++) {
    const recon = reconByChain[ci];
    if (!recon || recon.length === 0) continue;
    const ch = cache.chains[ci];
    if (!ch) continue;
    const dv = ch.denseVerts;

    // Determine whether the chain's start/end vertices are junction-pinned.
    let pinStart = false, pinEnd = false;
    if (chainInfos && graph) {
      const info = chainInfos[ci];
      if (info && !info.isClosed) {
        const sv = graph.vertices[info.startVi];
        const ev = graph.vertices[info.endVi];
        if (sv?.type === "junction") pinStart = true;
        if (ev?.type === "junction") pinEnd   = true;
      }
    }

    for (let si = 0; si < recon.length; si++) {
      const s = recon[si];
      const p = s.prim;
      if (p.type !== "line") continue;
      const nv = s.wj - s.wi + 1;
      if (nv < minVerts) continue;

      // Determine which endpoints are pinned (shared with a junction).
      const isFirstSeg = (si === 0);
      const isLastSeg  = (si === recon.length - 1);
      const pin1 = isFirstSeg && pinStart;
      const pin2 = isLastSeg  && pinEnd;

      if (pin1 || pin2) {
        // At least one endpoint is junction-pinned.  Skip recentering to
        // preserve the closure established by collapseJunctionTapers /
        // snapJunctionEndpoints.  A junction-pinned segment often has its
        // start (or end) extended into a different skeleton region by
        // collapse, so the mean perpendicular offset mixes two regions
        // (junction centre + body) and cannot correctly position both ends.
        continue;
      }

      const dx = p.x2 - p.x1, dy = p.y2 - p.y1;
      const len = Math.hypot(dx, dy);
      if (len < 1e-10) continue;

      // Perpendicular unit vector (points "left" of the direction).
      const perpX = -dy / len, perpY = dx / len;

      // Mean perpendicular distance of skeleton vertices from the fitted line.
      // Positive = skeleton is to the "left", negative = to the "right".
      let sumPerp = 0;
      for (let vi = s.wi; vi <= s.wj; vi++) {
        sumPerp += (dv[vi].x - p.x1) * perpX + (dv[vi].y - p.y1) * perpY;
      }
      const meanPerp = sumPerp / nv;

      // Shift both endpoints by the perpendicular bias.
      p.x1 += meanPerp * perpX; p.y1 += meanPerp * perpY;
      p.x2 += meanPerp * perpX; p.y2 += meanPerp * perpY;
    }
  }
}

/**
 * Put every exactly-horizontal / exactly-vertical line in the middle of its own
 * stroke, to sub-pixel precision.
 *
 * `snapAxisAligned` makes a nearly-axis-aligned line exact by averaging its two
 * ENDPOINTS — but those have already been dragged around by junction snapping,
 * G1 and stub absorption, so the average is wherever the ends happened to land,
 * not where the ink is. `recenterOnSkeleton` then corrects only segments of
 * ≥ 100 dense vertices, and corrects them onto *skeleton* vertices, which live
 * on the integer grid: for an even-width stroke the medial axis has to pick a
 * side, so that correction is itself up to half a pixel off.
 *
 * Half a pixel is exactly what shows up. Measured on a real sheet, the
 * axis-aligned lines were median-perfect but 10% of the samples in one ink sat
 * 0.50 px out, and another ink averaged +0.245 px — a stroke-parity error, not
 * noise.
 *
 * The pixel cloud already knows the answer: for a solid run of integer pixels
 * the centroid IS the run centre, which is the middle of the middle row for an
 * odd width and the boundary between the two middle rows for an even one — the
 * two cases a human would draw by hand. So each dense vertex contributes the
 * perpendicular coordinate of its own centroid and the line takes their MEDIAN.
 * Median, not mean, because the band can reach across to a parallel stroke near
 * one end (the contamination `recenterOnSkeleton` exists for); that skews a few
 * vertices badly and the rest not at all.
 *
 * Shifts beyond `maxShift` are refused — at that size the band is contaminated
 * along most of its length, or the segment is not really on this stroke, and
 * either way the ink is not to be trusted over the fit.
 */
/** A line within this tangent of an axis is a candidate (~6°). */
const AXIS_TAN = 0.105;
/** The ink must be flat to this, across the whole segment, to be straightened. */
const AXIS_FLAT_PX = 0.75;
/** …and straightening may not fit the ink worse than the fitted direction by more. */
const AXIS_NO_WORSE_PX = 0.35;

function recentreAxisAligned(
  reconByChain: Array<ReconEntry[] | null>,
  cache:        FitCache,
  maxShift:     number,
): void {
  for (let ci = 0; ci < reconByChain.length; ci++) {
    const recon = reconByChain[ci];
    const ch    = cache.chains[ci];
    if (!recon || !ch) continue;
    const nv = ch.denseVerts.length;

    for (const s of recon) {
      const p = s.prim;
      if (p.type !== "line") continue;
      const dx = p.x2 - p.x1, dy = p.y2 - p.y1;
      const len = Math.hypot(dx, dy);
      if (len < 1e-9) continue;

      // Which axis is this line a candidate for?  Only lines already close to
      // one, so the "across" coordinate is a fair stand-in for the true
      // perpendicular.
      const horizontal = Math.abs(dy) <= Math.abs(dx) * AXIS_TAN;
      const vertical   = Math.abs(dx) <= Math.abs(dy) * AXIS_TAN;
      if (horizontal === vertical) continue;      // neither, or degenerate

      // Where the stroke actually is, across the line, at each dense vertex.
      const vals: number[] = [];
      for (let vi = s.wi; vi <= s.wj && vi < nv; vi++) {
        const pxs = ch.pixelsPerVert[vi];
        if (!pxs || pxs.length < 2) continue;
        let sum = 0;
        for (const px of pxs) sum += horizontal ? px.y : px.x;
        vals.push(sum / pxs.length);
      }
      if (vals.length < 3) continue;

      const sorted = vals.slice().sort((a, b) => a - b);
      const mid = sorted.length >> 1;
      const med = sorted.length % 2 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;

      // Compare against the MIDDLE of the segment, not an endpoint: on a line
      // that is merely near an axis the two ends are half the total rise apart,
      // and measuring from an end rejects every candidate before the ink is
      // ever consulted.
      const cur = horizontal ? (p.y1 + p.y2) / 2 : (p.x1 + p.x2) / 2;
      if (!(Math.abs(med - cur) <= maxShift)) continue;

      const already = Math.abs(horizontal ? dy : dx) <= 1e-6;
      if (!already) {
        // Straightening a line that is merely NEAR an axis is only right when
        // the ink is itself flat.  Plenty of real geometry is not: a panel
        // edge drawn at ~1.14° has ink sloping by the same 1.14°, and forcing
        // it to horizontal would put it 5px out.  So ask the ink, and
        // require both that a perfectly axis-aligned line fits it outright and
        // that doing so is no worse than the fitted direction.
        let axisDev = 0;
        for (const v of vals) axisDev = Math.max(axisDev, Math.abs(v - med));
        if (axisDev > AXIS_FLAT_PX) continue;

        let fitDev = 0;
        const px0 = p.x1, py0 = p.y1;
        for (let vi = s.wi, k = 0; vi <= s.wj && vi < nv; vi++) {
          const pxs = ch.pixelsPerVert[vi];
          if (!pxs || pxs.length < 2) continue;
          let sx = 0, sy = 0;
          for (const q of pxs) { sx += q.x; sy += q.y; }
          const cxv = sx / pxs.length, cyv = sy / pxs.length;
          fitDev = Math.max(fitDev, Math.abs((cxv - px0) * dy - (cyv - py0) * dx) / len);
          k++;
        }
        if (axisDev > fitDev + AXIS_NO_WORSE_PX) continue;
      }

      if (horizontal) { p.y1 = med; p.y2 = med; }
      else            { p.x1 = med; p.x2 = med; }
    }
  }
}

/**
 * Slide a long line sideways onto the middle of its own stroke.
 *
 * `recentreAxisAligned` above does two things at once — it *straightens* a line
 * onto an axis and it *re-centres* it — and gates both on the same test: the ink
 * must be flat across the whole span.  That is the right gate for straightening
 * and the wrong one for re-centring, and the difference matters, because a line
 * that is genuinely sloped fails it and then gets neither.
 *
 * Measured on a real sheet: a 440 px outline at 2 degrees sat most of a pixel
 * below its stroke's centre for its whole length, and it was not alone — of 122
 * lines over 100 px, **34 were more than 0.25 px off centre and 8 more than
 * 0.5**.  Nothing had moved them there.  The DP fits a line to the pixel cloud,
 * `recenterOnSkeleton` then corrects long segments onto integer-grid skeleton
 * vertices (and an even-width stroke's medial axis has to pick a side), and the
 * axis pass would only take a line it could also flatten.  Sloped lines fell
 * between all three.
 *
 * Translation changes no direction, so it needs no flatness test at all — it
 * needs only to be checked against the ink afterwards.  The median offset is
 * the shift (median, not mean, for the reason the axis pass gives: the
 * collection band can reach across to a parallel stroke near one end, which
 * skews a few vertices badly and the rest not at all), and the shift is kept
 * only if the centring error actually falls.  Six of those 122 would have been
 * made worse by their own median, and that test is what refuses them.
 *
 * No new threshold: the length bar is the one freezing already uses, since it
 * means the same thing — long enough that a fraction of a pixel is visible.
 */
function recentreLongLines(
  reconByChain: Array<ReconEntry[] | null>,
  cache:        FitCache,
  minLenPx:     number,
  maxShift:     number,
): void {
  /** Below this the shift is not worth reopening a junction for. */
  const MIN_SHIFT_PX = 0.05;

  for (let ci = 0; ci < reconByChain.length; ci++) {
    const recon = reconByChain[ci];
    const ch    = cache.chains[ci];
    if (!recon || !ch) continue;
    const nv = ch.denseVerts.length;

    for (const s of recon) {
      const p = s.prim;
      if (p.type !== "line") continue;
      const dx = p.x2 - p.x1, dy = p.y2 - p.y1;
      const len = Math.hypot(dx, dy);
      if (len < minLenPx || s.wi > s.wj) continue;
      const ux = dx / len, uy = dy / len;
      const nx = -uy, ny = ux;

      // Signed perpendicular offset of each dense vertex's pixel centroid from
      // the line as it stands.
      const offs: number[] = [];
      for (let vi = s.wi; vi <= s.wj && vi < nv; vi++) {
        const pxs = ch.pixelsPerVert[vi];
        if (!pxs || pxs.length < 2) continue;
        let sx = 0, sy = 0;
        for (const q of pxs) { sx += q.x; sy += q.y; }
        offs.push((sx / pxs.length - p.x1) * nx + (sy / pxs.length - p.y1) * ny);
      }
      if (offs.length < 3) continue;

      offs.sort((a, b) => a - b);
      const mid = offs.length >> 1;
      const med = offs.length % 2 ? offs[mid] : (offs[mid - 1] + offs[mid]) / 2;
      const shift = Math.abs(med);
      if (shift < MIN_SHIFT_PX || shift > maxShift) continue;

      // Ask the ink whether the shift helped.  A contaminated band can put the
      // median somewhere the stroke is not, and this is what catches it.
      const before = lineCEFast(ch.vertStats, s.wi, s.wj, p.x1, p.y1, ux, uy);
      const after  = lineCEFast(ch.vertStats, s.wi, s.wj,
        p.x1 + med * nx, p.y1 + med * ny, ux, uy);
      if (!(after < before)) continue;

      p.x1 += med * nx; p.y1 += med * ny;
      p.x2 += med * nx; p.y2 += med * ny;
    }
  }
}

function collapseJunctionTapers(
  graph:          PathGraph,
  chainInfos:     ChainInfo[],
  reconByChain:   Array<ReconEntry[] | null>,
  maxStubPx:      number,
  maxParallelSin: number,
): void {
  const { vertices } = graph;

  // Build map: junction vertex index → list of {ci, isStart} chain ends
  type ChainEnd = { ci: number; isStart: boolean };
  const jmap = new Map<number, ChainEnd[]>();

  for (let ci = 0; ci < chainInfos.length; ci++) {
    const recon = reconByChain[ci];
    if (!recon || recon.length === 0) continue;
    const info = chainInfos[ci];
    if (info.isClosed) continue;

    if (vertices[info.startVi]?.type === "junction") {
      const list = jmap.get(info.startVi) ?? [];
      list.push({ ci, isStart: true });
      jmap.set(info.startVi, list);
    }
    if (vertices[info.endVi]?.type === "junction") {
      const list = jmap.get(info.endVi) ?? [];
      list.push({ ci, isStart: false });
      jmap.set(info.endVi, list);
    }
  }

  /**
   * Perpendicular distance from a point to a line segment's infinite line.
   * A genuine taper's two sides CONVERGE on the stub tip, so the tip lies on
   * both of their lines.  Two parallel sides do not, and that is the whole
   * difference between a taper and a slot.
   */
  const tipOffLine = (l: LinePrimitive, px: number, py: number): number => {
    const dx = l.x2 - l.x1, dy = l.y2 - l.y1;
    const len = Math.hypot(dx, dy);
    if (len < 1e-10) return Infinity;
    return Math.abs((px - l.x1) * dy - (py - l.y1) * dx) / len;
  };
  /**
   * How far the tip may sit off a side's line and still count as the point they
   * converge on.  Below half a stroke: the two sides of a narrow slot are
   * parallel and ~5 px apart, so its "tip" is 2.5 px off each of them, and
   * collapsing swung both 900 px sides sideways and closed the slot.
   */
  const MAX_TIP_OFFSET = 1.5;

  for (const [_vi, ends] of jmap.entries()) {
    if (ends.length !== 3) continue;

    // Find the stub: shortest chain whose far end is an endpoint (not junction),
    // with fitted length ≤ maxStubPx.
    let stubK = -1, stubLen = Infinity;
    for (let k = 0; k < 3; k++) {
      const { ci, isStart } = ends[k];
      const farVi = isStart ? chainInfos[ci].endVi : chainInfos[ci].startVi;
      if (vertices[farVi]?.type === "junction") continue;   // far end must be an endpoint
      const recon = reconByChain[ci]!;
      let len = 0;
      for (const s of recon) len += reconSegLength(s.prim);
      if (len <= maxStubPx && len < stubLen) { stubK = k; stubLen = len; }
    }
    if (stubK < 0) continue;

    const sideKs = [0, 1, 2].filter(k => k !== stubK);
    const stub = ends[stubK];
    const stubRecon = reconByChain[stub.ci]!;
    const side0 = ends[sideKs[0]];
    const side1 = ends[sideKs[1]];

    // Guard: stub must be ≤ half the shorter side's length.
    const sideLen = (se: ChainEnd) => {
      const r = reconByChain[se.ci]!;
      let l = 0;
      for (const s of r) l += reconSegLength(s.prim);
      return l;
    };
    const minSideLen = Math.min(sideLen(side0), sideLen(side1));
    if (stubLen > minSideLen * 0.5) continue;

    // Determine topology variant and get direction vectors for the sides at the junction.
    // "isStart" means the junction is at the chain's START (so the chain departs junction).
    if (!stub.isStart && side0.isStart && side1.isStart) {
      // TOP variant: stub arrives at junction (stub.endVi = junction);
      // both sides depart from junction (side.startVi = junction).
      // Stub tip = start of first stub segment (chord start for an arc stub).
      const tip = primitiveEndPoint(stubRecon[0].prim, /*atStart=*/true);
      const tipX = tip.x;
      const tipY = tip.y;

      // Check sides are nearly parallel (compare their first-segment directions).
      // Arc sides are skipped: collapsing would require re-aiming the arc, and
      // a curved taper side is not the geometry this pass is built for.
      const r0 = reconByChain[side0.ci]!, r1 = reconByChain[side1.ci]!;
      const p0 = r0[0].prim, p1 = r1[0].prim;
      if (p0.type !== "line" || p1.type !== "line") continue;
      const d0x = p0.x2 - p0.x1, d0y = p0.y2 - p0.y1, d0l = Math.hypot(d0x, d0y);
      const d1x = p1.x2 - p1.x1, d1y = p1.y2 - p1.y1, d1l = Math.hypot(d1x, d1y);
      if (d0l < 1e-10 || d1l < 1e-10) continue;
      if (Math.abs(d0x/d0l * d1y/d1l - d0y/d0l * d1x/d1l) > maxParallelSin) continue;
      // …and they must actually converge ON the tip, not merely run alongside it.
      if (tipOffLine(p0, tipX, tipY) > MAX_TIP_OFFSET) continue;
      if (tipOffLine(p1, tipX, tipY) > MAX_TIP_OFFSET) continue;

      // Collapse: move both sides' first-segment start to the stub tip.
      p0.x1 = tipX; p0.y1 = tipY;
      p1.x1 = tipX; p1.y1 = tipY;

      // Mark stub as removed.
      reconByChain[stub.ci] = [];

    } else if (stub.isStart && !side0.isStart && !side1.isStart) {
      // BOTTOM variant: stub departs from junction (stub.startVi = junction);
      // both sides arrive at junction (side.endVi = junction).
      // Stub tip = end of last stub segment (chord end for an arc stub).
      const tip = primitiveEndPoint(stubRecon[stubRecon.length - 1].prim, /*atStart=*/false);
      const tipX = tip.x;
      const tipY = tip.y;

      // Check sides are nearly parallel (compare their last-segment directions).
      const r0 = reconByChain[side0.ci]!, r1 = reconByChain[side1.ci]!;
      const p0 = r0[r0.length - 1].prim, p1 = r1[r1.length - 1].prim;
      if (p0.type !== "line" || p1.type !== "line") continue;
      const d0x = p0.x2 - p0.x1, d0y = p0.y2 - p0.y1, d0l = Math.hypot(d0x, d0y);
      const d1x = p1.x2 - p1.x1, d1y = p1.y2 - p1.y1, d1l = Math.hypot(d1x, d1y);
      if (d0l < 1e-10 || d1l < 1e-10) continue;
      if (Math.abs(d0x/d0l * d1y/d1l - d0y/d0l * d1x/d1l) > maxParallelSin) continue;
      if (tipOffLine(p0, tipX, tipY) > MAX_TIP_OFFSET) continue;
      if (tipOffLine(p1, tipX, tipY) > MAX_TIP_OFFSET) continue;

      // Collapse: append a convergence segment to each side pointing to the tip.
      const newWj0 = r0[r0.length - 1].wj;
      r0.push({ wi: newWj0, wj: newWj0, ce: 0,
        prim: makeLinePrimitive(p0.x2, p0.y2, tipX, tipY) });

      const newWj1 = r1[r1.length - 1].wj;
      r1.push({ wi: newWj1, wj: newWj1, ce: 0,
        prim: makeLinePrimitive(p1.x2, p1.y2, tipX, tipY) });

      // Update chainInfos so the sides now end at the stub's endpoint vertex.
      chainInfos[side0.ci].endVi = chainInfos[stub.ci].endVi;
      chainInfos[side1.ci].endVi = chainInfos[stub.ci].endVi;

      // Mark stub as removed.
      reconByChain[stub.ci] = [];
    }
    // Mixed topology (one side starts, one ends at junction) — not a taper; skip.
  }
}

// ---------------------------------------------------------------------------
// Recon entry type (shared between fitCurves and postFitUndash)
// ---------------------------------------------------------------------------

export type ReconEntry = {
  wi: number; wj: number; prim: LinePrimitive | ArcPrimitive; ce: number;
  /**
   * This primitive's direction is settled and later passes may not change it.
   *
   * Set by `freezeConfidentLines` on lines that are long and sit squarely on
   * their ink.  It is a statement about *provenance*, not about geometry: two
   * passes asked to close the same joint cannot tell from the joint alone which
   * side has more evidence behind it, and the flag says so.
   *
   * A frozen segment may still be translated (`recentreAxisAligned` moves an
   * axis-aligned line onto the middle of its own stroke, which is what makes it
   * right) and its endpoints may still slide ALONG its own axis, which is how a
   * junction gets closed without pivoting it.  What is forbidden is moving an
   * endpoint sideways, because moving one end of a line rotates the whole of
   * it, and re-fitting it as part of something larger.
   */
  frozen?: boolean;
};

/**
 * Commit to the fits we are most certain about, so that later passes closing a
 * junction know which of its two sides to move.
 *
 * The repair passes are individually reasonable and collectively destructive: a
 * measured horizontal is fitted at -0.014 degrees, snapped to exactly 0 by
 * `axis 1`, holds for eight passes, and then leaves the pipeline at -0.921
 * degrees — 1.9 px of drift over 108 px of dead-straight ink — while its mirror
 * image on the same sheet keeps 0.000 to the end.  Nothing is wrong with any
 * one pass.  What is wrong is that every one of them resolves a joint by
 * splitting the difference, and splitting the difference is only correct when
 * the two sides are equally believable.
 *
 * Long and straight with low centring error is the one case where they
 * demonstrably are not, so it is the one this marks.  Length matters because a
 * PCA direction over hundreds of pixels of ink is worth more than one over a
 * handful, and it is also what makes the damage visible: a fraction of a degree
 * is nothing on a 12 px stub and 2 px of drift on a long wall.
 *
 * The error is re-measured here rather than read off `ce`, which was computed
 * before the merge and snap passes moved the geometry.  Whatever a segment is
 * about to be trusted for is what it has to be judged on.
 *
 * And it is measured about the line's own median offset, not about the line
 * where it sits.  Centring error as placed answers two questions at once — *is
 * this the right direction* and *is it in the right place* — and only the first
 * is what freezing claims.  A line running exactly parallel to its stroke but
 * most of a pixel to one side has a perfectly settled direction and a centring
 * error of 0.8, so the plain test rejects it.  That is backwards: an off-centre
 * line is precisely the one that needs its direction protected while
 * `recentreLongLines` slides it over, and on a real sheet a 440 px outline was
 * refused the freeze for being off centre, then had the correction welded
 * straight back out of it by an arc at its end.
 */
function freezeConfidentLines(
  recon:     ReconEntry[],
  vertStats: Float64Array,
  minLenPx:  number,
  maxCE:     number,
): void {
  for (const s of recon) {
    const p = s.prim;
    if (p.type !== "line") continue;
    const dx = p.x2 - p.x1, dy = p.y2 - p.y1;
    const len = Math.hypot(dx, dy);
    if (len < minLenPx) continue;
    if (s.wi > s.wj) continue;        // seam-wrapping entry: not a contiguous span
    const ux = dx / len, uy = dy / len;
    const nx = -uy, ny = ux;

    // Per-vertex mean perpendicular offsets, then the error about their median.
    const offs: number[] = [];
    for (let vi = s.wi; vi <= s.wj; vi++) {
      const b = vi * 6, n = vertStats[b];
      if (n < 2) continue;
      offs.push(((vertStats[b + 1] - n * p.x1) * nx +
                 (vertStats[b + 2] - n * p.y1) * ny) / n);
    }
    if (offs.length === 0) continue;
    const sorted = offs.slice().sort((a, b) => a - b);
    const mid = sorted.length >> 1;
    const med = sorted.length % 2 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
    let sum2 = 0;
    for (const o of offs) sum2 += (o - med) * (o - med);
    const ce = Math.sqrt(sum2 / offs.length);
    if (ce <= maxCE) s.frozen = true;
  }
}

/** Length of a recon segment: chord for lines, arc length for arcs. */
function reconSegLength(prim: LinePrimitive | ArcPrimitive): number {
  if (prim.type === "line") return Math.hypot(prim.x2 - prim.x1, prim.y2 - prim.y1);
  return prim.r * prim.sweep;
}

// ---------------------------------------------------------------------------
// Post-DP segment cleanup: merge near-collinear adjacent segments
// ---------------------------------------------------------------------------

/**
 * For closed chains, check whether the last and first segments are collinear
 * and should be merged across the chain seam.
 *
 * The standard mergeCollinearSegments loop only checks consecutive pairs
 * (i, i+1), so it misses the wrap-around pair (last, first).  This matters
 * when the skeleton traversal happens to start inside a straight edge, leaving
 * two collinear pieces on either side of the seam.
 *
 * A wider angular threshold (sin < 0.05 ≈ 2.9°) is used here because
 * axis-snapping can fractionally tilt one piece of a straight edge, making the
 * two halves appear to have a tiny angle discrepancy even though they are
 * geometrically the same line.  The CE quality gate provides the primary
 * protection against merging across a real (but shallow) corner.
 */
function mergeClosedChainSeam(
  recon:      ReconEntry[],
  denseVerts: Array<{ x: number; y: number }>,
  vertStats:  Float64Array,
): void {
  if (recon.length < 2) return;
  const sLast  = recon[recon.length - 1];
  const sFirst = recon[0];
  if (sLast.prim.type !== "line" || sFirst.prim.type !== "line") return;

  const pLast  = sLast.prim, pFirst = sFirst.prim;
  const lenLast  = Math.hypot(pLast.x2  - pLast.x1,  pLast.y2  - pLast.y1);
  const lenFirst = Math.hypot(pFirst.x2 - pFirst.x1, pFirst.y2 - pFirst.y1);
  if (lenLast < 1e-10 || lenFirst < 1e-10) return;

  // Angular collinearity check — wider threshold than the standard 0.02 to
  // tolerate axis-snap-induced micro-tilts on seam-split straight edges.
  const crossAbs = Math.abs(
    (pLast.x2 - pLast.x1) * (pFirst.y2 - pFirst.y1) -
    (pLast.y2 - pLast.y1) * (pFirst.x2 - pFirst.x1),
  );
  if (crossAbs / (lenLast * lenFirst) >= 0.05) return;

  // Accumulate pixel window across the seam (wrap-around).
  const nVerts = denseVerts.length;
  const allWin = new Float64Array(6);
  for (let vi = sLast.wi; vi < nVerts; vi++) windowAdd(allWin, vertStats, vi);
  for (let vi = 0; vi <= sFirst.wj; vi++) windowAdd(allWin, vertStats, vi);

  let lDirX = 1, lDirY = 0, lCx = 0, lCy = 0;
  if (allWin[0] >= 2) {
    const r = dirFromWindow(allWin);
    lDirX = r.dirX; lDirY = r.dirY; lCx = r.cx; lCy = r.cy;
  } else {
    lCx = (pLast.x1 + pFirst.x2) / 2; lCy = (pLast.y1 + pFirst.y2) / 2;
    const ddx = pFirst.x2 - pLast.x1, ddy = pFirst.y2 - pLast.y1;
    const dl = Math.hypot(ddx, ddy);
    if (dl > 1e-10) { lDirX = ddx / dl; lDirY = ddy / dl; }
  }

  // CE quality gate: check each piece individually against the merged direction.
  // (lineCEFast requires a contiguous range; we call it twice for the two halves.)
  const ceLast  = lineCEFast(vertStats, sLast.wi,  nVerts - 1, lCx, lCy, lDirX, lDirY);
  const ceFirst = lineCEFast(vertStats, sFirst.wi, sFirst.wj,  lCx, lCy, lDirX, lDirY);
  const mergedCE = Math.max(ceLast, ceFirst);
  if (mergedCE > Math.max(sLast.ce, sFirst.ce) * 3 + 0.5) return;

  // Build merged primitive: project seam endpoints onto the combined PCA axis.
  const tStart = (pLast.x1  - lCx) * lDirX + (pLast.y1  - lCy) * lDirY;
  const tEnd   = (pFirst.x2 - lCx) * lDirX + (pFirst.y2 - lCy) * lDirY;
  const mergedPrim = makeLinePrimitive(
    lCx + tStart * lDirX, lCy + tStart * lDirY,
    lCx + tEnd   * lDirX, lCy + tEnd   * lDirY,
  );

  // Replace recon[0] with the merged entry and drop the last entry.
  // wi > wj signals a seam-wrapping entry to downstream consumers.
  recon[0] = { wi: sLast.wi, wj: sFirst.wj, prim: mergedPrim, ce: mergedCE };
  recon.pop();
}

// ---------------------------------------------------------------------------

/**
 * Collapse degenerate (near-zero physical length) adjacent line segments into
 * a single PCA-fitted line.  Runs to convergence (typically 1–2 passes).
 *
 * A segment is considered degenerate when its physical endpoint distance is
 * less than minLengthPx.  This removes the tiny DP boundary stubs (e.g.
 * 0.04 px) that form when a few skeleton vertices near a chain end deviate
 * slightly from the main segment axis, creating visible backwards micro-kinks.
 *
 * Only physical length is used as the criterion — no angle threshold — to
 * avoid incorrectly merging arc segments whose adjacent-pair angles may be
 * only a few degrees apart.
 */
export function mergeCollinearSegments(
  recon:       ReconEntry[],
  denseVerts:  Array<{ x: number; y: number }>,
  vertStats:   Float64Array,
  minLengthPx: number,
  mdlPenalty:  number = 3,
  maxCE:       number = 0.5,
): void {
  /**
   * How much better a fresh fit must describe the combined span before it may
   * override a frozen direction: at most this fraction of the frozen fit's
   * error, and better by at least `FREEZE_OVERRIDE_MIN_PX` in absolute terms.
   *
   * Shaped after `arcBenefit`, and for the same reason — a relative bar alone
   * is meaningless when both errors are near zero, and an absolute one alone
   * scales wrong.
   *
   * Measured rather than picked.  The one case that must override —
   * `long_slight_diagonal`, where an axis snap froze the middle of a tilted
   * stroke exactly vertical — sits at 0.47.  Every frozen-merge candidate on a
   * real sheet (20 of them, including the horizontal this protects, at 0.86)
   * sits at 0.86 or above, most of them at 0.98-1.00: extending the frozen line
   * over its neighbour's span describes the ink about as well as re-fitting
   * both does, which is exactly what "the split was an artifact" looks like
   * from the other side.  0.65 sits in that gap.
   */
  const FREEZE_OVERRIDE_RATIO  = 0.65;
  const FREEZE_OVERRIDE_MIN_PX = 0.05;
  /**
   * A merge that moves the frozen segment's far end by less than this is not a
   * rotation, so the freeze has no opinion about it.  Small on purpose: the
   * damage it must still catch displaces the line 0.38 px, and the cases it
   * exists to let through do not move it at all.
   */
  const FREEZE_NO_ROTATION_PX = 0.1;

  // Short interior segments (< cornerStubMax) flanked by non-collinear longer
  // segments are corner stubs — replace them with a single corner vertex at
  // the intersection of the two flanking lines.  This runs alongside the
  // pair-merge pass so both cleanup phases converge together.
  const cornerStubMax = minLengthPx * 6;

  let changed = true;
  while (changed) {
    changed = false;

    // Pass A: PCA-merge short adjacent pairs (nearly collinear case).
    for (let i = 0; i + 1 < recon.length; i++) {
      const s1 = recon[i], s2 = recon[i + 1];
      if (s1.prim.type !== "line" || s2.prim.type !== "line") continue;
      const p1 = s1.prim, p2 = s2.prim;
      const len1 = Math.hypot(p1.x2 - p1.x1, p1.y2 - p1.y1);
      const len2 = Math.hypot(p2.x2 - p2.x1, p2.y2 - p2.y1);

      // Track whether this is a short-absorb merge so we can relax the CE gate.
      let shortAbsorb = false;

      if (len1 >= minLengthPx && len2 >= minLengthPx) {
        // Both segments are long.  Only merge if they are nearly collinear —
        // a phantom DP breakpoint on a straight line creates two long segments
        // with angle ≈ 0 that snapAdjacentJunctions will turn into a visible zigzag.
        // Any real corner visible to the eye is at least a few degrees, so a
        // threshold of sin < 0.02 (≈ 1.1°) is conservative and safe.
        //
        // Relaxation for short segments: when the shorter of the two is under
        // SHORT_ABSORB (10× denseSeg ≈ 20 px), the angular noise from skeleton
        // zigzag through erased notches can be several degrees even though the
        // underlying stroke is straight.  Widen the threshold to sin < 0.10
        // (≈ 5.7°) so these fragments get absorbed.  The angular check alone
        // provides sufficient geometric protection; the CE gate is skipped for
        // short-absorb merges because axis-snapped individual CEs being near-
        // zero is an artifact of snapping, not a sign of genuinely better fit.
        const SHORT_ABSORB = minLengthPx * 10;     // 20 px for denseSeg=2
        shortAbsorb = Math.min(len1, len2) < SHORT_ABSORB;
        const sinLimit = shortAbsorb ? 0.10 : 0.02;
        const crossAbs = Math.abs(
          (p1.x2 - p1.x1) * (p2.y2 - p2.y1) -
          (p1.y2 - p1.y1) * (p2.x2 - p2.x1),
        );
        const sinAng = crossAbs / (len1 * len2);

        // An angle on its own does not say how visible a joint is; the
        // displacement it puts into the path does, and that is the shorter
        // segment's length times the sine of the turn.  The two tiers above
        // disagree wildly about it — 20 px at 5.7 degrees is 2 px of
        // displacement, while 500 px at the "conservative" 1.1 degrees is 10 px
        // — so a fragment can be refused for an angle that moves the path a
        // twentieth of what an accepted one moves it.
        //
        // That gap is where the reported kinks live.  A thin sloped line
        // rasterises as a staircase, its skeleton zigzags, and the DP splits
        // off pieces about one dash long.  At 24-26 px those are just over
        // SHORT_ABSORB, so they face the 1.1 degree threshold and miss it by
        // hundredths of a degree while displacing the path half a pixel.
        //
        // So also accept a pair whose joint displaces the path less than
        // MAX_KINK_PX.  This only ever ADDS merges — every pair the angle
        // tiers accept is still accepted — and the CE gates below still decide
        // whether the merged primitive is good enough to keep.
        // 2.5 px is about half a stroke width at 200 dpi: a joint that moves
        // the path less than that keeps the polyline inside the ink it
        // describes, so there is nothing to see.  Swept against the plans —
        // below this it leaves kinks behind, and at 3.5 it starts merging
        // real bends and black centering degrades.
        const MAX_KINK_PX = 2.5;
        /**
         * …but only for joints that are shallow to begin with.  Displacement
         * alone cannot tell a shallow wobble from a short deliberate feature:
         * a 4.8 px chamfer turning 28 degrees moves the path just 2.2 px, so
         * the displacement rule swallowed it and a chamfered corner came back
         * square while its three identical neighbours were cut correctly.
         *
         * A turn this sharp is a corner however little of it there is, so the
         * relaxation is bounded by angle as well.  15 degrees clears the
         * dash-end wobble this rule exists for — those measured 1.2 and 5.7
         * degrees — with room to spare.
         */
        const KINK_MAX_SIN = 0.26;   // ~15 degrees
        const kinkPx = Math.min(len1, len2) * sinAng;
        if (sinAng >= sinLimit && (sinAng > KINK_MAX_SIN || kinkPx > MAX_KINK_PX)) continue;
        // Fall through to PCA-merge the nearly-collinear pair.
      }

      // Re-fit merged span with a single PCA line through combined pixel moments.
      const allWin = new Float64Array(6);
      for (let vi = s1.wi; vi <= s2.wj; vi++) windowAdd(allWin, vertStats, vi);

      let lDirX = 1, lDirY = 0, lCx = 0, lCy = 0;
      if (allWin[0] >= 2) {
        const r = dirFromWindow(allWin);
        lDirX = r.dirX; lDirY = r.dirY; lCx = r.cx; lCy = r.cy;
      } else {
        const v0 = denseVerts[s1.wi], v1 = denseVerts[s2.wj];
        lCx = (v0.x + v1.x) / 2; lCy = (v0.y + v1.y) / 2;
        const ddx = v1.x - v0.x, ddy = v1.y - v0.y;
        const dl  = Math.hypot(ddx, ddy);
        if (dl > 1e-10) { lDirX = ddx / dl; lDirY = ddy / dl; }
      }

      // Quality gate: reject the merge if the combined pixel cloud is much
      // worse than either individual segment.  The MDL-consistent check
      // prevents undoing DP splits that were made for good reason (e.g. bowing
      // lines): we only merge when the merged cost does not exceed the split
      // cost, i.e. mergedCE*(n1+n2) ≤ s1.ce*n1 + s2.ce*n2 + mdlPenalty.
      // This is equivalent to asking "would the DP still have preferred the
      // split?".  Phantom DP breakpoints (where all three CEs are near-equal)
      // are still absorbed because the MDL term gives the single segment a
      // free penalty budget.
      //
      // Short-absorb bypass: when a short fragment (< SHORT_ABSORB) is being
      // absorbed into a longer neighbor and the angular test already passed,
      // the CE gate is skipped.  Axis-snapping drives individual CEs to near-
      // zero (an artifact of snapping, not fit quality), so the MDL budget is
      // effectively zero and even sub-pixel zigzag noise fails.  The 5.7°
      // angular guard is sufficient geometric protection for fragments this
      // short.
      //
      // Collinear-shift bypass: when two nearly-collinear segments differ by
      // ≤ 1 px laterally, the split is an artifact of the pixel staircase —
      // the underlying stroke is a single straight line whose skeleton steps
      // between integer x (or y) positions.  The DP correctly fits each step
      // with CE ≈ 0, but the MDL budget is too small to absorb even sub-pixel
      // CE when multiplied by hundreds of vertices in the merged span.  The
      // angular test already ensures the segments are nearly parallel, and the
      // lateral proximity proves they describe the same feature.
      //
      // Quantisation noise floor (QUANT_FLOOR): when the merged CE is below
      // this threshold the deviation is indistinguishable from bitmap
      // staircase artifacts (sub-pixel grid rounding) and the merge proceeds
      // unconditionally.  Without this floor, axis-snapped vertical segments
      // at slightly different x positions accumulate enough cost over many
      // vertices to exceed the MDL budget, fragmenting long straight runs
      // (and skeleton zigzag through erased notches) into many tiny pieces.
      const QUANT_FLOOR = 0.25;   // px — sub-pixel bitmap noise
      const LATERAL_SHIFT_MAX = 1.0; // px — max lateral offset for bypass
      const vStart = denseVerts[s1.wi], vEnd = denseVerts[s2.wj];
      const mergedCE = lineCEFast(vertStats, s1.wi, s2.wj,
        lCx, lCy, lDirX, lDirY);
      const n1m = s1.wj - s1.wi + 1, n2m = s2.wj - s2.wi + 1;

      // Compute lateral offset: perpendicular distance from the midpoint of
      // the SHORTER segment to the longer one's infinite line.
      //
      // Which of the two supplies the midpoint matters, and taking p2's
      // unconditionally — as this did — makes the test measure something else.
      // The lever arm is what it measures: a midpoint L/2 from the joint turns
      // an angular difference θ into L/2·sin θ of lateral offset.  Pair a 73 px
      // fragment with a 1245 px line 0.3° off it and p2's midpoint is 620 px
      // out, reporting 3.2 px and failing a 1 px threshold, while the two
      // segments are within half a pixel of each other everywhere they are
      // both near.  Long lines could therefore never absorb a fragment, and
      // the longer the line the harder it got — which is backwards, and is
      // what left long straight runs carrying a little kink near one end.
      // Bounding the lever arm by the shorter segment keeps the test asking
      // the question it is named for: was this split an artifact?
      let collinearShift = false;
      if (!shortAbsorb) {
        const [pLong, pShort] = len1 >= len2 ? [p1, p2] : [p2, p1];
        const lenLong = Math.max(len1, len2);
        const perpX = -(pLong.y2 - pLong.y1) / lenLong, perpY = (pLong.x2 - pLong.x1) / lenLong;
        const msx = (pShort.x1 + pShort.x2) / 2, msy = (pShort.y1 + pShort.y2) / 2;
        const latOffset = Math.abs((msx - pLong.x1) * perpX + (msy - pLong.y1) * perpY);
        collinearShift = latOffset <= LATERAL_SHIFT_MAX;
      }

      // Merging must never produce a primitive the fitter itself would have
      // rejected.  The bypasses above answer "was this split an artifact?" with
      // a LOCAL test — an angle, a lateral offset between neighbours — and a
      // local test cannot see what repeated merging accumulates.
      //
      // Measured on a very gently curved panel edge: ~0.3 degrees of turn
      // between adjacent DP segments and 1.0 px of lateral offset — passing
      // both bypasses at every step.  Merged pairwise all the way up, it became
      // ONE 1606 px line sitting up to 9 px off the ink it described.
      //
      // So the absolute gate stands regardless of which bypass applied: below
      // the quantisation floor the deviation is bitmap staircase and always
      // fine; above `maxCE` it is a real feature and never fine.
      if (mergedCE > QUANT_FLOOR && mergedCE > maxCE) continue;
      if (!shortAbsorb && !collinearShift && mergedCE > QUANT_FLOOR &&
          mergedCE * (n1m + n2m) > s1.ce * n1m + s2.ce * n2m + mdlPenalty) continue;

      // A merge re-fits both sides from scratch, so it is the one operation a
      // frozen segment cannot survive intact.  Refusing outright is wrong,
      // though, and the case that proves it is `long_slight_diagonal`: a 453 px
      // stroke tilted 0.25 degrees rasterises with its middle 224 px sitting at
      // one integer column, so that piece is snapped exactly vertical and fits
      // its own span to 0.019 px.  It is locally perfect and globally wrong, and
      // the evidence that it is wrong exists only over a longer run than the one
      // it was frozen on.
      //
      // So the freeze is an incumbent rather than a veto: keep the frozen
      // direction unless a fresh fit describes the COMBINED span decisively
      // better than extending the frozen line over it would.  That is the same
      // question the DP asks, put to the one span where the answer is in doubt.
      // Measured: the diagonal's fresh fit scores 0.27 px over the combined
      // span against 0.58 for the frozen direction, so it wins and the freeze
      // is released.  The horizontal this exists to protect scores 0.23 against
      // 0.26 — the fresh fit is barely better, because all it is doing is
      // splitting the difference between a level run and an 8 px step — so the
      // freeze holds.
      let mergedFrozen = false;
      if (s1.frozen || s2.frozen) {
        const fp = (s1.frozen ? p1 : p2) as LinePrimitive;
        const fdx = fp.x2 - fp.x1, fdy = fp.y2 - fp.y1;
        const flen = Math.hypot(fdx, fdy);
        if (flen < 1e-9) continue;

        // What the freeze guards against is ROTATION.  A merge whose fitted
        // direction is the frozen one is not a rotation at all — it is the
        // frozen line extended over its neighbour's span, which is a thing a
        // frozen segment is explicitly allowed to do.  Refusing those was
        // costing far more than the freeze was buying: on one sheet it left a
        // 2.3 px connector standing between a 289 px horizontal and the fillet
        // it runs into, both of them still exactly level, and that stub reads as
        // two visible kinks where there had been none.  Measured across the
        // page, refusing no-rotation merges accounted for 7 of the 7 kinks the
        // freeze added and 10 of its 10 extra segments.
        //
        // Measured as displacement at the frozen segment's far end, in keeping
        // with the rest of this function: an angle says nothing about how
        // visible a joint is, and the lever arm is what turns one into the
        // other.
        const rotPx = Math.abs(fdx * lDirY - fdy * lDirX);   // flen · |sin θ|
        // A merge that does not rotate the line produces the frozen line
        // extended, so the merged entry is still the settled direction and must
        // say so.  Whatever replaces a frozen primitive inherits the claim or
        // the claim is silently dropped — the same mistake `refitPoorSpans`
        // made, found the same way, by a protected line arriving at the final
        // weld with nothing to protect it.
        mergedFrozen = rotPx <= FREEZE_NO_ROTATION_PX;
        if (rotPx > FREEZE_NO_ROTATION_PX) {
          const frozenCE = lineCEFast(
            vertStats, s1.wi, s2.wj, fp.x1, fp.y1, fdx / flen, fdy / flen);
          if (!(mergedCE < frozenCE * FREEZE_OVERRIDE_RATIO &&
                mergedCE < frozenCE - FREEZE_OVERRIDE_MIN_PX)) continue;
        }
      }

      // Anchor endpoints to the pixel centroid — correctly centres the segment
      // on thick strokes.  The CE gate above already rejected any merge where
      // the pixel cloud is contaminated by a parallel feature.
      const tFirst = (vStart.x - lCx) * lDirX + (vStart.y - lCy) * lDirY;
      const tLast  = (vEnd.x   - lCx) * lDirX + (vEnd.y   - lCy) * lDirY;
      const mergedPrim = makeLinePrimitive(
        lCx + tFirst * lDirX, lCy + tFirst * lDirY,
        lCx + tLast  * lDirX, lCy + tLast  * lDirY,
      );
      recon.splice(i, 2, {
        wi: s1.wi, wj: s2.wj, prim: mergedPrim, ce: mergedCE,
        ...(mergedFrozen ? { frozen: true } : {}),
      });
      changed = true;
      break;
    }

    // Pass B: squash corner stubs — short segment between two non-collinear
    // longer segments.  Use line-line intersection instead of PCA refit so the
    // direction of each flanking segment is preserved exactly.
    for (let i = 1; i < recon.length - 1; i++) {
      const sc = recon[i];
      if (sc.prim.type !== "line") continue;
      const pc = sc.prim;
      const stubLen = Math.hypot(pc.x2 - pc.x1, pc.y2 - pc.y1);
      if (stubLen >= cornerStubMax) continue;

      const sp = recon[i - 1], sn = recon[i + 1];
      if (sp.prim.type !== "line" || sn.prim.type !== "line") continue;
      const pp = sp.prim, pn = sn.prim;

      const pdx = pp.x2 - pp.x1, pdy = pp.y2 - pp.y1;
      const ndx = pn.x2 - pn.x1, ndy = pn.y2 - pn.y1;
      const pLen = Math.hypot(pdx, pdy), nLen = Math.hypot(ndx, ndy);
      if (pLen < 1e-10 || nLen < 1e-10) continue;
      // Both flanking segments must be substantially longer than the stub.
      if (pLen < stubLen * 3 || nLen < stubLen * 3) continue;

      // Anti-parallel stubs (going backward relative to the chain direction)
      // are never valid geometry and must be removed unconditionally — no CE
      // gate.  All other stubs are gated by the 2% CE threshold: genuine arc
      // stubs have ce/len ≥ 3%; staircase pixel-noise stubs have ce/len ≤ 2%.
      const cdx = pc.x2 - pc.x1, cdy = pc.y2 - pc.y1;
      const dotPC = (cdx * pdx + cdy * pdy) / (stubLen * pLen);
      const isAntiParallel = dotPC < -0.5;
      if (!isAntiParallel && sc.ce > stubLen * 0.02) continue;

      const denom = pdx * ndy - pdy * ndx;
      // Nearly-collinear flanking: use midpoint to absorb the stub.
      // Safety check: midpoint must be "ahead" of pp's start and "before"
      // pn's end — otherwise removing the stub would reverse a flanking segment.
      if (Math.abs(denom) / (pLen * nLen) < 0.25) {
        // Same rule as `stitchJunctions`: the midpoint moves both flanks, so
        // where exactly one is frozen the joint goes on its endpoint instead.
        // (The stub itself is never frozen — it is far too short to qualify —
        // and the significant-angle branch below uses the two flanks' own
        // intersection, which slides each along its own axis and is safe.)
        const mx = sp.frozen && !sn.frozen ? pp.x2
          : sn.frozen && !sp.frozen ? pn.x1 : (pp.x2 + pn.x1) / 2;
        const my = sp.frozen && !sn.frozen ? pp.y2
          : sn.frozen && !sp.frozen ? pn.y1 : (pp.y2 + pn.y1) / 2;
        if ((mx - pp.x1) * pdx + (my - pp.y1) * pdy <= 0) continue;
        if ((pn.x2 - mx) * ndx + (pn.y2 - my) * ndy <= 0) continue;
        pp.x2 = mx; pp.y2 = my;
        pn.x1 = mx; pn.y1 = my;
        recon.splice(i, 1);
        changed = true; break;
      }

      // In the significant-angle branch, only squash stubs that are going backward
      // (anti-parallel).  Forward stubs between flanking segments at a real corner
      // angle represent genuine geometry — a rounded corner diagonal, say — and
      // should be preserved for G1 to handle via intersection.  Squashing them
      // here would square off genuinely rounded corners.
      if (!isAntiParallel) continue;

      const gx = pn.x1 - pp.x2, gy = pn.y1 - pp.y2;
      const t  = (gx * ndy - gy * ndx) / denom;
      const s  = (gx * pdy - gy * pdx) / denom;
      // t < 0: intersection is behind pp's end (lines diverge — would shorten/reverse pp).
      // s > 0: intersection is ahead of pn's start (would reverse pn).
      if (t < 0 || s > 0) continue;
      const ix = pp.x2 + t * pdx, iy = pp.y2 + t * pdy;
      if (Math.hypot(ix - pc.x1, iy - pc.y1) > stubLen * 4) continue;

      pp.x2 = ix; pp.y2 = iy;
      pn.x1 = ix; pn.y1 = iy;
      recon.splice(i, 1);
      changed = true;
      break;
    }
  }
}

// ---------------------------------------------------------------------------
// Absorb short lines that lie on a neighbouring arc's circle
// ---------------------------------------------------------------------------

/**
 * Second-chance fit for spans the first pass got wrong.
 *
 * The DP that produced these primitives ran once, over the whole chain, under a
 * segment penalty tuned for the page as a whole — and then a dozen passes moved
 * endpoints around to close junctions.  Neither the penalty nor those passes
 * can see that one particular corner came out square where the ink is
 * chamfered, or that a long line would sit down the middle of its stroke if it
 * were allowed one more vertex at the end.
 *
 * So: find the spans that are actually off their ink, and let the DP have
 * another go at just those, with one more segment than they currently use and
 * the penalty swept downward.  `fitDenseChain` weighs an arc against a line in
 * every window it considers, so a re-fit can change a segment's TYPE, split it,
 * merge it, or move its boundaries — all the freedom the first pass had, but
 * spent locally where it is needed instead of globally where it is not.
 *
 * Two things keep this from bloating the output.  A span is only considered if
 * something in it is genuinely off the ink (or if a connector was just spliced
 * into it, which is the same situation by construction — see
 * `snapAdjacentJunctions`).  And a result is only taken if it measurably
 * improves the worst deviation over that span, so a neighbourhood the first
 * pass had right is left exactly as it was.
 */
function refitPoorSpans(
  recon:         ReconEntry[],
  connectors:    number[],
  denseVerts:    Array<{ x: number; y: number }>,
  pixelsPerVert: Array<Array<{ x: number; y: number }>>,
  vertStats:     Float64Array,
  opts:          CurveFitOptions,
): void {
  /** A vertex further than this from its own primitive is a defect worth re-fitting. */
  const REFIT_TOL_PX = 1.5;
  /**
   * Longest span to re-fit.  Generous, because a span is padded by whole
   * neighbouring entries and a defect between two long runs therefore drags
   * them both in: the corner this limit was first found on sits between a
   * 445-vertex line and its neighbours, so a 400-vertex cap silently skipped
   * exactly the case that needed re-fitting.  The DP caps its own windows at
   * MAX_SEG_VERTS, so cost here is linear in the span, not quadratic.
   */
  const MAX_SPAN_VERTS = 1500;

  const distTo = (p: ReconEntry["prim"], x: number, y: number): number => {
    if (p.type === "line") {
      const dx = p.x2 - p.x1, dy = p.y2 - p.y1;
      const L2 = dx * dx + dy * dy;
      const t = L2 > 0 ? Math.max(0, Math.min(1, ((x - p.x1) * dx + (y - p.y1) * dy) / L2)) : 0;
      return Math.hypot(x - (p.x1 + t * dx), y - (p.y1 + t * dy));
    }
    if (p.type === "arc") return Math.abs(Math.hypot(x - p.cx, y - p.cy) - p.r);
    return Infinity;
  };

  /** Worst distance from any dense vertex in [lo,hi] to the nearest of `entries`. */
  const worstOver = (entries: ReconEntry[], lo: number, hi: number): number => {
    let worst = 0;
    for (let vi = lo; vi <= hi; vi++) {
      const v = denseVerts[vi];
      let best = Infinity;
      for (const e of entries) {
        const d = distTo(e.prim, v.x, v.y);
        if (d < best) best = d;
      }
      if (best !== Infinity && best > worst) worst = best;
    }
    return worst;
  };

  // ── Which entries are worth revisiting ──────────────────────────────────
  const poor = new Set<number>(connectors.flatMap((k) => [k - 1, k, k + 1]));
  for (let i = 0; i < recon.length; i++) {
    const e = recon[i];
    if (e.wj <= e.wi) continue;
    for (let vi = e.wi; vi <= e.wj; vi++) {
      const v = denseVerts[vi];
      if (v && distTo(e.prim, v.x, v.y) > REFIT_TOL_PX) { poor.add(i); break; }
    }
  }
  if (poor.size === 0) return;

  // Group into maximal runs, each padded by a neighbour either side so the
  // re-fit has somewhere to move a boundary TO.
  const idx = [...poor].filter((i) => i >= 0 && i < recon.length).sort((a, b) => a - b);
  const runs: Array<[number, number]> = [];
  for (const i of idx) {
    const last = runs[runs.length - 1];
    if (last && i <= last[1] + 1) last[1] = i;
    else runs.push([i, i]);
  }

  // Back to front: replacing a run shifts every index after it.
  for (let r = runs.length - 1; r >= 0; r--) {
    const a = Math.max(0, runs[r][0] - 1);
    const b = Math.min(recon.length - 1, runs[r][1] + 1);
    const lo = recon[a].wi, hi = recon[b].wj;
    if (hi - lo < 8 || hi - lo > MAX_SPAN_VERTS) continue;
    if (lo < 0 || hi >= denseVerts.length) continue;

    const before = recon.slice(a, b + 1);
    const wasWorst = worstOver(before, lo, hi);
    if (wasWorst <= 0.5) continue;   // already within the fitter's own bar

    const sliceVerts = denseVerts.slice(lo, hi + 1);
    const slicePx    = pixelsPerVert.slice(lo, hi + 1);
    const sliceStats = vertStats.slice(lo * 6, (hi + 1) * 6);

    // At its normal penalty the DP just reproduces the answer it already gave;
    // at zero it splits as far as MIN_SEG allows.  Sweep down and keep the best
    // result that stays inside the budget.
    // Two, not one.  A span re-fitted on its own often wants one more segment
    // than the global pass gave it before it can improve at all — the boundary
    // it needs to move is itself a segment — so a budget of +1 rejects the
    // result before its quality is ever considered.
    const budget = before.length + 2;
    let bestFit: ReconEntry[] | null = null;
    let bestWorst = wasWorst;
    for (const scale of [1, 0.5, 0.25, 0.1, 0.03]) {
      const refit = fitDenseChain(sliceVerts, slicePx, sliceStats, {
        ...opts, mdlPenalty: (opts.mdlPenalty ?? 3) * scale,
      });
      if (refit.length === 0 || refit.length > budget) continue;
      const shifted: ReconEntry[] = refit.map((e) => ({
        wi: e.wi + lo, wj: e.wj + lo, prim: e.prim, ce: e.ce,
      }));
      const w = worstOver(shifted, lo, hi);
      if (w < bestWorst * 0.9) { bestWorst = w; bestFit = shifted; }
    }
    if (!bestFit) continue;

    // A re-fit is the one way a frozen primitive can be replaced without any
    // pass having moved it, and the padding rule above makes that common rather
    // than rare: a confident line's whole job is to sit next to the awkward
    // geometry that needs re-fitting.
    //
    // Refusing to re-fit near a frozen entry is the wrong fix, and cost a
    // watertightness leak to learn.  On a real sheet a nearly-tangent line/arc
    // joint has `snapAdjacentJunctions` trim 14 px off the line to reach the
    // circle, and this pass is what repairs it; blocked, the arc never reaches
    // and the chain ships a 16 px hole.  The re-fit was doing its job.
    //
    // So the flag is re-derived for what came back rather than defended.  The
    // test is the same one that granted it, applied to the new geometry — which
    // is the only version of it that can be true.
    if ((opts.freezeMinLenPx ?? 0) > 0) {
      freezeConfidentLines(bestFit, vertStats, opts.freezeMinLenPx!, opts.freezeMaxCE ?? 0.25);
    }
    recon.splice(a, b - a + 1, ...bestFit);
  }
}

/**
 * Remove short line segments that are really part of an adjacent arc.
 *
 * The DP arc gate needs ~6 dense vertices (~12 px) of consistent bow before it
 * will emit an arc.  A smooth compound curve whose radius changes gradually can
 * therefore leave a short straight "transition" segment between two arcs — the
 * span is too short to qualify as its own arc, so DP covers it with a line.
 * That line is a chord of the surrounding curve: it pokes slightly OUTWARD of
 * the stroke and, because its direction differs from both flanking arcs'
 * tangents, it introduces the inward-pointing inflection the user reported.
 *
 * For each short line (chord < maxLen) that has at least one arc neighbour,
 * this pass finds the flanking arc whose circle passes closest to BOTH line
 * endpoints.  If that fit is tight (max radial error ≤ absorbTol) the line
 * genuinely lies on the arc, so we extend the arc over the line's span and drop
 * the line.  The two flanking segments then meet directly and the subsequent
 * snapAdjacentJunctions pass smooths the joint to G1 continuity.
 *
 * The absorbTol gate protects genuine straight tangent runs: a real straight
 * bit long enough to matter would have an endpoint measurably off the arc
 * circle, so it is left intact.
 */
export function absorbShortArcLines(
  recon:     ReconEntry[],
  maxLen:    number,
  absorbTol: number = 2.0,
): void {
  // Radial error of a point relative to an arc's circle.
  const radialErr = (p: ArcPrimitive, x: number, y: number) =>
    Math.abs(Math.hypot(x - p.cx, y - p.cy) - p.r);

  let changed = true;
  while (changed) {
    changed = false;
    for (let i = 0; i < recon.length; i++) {
      const seg = recon[i];
      if (seg.prim.type !== "line") continue;
      const line = seg.prim;
      const len  = Math.hypot(line.x2 - line.x1, line.y2 - line.y1);
      if (len >= maxLen) continue;

      const prev = i > 0 ? recon[i - 1] : null;
      const next = i + 1 < recon.length ? recon[i + 1] : null;
      const prevArc = prev && prev.prim.type === "arc" ? prev.prim : null;
      const nextArc = next && next.prim.type === "arc" ? next.prim : null;
      if (!prevArc && !nextArc) continue;

      // Fit error of each candidate arc against both line endpoints.
      const prevErr = prevArc
        ? Math.max(radialErr(prevArc, line.x1, line.y1),
                   radialErr(prevArc, line.x2, line.y2))
        : Infinity;
      const nextErr = nextArc
        ? Math.max(radialErr(nextArc, line.x1, line.y1),
                   radialErr(nextArc, line.x2, line.y2))
        : Infinity;

      // Try the better-fitting neighbour first, but fall back to the other one
      // if it cannot take the span.  Extending an arc adds chord/r radians to
      // its sweep, and snapArcAngle refuses to exceed MAX_SWEEP — so an arc
      // that is already most of a circle will reject the absorb even though the
      // chord plainly belongs to the curve.  Small slots hit this constantly
      // (a 188° arc + an 18px chord + a 95° arc): preferring the 188° arc and
      // giving up on failure left a flat spot in what is nearly a circle.
      const candidates: Array<"prev" | "next"> = nextErr < prevErr
        ? ["next", "prev"]
        : ["prev", "next"];

      let absorbed = false;
      for (const which of candidates) {
        const arc = which === "next" ? nextArc : prevArc;
        const err = which === "next" ? nextErr : prevErr;
        if (!arc || err > absorbTol) continue;  // genuine straight run for this side
        if (which === "next") {
          // Arc follows the line: extend its start back over the line's start.
          if (!snapArcAngle(arc, Math.atan2(line.y1 - arc.cy, line.x1 - arc.cx), true)) continue;
          next!.wi = Math.min(next!.wi, seg.wi);
        } else {
          // Arc precedes the line: extend its end forward over the line's end.
          if (!snapArcAngle(arc, Math.atan2(line.y2 - arc.cy, line.x2 - arc.cx), false)) continue;
          prev!.wj = Math.max(prev!.wj, seg.wj);
        }
        absorbed = true;
        break;
      }
      if (!absorbed) continue;

      recon.splice(i, 1);
      changed = true;
      break;
    }
  }
}

// ---------------------------------------------------------------------------
// Final C0 weld
// ---------------------------------------------------------------------------

/**
 * Guarantee that consecutive segments in a chain share an endpoint exactly.
 *
 * `snapAdjacentJunctions` establishes shared junctions, but several passes run after it
 * (`snapAxisAligned`, `stitchJunctions`, the final `mergeCollinearSegments`,
 * the degenerate-stub `projectExtend`) and each can move an endpoint again.
 * `stitchJunctions` only repairs nearly-collinear line→line pairs, so
 * everything else — arc→arc especially — can reach the exporter with a
 * sub-pixel gap.  A gap is cosmetically invisible but is exactly what CAM
 * software treats as an open contour, refusing a profile toolpath or inserting
 * a retract, so it must be zero rather than small.
 *
 * Welding is deliberately minimal and never invents geometry:
 *   • line↔line  — both endpoints move to the midpoint.
 *   • line↔arc   — the junction is placed ON the arc's circle (nearest point to
 *                  the midpoint) and the line endpoint follows it, so the arc
 *                  keeps its fitted centre and radius.
 *   • arc↔arc    — a true circle-circle intersection near the joint is adopted
 *                  when one exists (exact for both arcs); otherwise the first
 *                  arc's endpoint wins and the second arc's radius is nudged by
 *                  the sub-pixel amount needed to reach it.
 *
 * Gaps larger than `maxGap` are left alone: those indicate a structural problem
 * (a dropped segment, a bad merge) that silently stitching would only disguise.
 * Runs twice, since an arc radius nudge can perturb that arc's far end.
 */
/**
 * Where the infinite line through (px,py) with unit direction (ux,uy) crosses
 * the circle (ccx,ccy,r), taking whichever crossing is nearer (rx,ry).
 */
function lineMeetsCircle(
  px: number, py: number, ux: number, uy: number,
  ccx: number, ccy: number, r: number, rx: number, ry: number,
): { x: number; y: number } | null {
  const fx = px - ccx, fy = py - ccy;
  const b = 2 * (fx * ux + fy * uy);
  const c = fx * fx + fy * fy - r * r;
  const disc = b * b - 4 * c;
  if (disc < 0) return null;
  const sq = Math.sqrt(disc);
  const cands = [(-b - sq) / 2, (-b + sq) / 2]
    .map((t) => ({ x: px + t * ux, y: py + t * uy }));
  return Math.hypot(cands[0].x - rx, cands[0].y - ry) <=
         Math.hypot(cands[1].x - rx, cands[1].y - ry) ? cands[0] : cands[1];
}

/**
 * Replace a false concavity between two same-handed arcs with a short line.
 *
 * Where the DP splits one smooth convex curve into two arcs, each arc can sit
 * within half a pixel of the ink over its own span and still meet its
 * neighbour at an angle — nothing in the objective ever required the tangents
 * to agree. On the page-2 oblong hole two arcs of r=24.1 and r=23.4 met at 22°,
 * which reads as a pinched point in an outline that plainly has no corner.
 *
 * The signal that distinguishes it from a real corner is the one a person uses
 * looking at it: **the run is convex, and the cusp is a small concavity in it.**
 * Both arcs curve the same way, so their shared tangent should keep turning
 * that way through the joint; a joint that turns the OTHER way is not geometry,
 * it is the seam between two independent fits. That test needs no threshold on
 * the angle — which matters, because the 22° cusp here is sharper than plenty
 * of genuine corners are shallow, so no angle threshold can separate them.
 *
 * The repair is the obvious one: cut the notch off with a straight segment.
 * A line is fitted to the pixel centroids spanning the joint, each arc is
 * trimmed back to where that line crosses its circle, and the line is spliced
 * in between. The arcs keep their own centres and radii — only their end
 * angles move — so nothing slides off the ink.
 *
 * It is speculative: the result is scored against the same pixel centroids over
 * the same span and rolled back unless it is at least as well centred as the
 * cusp it replaced. Trading a visible kink for a fit that wanders is not a win.
 */
function relaxCuspsToLine(
  recon:  ReconEntry[],
  pverts: Array<Array<{ x: number; y: number }>>,
  dv:     Array<{ x: number; y: number }>,
): void {
  const N = dv.length;
  if (recon.length < 2 || N < 8) return;

  const cx = new Float64Array(N), cy = new Float64Array(N);
  for (let vi = 0; vi < N; vi++) {
    const pxs = pverts[vi];
    if (pxs && pxs.length >= 2) {
      let sx = 0, sy = 0;
      for (const p of pxs) { sx += p.x; sy += p.y; }
      cx[vi] = sx / pxs.length; cy[vi] = sy / pxs.length;
    } else { cx[vi] = dv[vi].x; cy[vi] = dv[vi].y; }
  }

  /** Perpendicular / radial deviation of centroid `vi` from a primitive. */
  const devAt = (p: LinePrimitive | ArcPrimitive, vi: number): number => {
    if (p.type === "arc") return Math.abs(Math.hypot(cx[vi] - p.cx, cy[vi] - p.cy) - p.r);
    const dx = p.x2 - p.x1, dy = p.y2 - p.y1;
    const L2 = dx * dx + dy * dy;
    if (L2 < 1e-18) return Math.hypot(cx[vi] - p.x1, cy[vi] - p.y1);
    // Clamped to the SEGMENT, not measured against its infinite extension.
    // A bridge shorter than the span it is credited with used to score as
    // though it covered the whole of it, because the vertices past its ends
    // sit near the extension and so cost nothing — which is exactly the
    // mistake this pass was making, and the reason its own roll-back guard
    // could not see it.
    const t = Math.max(0, Math.min(1, ((cx[vi] - p.x1) * dx + (cy[vi] - p.y1) * dy) / L2));
    return Math.hypot(cx[vi] - (p.x1 + t * dx), cy[vi] - (p.y1 + t * dy));
  };
  /** Worst and mean deviation of a set of [primitive, vertex range] pieces. */
  const score = (pieces: Array<{ p: LinePrimitive | ArcPrimitive; a: number; b: number }>) => {
    let worst = 0, sum = 0, n = 0;
    for (const { p, a, b } of pieces) {
      for (let vi = Math.max(0, a); vi <= Math.min(N - 1, b); vi++) {
        const d = devAt(p, vi);
        worst = Math.max(worst, d); sum += d; n++;
      }
    }
    return { worst, mean: n ? sum / n : Infinity };
  };

  for (let i = 0; i + 1 < recon.length; i++) {
    const A = recon[i], B = recon[i + 1];
    const pa = A.prim, pb = B.prim;
    if (pa.type !== "arc" || pb.type !== "arc") continue;
    if (pa.ccw !== pb.ccw) continue;                 // an inflection, not a cusp

    const t0 = primitiveTangentAt(pa, false);
    const t1 = primitiveTangentAt(pb, true);
    const cross = t0.tx * t1.ty - t0.ty * t1.tx;
    const dot   = t0.tx * t1.tx + t0.ty * t1.ty;
    const turn  = Math.atan2(cross, dot);            // signed, traversal order
    if (Math.abs(turn) < 4 * Math.PI / 180) continue;  // nothing worth cutting

    // Both arcs bend the same way; a joint bending the other way is the seam.
    const bend = pa.ccw ? 1 : -1;
    if (Math.sign(turn) === bend) continue;

    const k = A.wj;
    const before = score([{ p: pa, a: A.wi, b: A.wj }, { p: pb, a: B.wi, b: B.wj }]);
    const savedA = { s: pa.startAngle, e: pa.endAngle, w: pa.sweep };
    const savedB = { s: pb.startAngle, e: pb.endAngle, w: pb.sweep };

    // How far the straight section extends either side of the joint is not
    // known in advance — on the oblong hole the flat flank is 12 px between
    // r≈23 caps, and a bridge sized for a longer flat would reach into them and
    // miss the ink by 1.65 px.  So try the longest bridge first and shorten it
    // until one is at least as well centred as the cusp it replaces.
    const mMax = Math.min(8, (A.wj - A.wi) >> 1, (B.wj - B.wi) >> 1);
    let placed = false;
    for (let m = mMax; m >= 3 && !placed; m--) {
      const lo = k - m, hi = k + m;
      if (lo < 0 || hi >= N) continue;

      // PCA line through the centroids spanning the joint.
      let sx = 0, sy = 0, n = 0;
      for (let vi = lo; vi <= hi; vi++) { sx += cx[vi]; sy += cy[vi]; n++; }
      const mx = sx / n, my = sy / n;
      let sxx = 0, sxy = 0, syy = 0;
      for (let vi = lo; vi <= hi; vi++) {
        const ex = cx[vi] - mx, ey = cy[vi] - my;
        sxx += ex * ex; sxy += ex * ey; syy += ey * ey;
      }
      const theta = 0.5 * Math.atan2(2 * sxy, sxx - syy);
      const ux = Math.cos(theta), uy = Math.sin(theta);

      // Trim each arc to where the line crosses its circle, nearest that arc's
      // own side of the joint.
      const J0 = lineMeetsCircle(mx, my, ux, uy, pa.cx, pa.cy, pa.r, cx[lo], cy[lo]);
      const J1 = lineMeetsCircle(mx, my, ux, uy, pb.cx, pb.cy, pb.r, cx[hi], cy[hi]);
      if (!J0 || !J1) continue;
      if (Math.hypot(J1.x - J0.x, J1.y - J0.y) < 1e-6) continue;

      if (!snapArcAngle(pa, Math.atan2(J0.y - pa.cy, J0.x - pa.cx), false)) continue;
      if (!snapArcAngle(pb, Math.atan2(J1.y - pb.cy, J1.x - pb.cx), true)) {
        pa.startAngle = savedA.s; pa.endAngle = savedA.e; pa.sweep = savedA.w;
        continue;
      }

      const bridge = makeLinePrimitive(J0.x, J0.y, J1.x, J1.y);

      // Credit the bridge with the vertices it actually reaches, not the
      // window [lo, hi] that was picked before its endpoints were known.
      //
      // J0 and J1 land wherever the PCA line crosses the two circles, which is
      // generally not at those vertices: on a real sheet an 18 px bridge was
      // credited with a 32 px run, leaving its last vertex 13 px beyond its own
      // end.  Nothing about the geometry was wrong — the bridge sits on the ink
      // — but `refitPoorSpans` reads these indices, saw a 13 px defect that did
      // not exist, and re-fitted the region, undoing correct work.
      //
      // The correction has to happen HERE rather than after the score, because
      // the score has to weigh each primitive against the vertices it will be
      // held to; scoring the bridge against [lo, hi] and then handing it a
      // different range is how the two drifted apart in the first place.
      const nearestVert = (px: number, py: number) => {
        let best = lo, bd = Infinity;
        for (let vi = Math.max(0, A.wi); vi <= Math.min(N - 1, B.wj); vi++) {
          const d = (cx[vi] - px) ** 2 + (cy[vi] - py) ** 2;
          if (d < bd) { bd = d; best = vi; }
        }
        return best;
      };
      const bLo = nearestVert(J0.x, J0.y);
      const bHi = nearestVert(J1.x, J1.y);
      if (bHi <= bLo) {
        pa.startAngle = savedA.s; pa.endAngle = savedA.e; pa.sweep = savedA.w;
        pb.startAngle = savedB.s; pb.endAngle = savedB.e; pb.sweep = savedB.w;
        continue;
      }

      const after = score([
        { p: pa, a: A.wi, b: bLo },
        { p: bridge, a: bLo, b: bHi },
        { p: pb, a: bHi, b: B.wj },
      ]);

      if (after.worst > Math.max(before.worst, 0.6) || after.mean > before.mean + 0.1) {
        pa.startAngle = savedA.s; pa.endAngle = savedA.e; pa.sweep = savedA.w;
        pb.startAngle = savedB.s; pb.endAngle = savedB.e; pb.sweep = savedB.w;
        continue;
      }

      A.wj = bLo;
      B.wi = bHi;
      recon.splice(i + 1, 0, { wi: bLo, wj: bHi, ce: after.mean, prim: bridge });
      placed = true;
    }
    if (placed) i++;   // skip past the segment just inserted
  }
}

export function weldChainJunctions(
  recon:    ReconEntry[],
  isClosed: boolean,
  maxGap:   number,
): void {
  if (recon.length < 2) return;

  /** Nearest point on an arc's circle to (mx,my). */
  const onCircle = (a: ArcPrimitive, mx: number, my: number) => {
    const dx = mx - a.cx, dy = my - a.cy;
    const d  = Math.hypot(dx, dy);
    if (d < 1e-9) return null;
    return { x: a.cx + a.r * dx / d, y: a.cy + a.r * dy / d };
  };

  const weldPair = (sa: ReconEntry, sb: ReconEntry): void => {
    const pa = sa.prim, pb = sb.prim;
    const E0 = primitiveEndPoint(pa, false);
    const E1 = primitiveEndPoint(pb, true);
    const gap = Math.hypot(E1.x - E0.x, E1.y - E0.y);
    if (gap <= 1e-9 || gap > maxGap) return;

    const mx = (E0.x + E1.x) * 0.5, my = (E0.y + E1.y) * 0.5;

    if (pa.type === "line" && pb.type === "line") {
      // At a real corner the two lines' intersection IS the corner; welding to
      // the midpoint instead would blunt it by up to half the gap.  Use the
      // intersection when the lines meet at a meaningful angle and it sits near
      // the joint, else fall back to the midpoint (near-parallel intersections
      // are numerically wild and can be far away).
      const dx0 = pa.x2 - pa.x1, dy0 = pa.y2 - pa.y1;
      const dx1 = pb.x2 - pb.x1, dy1 = pb.y2 - pb.y1;
      const l0 = Math.hypot(dx0, dy0), l1 = Math.hypot(dx1, dy1);
      let Jx = mx, Jy = my;
      let haveIx = false;
      if (l0 > 1e-9 && l1 > 1e-9 && Math.abs(dx0 * dy1 - dy0 * dx1) >= 0.035 * l0 * l1) {
        const ix = lineLineIntersect(pa.x1, pa.y1, dx0, dy0, pb.x1, pb.y1, dx1, dy1);
        if (ix && Math.hypot(ix.x - mx, ix.y - my) <= gap * 2 + 1) {
          Jx = ix.x; Jy = ix.y; haveIx = true;
        }
      }
      // The intersection sits on both lines, so it never rotates either.  The
      // midpoint fallback does, so a frozen side keeps the joint on its own axis
      // and lets the other line turn instead.
      if (!haveIx) {
        if (sa.frozen && !sb.frozen && l0 > 1e-9) {
          const t = ((mx - pa.x1) * dx0 + (my - pa.y1) * dy0) / (l0 * l0);
          Jx = pa.x1 + t * dx0; Jy = pa.y1 + t * dy0;
        } else if (sb.frozen && !sa.frozen && l1 > 1e-9) {
          const t = ((mx - pb.x1) * dx1 + (my - pb.y1) * dy1) / (l1 * l1);
          Jx = pb.x1 + t * dx1; Jy = pb.y1 + t * dy1;
        }
      }
      pa.x2 = Jx; pa.y2 = Jy;
      pb.x1 = Jx; pb.y1 = Jy;
      return;
    }

    // line ↔ arc.  Move the ARC to the line, not the line to the arc.
    //
    // The obvious resolution — put the joint on the arc's circle nearest the
    // midpoint and drag the line's endpoint there — moves that endpoint OFF the
    // line's own axis and so TILTS it.  At a smooth joint the arc is nearly
    // tangent to the line, so the offset is almost entirely perpendicular: a
    // 1.2 px gap tilted a 116 px horizontal by 1.16 px, which is how segments
    // that had just been straightened onto their ink arrived at the output a
    // degree out of true.  (Intersecting the line's own axis with the circle
    // does not rescue it either: tangent-ish and offset outward, the axis
    // usually misses the circle entirely.)
    //
    // A line's direction is a PCA fit over its whole span and is the more
    // trustworthy of the two, so the line only ever slides ALONG itself, and
    // the arc is re-anchored through that point with its far end pinned —
    // bounded by the gap, tapering to zero, and unable to propagate.
    // Only lines whose direction is *known* get this treatment.  Letting every
    // line push its arc around instead costs more than it buys: page-wide it
    // moved black p90 from 0.25 px to 0.50 px, because the arc then absorbs the
    // whole gap near the joint.
    //
    // Exactly axis-aligned was the original test, and it is a good one — such a
    // line's direction was not merely fitted but established deliberately
    // against flat ink by `recentreAxisAligned`.  It is also brittle in a way
    // that was measured: a line knocked 0.19 degrees off level by an upstream
    // stitch stops being axis-aligned, loses the protection, and is then tilted
    // a further 0.73 degrees here, by an arc it is very nearly tangent to.  Two
    // small concessions compound into 1.9 px of drift over 108 px.
    //
    // A frozen segment qualifies for the same reason and does not depend on
    // surviving intact to get here: the flag records that this line's direction
    // was trusted, and it is still there after something has nudged it.
    const axisLocked = (s: ReconEntry, l: LinePrimitive) =>
      s.frozen === true ||
      Math.abs(l.y2 - l.y1) <= 1e-6 || Math.abs(l.x2 - l.x1) <= 1e-6;
    const projectOnto = (s: ReconEntry, l: LinePrimitive) => {
      if (!axisLocked(s, l)) return null;
      const ux = l.x2 - l.x1, uy = l.y2 - l.y1;
      const ll = Math.hypot(ux, uy);
      if (ll < 1e-9) return null;
      const t = ((mx - l.x1) * ux + (my - l.y1) * uy) / (ll * ll);
      return { x: l.x1 + t * ux, y: l.y1 + t * uy };
    };

    // Best of all: the point where the line's own axis crosses the arc's
    // circle.  It lies on BOTH, so the line only slides along itself and the
    // arc only changes an end angle — neither is distorted at all.
    // `snapAdjacentJunctions` has always tried this first; the weld did not,
    // and went straight to bending the arc.  Measured: a frozen 439 px wall
    // reopened its joint by half a pixel when a later pass slid it onto its
    // stroke, and the weld paid for that out of the arc — 10 px of radius on an
    // r=483 fillet, which put it 0.59 px off its ink along its whole span.
    const meetOnCircle = (
      l: LinePrimitive, a: ArcPrimitive, lineEndMoves: boolean,
    ): boolean => {
      const j = lineArcJunction(l.x1, l.y1, l.x2, l.y2, a.cx, a.cy, a.r,
        lineEndMoves ? 1 : 0, 2);
      if (!j || Math.hypot(j.x - mx, j.y - my) > gap * 2 + 1) return false;
      // The arc's START moves when the line's END does — they are the two
      // sides of the same joint.
      if (!snapArcAngle(a, Math.atan2(j.y - a.cy, j.x - a.cx), lineEndMoves)) return false;
      if (lineEndMoves) { l.x2 = j.x; l.y2 = j.y; } else { l.x1 = j.x; l.y1 = j.y; }
      return true;
    };

    if (pa.type === "line" && pb.type === "arc") {
      if (meetOnCircle(pa, pb, /*lineEndMoves=*/true)) return;
      const J = projectOnto(sa, pa);
      if (J && reanchorArcThrough(pb, J.x, J.y, /*atStart=*/true)) {
        pa.x2 = J.x; pa.y2 = J.y;
        return;
      }
      const K = onCircle(pb, mx, my);
      if (!K) return;
      if (!snapArcAngle(pb, Math.atan2(K.y - pb.cy, K.x - pb.cx), true)) return;
      pa.x2 = K.x; pa.y2 = K.y;
      return;
    }

    if (pa.type === "arc" && pb.type === "line") {
      if (meetOnCircle(pb, pa, /*lineEndMoves=*/false)) return;
      const J = projectOnto(sb, pb);
      if (J && reanchorArcThrough(pa, J.x, J.y, /*atStart=*/false)) {
        pb.x1 = J.x; pb.y1 = J.y;
        return;
      }
      const K = onCircle(pa, mx, my);
      if (!K) return;
      if (!snapArcAngle(pa, Math.atan2(K.y - pa.cy, K.x - pa.cx), false)) return;
      pb.x1 = K.x; pb.y1 = K.y;
      return;
    }

    // arc ↔ arc — a shared point on both circles when one exists, else each arc
    // re-anchored about its own far end so the correction cannot travel down
    // the chain.  See `joinArcsExactly`.
    const a0 = pa as ArcPrimitive, a1 = pb as ArcPrimitive;
    if (joinArcsExactly(a0, a1)) return;

    // Last resort: hold a0's endpoint and pull a1 onto it by changing its
    // radius.  This displaces the whole of a1, far end included, so it is only
    // acceptable because everything above has already been refused.
    const newR = Math.hypot(E0.x - a1.cx, E0.y - a1.cy);
    if (newR < 1) return;
    const prevR = a1.r;
    a1.r = newR;
    if (!snapArcAngle(a1, Math.atan2(E0.y - a1.cy, E0.x - a1.cx), true)) a1.r = prevR;
  };

  for (let pass = 0; pass < 2; pass++) {
    for (let i = 0; i + 1 < recon.length; i++) weldPair(recon[i], recon[i + 1]);
    if (isClosed) weldPair(recon[recon.length - 1], recon[0]);
  }
}

/**
 * Run a free chain end on to the geometry it plainly terminates against.
 *
 * A red centreline drawn up to a black outline stops where its own *ink* stops,
 * which is at the edge of the black stroke — so its fitted endpoint lands about
 * a stroke half-width short of the black centreline. One real sheet had 89 such
 * ends within 12 px of another layer, bunched at 3–5 px, and they read as
 * "not quite touching".
 *
 * The extension is deliberately timid, because a centreline that genuinely
 * stops short must not be dragged anywhere:
 *   • it only ever moves the endpoint FORWARD along the segment's own tangent,
 *     so no direction and no interior geometry changes;
 *   • the target must be crossed at a real angle, not grazed;
 *   • the target must belong to a different ink, since same-layer joins are
 *     `snapJunctionEndpoints`' and `undashPaths`' business and have already run;
 *   • an end that another chain already shares (a welded junction) is left
 *     alone.
 *
 * The audit's centering will get slightly worse where this fires, and that is
 * correct rather than a regression: the last pixel or two of the extension is
 * deliberately past the end of its own ink.
 */
export function extendEndsToOtherInk(
  keptByChain: Array<ReconEntry[] | null>,
  chainInfos:  ChainInfo[],
  maxExtend:   number,
): void {
  // Targets: every segment, tessellated to short chords, tagged by layer.
  type Chord = { x1: number; y1: number; x2: number; y2: number; layer: number };
  const chords: Chord[] = [];
  for (let ci = 0; ci < keptByChain.length; ci++) {
    const kept = keptByChain[ci];
    if (!kept) continue;
    const layer = chainInfos[ci]?.layer ?? 0;
    for (const s of kept) {
      const p = s.prim;
      if (p.type === "line") {
        chords.push({ x1: p.x1, y1: p.y1, x2: p.x2, y2: p.y2, layer });
      } else {
        const n = Math.max(2, Math.ceil(p.r * p.sweep / 4));
        const d = (p.ccw ? p.sweep : -p.sweep) / n;
        let px = p.cx + p.r * Math.cos(p.startAngle);
        let py = p.cy + p.r * Math.sin(p.startAngle);
        for (let i = 1; i <= n; i++) {
          const t = p.startAngle + d * i;
          const qx = p.cx + p.r * Math.cos(t), qy = p.cy + p.r * Math.sin(t);
          chords.push({ x1: px, y1: py, x2: qx, y2: qy, layer });
          px = qx; py = qy;
        }
      }
    }
  }

  const MIN_SIN = 0.34;   // ~20°: below this the ray grazes rather than crosses

  // How many chain ends land on each point: >1 means a welded junction.
  const endCount = new Map<string, number>();
  for (let ci = 0; ci < keptByChain.length; ci++) {
    const kept = keptByChain[ci];
    const info = chainInfos[ci];
    if (!kept || kept.length === 0 || !info || info.isClosed) continue;
    for (const atStart of [true, false]) {
      const q = primitiveEndPoint((atStart ? kept[0] : kept[kept.length - 1]).prim, atStart);
      const k = `${q.x.toFixed(4)},${q.y.toFixed(4)}`;
      endCount.set(k, (endCount.get(k) ?? 0) + 1);
    }
  }

  for (let ci = 0; ci < keptByChain.length; ci++) {
    const kept = keptByChain[ci];
    const info = chainInfos[ci];
    if (!kept || kept.length === 0 || !info || info.isClosed) continue;

    for (const atStart of [true, false]) {
      const seg = atStart ? kept[0] : kept[kept.length - 1];
      const P = primitiveEndPoint(seg.prim, atStart);
      const T = primitiveTangentAt(seg.prim, atStart);
      // Outward direction: away from the chain's interior.
      const ux = atStart ? -T.tx : T.tx;
      const uy = atStart ? -T.ty : T.ty;

      // Already part of a welded junction? Then it is where it belongs.
      if ((endCount.get(`${P.x.toFixed(4)},${P.y.toFixed(4)}`) ?? 0) > 1) continue;

      let bestT = Infinity, bx = 0, by = 0;
      for (const c of chords) {
        if (c.layer === info.layer) continue;
        const rx = c.x2 - c.x1, ry = c.y2 - c.y1;
        const den = ux * ry - uy * rx;
        if (Math.abs(den) < 1e-12) continue;
        const t = ((c.x1 - P.x) * ry - (c.y1 - P.y) * rx) / den;
        if (!(t > 1e-6) || t > maxExtend || t >= bestT) continue;
        const s2 = ((c.x1 - P.x) * uy - (c.y1 - P.y) * ux) / den;
        if (s2 < 0 || s2 > 1) continue;
        const rl = Math.hypot(rx, ry);
        if (rl < 1e-9 || Math.abs(den) / rl < MIN_SIN) continue;   // grazing
        bestT = t; bx = P.x + t * ux; by = P.y + t * uy;
      }
      if (!Number.isFinite(bestT)) continue;

      const p = seg.prim;
      if (p.type === "line") {
        if (atStart) { p.x1 = bx; p.y1 = by; } else { p.x2 = bx; p.y2 = by; }
      } else {
        // An arc cannot be extended along a straight tangent; leave it.
        continue;
      }
    }
  }
}

/**
 * Cross-chain C0 weld — `weldChainJunctions`, one level up.
 *
 * `weldChainJunctions` guarantees that consecutive segments *within* a chain
 * share an endpoint exactly. Where three chains meet at a Y or a T, the closure
 * is between different chains and nothing was enforcing it at the end: it was
 * left to `snapJunctionEndpoints` and `snapEndpointPairs`, which run well
 * before the last several passes and can be undone by any of them (a long
 * segment re-centred on the skeleton drags its terminal; a dropped degenerate
 * stub gets absorbed by projecting onto a neighbour's axis). A real sheet
 * shipped a 3.8 px hole at a sharp inward Y and a 0.139 px one at a bridged
 * dash gap for exactly that reason, and the in-chain audit could not see
 * either.
 *
 * So the invariant is enforced where it can no longer be broken: last, over the
 * segments that will actually be emitted. Free chain ends that sit within
 * `maxGap` of each other on the same layer are one junction and are moved onto
 * their common centroid — lines by setting the endpoint, arcs through
 * `reanchorArcThrough` so the arc's far end (and hence its in-chain joint)
 * does not move.
 *
 * Clusters wider than `maxGap` are left alone, on the same reasoning as the
 * in-chain weld: that is a dropped segment or a real gap, and silently
 * stitching it would hide a defect rather than fix one.
 */
/**
 * Replace a ring of co-circular arcs with the circle they are describing.
 *
 * A dashed circle reaches the fitter as a handful of arcs that all sit on the
 * same circle, because that is what they are.  Bridging every dash gap would
 * turn them back into one closed ring and the whole-ring circle fit would take
 * it from there, but that asks every gap in the ring to clear the bridging
 * test, and one marginal gap out of six leaves the whole thing as loose arcs.
 * Recognising the circle from the arcs themselves does not care how the ring
 * was broken up.
 *
 * Only isolated rings are consolidated.  If any arc in the group has an
 * endpoint shared with a segment outside it — a leader line touching the
 * circle, say — the group is left alone, because collapsing it to a circle
 * would strand that connection and open a junction that was watertight.
 */
/**
 * Drop a chain that is one short primitive with nothing attached to either end.
 *
 * At 200 dpi a 4 px stroke is 0.02 inch — below anything that means something
 * on a plan, and the same reasoning (and the same threshold) as spur removal,
 * which cannot see these because they are not spurs: an isolated speck has no
 * junction to dangle from.  A handful of them survive palette cleanup on a
 * busy sheet and each one is emitted as a stray mark with two free ends, which
 * the watertightness audit then reports as an open junction.
 *
 * Only wholly unattached chains are dropped.  A short segment that touches
 * anything is carrying a connection and stays.
 */
export function dropIsolatedSpecks(
  keptByChain: Array<ReconEntry[] | null>,
  minLengthPx: number,
): number {
  const TOUCH = 0.5;
  let dropped = 0;

  for (let ci = 0; ci < keptByChain.length; ci++) {
    const kept = keptByChain[ci];
    if (!kept || kept.length !== 1) continue;
    const p = kept[0].prim;
    if (p.type !== "line") continue;
    if (Math.hypot(p.x2 - p.x1, p.y2 - p.y1) >= minLengthPx) continue;

    let attached = false;
    for (const atStart of [true, false]) {
      const e = primitiveEndPoint(p, atStart);
      for (let cj = 0; cj < keptByChain.length && !attached; cj++) {
        if (cj === ci) continue;
        const other = keptByChain[cj];
        if (!other) continue;
        for (const o of other) {
          for (const os of [true, false]) {
            const q = primitiveEndPoint(o.prim, os);
            if (Math.hypot(q.x - e.x, q.y - e.y) <= TOUCH) { attached = true; break; }
          }
          if (attached) break;
        }
      }
    }
    if (attached) continue;

    keptByChain[ci] = [];
    dropped++;
  }
  return dropped;
}

export function consolidateCircles(
  keptByChain: Array<ReconEntry[] | null>,
  chainInfos:  ChainInfo[],
): Array<{ layer: number; chainId: number; primitive: CirclePrimitive }> {
  const out: Array<{ layer: number; chainId: number; primitive: CirclePrimitive }> = [];
  /** Centres this close and radii this close are the same circle. */
  const CENTRE_TOL = 2.0;
  const RADIUS_TOL = 2.0;
  /**
   * A dashed circle is mostly gaps by design, so "how much is covered" is a
   * weak test on its own — a 274-degree ring of four dashes is a circle and a
   * single 180-degree fillet is not.  What separates them is the SIZE of the
   * largest single gap: dashes leave several small ones, a partial arc leaves
   * one big one.
   */
  const MIN_COVER = 0.60;
  const MAX_GAP_ANGLE = 45 * Math.PI / 180;
  /** Endpoints this close are the same point. */
  const TOUCH = 0.5;

  interface Piece { ci: number; si: number; arc: ArcPrimitive }
  const pieces: Piece[] = [];
  for (let ci = 0; ci < keptByChain.length; ci++) {
    const kept = keptByChain[ci];
    if (!kept) continue;
    for (let si = 0; si < kept.length; si++) {
      if (kept[si].prim.type === "arc") pieces.push({ ci, si, arc: kept[si].prim as ArcPrimitive });
    }
  }
  if (pieces.length < 2) return out;

  /**
   * Short dashes on a small circle get fitted as chords, not arcs — the bow
   * over a few pixels is under the arc-acceptance gate.  They belong to the
   * ring as much as the arcs do, and if they are not claimed with it they
   * fail the attachment test below and block the whole consolidation.
   */
  const chordsOn = (cx: number, cy: number, r: number, layer: number) => {
    const found: Array<{ ci: number; si: number; a0: number; a1: number }> = [];
    for (let ci = 0; ci < keptByChain.length; ci++) {
      const kept = keptByChain[ci];
      if (!kept || chainInfos[ci].layer !== layer) continue;
      for (let si = 0; si < kept.length; si++) {
        const p = kept[si].prim;
        if (p.type !== "line") continue;
        const len = Math.hypot(p.x2 - p.x1, p.y2 - p.y1);
        if (len > r) continue;                       // a chord this long is not a dash
        const d1 = Math.hypot(p.x1 - cx, p.y1 - cy);
        const d2 = Math.hypot(p.x2 - cx, p.y2 - cy);
        if (Math.abs(d1 - r) > RADIUS_TOL || Math.abs(d2 - r) > RADIUS_TOL) continue;
        const t1 = Math.atan2(p.y1 - cy, p.x1 - cx), t2 = Math.atan2(p.y2 - cy, p.x2 - cx);
        found.push({ ci, si, a0: t1, a1: t2 });
      }
    }
    return found;
  };

  const used = new Set<number>();
  /** "ci:si" of arcs already claimed by a circle — invisible to later scans. */
  const removed = new Set<string>();
  for (let i = 0; i < pieces.length; i++) {
    if (used.has(i)) continue;
    const seed = pieces[i].arc;
    const layer = chainInfos[pieces[i].ci].layer;
    const group = [i];
    for (let j = i + 1; j < pieces.length; j++) {
      if (used.has(j)) continue;
      if (chainInfos[pieces[j].ci].layer !== layer) continue;
      const a = pieces[j].arc;
      if (Math.hypot(a.cx - seed.cx, a.cy - seed.cy) > CENTRE_TOL) continue;
      if (Math.abs(a.r - seed.r) > RADIUS_TOL) continue;
      group.push(j);
    }
    if (group.length < 2) continue;

    // Angular coverage: union of each arc's span, as intervals on [0, 2pi).
    const spans: Array<[number, number]> = [];
    for (const gi of group) {
      const a = pieces[gi].arc;
      const start = a.ccw ? a.startAngle : a.startAngle - a.sweep;
      let lo = ((start % (2 * Math.PI)) + 2 * Math.PI) % (2 * Math.PI);
      spans.push([lo, lo + Math.min(a.sweep, 2 * Math.PI)]);
    }
    const chords = chordsOn(seed.cx, seed.cy, seed.r, layer);
    for (const c of chords) {
      let lo = ((Math.min(c.a0, c.a1) % (2 * Math.PI)) + 2 * Math.PI) % (2 * Math.PI);
      let d = Math.abs(c.a1 - c.a0);
      if (d > Math.PI) d = 2 * Math.PI - d;
      spans.push([lo, lo + d]);
    }
    spans.sort((p, q) => p[0] - q[0]);

    // Merge the spans into disjoint covered intervals on [0, 2pi), then read
    // both the total coverage and the largest gap off the result.
    const merged: Array<[number, number]> = [];
    for (const [lo, hi] of spans) {
      const last = merged[merged.length - 1];
      if (last && lo <= last[1]) last[1] = Math.max(last[1], hi);
      else merged.push([lo, Math.min(hi, lo + 2 * Math.PI)]);
    }
    // A span may wrap past 2pi; fold the overhang back to the front.
    for (const m of merged) {
      if (m[1] > 2 * Math.PI) {
        const wrap: [number, number] = [0, m[1] - 2 * Math.PI];
        m[1] = 2 * Math.PI;
        merged.push(wrap);
      }
    }
    merged.sort((p, q) => p[0] - q[0]);
    const flat: Array<[number, number]> = [];
    for (const [lo, hi] of merged) {
      const last = flat[flat.length - 1];
      if (last && lo <= last[1]) last[1] = Math.max(last[1], hi);
      else flat.push([lo, hi]);
    }
    let covered = 0;
    for (const [lo, hi] of flat) covered += hi - lo;
    let maxGap = 0;
    for (let k = 0; k < flat.length; k++) {
      const next = flat[(k + 1) % flat.length];
      const gap = k + 1 < flat.length
        ? next[0] - flat[k][1]
        : (flat[0][0] + 2 * Math.PI) - flat[k][1];
      if (gap > maxGap) maxGap = gap;
    }
    if (maxGap > MAX_GAP_ANGLE) continue;
    if (covered < MIN_COVER * 2 * Math.PI) continue;

    // Reject if anything outside the group is attached to it.
    const inGroup = new Set([
      ...group.map((gi) => `${pieces[gi].ci}:${pieces[gi].si}`),
      ...chords.map((c) => `${c.ci}:${c.si}`),
    ]);
    let attached = false;
    for (const gi of group) {
      for (const atStart of [true, false]) {
        const e = primitiveEndPoint(pieces[gi].arc, atStart);
        for (let ci = 0; ci < keptByChain.length && !attached; ci++) {
          const kept = keptByChain[ci];
          if (!kept) continue;
          for (let si = 0; si < kept.length; si++) {
            if (inGroup.has(`${ci}:${si}`) || removed.has(`${ci}:${si}`)) continue;
            for (const os of [true, false]) {
              const o = primitiveEndPoint(kept[si].prim, os);
              if (Math.hypot(o.x - e.x, o.y - e.y) <= TOUCH) { attached = true; break; }
            }
            if (attached) break;
          }
        }
      }
    }
    if (attached) continue;

    // Sweep-weighted mean centre and radius, then keep one circle and drop the
    // rest of the group.
    let wsum = 0, cx = 0, cy = 0, r = 0;
    for (const gi of group) {
      const a = pieces[gi].arc, w = a.sweep;
      wsum += w; cx += a.cx * w; cy += a.cy * w; r += a.r * w;
    }
    cx /= wsum; cy /= wsum; r /= wsum;

    out.push({
      layer:     layer,
      chainId:   pieces[group[0]].ci,
      primitive: { type: "circle", cx, cy, r },
    });
    for (const gi of group) {
      const p = pieces[gi];
      removed.add(`${p.ci}:${p.si}`);
      used.add(gi);
    }
    for (const c of chords) removed.add(`${c.ci}:${c.si}`);
  }

  // Drop the consumed arcs, now that no scan depends on their indices.
  if (removed.size > 0) {
    for (let ci = 0; ci < keptByChain.length; ci++) {
      const kept = keptByChain[ci];
      if (!kept) continue;
      keptByChain[ci] = kept.filter((_, si) => !removed.has(`${ci}:${si}`));
    }
  }
  return out;
}

export function weldCrossChainJunctions(
  keptByChain: Array<ReconEntry[] | null>,
  chainInfos:  ChainInfo[],
  maxGap:      number,
): void {
  type End = {
    ci: number; atStart: boolean; prim: LinePrimitive | ArcPrimitive;
    layer: number; vi: number;
  };
  const ends: End[] = [];
  for (let ci = 0; ci < keptByChain.length; ci++) {
    const kept = keptByChain[ci];
    if (!kept || kept.length === 0) continue;
    const info = chainInfos[ci];
    if (!info || info.isClosed) continue;
    ends.push({ ci, atStart: true,  prim: kept[0].prim,               layer: info.layer, vi: info.startVi });
    ends.push({ ci, atStart: false, prim: kept[kept.length - 1].prim, layer: info.layer, vi: info.endVi });
  }

  // Two ends belong together only when the SKELETON says so — they meet at the
  // same graph vertex — or when they are already all but coincident, which is
  // the "was welded upstream, then nudged apart by a later pass" case.
  //
  // Proximity alone is not enough, and the counter-example is a narrow slot:
  // its two sides are separate strokes ~5 px apart, and their free ends sit
  // well inside any sensible gap threshold. Grouping those welds
  // the slot shut — both sides get dragged to their midpoint and the part loses
  // its cut-out. Nothing about "these two ends are near each other" implies
  // they are the same junction.
  const NEAR_COINCIDENT = 0.75;

  /**
   * ...but there IS a signal that separates the two cases, and it is not
   * distance: a corner CONVERGES and a slot does not.  At a corner broken by a
   * row of missing raster, each stroke is heading at the other, so the
   * separation lies ALONG at least one of the two outward directions.  At a
   * slot's end cap the two sides run parallel and the separation is ACROSS
   * both of them.  So proximity is allowed to group ends that converge, and
   * still refused for ends that merely sit near each other.
   */
  const CONVERGE_DOT = 0.5;
  /** Unit vector leaving the chain at this end. */
  const outwardDir = (e: End) => {
    const t = primitiveTangentAt(e.prim, e.atStart);
    return e.atStart ? { x: -t.tx, y: -t.ty } : { x: t.tx, y: t.ty };
  };
  const converges = (a: End, b: End): boolean => {
    const qa = primitiveEndPoint(a.prim, a.atStart);
    const qb = primitiveEndPoint(b.prim, b.atStart);
    const gx = qb.x - qa.x, gy = qb.y - qa.y;
    const g = Math.hypot(gx, gy);
    if (g < 1e-9) return true;
    const da = outwardDir(a), db = outwardDir(b);
    const towardB = (da.x * gx + da.y * gy) / g;
    const towardA = (db.x * -gx + db.y * -gy) / g;
    return Math.max(towardB, towardA) >= CONVERGE_DOT;
  };

  const used = new Uint8Array(ends.length);
  for (let i = 0; i < ends.length; i++) {
    if (used[i]) continue;
    const group = [i];
    used[i] = 1;
    // Transitive: a fork leaves several ends in a small cluster and they do
    // not all pair off against whichever one happened to be the seed.  Test
    // each candidate against every member found so far, and keep going until
    // nothing new joins.  A real fork left five ends spread 3.2 px apart that
    // stayed open because only the seed was consulted.
    let grew = true;
    while (grew) {
      grew = false;
      for (let j = 0; j < ends.length; j++) {
        if (used[j] || ends[j].layer !== ends[i].layer) continue;
        const qj = primitiveEndPoint(ends[j].prim, ends[j].atStart);
        for (const k of group) {
          const qk = primitiveEndPoint(ends[k].prim, ends[k].atStart);
          const d = Math.hypot(qk.x - qj.x, qk.y - qj.y);
          if (d > maxGap) continue;
          const sameVertex = ends[j].vi === ends[k].vi;
          if (!sameVertex && d > NEAR_COINCIDENT && !converges(ends[k], ends[j])) continue;
          group.push(j); used[j] = 1; grew = true;
          break;
        }
      }
    }
    if (group.length < 2) continue;

    let sx = 0, sy = 0, spread = 0;
    for (const a of group) {
      const qa = primitiveEndPoint(ends[a].prim, ends[a].atStart);
      sx += qa.x; sy += qa.y;
      for (const b of group) {
        const qb = primitiveEndPoint(ends[b].prim, ends[b].atStart);
        spread = Math.max(spread, Math.hypot(qa.x - qb.x, qa.y - qb.y));
      }
    }
    if (spread <= 1e-9 || spread > maxGap) continue;
    // Ends that sit SIDE BY SIDE rather than one after another are not a
    // junction: they are the two sides of a narrow slot at its end cap, and
    // welding them to a shared point drags 900 px of line 2.5 px sideways and
    // closes the slot. Ends that are separated ALONG their common direction —
    // an arc running into a collinear line — are a continuation and must still
    // be joined. So the test is where the separation points, not whether the
    // directions differ.
    const jx = sx / group.length, jy = sy / group.length;

    for (const k of group) {
      const e = ends[k];
      if (e.prim.type === "line") {
        if (e.atStart) { e.prim.x1 = jx; e.prim.y1 = jy; }
        else           { e.prim.x2 = jx; e.prim.y2 = jy; }
      } else {
        reanchorArcThrough(e.prim, jx, jy, e.atStart);
      }
    }
  }
}

// ---------------------------------------------------------------------------
// Axis-alignment snap
// ---------------------------------------------------------------------------

/**
 * After snapAxisAligned, consecutive line segments in a chain may have lost
 * their shared junction point: snapping averages each segment's x (or y)
 * independently, so the end of segment i and the start of segment i+1 can
 * diverge by up to 2×maxDevPx.  This helper re-stitches them by averaging
 * the two gapped endpoints and writing the result back to both primitives.
 *
 * Only nearly-collinear pairs are stitched (angle < ~20°).  Perpendicular
 * corners (rectangle turns) are left alone — snapAdjacentJunctions handles those
 * with proper line-line intersection.
 *
 * This is intentionally cheap (O(n) in the number of segments) and is called
 * after every snapAxisAligned pass to keep the chain continuous.
 */
function stitchJunctions(
  recon: Array<{ prim: LinePrimitive | ArcPrimitive; frozen?: boolean }>,
): void {
  const SIN_THRESH = 0.34;  // ~20°: below this, segments are nearly collinear
  for (let i = 0; i + 1 < recon.length; i++) {
    const p0 = recon[i].prim;
    const p1 = recon[i + 1].prim;
    if (p0.type !== "line" || p1.type !== "line") continue;
    // If the endpoints already match, skip.
    if (p0.x2 === p1.x1 && p0.y2 === p1.y1) continue;

    // Only stitch nearly-collinear pairs; perpendicular corners need
    // line-line intersection (handled by snapAdjacentJunctions), not averaging.
    const dx0 = p0.x2 - p0.x1, dy0 = p0.y2 - p0.y1;
    const dx1 = p1.x2 - p1.x1, dy1 = p1.y2 - p1.y1;
    const len0 = Math.hypot(dx0, dy0), len1 = Math.hypot(dx1, dy1);
    if (len0 < 1e-9 || len1 < 1e-9) continue;
    const sinAngle = Math.abs(dx0 * dy1 - dy0 * dx1) / (len0 * len1);
    if (sinAngle > SIN_THRESH) continue;

    // Averaging is the right answer only when the two sides are equally
    // believable.  Where exactly one is frozen it is not: closing on the frozen
    // endpoint moves the other line, which is what should happen, whereas the
    // midpoint moves BOTH, and half a pixel sideways at the end of a long line
    // is a rotation of the whole of it.  This is the pass that first knocks the
    // measured horizontal off level — 0.000 to -0.220 degrees — and it does so
    // by conceding half of a 0.9 px gap to a 2 px stub.
    //
    // Two frozen sides that do not meet want a connector rather than an
    // exemption, and until there is one they keep today's average: a joint
    // closed approximately is still watertight, and an open one never is.
    const f0 = recon[i].frozen === true, f1 = recon[i + 1].frozen === true;
    let mx: number, my: number;
    if (f0 && !f1)      { mx = p0.x2; my = p0.y2; }
    else if (f1 && !f0) { mx = p1.x1; my = p1.y1; }
    else                { mx = (p0.x2 + p1.x1) / 2; my = (p0.y2 + p1.y1) / 2; }
    p0.x2 = mx; p0.y2 = my;
    p1.x1 = mx; p1.y1 = my;
  }
}

/**
 * Snap line segments that are within `maxDevPx` pixels of horizontal or
 * vertical to exact axis alignment.  The threshold is absolute (in pixels),
 * not angular, so a long line at a true 2° angle is never incorrectly snapped.
 * Preserves the segment's extent along the dominant axis; averages the
 * perpendicular coordinate across both endpoints.
 */
function snapAxisAligned(
  recon:     Array<{ prim: LinePrimitive | ArcPrimitive }>,
  maxDevPx:  number,
): void {
  for (const s of recon) {
    const p = s.prim;
    if (p.type !== "line") continue;
    // Check max perpendicular deviation (= half the endpoint spread), not the
    // raw endpoint difference.  A segment from y=94.5 to y=95.9 has |dy|=1.4px
    // but max-perp = 0.7px; the old check (|dy| ≤ threshold) missed it.
    if (Math.abs(p.y2 - p.y1) <= 2 * maxDevPx) {
      // Nearly horizontal → exact horizontal at average y.
      const avgY = (p.y1 + p.y2) / 2;
      p.y1 = avgY; p.y2 = avgY;
    } else if (Math.abs(p.x2 - p.x1) <= 2 * maxDevPx) {
      // Nearly vertical → exact vertical at average x.
      const avgX = (p.x1 + p.x2) / 2;
      p.x1 = avgX; p.x2 = avgX;
    }
  }
}

// ---------------------------------------------------------------------------
// Post-fit undash
// ---------------------------------------------------------------------------

/**
 * After DP fitting, attempt a second round of gap-bridging using the fitted
 * segment directions (more reliable than skeleton look-back for noisy chains).
 * Compatible collinear endpoint pairs are merged, the combined dense-vertex
 * sequence is refitted, and chainInfos is updated so subsequent snapping sees
 * the correct outer endpoints.  Iterates until no more merges are possible.
 */
function postFitUndash(
  graph:          PathGraph,
  cache:          FitCache,
  chainInfos:     ChainInfo[],
  reconByChain:   Array<ReconEntry[] | null>,
  opts:           CurveFitOptions,
  maxGap:         number,
  maxAngleDeg:    number,
  absorbedChains: Set<number>,
): void {
  const cosThresh = Math.cos(maxAngleDeg * Math.PI / 180);
  const denseSeg  = opts.denseSeg ?? 2;
  const { vertices } = graph;

  // isJunction flag travels with the EP so the candidate loop can enforce the
  // junction×junction long-chain restriction there rather than in collectEPs.
  type EP = { ci: number; isStart: boolean; x: number; y: number; dx: number; dy: number; layer: number; isJunction: boolean; chainLen: number };

  function collectEPs(): EP[] {
    const eps: EP[] = [];
    for (let ci = 0; ci < reconByChain.length; ci++) {
      const recon = reconByChain[ci];
      if (!recon || recon.length === 0) continue;
      const info = chainInfos[ci];
      if (info.isClosed) continue;

      const svType = vertices[info.startVi]?.type;
      const evType = vertices[info.endVi]?.type;
      const chainLen = cache.chains[ci].denseVerts.length * denseSeg;

      const fp = recon[0].prim;
      if (fp.type === "line") {
        const dx = fp.x1 - fp.x2, dy = fp.y1 - fp.y2, len = Math.hypot(dx, dy);
        if (len > 1e-10)
          eps.push({ ci, isStart: true, x: fp.x1, y: fp.y1, dx: dx/len, dy: dy/len,
            layer: info.layer, isJunction: svType === "junction", chainLen });
      }
      const lp = recon[recon.length - 1].prim;
      if (lp.type === "line") {
        const dx = lp.x2 - lp.x1, dy = lp.y2 - lp.y1, len = Math.hypot(dx, dy);
        if (len > 1e-10)
          eps.push({ ci, isStart: false, x: lp.x2, y: lp.y2, dx: dx/len, dy: dy/len,
            layer: info.layer, isJunction: evType === "junction", chainLen });
      }
    }
    return eps;
  }

  for (let pass = 0; pass < 20; pass++) {
    const eps = collectEPs();

    interface Cand { ai: number; bi: number; gapDist: number }
    const candidates: Cand[] = [];

    for (let a = 0; a < eps.length; a++) {
      for (let b = a + 1; b < eps.length; b++) {
        const ea = eps[a], eb = eps[b];
        if (ea.layer !== eb.layer || ea.ci === eb.ci) continue;
        // Block junction↔junction merges when both chains are long — this would
        // incorrectly extend solid station lines across shared junction vertices.
        // A free endpoint bridging to a junction endpoint is always allowed; the
        // direction and coverage checks are the real safety guards.
        if (ea.isJunction && ea.chainLen >= maxGap &&
            eb.isJunction && eb.chainLen >= maxGap) continue;
        const gapDist = Math.hypot(eb.x - ea.x, eb.y - ea.y);
        if (gapDist > maxGap || gapDist < 0.01) continue;
        const gx = (eb.x - ea.x) / gapDist, gy = (eb.y - ea.y) / gapDist;
        // Log near-misses (within gap range but failing direction/anti-parallel check)
        // so we can diagnose why specific gaps fail.
        const dotAB  = ea.dx *   gx  + ea.dy *   gy;
        const dotBA  = eb.dx * (-gx) + eb.dy * (-gy);
        const dotAP  = ea.dx * (-eb.dx) + ea.dy * (-eb.dy);
        if (dotAB < cosThresh || dotBA < cosThresh || dotAP < cosThresh) {
          console.debug(
            `[undash near-miss] ci${ea.ci}(${ea.isStart?"start":"end"})↔ci${eb.ci}(${eb.isStart?"start":"end"})` +
            ` gap=${gapDist.toFixed(1)}px` +
            ` dotAB=${dotAB.toFixed(2)}(need≥${cosThresh.toFixed(2)})` +
            ` dotBA=${dotBA.toFixed(2)} dotAP=${dotAP.toFixed(2)}` +
            ` ea@(${ea.x.toFixed(1)},${ea.y.toFixed(1)}) eb@(${eb.x.toFixed(1)},${eb.y.toFixed(1)})`
          );
          continue;
        }
        candidates.push({ ai: a, bi: b, gapDist });
      }
    }
    if (candidates.length === 0) break;
    candidates.sort((x, y) => x.gapDist - y.gapDist);

    const matchedEPs     = new Set<number>(); // EP indices — one EP per match
    const matchedChains  = new Set<number>(); // chain indices — one merge per chain per pass
    let   anyMerge = false;

    for (const { ai, bi } of candidates) {
      if (matchedEPs.has(ai) || matchedEPs.has(bi)) continue;
      const ea = eps[ai], eb = eps[bi];
      const ciA = ea.ci, ciB = eb.ci;
      if (matchedChains.has(ciA) || matchedChains.has(ciB)) continue;
      const infoA = chainInfos[ciA], infoB = chainInfos[ciB];
      const cacheA = cache.chains[ciA], cacheB = cache.chains[ciB];
      const aAtEnd   = !ea.isStart;   // true  → A's end  is the bridged side
      const bAtStart =  eb.isStart;   // true  → B's start is the bridged side

      // Build tip-last A and tip-first B sequences.
      let dvA = cacheA.denseVerts, pvA = cacheA.pixelsPerVert, vsA = cacheA.vertStats;
      if (!aAtEnd) {
        dvA = [...dvA].reverse(); pvA = [...pvA].reverse();
        const nA = dvA.length, tmp = new Float64Array(nA * 6);
        for (let i = 0; i < nA; i++) { const s = nA-1-i; tmp.set(vsA.subarray(s*6, s*6+6), i*6); }
        vsA = tmp;
      }
      let dvB = cacheB.denseVerts, pvB = cacheB.pixelsPerVert, vsB = cacheB.vertStats;
      if (!bAtStart) {
        dvB = [...dvB].reverse(); pvB = [...pvB].reverse();
        const nB = dvB.length, tmp = new Float64Array(nB * 6);
        for (let i = 0; i < nB; i++) { const s = nB-1-i; tmp.set(vsB.subarray(s*6, s*6+6), i*6); }
        vsB = tmp;
      }

      // Interpolate gap vertices (no pixels — empty stats).
      const gdist = Math.hypot(dvB[0].x - dvA[dvA.length-1].x, dvB[0].y - dvA[dvA.length-1].y);
      const gapN  = Math.max(1, Math.round(gdist / denseSeg));
      const ax0 = dvA[dvA.length-1].x, ay0 = dvA[dvA.length-1].y;
      const bx0 = dvB[0].x,            by0 = dvB[0].y;
      const gapDV: { x: number; y: number }[] = [];
      for (let k = 1; k <= gapN; k++) {
        const t = k / (gapN + 1);
        gapDV.push({ x: ax0 + t*(bx0-ax0), y: ay0 + t*(by0-ay0) });
      }
      const gapPV: Array<{ x: number; y: number }[]> = gapDV.map(() => []);
      const gapVS = new Float64Array(gapN * 6);

      const nA = dvA.length, nGap = gapDV.length, nB = dvB.length;
      const mergedDV = [...dvA, ...gapDV, ...dvB];
      const mergedPV = [...pvA, ...gapPV, ...pvB];
      const mergedVS = new Float64Array((nA + nGap + nB) * 6);
      mergedVS.set(vsA, 0); mergedVS.set(gapVS, nA*6); mergedVS.set(vsB, (nA+nGap)*6);

      // Single-line fit: post-undash bridges are always collinear by construction,
      // so we fit one segment through the combined pixel moments rather than
      // running the full DP (which may kink at the gap boundary).
      const allWin = new Float64Array(6);
      for (let vi = 0; vi < mergedDV.length; vi++) windowAdd(allWin, mergedVS, vi);
      let lDirX = 1, lDirY = 0, lCx = 0, lCy = 0;
      if (allWin[0] >= 2) {
        const r = dirFromWindow(allWin);
        lDirX = r.dirX; lDirY = r.dirY; lCx = r.cx; lCy = r.cy;
      } else {
        // No pixels: use geometric direction of the merged dense vertices.
        for (const v of mergedDV) { lCx += v.x; lCy += v.y; }
        lCx /= mergedDV.length; lCy /= mergedDV.length;
        const ddx = mergedDV[mergedDV.length-1].x - mergedDV[0].x;
        const ddy = mergedDV[mergedDV.length-1].y - mergedDV[0].y;
        const dlen = Math.hypot(ddx, ddy);
        if (dlen > 1e-10) { lDirX = ddx / dlen; lDirY = ddy / dlen; }
      }
      const tFirst = (mergedDV[0].x - lCx) * lDirX + (mergedDV[0].y - lCy) * lDirY;
      const tLast  = (mergedDV[mergedDV.length-1].x - lCx) * lDirX + (mergedDV[mergedDV.length-1].y - lCy) * lDirY;
      const mergedPrim = makeLinePrimitive(
        lCx + tFirst * lDirX, lCy + tFirst * lDirY,
        lCx + tLast  * lDirX, lCy + tLast  * lDirY,
      );
      // Merge quality gate: reject if any merged dense vertex is too far from
      // the fitted line — indicates non-collinear chains were paired.
      // Dense-vertex positions are more reliable than accumulated pixel moments
      // for long chains (global pixel variance is inflated by corner noise even
      // when the endpoints are perfectly collinear).
      const perpX = -lDirY, perpY = lDirX; // unit perp to fitted direction
      {
        let worstPerp = 0;
        for (const dv of mergedDV) {
          const perp = Math.abs((dv.x - lCx) * perpX + (dv.y - lCy) * perpY);
          if (perp > worstPerp) worstPerp = perp;
        }
        if (worstPerp > denseSeg * 4) {
          continue;
        }
      }

      // Run full DP + post-processing pipeline on the merged chain so that
      // collinear runs spanning the bridged gap become single long segments
      // rather than many nearly-collinear short ones.
      let newRecon = fitDenseChain(mergedDV, mergedPV, mergedVS, opts);
      if (newRecon.length === 0) {
        newRecon = [{ wi: 0, wj: mergedDV.length - 1, prim: mergedPrim, ce: 0 }];
      }
      mergeCollinearSegments(newRecon, mergedDV, mergedVS, denseSeg);
      snapAxisAligned(newRecon, opts.axisSnapPx ?? 1);
      // Same position in the sequence as the main loop's `freeze`, and for the
      // same reason: this re-fit throws away the flags both source chains
      // carried, so a confident line that happens to sit in a dash-bridged
      // chain would arrive at the passes below with nothing to say for itself.
      if ((opts.freezeMinLenPx ?? 0) > 0) {
        freezeConfidentLines(
          newRecon, mergedVS, opts.freezeMinLenPx!, opts.freezeMaxCE ?? 0.25);
      }
      stitchJunctions(newRecon);
      mergeCollinearSegments(newRecon, mergedDV, mergedVS, denseSeg);
      snapAxisAligned(newRecon, opts.axisSnapPx ?? 1);
      stitchJunctions(newRecon);
      const connM = snapAdjacentJunctions(newRecon);
      refitPoorSpans(newRecon, connM, mergedDV, mergedPV, mergedVS, opts);
      snapAxisAligned(newRecon, opts.axisSnapPx ?? 1);
      stitchJunctions(newRecon);
      stitchJunctions(newRecon);
      mergeCollinearSegments(newRecon, mergedDV, mergedVS, denseSeg);

      reconByChain[ciA] = newRecon;
      reconByChain[ciB]  = null;
      absorbedChains.add(ciB);
      cache.chains[ciA]  = { ...cacheA, denseVerts: mergedDV, pixelsPerVert: mergedPV, vertStats: mergedVS };

      // Update chainInfos[ciA]: outer endpoints are A's far end and B's far end.
      // (When A was reversed, A's far end = original infoA.endVi; etc.)
      infoA.startVi  = aAtEnd   ? infoA.startVi : infoA.endVi;
      infoA.endVi    = bAtStart ? infoB.endVi   : infoB.startVi;
      infoA.isClosed = false;

      matchedEPs.add(ai); matchedEPs.add(bi);
      matchedChains.add(ciA); matchedChains.add(ciB);
      anyMerge = true;
    }
    if (!anyMerge) break;
  }
}

// ---------------------------------------------------------------------------
// Fit validation
// ---------------------------------------------------------------------------

/**
 * Validate the output of fitCurves against the dense-vertex chain data.
 *
 * Coverage check: for every dense vertex in a non-null chain, find the unique
 * fitted segment that covers it (using the wi/wj index range — O(N) per chain
 * via linear scan) and compute its perpendicular distance to the line.
 *
 * Topology check: every chain with N≥2 dense vertices must either have a
 * non-null reconByChain entry OR have been intentionally absorbed by
 * postFitUndash (tracked in absorbedChains).
 */
function computeFitValidation(
  cache:          FitCache,
  reconByChain:   Array<ReconEntry[] | null>,
  absorbedChains: Set<number>,
  denseSeg:       number,
  coverThreshold: number,
): FitValidationResult {
  let droppedChains       = 0;
  let totalChains         = 0;
  let backwardSegments    = 0;
  let disconnectedJunctions = 0;
  let sumError            = 0;
  let maxError            = 0;
  let coveredVertices     = 0;
  const warnings: FitValidationWarning[] = [];
  const junctionGapThresh = denseSeg * 2;

  for (let ci = 0; ci < reconByChain.length; ci++) {
    const ch = cache.chains[ci];
    const N  = ch.denseVerts.length;
    if (N < 2) continue;
    totalChains++;

    const recon = reconByChain[ci];
    if (!recon || recon.length === 0) {
      if (!absorbedChains.has(ci)) {
        droppedChains++;
        const v = ch.denseVerts[0];
        warnings.push({ ci, layer: ch.layer, type: "dropped",
          message: `Chain ${ci} (layer ${ch.layer}, ${N} verts) produced no output and was not absorbed`,
          x: v.x, y: v.y });
      }
      continue;
    }

    // ── Coverage: O(N) linear scan ─────────────────────────────────────────
    // Segments are contiguous: recon[k].wj + 1 == recon[k+1].wi
    let si = 0;
    let chainMaxErr = 0;
    let worstV: { x: number; y: number } | null = null;
    for (let vi = 0; vi < N; vi++) {
      // Advance segment cursor.
      while (si + 1 < recon.length && recon[si].wj < vi) si++;
      const seg = recon[si];
      if (vi < seg.wi || vi > seg.wj) continue; // gap (shouldn't happen)

      const p  = seg.prim;
      const vx = ch.denseVerts[vi].x, vy = ch.denseVerts[vi].y;
      let dist: number;
      if (p.type === "arc") {
        // Radial deviation from the arc circle.
        dist = Math.abs(Math.hypot(vx - p.cx, vy - p.cy) - p.r);
      } else {
        const dx = p.x2 - p.x1, dy = p.y2 - p.y1;
        const len = Math.hypot(dx, dy);
        if (len < 1e-10) continue;
        // Perpendicular distance (signed, take abs).
        dist = Math.abs((vx - p.x1) * (-dy / len) + (vy - p.y1) * (dx / len));
      }
      coveredVertices++;
      sumError += dist;
      if (dist > maxError) maxError = dist;
      if (dist > chainMaxErr) { chainMaxErr = dist; worstV = { x: vx, y: vy }; }
    }
    if (chainMaxErr > coverThreshold && worstV) {
      warnings.push({ ci, layer: ch.layer, type: "coverage",
        message: `Chain ${ci} (layer ${ch.layer}): max coverage error ${chainMaxErr.toFixed(2)} px > ${coverThreshold} px`,
        x: worstV.x, y: worstV.y });
    }

    // ── Backward segments ──────────────────────────────────────────────────
    // Compare adjacent segment directions: a dot product < -0.1 means >~96°
    // reversal which is a real zigzag. This avoids false positives on
    // multi-directional chains like closed rectangular loops.
    for (let k = 0; k + 1 < recon.length; k++) {
      const s0 = recon[k], s1 = recon[k + 1];
      // Chord direction works for both lines and arcs (an arc's chord follows
      // its traversal direction since sweeps are < 2π).
      const a0 = primitiveEndPoint(s0.prim, true), b0 = primitiveEndPoint(s0.prim, false);
      const a1 = primitiveEndPoint(s1.prim, true), b1 = primitiveEndPoint(s1.prim, false);
      const dx0 = b0.x - a0.x, dy0 = b0.y - a0.y;
      const dx1 = b1.x - a1.x, dy1 = b1.y - a1.y;
      const len0 = Math.hypot(dx0, dy0), len1 = Math.hypot(dx1, dy1);
      if (len0 < 1e-6 || len1 < 1e-6) continue;
      const dot = (dx0/len0)*(dx1/len1) + (dy0/len0)*(dy1/len1);
      if (dot < -0.1) {
        backwardSegments++;
        // Also report the dense-vertex direction for [s1.wi..s1.wj] so we can
        // tell whether it's the DP that created the backward direction or whether
        // the dense vertex chain itself is backward in this range.
        const dvStart = ch.denseVerts[s1.wi], dvEnd = ch.denseVerts[Math.min(s1.wj, ch.denseVerts.length - 1)];
        const dvDx = dvEnd.x - dvStart.x, dvDy = dvEnd.y - dvStart.y;
        const dvLen = Math.hypot(dvDx, dvDy);
        const dvDot = dvLen > 1e-6
          ? ((dx0/len0)*(dvDx/dvLen) + (dy0/len0)*(dvDy/dvLen))
          : 0;
        const dvBackward = dvDot < -0.1;
        warnings.push({ ci, layer: ch.layer, type: "backward",
          message: `Chain ${ci} (layer ${ch.layer}): segment [${s1.wi},${s1.wj}] reverses vs prev` +
            ` | seg:(${a1.x.toFixed(1)},${a1.y.toFixed(1)})→(${b1.x.toFixed(1)},${b1.y.toFixed(1)})` +
            ` | dv[${s1.wi}]=(${dvStart.x.toFixed(1)},${dvStart.y.toFixed(1)})→dv[${s1.wj}]=(${dvEnd.x.toFixed(1)},${dvEnd.y.toFixed(1)})` +
            ` | dv_dir_vs_prev_dot=${dvDot.toFixed(2)} (dv_backward=${dvBackward})`,
          x: a1.x, y: a1.y });
      }
    }

    // ── Disconnected junctions ─────────────────────────────────────────────
    for (let k = 0; k + 1 < recon.length; k++) {
      const e1 = primitiveEndPoint(recon[k].prim, false);
      const s2 = primitiveEndPoint(recon[k + 1].prim, true);
      const gap = Math.hypot(s2.x - e1.x, s2.y - e1.y);
      if (gap > junctionGapThresh) {
        disconnectedJunctions++;
        warnings.push({ ci, layer: ch.layer, type: "junction-gap",
          message: `Chain ${ci} (layer ${ch.layer}): junction gap ${gap.toFixed(2)} px between segs ${k} and ${k+1}`,
          x: e1.x, y: e1.y });
      }
    }
  }

  return {
    droppedChains,
    absorbedChains: absorbedChains.size,
    totalChains,
    maxCoverageError:  maxError,
    meanCoverageError: coveredVertices > 0 ? sumError / coveredVertices : 0,
    coveredVertices,
    backwardSegments,
    disconnectedJunctions,
    warnings,
  };
}

// ---------------------------------------------------------------------------
// Public API: fitCurves
// ---------------------------------------------------------------------------

/**
 * Fit lines, arcs, and circles to all chains in `graph` using the same
 * centroid-based DP approach as `computeHoverFit`.
 *
 * Replaces the old recursive-splitting pipeline with a globally-optimal DP
 * per chain, Voronoi pixel assignment, G1 junction adjustment, and
 * geometric arc–line intersection for junction points.
 */
export async function fitCurves(
  device:     GPUDevice | null,
  graph:      PathGraph,
  decomp:     PaletteDecomposition,
  opts:       CurveFitOptions,
  onProgress?:    (fraction: number, label: string) => void,
  /** If provided, validation result is written here after fitting. */
  outValidation?: { result: FitValidationResult },
): Promise<CurveGraph> {
  const { width, height, layerCount } = graph;
  const denseSeg = opts.denseSeg ?? 2;
  const freezeMinLenPx = opts.freezeMinLenPx ?? 0;
  const freezeMaxCE    = opts.freezeMaxCE ?? 0.25;

  const cache     = await buildFitCache(
    device, graph, decomp, opts.bandWidth, denseSeg,
    onProgress ? (f, lbl) => onProgress(f * 0.5, lbl) : undefined,
  );
  const rawChains = extractChains(graph);
  const segments: CurveSegment[] = [];
  const reconByChain: Array<ReconEntry[] | null> = [];
  const chainInfos:   ChainInfo[] = [];

  const total     = cache.chains.length;
  let   lastYield = performance.now();

  for (let ci = 0; ci < total; ci++) {
    const now = performance.now();
    if (now - lastYield > 16) {
      const pct = Math.round((ci / total) * 100);
      onProgress?.(0.5 + (ci / total) * 0.5, `Fitting chains… ${pct}%`);
      await new Promise<void>(r => setTimeout(r, 0));
      lastYield = performance.now();
    }

    const ch               = cache.chains[ci];
    const { layer, isClosed } = ch;
    const raw = rawChains[ci];
    const startVi = raw.vertices[0];
    const endVi   = raw.vertices[raw.vertices.length - 1];

    const N = ch.denseVerts.length;
    if (N < 2) {
      reconByChain.push(null);
      chainInfos.push({ startVi, endVi, layer, isClosed });
      continue;
    }

    // ── Closed rings: try full-circle fit first ───────────────────────────
    if (isClosed) {
      const cxArr = new Float64Array(N), cyArr = new Float64Array(N);
      for (let vi = 0; vi < N; vi++) {
        const pxs = ch.pixelsPerVert[vi];
        if (pxs.length >= 2) {
          let sx = 0, sy = 0;
          for (const p of pxs) { sx += p.x; sy += p.y; }
          cxArr[vi] = sx / pxs.length;
          cyArr[vi] = sy / pxs.length;
        } else {
          cxArr[vi] = ch.denseVerts[vi].x;
          cyArr[vi] = ch.denseVerts[vi].y;
        }
      }
      const cf = fitCircle(cxArr, cyArr);
      if (cf.valid && cf.r > 0) {
        let rms = 0;
        for (let vi = 0; vi < N; vi++) {
          const d = Math.hypot(cxArr[vi] - cf.cx, cyArr[vi] - cf.cy) - cf.r;
          rms += d * d;
        }
        rms = Math.sqrt(rms / N);
        if (rms <= opts.maxCenteringError) {
          segments.push({
            layer, chainId: ci, isClosed: true,
            primitive: { type: "circle", cx: cf.cx, cy: cf.cy, r: cf.r },
          });
          reconByChain.push(null);
          chainInfos.push({ startVi, endVi, layer, isClosed: true });
          continue;
        }
      }
    }

    // ── Open chains and non-circular rings: DP fit ───────────────────────
    const recon = fitDenseChain(ch.denseVerts, ch.pixelsPerVert, ch.vertStats, opts);
    if (recon.length === 0) {
      // N in [2, MIN_SEG-1]: too short for DP — emit a direct line rather than
      // silently dropping the chain.
      recon.push({ wi: 0, wj: N - 1, prim: makeLinePrimitive(
        ch.denseVerts[0].x, ch.denseVerts[0].y,
        ch.denseVerts[N - 1].x, ch.denseVerts[N - 1].y,
      ), ce: 0 });
    }
    // The per-chain repair sequence, as data rather than straight-line code.
    //
    // The order is exactly what it was written out longhand — this is a
    // rename, not a re-ordering — but naming the steps lets `opts.passProbe`
    // measure the fit between them.  That matters because the steps are not
    // independent: several exist only to repair what an earlier one disturbed
    // (see their comments), and until they could be measured individually the
    // only way to find one undoing another was to instrument by hand.
    let conn: number[] = [];
    const passes: Array<[string, () => void]> = [
      ["merge 1", () => mergeCollinearSegments(recon, ch.denseVerts, ch.vertStats, opts.denseSeg ?? 2, opts.mdlPenalty, opts.maxCenteringError)],
      ["axis 1", () => snapAxisAligned(recon, opts.axisSnapPx ?? 1)],
      // Commit to the fits we are certain about before anything starts closing
      // junctions, so that every pass below knows which side of a joint to
      // move.  It runs after `axis 1` rather than before because that snap is
      // the last thing that can make a confident line *more* certain — a
      // horizontal that ends up exactly level is frozen exactly level.
      ["freeze", () => {
        if (freezeMinLenPx > 0) {
          freezeConfidentLines(recon, ch.vertStats, freezeMinLenPx, freezeMaxCE);
        }
      }],
      ["stitch 1", () => stitchJunctions(recon)],
      // Second merge pass: snap may have made previously-tilted segments exactly
      // H/V, revealing collinear adjacent pairs that the first pass couldn't see.
      ["merge 2", () => mergeCollinearSegments(recon, ch.denseVerts, ch.vertStats, opts.denseSeg ?? 2, opts.mdlPenalty, opts.maxCenteringError)],
      // Re-snap: the second merge uses PCA on original pixel data, which can
      // re-introduce a slight slope in segments that snap had already straightened.
      ["axis 2", () => snapAxisAligned(recon, opts.axisSnapPx ?? 1)],
      ["stitch 2", () => stitchJunctions(recon)],
      // Absorb short lines that are really chords of an adjacent arc.  A compound
      // curve whose radius changes gradually leaves a short transition span that
      // is too short to qualify as its own arc, so DP covers it with a chord line
      // that pokes out of the stroke and produces the inward-pointing inflection
      // the fitter used to emit.  Merging it into the neighbouring arc lets the
      // flanking arcs meet directly, so snapAdjacentJunctions snaps a smooth joint.
      ["absorbShortArcLines", () => absorbShortArcLines(recon, (opts.denseSeg ?? 2) * 10)],
      // Whatever the absorb could not hand to a neighbouring arc, because the
      // radius is genuinely changing across it, becomes a transition arc of its
      // own.  Runs second so the cheaper answer — no primitive at all — always
      // gets first refusal.
      ["snapAdjacentJunctions", () => { conn = snapAdjacentJunctions(recon); }],
      ["refit 1", () => refitPoorSpans(recon, conn, ch.denseVerts, ch.pixelsPerVert, ch.vertStats, opts)],
      // Cut off any false concavity the DP left between two same-handed arcs.
      // Runs after G1 so the joints it inspects are the settled ones.
      ["relaxCuspsToLine", () => relaxCuspsToLine(recon, ch.pixelsPerVert, ch.denseVerts)],
      // Re-snap after G1: intersection adjustment can move an endpoint slightly
      // off an axis-aligned position that the earlier snap had established.
      ["axis 3", () => snapAxisAligned(recon, opts.axisSnapPx ?? 1)],
      ["stitch 3", () => stitchJunctions(recon)],
      // Final merge: G1 junction adjustment can make adjacent segments more
      // collinear (or reduce a stub to near-zero length).  One more pass absorbs
      // any remaining redundant vertices.
      ["merge 3", () => mergeCollinearSegments(recon, ch.denseVerts, ch.vertStats, opts.denseSeg ?? 2, opts.mdlPenalty, opts.maxCenteringError)],
      // Again, last.  The merge passes above can absorb the very vertices the
      // first re-fit added — a re-fitted corner came back square because the
      // final merge undid it — and nothing after this point can.
      ["refit 2", () => refitPoorSpans(recon, [], ch.denseVerts, ch.pixelsPerVert, ch.vertStats, opts)],
      ["closed seam", () => {
        if (isClosed) mergeClosedChainSeam(recon, ch.denseVerts, ch.vertStats);
        if (isClosed) closeChainSeam(recon, 20);
      }],
    ];

    opts.passProbe?.({ name: "fitDenseChain", chain: ci, recon, denseVerts: ch.denseVerts });
    for (const [name, run] of passes) {
      if (opts.passFilter && !opts.passFilter(name)) continue;
      run();
      opts.passProbe?.({ name, chain: ci, recon, denseVerts: ch.denseVerts });
    }
    reconByChain.push(recon);
    chainInfos.push({ startVi, endVi, layer, isClosed });

  }

  // ── Cross-chain tail ──────────────────────────────────────────────────
  //
  // Everything below acts on every chain at once rather than on one chain in
  // turn, so it cannot be expressed as an entry in the `passes` list above.
  // `tail` gives it the same name-and-probe treatment anyway: the probe is fed
  // one observation per chain after each named step, so `deno task passes` and
  // `vecfit.ts --without` reach these passes exactly as they reach the
  // per-chain ones.
  //
  // This is not a cosmetic symmetry.  The per-chain loop was the only
  // instrumented half, and a segment can leave it fitted and be walked off its
  // ink by the passes below with nothing able to see it happen — which is
  // precisely what a long straight line was measured doing.
  const tail = (name: string, run: () => void): void => {
    if (opts.passFilter && !opts.passFilter(name)) return;
    run();
    if (!opts.passProbe) return;
    for (let ci = 0; ci < reconByChain.length; ci++) {
      const recon = reconByChain[ci];
      if (recon) {
        opts.passProbe({ name, chain: ci, recon, denseVerts: cache.chains[ci].denseVerts });
      }
    }
  };

  const absorbedChains = new Set<number>();
  if (opts.postUndashMaxGap && opts.postUndashMaxGap > 0) {
    tail("postFitUndash", () => postFitUndash(graph, cache, chainInfos, reconByChain, opts,
      opts.postUndashMaxGap!, opts.postUndashMaxAngleDeg ?? 30, absorbedChains));
  }

  tail("snapJunctionEndpoints",
    () => snapJunctionEndpoints(graph, chainInfos, reconByChain, 30, opts.junctionStubMaxPx ?? 0));
  tail("snapEndpointPairs", () => snapEndpointPairs(graph, chainInfos, reconByChain, 30));
  if (opts.taperCollapseMaxStubPx && opts.taperCollapseMaxStubPx > 0) {
    tail("collapseJunctionTapers", () => collapseJunctionTapers(graph, chainInfos, reconByChain,
      opts.taperCollapseMaxStubPx!, opts.taperCollapseMaxParallelSin ?? 0.15));
  }

  // Re-centre long axis-aligned segments on their skeleton-vertex mean.
  // This corrects the inward bias caused by cross-contamination from adjacent
  // parallel strokes in the pixel-moment centroid.  Only segments with ≥ 100
  // dense vertices are affected so that short isolated strokes (where the
  // integer-grid skeleton position is less accurate than the pixel centroid)
  // keep their PCA-derived position.
  tail("recenterOnSkeleton", () => recenterOnSkeleton(reconByChain, cache, 100, chainInfos, graph));

  // Put exactly-axis-aligned lines in the middle of their own stroke.  Runs
  // after recenterOnSkeleton because it supersedes it for these segments, and
  // before the re-stitch / re-snap below so the junctions it nudges are closed
  // again.
  tail("recentreAxisAligned", () => recentreAxisAligned(reconByChain, cache, 1.5));

  // …and slide the lines the axis pass could not take — the ones that are
  // genuinely sloped — onto the middle of their own strokes.  Same correction,
  // without the flatness test that only straightening needs.
  tail("recentreLongLines",
    () => recentreLongLines(reconByChain, cache, freezeMinLenPx || 100, 1.5));

  // Re-stitch intra-chain junctions: recenterOnSkeleton shifts each segment
  // independently by its perpendicular skeleton bias.  When two consecutive
  // segments in the same chain have different biases (e.g. a gentle curve
  // changing direction), the shared junction point diverges.  Re-stitching
  // re-averages nearly-collinear junction pairs to restore continuity.
  tail("stitch tail", () => {
    for (const recon of reconByChain) {
      if (recon) stitchJunctions(recon);
    }
  });

  // Re-snap junction endpoints: recenterOnSkeleton may have slightly shifted
  // endpoints that meet at shared junction points (even with pinning, the
  // doubled free-end correction can create a small mismatch if two chains
  // share the same junction).  A lightweight re-snap restores exact sharing.
  tail("snapJunctionEndpoints 2",
    () => snapJunctionEndpoints(graph, chainInfos, reconByChain, 30, 0));

  // …and the endpoint pairs for the same reason: recenterOnSkeleton pins ends
  // that sit on a junction vertex, but not ends that were joined to another
  // chain across a bridged dash gap, so a long re-centred segment drags one of
  // those apart again.  Left alone it was a 0.139 px hole — small, and still an
  // open contour as far as CAM is concerned.
  tail("snapEndpointPairs 2", () => snapEndpointPairs(graph, chainInfos, reconByChain, 30));

  // ── Validation ────────────────────────────────────────────────────────
  if (outValidation) {
    const coverThreshold = (opts.denseSeg ?? 2) * 3;
    outValidation.result = computeFitValidation(
      cache, reconByChain, absorbedChains, opts.denseSeg ?? 2, coverThreshold);
  }

  // Segments that survive the degenerate filter, per chain, so the cross-chain
  // weld below can act on exactly what will be emitted.
  const keptByChain: Array<ReconEntry[] | null> = new Array(total).fill(null);

  // ── Build segments from reconByChain (circles already added above) ────
  // Filter degenerate stubs (short physical length AND/OR very sparse pixel
  // count) that survive from dashed-line noise or near-zero DP artifacts.
  // Rather than silently dropping them, we extend the nearest retained
  // neighbor's endpoint to absorb their spatial extent.
  for (let ci = 0; ci < total; ci++) {
    const recon = reconByChain[ci];
    if (!recon) continue;
    const info = chainInfos[ci];
    const vs   = cache.chains[ci].vertStats;

    // Count pixels attributed to a segment's vertex range.
    // wi > wj indicates a seam-wrapping entry (last+first merged across the
    // closed-chain seam); count both halves in that case.
    const nVerts = cache.chains[ci].denseVerts.length;
    const pixCount = (s: ReconEntry): number => {
      let n = 0;
      if (s.wi <= s.wj) {
        for (let vi = s.wi; vi <= s.wj; vi++) n += vs[vi * 6];
      } else {
        for (let vi = s.wi; vi < nVerts; vi++) n += vs[vi * 6];
        for (let vi = 0; vi <= s.wj; vi++) n += vs[vi * 6];
      }
      return n;
    };

    // A segment is degenerate if it is physically very short (< denseSeg), or
    // slightly longer but nearly devoid of pixels (length < 3×denseSeg and
    // total pixel count ≤ 2).  Circle primitives are never degenerate.
    const isDegenerate = (s: ReconEntry): boolean => {
      if (s.prim.type !== "line") return false;
      const len = Math.hypot(s.prim.x2 - s.prim.x1, s.prim.y2 - s.prim.y1);
      if (len < denseSeg) return true;
      if (len < denseSeg * 3 && pixCount(s) <= 2) return true;
      return false;
    };

    const keep = recon.map(s => !isDegenerate(s));

    // For each dropped segment, extend the nearest kept neighbour along its
    // own direction so coverage is maintained without introducing kinks.
    // (We project onto the kept segment's axis rather than adopting the
    // dropped segment's endpoint directly, which would create a direction
    // change at the junction after G1 adjustment.)
    const projectExtend = (
      p: LinePrimitive,
      tx: number, ty: number,   // target point to project
      atEnd: boolean,           // true → extend far end, false → extend near end
    ) => {
      const dx = p.x2 - p.x1, dy = p.y2 - p.y1;
      const len = Math.hypot(dx, dy);
      if (len < 1e-10) return;
      const ux = dx / len, uy = dy / len;
      const t = (tx - p.x1) * ux + (ty - p.y1) * uy;
      if (atEnd  && t > len) { p.x2 = p.x1 + t * ux; p.y2 = p.y1 + t * uy; }
      if (!atEnd && t < 0)   { p.x1 = p.x1 + t * ux; p.y1 = p.y1 + t * uy; }
    };

    for (let i = 0; i < recon.length; i++) {
      if (keep[i]) continue;
      const s = recon[i];

      // Nearest previous kept segment.
      let prevKept = -1;
      for (let j = i - 1; j >= 0; j--) { if (keep[j]) { prevKept = j; break; } }

      if (prevKept >= 0) {
        const prev = recon[prevKept];
        const sEnd = primitiveEndPoint(s.prim, false);
        if (prev.prim.type === "line") projectExtend(prev.prim, sEnd.x, sEnd.y, true);
        prev.wj = s.wj;
        continue;
      }

      // No previous kept segment — extend the next one backward instead.
      let nextKept = -1;
      for (let j = i + 1; j < recon.length; j++) { if (keep[j]) { nextKept = j; break; } }
      if (nextKept >= 0) {
        const next = recon[nextKept];
        const sStart = primitiveEndPoint(s.prim, true);
        if (next.prim.type === "line") projectExtend(next.prim, sStart.x, sStart.y, false);
        next.wi = s.wi;
      }
      // If no neighbour at all (single-segment chain that is itself
      // degenerate), the segment is simply omitted.
    }

    // Final C0 weld over the segments that will actually be emitted.  This is
    // the last point at which geometry is touched, so any junction reopened by
    // the passes above (snap, merge, stub absorption) is closed here.
    const kept = recon.filter((_, i) => keep[i]);
    // Consecutive entries of one chain cover consecutive spans of the same
    // stroke, so there is no discontinuity here to preserve — the only reason
    // they are ever apart is that the passes above moved their endpoints
    // independently.  The old 2x denseSeg (4 px) limit was small enough to
    // leave that unclosed: a real sheet produced a 4.24 px in-chain gap, which
    // is a watertightness failure by a quarter of a pixel of threshold.  8x leaves room for the accumulated adjustment without
    // reaching across anything meaningful.
    weldChainJunctions(kept, info.isClosed, (opts.denseSeg ?? 2) * 8);
    keptByChain[ci] = kept;
  }

  // From here on the geometry that will be emitted lives in `keptByChain`, so
  // the probe follows it there.
  const probeKept = (name: string): void => {
    if (!opts.passProbe) return;
    for (let ci = 0; ci < keptByChain.length; ci++) {
      const kept = keptByChain[ci];
      if (kept) {
        opts.passProbe({ name, chain: ci, recon: kept, denseVerts: cache.chains[ci].denseVerts });
      }
    }
  };
  const tailKept = (name: string, run: () => void): void => {
    if (opts.passFilter && !opts.passFilter(name)) return;
    run();
    probeKept(name);
  };
  // The degenerate-stub filter and `weldChainJunctions` ran inside the loop
  // above, so this is a checkpoint rather than a pass: it is where their effect
  // becomes visible, and it is not separately removable.
  probeKept("drop stubs + weld");

  // Cross-chain weld: the same argument as weldChainJunctions, one level up.
  tailKept("weldCrossChainJunctions",
    () => weldCrossChainJunctions(keptByChain, chainInfos, (opts.denseSeg ?? 2) * 3));

  // Isolated specks are noise, not geometry.
  tailKept("dropIsolatedSpecks", () => dropIsolatedSpecks(keptByChain, DEFAULT_SPECK_MAX_PX));

  // A dashed circle arrives as several arcs on one circle; say so.
  tailKept("consolidateCircles", () => {
    for (const c of consolidateCircles(keptByChain, chainInfos)) {
      segments.push({ layer: c.layer, chainId: c.chainId, isClosed: true, primitive: c.primitive });
    }
  });

  // Finally, run free ends on to the other-ink geometry they terminate
  // against.  After the welds, so a junction that has just been made watertight
  // is never disturbed.
  if (opts.extendToOtherInkPx && opts.extendToOtherInkPx > 0) {
    tailKept("extendEndsToOtherInk",
      () => extendEndsToOtherInk(keptByChain, chainInfos, opts.extendToOtherInkPx!));
  }

  for (let ci = 0; ci < total; ci++) {
    const kept = keptByChain[ci];
    if (!kept) continue;
    const info = chainInfos[ci];
    for (const s of kept) {
      segments.push({ layer: info.layer, chainId: ci, isClosed: info.isClosed, primitive: s.prim });
    }
  }

  onProgress?.(1, "Done");
  return { width, height, layerCount, segments };
}

// ---------------------------------------------------------------------------
// Tessellation for rendering
// ---------------------------------------------------------------------------

/**
 * Convert a CurveGraph into a PathGraph by tessellating arcs and circles
 * into short line segments.
 */
export function curveGraphToPathGraph(
  curves:  CurveGraph,
  arcStep: number,
): PathGraph {
  const { width, height, layerCount, segments } = curves;

  const vertices: PathVertex[] = [];
  const edges:    PathEdge[]   = [];

  // Deduplicate chain-boundary vertices that land at the same pixel position
  // (e.g. after snapEndpointPairs snaps two chain ends to the same midpoint).
  // Key: "rx,ry,layer"  where rx/ry are coordinates rounded to 0.5px.
  const boundaryVtxMap = new Map<string, number>();

  function addVertex(
    x: number, y: number, layer: number, type: PathVertex["type"],
    deduplicate = false,
  ): number {
    if (deduplicate) {
      const key = `${Math.round(x * 2)},${Math.round(y * 2)},${layer}`;
      const existing = boundaryVtxMap.get(key);
      if (existing !== undefined) return existing;
      const idx = vertices.length;
      vertices.push({ x, y, layer, type });
      boundaryVtxMap.set(key, idx);
      return idx;
    }
    const idx = vertices.length;
    vertices.push({ x, y, layer, type });
    return idx;
  }

  function addEdge(from: number, to: number, layer: number): void {
    if (from === to) return;
    edges.push({ from: Math.min(from, to), to: Math.max(from, to), layer });
  }

  const byChain = new Map<number, CurveSegment[]>();
  for (const seg of segments) {
    const arr = byChain.get(seg.chainId);
    if (arr) arr.push(seg);
    else byChain.set(seg.chainId, [seg]);
  }

  for (const chainSegs of byChain.values()) {
    const isClosed = chainSegs[0].isClosed;
    const layer    = chainSegs[0].layer;

    if (chainSegs.length === 1 && chainSegs[0].primitive.type === "circle") {
      const { cx, cy, r } = chainSegs[0].primitive;
      const circumference  = 2 * Math.PI * r;
      const steps          = Math.max(3, Math.ceil(circumference / arcStep));
      const dTheta         = (2 * Math.PI) / steps;

      const first = addVertex(cx + r, cy, layer, "endpoint");
      let prev    = first;
      for (let s = 1; s < steps; s++) {
        const theta = s * dTheta;
        const curr  = addVertex(cx + r * Math.cos(theta), cy + r * Math.sin(theta), layer, "chain");
        addEdge(prev, curr, layer);
        prev = curr;
      }
      addEdge(prev, first, layer);
      continue;
    }

    let prevEndIdx = -1;
    const firstStartIdx_ref = { idx: -1 };

    for (let si = 0; si < chainSegs.length; si++) {
      const seg = chainSegs[si];
      const p   = seg.primitive;

      if (p.type === "circle") continue;

      const isFirstSeg = si === 0;
      const isLastSeg  = si === chainSegs.length - 1;

      const startType: PathVertex["type"] = "endpoint";
      const endType:   PathVertex["type"] = "endpoint";

      if (p.type === "line") {
        let startIdx: number;
        if (prevEndIdx >= 0) {
          startIdx = prevEndIdx;
        } else {
          startIdx = addVertex(p.x1, p.y1, layer, startType, /*deduplicate=*/isFirstSeg);
          if (isFirstSeg) firstStartIdx_ref.idx = startIdx;
        }

        const endIdx = (isClosed && isLastSeg && firstStartIdx_ref.idx >= 0)
          ? firstStartIdx_ref.idx
          : addVertex(p.x2, p.y2, layer, endType, /*deduplicate=*/isLastSeg);

        addEdge(startIdx, endIdx, layer);
        prevEndIdx = endIdx;

      } else { // arc
        const { cx, cy, r, startAngle, endAngle, ccw, sweep } = p;

        const span   = ccw ? sweep : -sweep;
        const arcLen = sweep * r;
        const steps  = Math.max(1, Math.ceil(arcLen / arcStep));
        const dTheta = span / steps;

        const arcStartX = cx + r * Math.cos(startAngle);
        const arcStartY = cy + r * Math.sin(startAngle);
        const arcEndX   = cx + r * Math.cos(endAngle);
        const arcEndY   = cy + r * Math.sin(endAngle);

        let startIdx: number;
        if (prevEndIdx >= 0) {
          startIdx = prevEndIdx;
        } else {
          startIdx = addVertex(arcStartX, arcStartY, layer, startType);
          if (isFirstSeg) firstStartIdx_ref.idx = startIdx;
        }

        let prev = startIdx;
        for (let s = 1; s <= steps; s++) {
          const isLastStep = s === steps;
          let curr: number;
          if (isLastStep) {
            if (isClosed && isLastSeg && firstStartIdx_ref.idx >= 0) {
              curr = firstStartIdx_ref.idx;
            } else {
              curr = addVertex(arcEndX, arcEndY, layer, endType);
            }
          } else {
            const theta = startAngle + s * dTheta;
            curr = addVertex(cx + r * Math.cos(theta), cy + r * Math.sin(theta), layer, "chain");
          }
          addEdge(prev, curr, layer);
          prev = curr;
        }
        prevEndIdx = prev;
      }
    }
  }

  return { width, height, layerCount, vertices, edges };
}

// ---------------------------------------------------------------------------
// Hover fit: dense skeleton helpers
// ---------------------------------------------------------------------------

/**
 * Densify a chain into uniformly-spaced vertices at ~`segLen` px arc-length
 * intervals.
 */
function densifyChain(
  chain:  Chain,
  verts:  PathVertex[],
  segLen: number,
): { x: number; y: number }[] {
  const numEdges = chain.vertices.length - 1 + (chain.isClosed ? 1 : 0);
  if (numEdges === 0) return [];

  const result: { x: number; y: number }[] = [];
  const v0 = verts[chain.vertices[0]];
  result.push({ x: v0.x, y: v0.y });

  let leftover = segLen;

  for (let ei = 0; ei < numEdges; ei++) {
    const aIdx = chain.vertices[ei];
    const bIdx = ei < chain.vertices.length - 1
      ? chain.vertices[ei + 1]
      : chain.vertices[0];
    const va = verts[aIdx], vb = verts[bIdx];
    const dx = vb.x - va.x, dy = vb.y - va.y;
    const edgeLen = Math.hypot(dx, dy);
    if (edgeLen < 1e-10) continue;
    const ux = dx / edgeLen, uy = dy / edgeLen;

    let t = leftover;
    while (t <= edgeLen) {
      result.push({ x: va.x + t * ux, y: va.y + t * uy });
      t += segLen;
    }
    leftover = t - edgeLen;
  }

  return result;
}

// ---------------------------------------------------------------------------
// Fit cache: public types
// ---------------------------------------------------------------------------

/**
 * Per-dense-vertex pixel data and 2nd moments, built once per page and
 * consumed by the DP fitter.
 */
export interface FitCache {
  graph:  PathGraph;
  chains: Array<{
    layer:        number;
    isClosed:     boolean;
    denseVerts:   { x: number; y: number }[];
    pixelsPerVert: Array<{ x: number; y: number }[]>;
    /**
     * Precomputed pixel moments per dense vertex for O(1) incremental PCA.
     * Layout: 6 Float64 values per vertex at index `vi*6`:
     *   [n, sumX, sumY, sumXX, sumXY, sumYY]
     */
    vertStats: Float64Array;
  }>;
}

// ---------------------------------------------------------------------------
// Public API: buildFitCache
// ---------------------------------------------------------------------------

export async function buildFitCache(
  device:      GPUDevice | null,
  graph:       PathGraph,
  decomp:      PaletteDecomposition,
  bandWidth:   number,
  denseSeg:    number,
  onProgress?: (fraction: number, label: string) => void,
): Promise<FitCache> {
  const layerPixels  = await readAllLayers(device, decomp);
  const chains       = extractChains(graph);
  const { vertices, width, height, layerCount } = graph;
  const total    = chains.length;
  let   lastYield = performance.now();

  // ── Phase 1: densify all chains ─────────────────────────────────────────────
  const chainDenseVerts: Array<Array<{ x: number; y: number }>> = [];
  for (let ci = 0; ci < total; ci++) {
    chainDenseVerts.push(densifyChain(chains[ci], vertices, denseSeg));
    const now = performance.now();
    if (now - lastYield > 16) {
      onProgress?.(ci / total * 0.25, `Densifying chains… ${Math.round(ci / total * 100)}%`);
      await new Promise<void>(r => setTimeout(r, 0));
      lastYield = performance.now();
    }
  }

  // ── Phase 2: global per-layer Voronoi pixel assignment ─────────────────────
  // Each pixel on a layer is assigned to the single nearest skeleton vertex
  // across ALL chains on that layer.  This eliminates double-counting at
  // junctions and between parallel/adjacent chains.

  // pixelsPerChainVert[ci][vi] accumulates the assigned pixels.
  const pixelsPerChainVert: Array<Array<Array<{ x: number; y: number }>>> =
    chainDenseVerts.map(dv => Array.from({ length: dv.length }, () => []));

  // Group all vertices by layer.
  const layerVerts: Array<Array<{ ci: number; vi: number; x: number; y: number }>> =
    Array.from({ length: layerCount }, () => []);
  for (let ci = 0; ci < total; ci++) {
    const layer = chains[ci].layer;
    const dv    = chainDenseVerts[ci];
    for (let vi = 0; vi < dv.length; vi++) {
      layerVerts[layer].push({ ci, vi, x: dv[vi].x, y: dv[vi].y });
    }
  }

  const bw2 = bandWidth * bandWidth;

  for (let layer = 0; layer < layerCount; layer++) {
    const verts   = layerVerts[layer];
    if (verts.length === 0) continue;
    const layerPx = layerPixels[layer] ?? new Uint8Array(0);

    // Bounding box of all verts on this layer.
    let vxMin = Infinity, vxMax = -Infinity, vyMin = Infinity, vyMax = -Infinity;
    for (const v of verts) {
      if (v.x < vxMin) vxMin = v.x; if (v.x > vxMax) vxMax = v.x;
      if (v.y < vyMin) vyMin = v.y; if (v.y > vyMax) vyMax = v.y;
    }

    const cellSize = bandWidth;
    const originX  = vxMin - bandWidth;
    const originY  = vyMin - bandWidth;
    const gridW    = Math.ceil((vxMax - vxMin + 2 * bandWidth) / cellSize) + 1;
    const gridH    = Math.ceil((vyMax - vyMin + 2 * bandWidth) / cellSize) + 1;
    const grid: number[][] = Array.from({ length: gridW * gridH }, () => []);
    for (let gi = 0; gi < verts.length; gi++) {
      const gx = Math.floor((verts[gi].x - originX) / cellSize);
      const gy = Math.floor((verts[gi].y - originY) / cellSize);
      if (gx >= 0 && gx < gridW && gy >= 0 && gy < gridH) grid[gy * gridW + gx].push(gi);
    }

    const xMin = Math.max(0,          Math.floor(vxMin - bandWidth));
    const xMax = Math.min(width  - 1, Math.ceil (vxMax + bandWidth));
    const yMin = Math.max(0,          Math.floor(vyMin - bandWidth));
    const yMax = Math.min(height - 1, Math.ceil (vyMax + bandWidth));

    for (let y = yMin; y <= yMax; y++) {
      for (let x = xMin; x <= xMax; x++) {
        if (!layerPx[y * width + x]) continue;
        const gcx = Math.floor((x - originX) / cellSize);
        const gcy = Math.floor((y - originY) / cellSize);
        let nearestGI = -1, nearestD2 = bw2;
        for (let dgx = -1; dgx <= 1; dgx++) {
          for (let dgy = -1; dgy <= 1; dgy++) {
            const nx = gcx + dgx, ny = gcy + dgy;
            if (nx < 0 || nx >= gridW || ny < 0 || ny >= gridH) continue;
            for (const gi of grid[ny * gridW + nx]) {
              const v = verts[gi];
              const ddx = x - v.x, ddy = y - v.y;
              const d2  = ddx * ddx + ddy * ddy;
              if (d2 < nearestD2) { nearestD2 = d2; nearestGI = gi; }
            }
          }
        }
        if (nearestGI >= 0) {
          const { ci, vi } = verts[nearestGI];
          pixelsPerChainVert[ci][vi].push({ x, y });
        }
      }
    }

    const now = performance.now();
    if (now - lastYield > 16) {
      const pct = Math.round((layer + 1) / layerCount * 100);
      onProgress?.(0.25 + (layer + 1) / layerCount * 0.75, `Assigning pixels… ${pct}%`);
      await new Promise<void>(r => setTimeout(r, 0));
      lastYield = performance.now();
    }
  }

  // ── Phase 3: endpoint trimming, vertStats, assemble result ─────────────────
  const cacheChains: FitCache["chains"] = [];

  for (let ci = 0; ci < total; ci++) {
    const chain        = chains[ci];
    const denseVerts   = chainDenseVerts[ci];
    const pixelsPerVert = pixelsPerChainVert[ci];
    const n            = denseVerts.length;

    if (!chain.isClosed && n >= 2) {
      {
        const v = denseVerts[0], next = denseVerts[1];
        const dx = next.x - v.x, dy = next.y - v.y;
        const len = Math.hypot(dx, dy);
        if (len > 1e-10) {
          const ux = dx / len, uy = dy / len, lo = -denseSeg * 0.5;
          pixelsPerVert[0] = pixelsPerVert[0].filter(
            p => (p.x - v.x) * ux + (p.y - v.y) * uy >= lo,
          );
        }
      }
      {
        const v = denseVerts[n - 1], prev = denseVerts[n - 2];
        const dx = v.x - prev.x, dy = v.y - prev.y;
        const len = Math.hypot(dx, dy);
        if (len > 1e-10) {
          const ux = dx / len, uy = dy / len, hi = denseSeg * 0.5;
          pixelsPerVert[n - 1] = pixelsPerVert[n - 1].filter(
            p => (p.x - v.x) * ux + (p.y - v.y) * uy <= hi,
          );
        }
      }
    }

    const vertStats = new Float64Array(n * 6);
    for (let vi = 0; vi < n; vi++) {
      const b = vi * 6, px = pixelsPerVert[vi];
      vertStats[b] = px.length;
      for (const p of px) {
        vertStats[b + 1] += p.x;  vertStats[b + 2] += p.y;
        vertStats[b + 3] += p.x * p.x; vertStats[b + 4] += p.x * p.y;
        vertStats[b + 5] += p.y * p.y;
      }
    }
    cacheChains.push({ layer: chain.layer, isClosed: chain.isClosed, denseVerts, pixelsPerVert, vertStats });
  }

  onProgress?.(1, "Done");
  return { graph, chains: cacheChains };
}
