/**
 * snapEndpointPairs — pure geometry, no GPU deps.
 * Extracted from curve_fit.ts so it can be unit-tested independently.
 */

import type { LinePrimitive, ArcPrimitive } from "./curve_fit_math.ts";

export interface SnapChainInfo {
  startVi:  number;
  endVi:    number;
  isClosed: boolean;
  layer?:   number;
}

/** Minimal graph interface — compatible with PathGraph but no GPU deps. */
export interface SnapGraph {
  vertices: Array<{ x: number; y: number; type: string }>;
}

/**
 * When two open chains both terminate at "endpoint" vertices that are close
 * together, snap both endpoints to:
 *   - the geometric intersection of their terminal segment directions
 *     (converging, non-parallel case), or
 *   - a merged single segment spanning both far endpoints (anti-parallel case).
 *
 * In the anti-parallel case the two terminal segments are merged into one:
 * prim_a is extended to span from a's far end to b's far end, and prim_b is
 * removed from reconByChain[b.ci].  This eliminates the redundant intermediate
 * vertex that would otherwise appear at the snap midpoint.
 *
 * Only fires when both extensions go *forward* from their respective
 * endpoints (dotA > 0, dotB > 0), i.e. the lines are converging toward the
 * snap target, not diverging.
 */
/**
 * Maximum distance (px) the merged line may fall from the point where the two
 * chains actually meet.  Half the fitter's own acceptance threshold, so a merge
 * can never produce geometry the fitter would have rejected outright.
 */
const MAX_MERGE_DEVIATION = 0.25;

export function snapEndpointPairs(
  graph:        SnapGraph,
  chainInfos:   SnapChainInfo[],
  reconByChain: Array<Array<{ prim: LinePrimitive | ArcPrimitive }> | null>,
  maxExtend:    number,
): void {
  const { vertices } = graph;

  type EP = { prim: LinePrimitive; isStart: boolean; ci: number; layer: number | undefined };
  const eps: EP[] = [];

  for (let ci = 0; ci < chainInfos.length; ci++) {
    const recon = reconByChain[ci];
    if (!recon || recon.length === 0) continue;
    const info = chainInfos[ci];
    if (info.isClosed) continue;

    const startVi = info.startVi;
    const endVi   = info.endVi;
    const layer   = info.layer;

    if (vertices[startVi]?.type === "endpoint") {
      const p = recon[0].prim;
      if (p.type === "line")
        eps.push({ prim: p, isStart: true, ci, layer });
    }
    if (vertices[endVi]?.type === "endpoint") {
      const p = recon[recon.length - 1].prim;
      if (p.type === "line")
        eps.push({ prim: p, isStart: false, ci, layer });
    }
  }

  for (let i = 0; i < eps.length; i++) {
    for (let j = i + 1; j < eps.length; j++) {
      const a = eps[i], b = eps[j];
      if (a.layer !== undefined && b.layer !== undefined && a.layer !== b.layer) continue;

      // Fitted endpoint positions.
      const ax = a.isStart ? a.prim.x1 : a.prim.x2, ay = a.isStart ? a.prim.y1 : a.prim.y2;
      const bx = b.isStart ? b.prim.x1 : b.prim.x2, by = b.isStart ? b.prim.y1 : b.prim.y2;

      // Fast reject: fitted endpoints must be within snap range.
      if (Math.hypot(bx - ax, by - ay) > maxExtend * 2) continue;

      // Forward direction from each endpoint (continuing past it, away from interior).
      const adx = a.isStart ? a.prim.x1 - a.prim.x2 : a.prim.x2 - a.prim.x1;
      const ady = a.isStart ? a.prim.y1 - a.prim.y2 : a.prim.y2 - a.prim.y1;
      const bdx = b.isStart ? b.prim.x1 - b.prim.x2 : b.prim.x2 - b.prim.x1;
      const bdy = b.isStart ? b.prim.y1 - b.prim.y2 : b.prim.y2 - b.prim.y1;

      // Convergence check: both forward directions must point toward the other
      // endpoint.  This is the primary gate — it replaces the t/s ≥ 0 check
      // and handles the nearly-anti-parallel case robustly.
      const gx = bx - ax, gy = by - ay;
      const dotA =  adx * gx + ady * gy;   // > 0  ⟹  a's fwd points toward b
      const dotB = -bdx * gx - bdy * gy;   // > 0  ⟹  b's fwd points toward a
      if (dotA <= 0 || dotB <= 0) continue;

      // Snap target: intersection for clearly non-parallel lines, merged segment
      // for nearly anti-parallel lines (sin of angle between directions is small).
      const adLen = Math.hypot(adx, ady);
      const bdLen = Math.hypot(bdx, bdy);
      const denom = adx * bdy - ady * bdx;                  // = adLen*bdLen*sin θ
      const sinTheta = Math.abs(denom) / (adLen * bdLen);   // sin of angle between dirs

      if (sinTheta < 0.1) {
        // Nearly anti-parallel: merge the two terminal segments into one.
        // prim_a is extended to span from a's far end to b's far end, eliminating
        // the intermediate vertex at the midpoint.  prim_b is removed from its chain.
        const bxFar = b.isStart ? b.prim.x2 : b.prim.x1;
        const byFar = b.isStart ? b.prim.y2 : b.prim.y1;
        const axFar = a.isStart ? a.prim.x2 : a.prim.x1;
        const ayFar = a.isStart ? a.prim.y2 : a.prim.y1;

        // The angle gate alone is not enough, because the deviation this merge
        // introduces scales with the LENGTHS being merged, not just the angle.
        // Two terminal segments meeting at 3.5 degrees is "nearly anti-parallel"
        // by any local measure, but if they are 170 px and 1435 px long the
        // single line replacing them misses the joint by 9 px.
        //
        // Measured: that is exactly how a very gently curved panel edge became
        // one 1606 px straight line sitting up to 9 px off its own ink.
        //
        // So gate on the thing that actually matters: how far the merged line
        // falls from the point where the two chains really meet.
        const jx = (ax + bx) * 0.5, jy = (ay + by) * 0.5;
        const mdx = bxFar - axFar, mdy = byFar - ayFar;
        const mLen = Math.hypot(mdx, mdy);
        if (mLen > 1e-9) {
          const dev = Math.abs((jx - axFar) * mdy - (jy - ayFar) * mdx) / mLen;
          if (dev > MAX_MERGE_DEVIATION) continue;
        }

        // Extend prim_a to reach b's far endpoint.
        if (a.isStart) {
          // prim_a starts at the snapped end; its "far" end is x2/y2.
          // We want: x1=bxFar, y1=byFar (b's far end replaces a's snap endpoint).
          a.prim.x1 = bxFar; a.prim.y1 = byFar;
        } else {
          a.prim.x2 = bxFar; a.prim.y2 = byFar;
        }

        // Remove prim_b from its chain (it is now subsumed by prim_a).
        const reconB = reconByChain[b.ci];
        if (reconB) {
          if (b.isStart) reconB.shift();
          else           reconB.pop();
        }
      } else {
        // Clearly converging: snap both endpoints to the precise line intersection.
        const t = (gx * bdy - gy * bdx) / denom;
        const ix = ax + t * adx;
        const iy = ay + t * ady;

        if (Math.hypot(ix - ax, iy - ay) > maxExtend) continue;
        if (Math.hypot(ix - bx, iy - by) > maxExtend) continue;

        if (a.isStart) { a.prim.x1 = ix; a.prim.y1 = iy; } else { a.prim.x2 = ix; a.prim.y2 = iy; }
        if (b.isStart) { b.prim.x1 = ix; b.prim.y1 = iy; } else { b.prim.x2 = ix; b.prim.y2 = iy; }
      }
    }
  }
}
