/**
 * RGBA image format: 4 bytes per pixel (R, G, B, A).
 *
 * This is the primary interchange format used throughout the pipeline.
 * Future modules (palettized, binary) will build on this foundation.
 */

/** An image stored as packed RGBA pixels. */
export interface RGBAImage {
  readonly width: number;
  readonly height: number;
  /** Pixel data in row-major order, 4 bytes per pixel (R, G, B, A). */
  readonly data: Uint8ClampedArray;
}

/** Create a blank (transparent black) RGBA image. */
export function createRGBAImage(width: number, height: number): RGBAImage {
  return {
    width,
    height,
    data: new Uint8ClampedArray(width * height * 4),
  };
}

/** Clone an RGBA image (deep copy of pixel data). */
export function cloneRGBAImage(image: RGBAImage): RGBAImage {
  return {
    width: image.width,
    height: image.height,
    data: new Uint8ClampedArray(image.data),
  };
}

/** Get the [R, G, B, A] values at a pixel coordinate. */
export function getPixelRGBA(
  image: RGBAImage,
  x: number,
  y: number,
): [number, number, number, number] {
  const i = (y * image.width + x) * 4;
  return [image.data[i], image.data[i + 1], image.data[i + 2], image.data[i + 3]];
}

/** Set the RGBA values at a pixel coordinate. */
export function setPixelRGBA(
  image: RGBAImage,
  x: number,
  y: number,
  r: number,
  g: number,
  b: number,
  a: number,
): void {
  const i = (y * image.width + x) * 4;
  // Cast away readonly for mutation — callers use this for construction.
  const data = image.data as Uint8ClampedArray;
  data[i] = r;
  data[i + 1] = g;
  data[i + 2] = b;
  data[i + 3] = a;
}

/** Crop a rectangular region from an RGBA image. */
export function cropRGBAImage(
  image: RGBAImage,
  cx: number,
  cy: number,
  cw: number,
  ch: number,
): RGBAImage {
  const data = new Uint8ClampedArray(cw * ch * 4);
  const srcW = image.width;
  const src = image.data;
  for (let y = 0; y < ch; y++) {
    const srcOff = ((cy + y) * srcW + cx) * 4;
    const dstOff = y * cw * 4;
    data.set(src.subarray(srcOff, srcOff + cw * 4), dstOff);
  }
  return { width: cw, height: ch, data };
}

/** Paste a source image into a target image at the given offset. Mutates target. */
export function pasteInto(
  target: RGBAImage,
  source: RGBAImage,
  offsetX: number,
  offsetY: number,
): void {
  const dst = target.data as Uint8ClampedArray;
  const src = source.data;
  const tw = target.width;
  const sw = source.width;
  const rows = Math.min(source.height, target.height - offsetY);
  const cols = Math.min(sw, target.width - offsetX);
  for (let y = 0; y < rows; y++) {
    const srcOff = y * sw * 4;
    const dstOff = ((offsetY + y) * tw + offsetX) * 4;
    dst.set(src.subarray(srcOff, srcOff + cols * 4), dstOff);
  }
}

/**
 * Convert RGBA image to a Float32Array of normalized RGB values in CHW layout.
 * Output shape: [3, height, width], values in [0, 1].
 * Used as input to the ONNX denoiser model.
 */
export function rgbaToFloat32CHW(image: RGBAImage): Float32Array {
  const { width, height, data } = image;
  const chw = new Float32Array(3 * height * width);
  const planeSize = height * width;
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      const srcIdx = (y * width + x) * 4;
      const dstIdx = y * width + x;
      chw[dstIdx] = data[srcIdx] / 255; // R
      chw[planeSize + dstIdx] = data[srcIdx + 1] / 255; // G
      chw[2 * planeSize + dstIdx] = data[srcIdx + 2] / 255; // B
    }
  }
  return chw;
}

/**
 * Convert a Float32Array in CHW layout back to an RGBAImage.
 * Input shape: [3, height, width], values in [0, 1].
 */
export function float32CHWToRGBA(
  chw: Float32Array,
  width: number,
  height: number,
): RGBAImage {
  const data = new Uint8ClampedArray(width * height * 4);
  const planeSize = height * width;
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      const srcIdx = y * width + x;
      const dstIdx = (y * width + x) * 4;
      data[dstIdx] = Math.round(chw[srcIdx] * 255); // R
      data[dstIdx + 1] = Math.round(chw[planeSize + srcIdx] * 255); // G
      data[dstIdx + 2] = Math.round(chw[2 * planeSize + srcIdx] * 255); // B
      data[dstIdx + 3] = 255; // A
    }
  }
  return { width, height, data };
}
