/**
 * PDF page rendering with a platform-agnostic canvas abstraction.
 *
 * The browser implementation supplies a real HTMLCanvasElement;
 * a future Deno CLI implementation could supply an off-screen canvas
 * (e.g. node-canvas or a custom WASM backend).
 */

import type { RGBAImage } from "../formats/rgba_image.ts";

// ---------------------------------------------------------------------------
// Canvas abstraction
// ---------------------------------------------------------------------------

export interface ImageDataLike {
  readonly width: number;
  readonly height: number;
  readonly data: Uint8ClampedArray;
}

export interface CanvasRenderingContext2DLike {
  getImageData(sx: number, sy: number, sw: number, sh: number): ImageDataLike;
  putImageData(imageData: ImageDataLike, dx: number, dy: number): void;
  drawImage(image: unknown, dx: number, dy: number): void;
}

export interface CanvasLike {
  width: number;
  height: number;
  getContext(contextId: "2d"): CanvasRenderingContext2DLike | null;
}

/** Abstraction over canvas creation for cross-platform support. */
export interface CanvasBackend {
  createCanvas(width: number, height: number): CanvasLike;
}

// ---------------------------------------------------------------------------
// PDF document wrapper
// ---------------------------------------------------------------------------

/** Opaque handle to a loaded PDF document. */
export interface PDFDocument {
  readonly numPages: number;
  // deno-lint-ignore no-explicit-any
  readonly _doc: any; // internal pdf.js document proxy
}

/**
 * Load a PDF document from raw bytes.
 * The document is loaded once; pages can then be rendered multiple times
 * without re-parsing (and without detaching the ArrayBuffer).
 */
export async function loadPdfDocument(
  file: Uint8Array,
  // deno-lint-ignore no-explicit-any
  pdfjsLib: any,
): Promise<PDFDocument> {
  // Copy the data so pdf.js can transfer its buffer without
  // detaching the caller's original.
  const copy = new Uint8Array(file);
  const loadingTask = pdfjsLib.getDocument({ data: copy });
  const doc = await loadingTask.promise;
  return { numPages: doc.numPages, _doc: doc };
}

/** Page size in PDF points (1/72 inch). */
export interface PageSize {
  widthPt: number;
  heightPt: number;
}

/**
 * Get page sizes (in PDF points) for all pages in the document.
 * Useful for computing relative thumbnail sizes.
 */
export async function getPageSizes(doc: PDFDocument): Promise<PageSize[]> {
  const sizes: PageSize[] = [];
  for (let i = 1; i <= doc.numPages; i++) {
    const page = await doc._doc.getPage(i);
    const vp = page.getViewport({ scale: 1 });
    sizes.push({ widthPt: vp.width, heightPt: vp.height });
  }
  return sizes;
}

/**
 * Get page labels from the PDF document.
 * Returns an array of labels (1-indexed: index 0 = page 1).
 * Falls back to page numbers if no labels are defined.
 */
export async function getPageLabels(doc: PDFDocument): Promise<string[]> {
  try {
    const labels: string[] | null = await doc._doc.getPageLabels();
    if (labels && labels.length > 0) return labels;
  } catch {
    // getPageLabels not supported or failed
  }
  // Fallback: generate numeric labels
  return Array.from({ length: doc.numPages }, (_, i) => String(i + 1));
}

// ---------------------------------------------------------------------------
// PDF rendering
// ---------------------------------------------------------------------------

/** Target DPI for full-resolution rendering. */
export const TARGET_DPI = 200;

/** Default scale for 200 DPI rendering (DPI / 72 PDF points-per-inch). */
export const SCALE_200DPI = TARGET_DPI / 72;

// ---------------------------------------------------------------------------
// Physical-size snapping
// ---------------------------------------------------------------------------

const CM_PER_INCH = 2.54;

/**
 * Snap an inch measurement to the nearest 0.01″ or 0.01 cm, picking
 * whichever produces a pixel count closest to a whole number at the
 * target DPI. This recovers the author's intended dimensions from
 * PDF point rounding errors.
 *
 * Example: 33.9957″ at 200 DPI
 *   inch snap → 34.00″  → 6800.0 px  (pixel residual 0.0)   ← winner
 *   cm snap   → 86.35cm → 6799.2 px  (pixel residual 0.2)
 */
export function snapToCleanUnit(rawInches: number, dpi: number): number {
  // Snap as inches: round to nearest 0.01"
  const snappedInch = Math.round(rawInches * 100) / 100;
  const pxResidualInch = Math.abs(snappedInch * dpi - Math.round(snappedInch * dpi));

  // Snap as cm: convert to cm, round to nearest 0.01 cm, convert back
  const rawCm = rawInches * CM_PER_INCH;
  const snappedCm = Math.round(rawCm * 100) / 100;
  const snappedCmAsInch = snappedCm / CM_PER_INCH;
  const pxResidualCm = Math.abs(snappedCmAsInch * dpi - Math.round(snappedCmAsInch * dpi));

  return pxResidualInch <= pxResidualCm ? snappedInch : snappedCmAsInch;
}

/** Result of rendering a PDF page, including physical page dimensions. */
export interface RenderedPage extends RGBAImage {
  /** Page width in inches (from PDF metadata). */
  pageWidthInches: number;
  /** Page height in inches (from PDF metadata). */
  pageHeightInches: number;
}

export async function renderPdfPage(
  doc: PDFDocument,
  pageNumber: number,
  backend: CanvasBackend,
  scale: number = SCALE_200DPI,
): Promise<RenderedPage> {
  const page = await doc._doc.getPage(pageNumber);

  // Get unscaled viewport to read physical page size in PDF points (1/72")
  const baseViewport = page.getViewport({ scale: 1 });
  const rawWidthInches = baseViewport.width / 72;
  const rawHeightInches = baseViewport.height / 72;

  // Recover target DPI from caller's scale
  const dpi = scale * 72;

  // PDF authoring tools work in inches or cm then convert to points,
  // introducing tiny rounding errors. Snap to the nearest 0.01" or 0.01 cm
  // (whichever gives cleaner pixel counts) to recover intended dimensions.
  const pageWidthInches = snapToCleanUnit(rawWidthInches, dpi);
  const pageHeightInches = snapToCleanUnit(rawHeightInches, dpi);

  // Compute desired pixel dimensions from snapped physical size × DPI,
  // then derive the exact scale factor that hits those pixel counts.
  const desiredW = Math.round(pageWidthInches * dpi);
  const desiredH = Math.round(pageHeightInches * dpi);
  const adjustedScaleX = desiredW / baseViewport.width;
  const adjustedScaleY = desiredH / baseViewport.height;
  const adjustedScale = (adjustedScaleX + adjustedScaleY) / 2;

  const viewport = page.getViewport({ scale: adjustedScale });

  console.log(
    `[pdf_render] page ${pageNumber}:\n` +
    `  PDF points:      ${baseViewport.width} × ${baseViewport.height}\n` +
    `  Raw inches:      ${rawWidthInches.toFixed(6)}″ × ${rawHeightInches.toFixed(6)}″\n` +
    `  Snapped inches:  ${pageWidthInches}″ × ${pageHeightInches}″\n` +
    `  Target DPI:      ${dpi}\n` +
    `  Desired pixels:  ${desiredW} × ${desiredH}\n` +
    `  Adjusted scale:  ${adjustedScale.toFixed(10)} (was ${scale.toFixed(10)})`
  );

  const canvas = backend.createCanvas(desiredW, desiredH);
  const context = canvas.getContext("2d");
  if (!context) throw new Error("Failed to get 2d context");

  await page.render({ canvasContext: context, viewport }).promise;

  const imageData = context.getImageData(0, 0, canvas.width, canvas.height);
  return {
    width: imageData.width,
    height: imageData.height,
    data: imageData.data,
    pageWidthInches,
    pageHeightInches,
  };
}

/**
 * Render a PDF page at thumbnail scale for page selection UI.
 */
export async function renderPdfThumbnail(
  doc: PDFDocument,
  pageNumber: number,
  backend: CanvasBackend,
  maxDimension = 200,
): Promise<RGBAImage> {
  const page = await doc._doc.getPage(pageNumber);

  // Calculate scale to fit within maxDimension
  const viewport1 = page.getViewport({ scale: 1 });
  const scale = maxDimension / Math.max(viewport1.width, viewport1.height);
  const viewport = page.getViewport({ scale });

  const canvas = backend.createCanvas(
    Math.round(viewport.width),
    Math.floor(viewport.height),
  );
  const context = canvas.getContext("2d");
  if (!context) throw new Error("Failed to get 2d context");

  await page.render({ canvasContext: context, viewport }).promise;

  const imageData = context.getImageData(0, 0, canvas.width, canvas.height);
  return {
    width: imageData.width,
    height: imageData.height,
    data: imageData.data,
  };
}
