/**
 * WebGPU graph overlay.
 *
 * Renders path-graph vertices (dots) and edges (line quads) as a transparent
 * overlay on top of any other view.  A dedicated canvas element is placed
 * above the main viewer canvas; the WebGPU context for that canvas uses
 * premultiplied alpha so the overlay composites correctly.
 *
 * Usage
 * ─────
 * 1. Call `createGraphOverlay(canvas, gpu)` once on startup.
 * 2. Call `handle.upload(pages, activeLayer)` whenever the graph data changes.
 *    Pass activeLayer = -1 to show all layers, ≥ 0 to show a single layer.
 * 3. Call `handle.render(panX, panY, zoom, dpr)` each frame.
 * 4. Call `handle.setVisible(bool)` to show/hide.
 * 5. Call `handle.destroy()` to release GPU resources.
 *
 * Render order
 * ────────────
 * 1. Edge halos  (wide white outlines — drawn behind edges for contrast)
 * 2. Edge fills  (colored, normal width)
 * 3. Dot halos   (large white outlines — drawn behind dots)
 * 4. Dot fills   (colored circles)
 *
 * Coordinate system
 * ─────────────────
 * Graph data is stored in virtual space (same coordinate system as the
 * MultiPageViewer).  The caller is responsible for transforming skeleton-space
 * pixel coordinates to virtual space before calling upload():
 *
 *   virtualX = pageOffsetX + skeletonX + 0.5   (0.5 for pixel center)
 *   virtualY = pageOffsetY + skeletonY + 0.5
 *
 * Buffer layout
 * ─────────────
 * Edge entry  : 8 × f32 → [x1, y1, x2, y2, r, g, b, a]
 * Vertex entry: 8 × f32 → [x, y, r, g, b, a, size_scale, 0]
 */

import type { GPUContext } from "./gpu_context.ts";
import type { PathGraph } from "./path_connect.ts";
import graphOverlayShader from "./shaders/graph_overlay.wgsl?raw";

// ---------------------------------------------------------------------------
// Public interface
// ---------------------------------------------------------------------------

export interface GraphPageInput {
  graph: PathGraph;
  /** Virtual-space X of skeleton pixel (0, 0) — before the 0.5 center offset. */
  imgOriginX: number;
  /** Virtual-space Y of skeleton pixel (0, 0) — before the 0.5 center offset. */
  imgOriginY: number;
  /** sRGB color [0-255] per layer index. */
  layerColors: Array<[number, number, number]>;
}

export interface GraphOverlayHandle {
  /**
   * Upload (or replace) graph data from one or more pages.
   *
   * @param pages       Per-page graph data and coordinate origins.
   * @param activeLayer Layer index to display, or -1 for all layers.
   */
  upload(pages: GraphPageInput[], activeLayer: number): void;

  /**
   * Render the overlay.  Parameters mirror the MultiPageViewer render call.
   *
   * @param panX  Horizontal pan in CSS pixels.
   * @param panY  Vertical pan in CSS pixels.
   * @param zoom  Virtual-pixel → CSS-pixel scale factor.
   * @param dpr   Device pixel ratio.
   */
  render(panX: number, panY: number, zoom: number, dpr: number): void;

  /** Show or hide the overlay without destroying GPU resources. */
  setVisible(visible: boolean): void;

  /** Release all GPU resources. */
  destroy(): void;
}

// ---------------------------------------------------------------------------
// Visual constants
// ---------------------------------------------------------------------------

/** Edge alpha (0-1). */
const EDGE_ALPHA = 0.85;
/** Dot alpha (0-1). */
const DOT_ALPHA = 1.0;
/** Edge half-width in CSS pixels. */
const EDGE_HALF_WIDTH_CSS = 1.0;
/** Dot radius in CSS pixels for endpoint/junction/isolated vertices. */
const DOT_RADIUS_CSS = 3.0;
/** Dot size_scale for all other vertex types. */
const DEFAULT_DOT_SCALE = 1.0;
/** Junction dots are slightly larger to stand out. */
const JUNCTION_DOT_SCALE = 1.3;

/** Extra half-width (CSS px) added to edges in the halo pass. */
const HALO_EXTRA_HALF_W_CSS = 1.5;
/** Extra radius (CSS px) added to dots in the halo pass. */
const HALO_EXTRA_R_CSS = 1.5;

// ---------------------------------------------------------------------------
// Flatten graph data into f32 buffers
// ---------------------------------------------------------------------------

interface FlatData {
  edgeData: Float32Array;  // edgeCount * 8 floats
  dotData:  Float32Array;  // dotCount  * 8 floats
  edgeCount: number;
  dotCount:  number;
}

function layerRgb(
  layerIndex: number,
  layerColors: Array<[number, number, number]>,
): [number, number, number] {
  if (layerIndex < layerColors.length) return layerColors[layerIndex];
  // Fallback: bright, high-contrast colors that avoid dark shades
  const FALLBACK: Array<[number, number, number]> = [
    [255,  80,  80], [ 80, 180,  80], [ 80,  80, 255], [255, 200,   0],
    [255,  80, 200], [ 80, 220, 220], [200, 160,  80], [160,  80, 200],
    [255, 140,  40], [  0, 200, 160], [160, 200,   0], [ 40, 120, 255],
    [220,  80, 120], [ 80, 160, 200], [200,  80,  80], [ 80, 200, 120],
  ];
  return FALLBACK[layerIndex % FALLBACK.length];
}

/**
 * Compute a visually boosted overlay color: ensures the color is bright
 * enough to be visible against typical dark skeleton pixels.
 * Dark colors (luminance < 0.25) are replaced with the layer's complement
 * shifted toward a bright hue.
 */
function boostColor(r: number, g: number, b: number): [number, number, number] {
  const luma = 0.299 * r + 0.587 * g + 0.114 * b;
  if (luma < 64) {
    // Color is too dark — rotate hue and boost brightness
    // Simple strategy: swap channels and clamp to a bright range
    return [Math.max(r, 180), Math.max(g, 100), Math.max(b, 180)];
  }
  return [r, g, b];
}

function flattenGraphs(pages: GraphPageInput[], activeLayer: number): FlatData {
  // Overallocate (max sizes); trim via subarray at the end.
  // +4 per page for the diagnostic border rectangle.
  let maxEdges = 0;
  let maxDots  = 0;
  for (const { graph } of pages) {
    maxEdges += graph.edges.length + 4;
    maxDots  += graph.vertices.length;
  }

  const edgeData = new Float32Array(maxEdges * 8);
  const dotData  = new Float32Array(maxDots  * 8);

  let ei = 0;
  let di = 0;

  for (const { graph, imgOriginX, imgOriginY, layerColors } of pages) {
    const { vertices, edges } = graph;

    // ── Edges ──────────────────────────────────────────────────────────────
    for (const edge of edges) {
      if (activeLayer >= 0 && edge.layer !== activeLayer) continue;

      const fromV = vertices[edge.from];
      const toV   = vertices[edge.to];
      if (!fromV || !toV) continue;

      const [lr, lg, lb] = layerRgb(edge.layer, layerColors);
      const [r, g, b]    = boostColor(lr, lg, lb);

      // +0.5 to hit pixel centers
      const x1 = imgOriginX + fromV.x + 0.5;
      const y1 = imgOriginY + fromV.y + 0.5;
      const x2 = imgOriginX + toV.x   + 0.5;
      const y2 = imgOriginY + toV.y   + 0.5;

      const base = ei * 8;
      edgeData[base + 0] = x1;
      edgeData[base + 1] = y1;
      edgeData[base + 2] = x2;
      edgeData[base + 3] = y2;
      edgeData[base + 4] = r / 255;
      edgeData[base + 5] = g / 255;
      edgeData[base + 6] = b / 255;
      edgeData[base + 7] = EDGE_ALPHA;
      ei++;
    }

    // ── Vertices (dots) ────────────────────────────────────────────────────
    for (const vtx of vertices) {
      if (vtx.type === "chain") continue; // interior path vertices — no dot, rendered via edges
      if (activeLayer >= 0 && vtx.layer !== activeLayer) continue;

      const [lr, lg, lb] = layerRgb(vtx.layer, layerColors);
      let [r, g, b]      = boostColor(lr, lg, lb);
      let sizeScale      = DEFAULT_DOT_SCALE;

      switch (vtx.type) {
        case "junction":
          // Bright white for branching points
          r = 255; g = 255; b = 255;
          sizeScale = JUNCTION_DOT_SCALE;
          break;
        case "isolated":
          // Orange accent for lone pixels
          r = 255; g = 160; b = 0;
          sizeScale = DEFAULT_DOT_SCALE;
          break;
        default:
          // "endpoint" — layer color, normal size
          break;
      }

      const base = di * 8;
      dotData[base + 0] = imgOriginX + vtx.x + 0.5;
      dotData[base + 1] = imgOriginY + vtx.y + 0.5;
      dotData[base + 2] = r / 255;
      dotData[base + 3] = g / 255;
      dotData[base + 4] = b / 255;
      dotData[base + 5] = DOT_ALPHA;
      dotData[base + 6] = sizeScale;
      dotData[base + 7] = 0;
      di++;
    }
  }

  return {
    edgeData: edgeData.subarray(0, ei * 8),
    dotData:  dotData.subarray(0, di * 8),
    edgeCount: ei,
    dotCount:  di,
  };
}

// ---------------------------------------------------------------------------
// Pipeline cache
// ---------------------------------------------------------------------------

interface Pipelines {
  device: GPUDevice;
  bgl: GPUBindGroupLayout;
  edgeHaloPipeline: GPURenderPipeline;
  edgeFillPipeline: GPURenderPipeline;
  dotHaloPipeline:  GPURenderPipeline;
  dotFillPipeline:  GPURenderPipeline;
  uniformBuf:   GPUBuffer;
  dummyEdgeBuf: GPUBuffer;
  dummyDotBuf:  GPUBuffer;
}

let cachedPipelines: Pipelines | null = null;

function getOrCreatePipelines(device: GPUDevice, format: GPUTextureFormat): Pipelines {
  if (cachedPipelines && cachedPipelines.device === device) return cachedPipelines;

  const bgl = device.createBindGroupLayout({
    entries: [
      { binding: 0, visibility: GPUShaderStage.VERTEX | GPUShaderStage.FRAGMENT,
        buffer:  { type: "uniform" } },
      { binding: 1, visibility: GPUShaderStage.VERTEX,
        buffer:  { type: "read-only-storage" } },
      { binding: 2, visibility: GPUShaderStage.VERTEX,
        buffer:  { type: "read-only-storage" } },
    ],
  });

  const layout = device.createPipelineLayout({ bindGroupLayouts: [bgl] });
  const module = device.createShaderModule({ code: graphOverlayShader });

  // Standard premultiplied-alpha compositing blend
  const blendState: GPUBlendState = {
    color: {
      operation: "add",
      srcFactor: "one",
      dstFactor: "one-minus-src-alpha",
    },
    alpha: {
      operation: "add",
      srcFactor: "one",
      dstFactor: "one-minus-src-alpha",
    },
  };

  const edgeHaloPipeline = device.createRenderPipeline({
    layout,
    vertex:    { module, entryPoint: "vs_edge_halo" },
    fragment:  { module, entryPoint: "fs_edge", targets: [{ format, blend: blendState }] },
    primitive: { topology: "triangle-list" },
  });

  const edgeFillPipeline = device.createRenderPipeline({
    layout,
    vertex:    { module, entryPoint: "vs_edge" },
    fragment:  { module, entryPoint: "fs_edge", targets: [{ format, blend: blendState }] },
    primitive: { topology: "triangle-list" },
  });

  const dotHaloPipeline = device.createRenderPipeline({
    layout,
    vertex:    { module, entryPoint: "vs_dot_halo" },
    fragment:  { module, entryPoint: "fs_dot", targets: [{ format, blend: blendState }] },
    primitive: { topology: "triangle-list" },
  });

  const dotFillPipeline = device.createRenderPipeline({
    layout,
    vertex:    { module, entryPoint: "vs_dot" },
    fragment:  { module, entryPoint: "fs_dot", targets: [{ format, blend: blendState }] },
    primitive: { topology: "triangle-list" },
  });

  // 48-byte uniform buffer: 12 × f32
  const uniformBuf = device.createBuffer({
    size:  48,
    usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST,
  });

  // Minimal dummy storage buffers (satisfies the bind group even when empty)
  const dummyEdgeBuf = device.createBuffer({
    size: 32, usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_DST,
  });
  const dummyDotBuf = device.createBuffer({
    size: 32, usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_DST,
  });

  cachedPipelines = {
    device, bgl,
    edgeHaloPipeline, edgeFillPipeline,
    dotHaloPipeline,  dotFillPipeline,
    uniformBuf, dummyEdgeBuf, dummyDotBuf,
  };
  return cachedPipelines;
}

// ---------------------------------------------------------------------------
// Implementation
// ---------------------------------------------------------------------------

export function createGraphOverlay(
  canvas: HTMLCanvasElement,
  gpu: GPUContext,
): GraphOverlayHandle {
  const { device } = gpu;

  // Configure overlay canvas as a WebGPU surface with premultiplied alpha
  // deno-lint-ignore no-explicit-any
  const gpuCtx = (canvas as any).getContext("webgpu") as GPUCanvasContext;
  if (!gpuCtx) throw new Error("Failed to get WebGPU context on overlay canvas");

  // deno-lint-ignore no-explicit-any
  const navGpu = (navigator as any).gpu as GPU;
  const format = navGpu.getPreferredCanvasFormat();
  gpuCtx.configure({ device, format, alphaMode: "premultiplied" });

  let _lastConfigW = 0;
  let _lastConfigH = 0;

  const pipelineState = getOrCreatePipelines(device, format);
  const { bgl, edgeHaloPipeline, edgeFillPipeline, dotHaloPipeline, dotFillPipeline, uniformBuf } = pipelineState;

  // GPU storage buffers for uploaded graph data
  let edgeBuf:  GPUBuffer | null = null;
  let dotBuf:   GPUBuffer | null = null;
  let edgeCount = 0;
  let dotCount  = 0;
  let bindGroup: GPUBindGroup | null = null;

  let visible = true;

  // ── Helpers ──────────────────────────────────────────────────────────────

  function uploadBuffer(data: Float32Array, oldBuf: GPUBuffer | null): GPUBuffer {
    oldBuf?.destroy();
    // Ensure minimum size (WebGPU requires non-zero buffers bound as storage)
    const byteLen = Math.max(data.byteLength, 32);
    // writeBuffer rather than mappedAtCreation: SwiftShader caps the size of a
    // buffer mapped at creation far below what a page of fitted curves needs
    // (it rejected a 178 KB upload), and the throw took the rest of the
    // vectorize run with it.  A queue write has no such cap and is the normal
    // path for a one-shot upload anyway.
    const buf = device.createBuffer({
      size:  byteLen,
      usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_DST,
    });
    device.queue.writeBuffer(buf, 0, data.buffer, data.byteOffset, data.byteLength);
    return buf;
  }

  function rebuildBindGroup(): void {
    const eb = edgeBuf ?? pipelineState.dummyEdgeBuf;
    const db = dotBuf  ?? pipelineState.dummyDotBuf;
    bindGroup = device.createBindGroup({
      layout: bgl,
      entries: [
        { binding: 0, resource: { buffer: uniformBuf } },
        { binding: 1, resource: { buffer: eb } },
        { binding: 2, resource: { buffer: db } },
      ],
    });
  }

  // ── Public methods ────────────────────────────────────────────────────────

  function upload(pages: GraphPageInput[], activeLayer: number): void {
    if (pages.length === 0) {
      edgeBuf?.destroy(); edgeBuf = null; edgeCount = 0;
      dotBuf?.destroy();  dotBuf  = null; dotCount  = 0;
      rebuildBindGroup();
      return;
    }

    const flat = flattenGraphs(pages, activeLayer);
    edgeCount = flat.edgeCount;
    dotCount  = flat.dotCount;
    edgeBuf = uploadBuffer(flat.edgeData, edgeBuf);
    dotBuf  = uploadBuffer(flat.dotData,  dotBuf);
    rebuildBindGroup();
  }

  function render(panX: number, panY: number, zoom: number, dpr: number): void {
    if (!visible) return;
    const hasGraph = (edgeCount > 0 || dotCount > 0) && bindGroup !== null;
    if (!hasGraph) return;

    const cw = canvas.width;
    const ch = canvas.height;
    if (cw === 0 || ch === 0) return;

    // Reconfigure swap chain on size change
    if (cw !== _lastConfigW || ch !== _lastConfigH) {
      gpuCtx.configure({ device, format, alphaMode: "premultiplied" });
      _lastConfigW = cw;
      _lastConfigH = ch;
    }

    // Write uniform buffer (12 × f32 = 48 bytes)
    // Layout (matching WGSL struct Uniforms):
    //   canvas_w, canvas_h, pan_x, pan_y,
    //   zoom, dpr, line_w, dot_r,
    //   halo_w, halo_r, _pad0, _pad1
    const uniforms = new Float32Array([
      cw, ch,
      panX, panY,
      zoom, dpr,
      EDGE_HALF_WIDTH_CSS * dpr,
      DOT_RADIUS_CSS * dpr,
      HALO_EXTRA_HALF_W_CSS * dpr,
      HALO_EXTRA_R_CSS * dpr,
      0.0, 0.0,
    ]);
    device.queue.writeBuffer(uniformBuf, 0, uniforms);

    const textureView = gpuCtx.getCurrentTexture().createView();
    const encoder = device.createCommandEncoder();

    const pass = encoder.beginRenderPass({
      colorAttachments: [{
        view: textureView,
        loadOp:  "clear",
        storeOp: "store",
        clearValue: { r: 0, g: 0, b: 0, a: 0 }, // fully transparent
      }],
    });

    // Halos (white outlines) first, then coloured fills.
    if (hasGraph) {
      pass.setBindGroup(0, bindGroup!);
      if (edgeCount > 0) {
        pass.setPipeline(edgeHaloPipeline);
        pass.draw(6, edgeCount);
        pass.setPipeline(edgeFillPipeline);
        pass.draw(6, edgeCount);
      }
      if (dotCount > 0) {
        pass.setPipeline(dotHaloPipeline);
        pass.draw(6, dotCount);
        pass.setPipeline(dotFillPipeline);
        pass.draw(6, dotCount);
      }
    }

    pass.end();
    device.queue.submit([encoder.finish()]);
  }

  function setVisible(v: boolean): void {
    visible = v;
    canvas.style.display = v ? "" : "none";
  }

  function destroy(): void {
    edgeBuf?.destroy();
    dotBuf?.destroy();
  }

  return { upload, render, setVisible, destroy };
}
